    public void Dispose() => Rendering.PropertyState.ClearGlobalsInternal();

    [Fact]
    public void CommandBuffer_Records_Clear_And_Viewport_Opcodes()
    {
        CommandBuffer cmd = global::XEngine.Runtime.Graphics.GetCommandBuffer("rhi-contract");
        cmd.SetViewport(0, 0, 128, 64);
        cmd.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(1f, 0f, 0f, 1f));

        Assert.True(cmd._streamPos > 0);

        ReadOnlySpan<byte> stream = cmd._stream.AsSpan(0, cmd._streamPos);
        int pos = 0;
        // Named buffers open with BeginSample so RenderDoc / PIX mirror the Frame Debugger tree.
        Assert.Equal(CommandOpcode.BeginSample, ReadOpcode(stream, ref pos));
        Assert.Equal("rhi-contract", cmd._objects[ReadU16(stream, ref pos)]);
        Assert.Equal(CommandOpcode.SetViewport, ReadOpcode(stream, ref pos));
        Assert.Equal(0, ReadI32(stream, ref pos));
        Assert.Equal(0, ReadI32(stream, ref pos));
        Assert.Equal(128u, ReadU32(stream, ref pos));
        Assert.Equal(64u, ReadU32(stream, ref pos));
        Assert.Equal(CommandOpcode.ClearRenderTarget, ReadOpcode(stream, ref pos));

        cmd._ownerReleased = true;
        CommandBufferPool.Return(cmd);
    }

    [Fact]
    public void CommandBuffer_Records_BackendNeutral_ShaderVariant()
    {
        var bytecode = new CompiledShaderBytecode(
            ShaderLanguage.Hlsl,
            ShaderBytecodeFormat.SpirV,
            [0x03, 0x02, 0x23, 0x07],
            [0x03, 0x02, 0x23, 0x07]);
        using var variant = new ShaderVariant(bytecode);
        CommandBuffer cmd = global::XEngine.Runtime.Graphics.GetCommandBuffer("rhi-shader-variant");

        cmd.SetShader(variant);

        ReadOnlySpan<byte> stream = cmd._stream.AsSpan(0, cmd._streamPos);
        int pos = 0;
        // Named buffers open with BeginSample so RenderDoc / PIX mirror the Frame Debugger tree.
        Assert.Equal(CommandOpcode.BeginSample, ReadOpcode(stream, ref pos));
        Assert.Equal("rhi-shader-variant", cmd._objects[ReadU16(stream, ref pos)]);
        Assert.Equal(CommandOpcode.SetShader, ReadOpcode(stream, ref pos));
        ushort objectIndex = ReadU16(stream, ref pos);
        Assert.Same(variant, cmd._objects[objectIndex]);
        Assert.Equal(stream.Length, pos);

        cmd._ownerReleased = true;
        CommandBufferPool.Return(cmd);
    }

    [Fact]
    public void CommandBuffer_Records_Compute_And_Indirect_Opcodes()
    {
        var bytecode = new CompiledShaderBytecode(
            ShaderLanguage.Hlsl,
            ShaderBytecodeFormat.SpirV,
            [],
            [],
            computeBytecode: [0x03, 0x02, 0x23, 0x07]);
        using var variant = new ShaderVariant(bytecode);
        using var args = new GraphicsBuffer(BufferType.IndirectBuffer, ReadOnlySpan<byte>.Empty, dynamic: true);
        using var vertices = new GraphicsBuffer(BufferType.VertexBuffer, ReadOnlySpan<byte>.Empty, dynamic: true);
        using var indices = new GraphicsBuffer(BufferType.ElementsBuffer, ReadOnlySpan<byte>.Empty, dynamic: true);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vao = new GraphicsVertexArray(format, vertices, indices);

        CommandBuffer cmd = global::XEngine.Runtime.Graphics.GetCommandBuffer();
        cmd.SetComputeShader(variant);
        cmd.DispatchCompute(8, 1, 1);
        cmd.DispatchIndirect(args, 16);
        cmd.ResourceBarrier(GpuBarrierKind.ComputeToIndirect, args);
        cmd.DrawIndexedIndirect(vao, Topology.Triangles, args, 0, index32bit: true);

        ReadOnlySpan<byte> stream = cmd._stream.AsSpan(0, cmd._streamPos);
        int pos = 0;
        Assert.Equal(CommandOpcode.SetComputeShader, ReadOpcode(stream, ref pos));
        Assert.Same(variant, cmd._objects[ReadU16(stream, ref pos)]);
        Assert.Equal(CommandOpcode.DispatchCompute, ReadOpcode(stream, ref pos));
        Assert.Equal(8u, ReadU32(stream, ref pos));
        Assert.Equal(1u, ReadU32(stream, ref pos));
        Assert.Equal(1u, ReadU32(stream, ref pos));
        Assert.Equal(CommandOpcode.DispatchIndirect, ReadOpcode(stream, ref pos));
        Assert.Same(args, cmd._objects[ReadU16(stream, ref pos)]);
        Assert.Equal(16u, ReadU32(stream, ref pos));
        Assert.Equal(CommandOpcode.ResourceBarrier, ReadOpcode(stream, ref pos));
        Assert.Equal((byte)GpuBarrierKind.ComputeToIndirect, stream[pos]);
        pos += 1;
        Assert.Same(args, cmd._objects[ReadU16(stream, ref pos)]);
        Assert.Equal(CommandOpcode.DrawIndexedIndirect, ReadOpcode(stream, ref pos));
        Assert.Same(vao, cmd._objects[ReadU16(stream, ref pos)]);
        Assert.Equal((byte)Topology.Triangles, stream[pos]);
        pos += 1;
        Assert.Same(args, cmd._objects[ReadU16(stream, ref pos)]);
        Assert.Equal(0u, ReadU32(stream, ref pos));
        Assert.Equal(1, stream[pos]);
        pos += 1;
        Assert.Equal(stream.Length, pos);

        var decoded = new List<Rendering.CapturedOp>();
        var owned = new List<Rendering.PropertyState>();
        Rendering.CommandBufferDecoder.Decode(cmd, "compute-record", null, decoded, owned);
        Assert.True(decoded.Exists(op => op.VisibleKind == Rendering.FrameEventKind.Dispatch && op.Label == "Dispatch 8x1x1"));
        Assert.True(decoded.Exists(op => op.Label == "DrawIndexedIndirect Triangles +0"));

        cmd._ownerReleased = true;
        CommandBufferPool.Return(cmd);
    }

    [Fact]
    public void MaterialSnapshot_ReplaceDisposedShaderDefaultsWithFallback()
    {
        using var texture = new Resources.Texture2D();
        var mainTexture = new Rendering.Shaders.ShaderProperty(texture)
        {
            Name = "_MainTex",
            DisplayName = "Main Texture",
        };
        using var shader = new Resources.Shader("Disposed Texture Default", [mainTexture], []);
        texture.Dispose();
        var bindings = new Dictionary<string, GraphicsTexture>();
        Rendering.PropertyState snapshot = PropertyStatePool.RentMaterialSnapshot(new Rendering.PropertyState(), shader);

        try
        {
            Exception? exception = Record.Exception(() =>
                Rendering.MaterialUniformPacking.ApplyTextureBindings(bindings, snapshot, shader));

            Assert.Null(exception);
            Assert.True(bindings.TryGetValue("_MainTex", out GraphicsTexture? fallback));
            Assert.False(fallback.IsDisposed);
        }
        finally
        {
            PropertyStatePool.Return(snapshot);
        }
    }

    [Fact]
    public void Factory_Creates_Null_And_OpenGL_Devices()
    {
        using IGraphicsDevice nullDevice = GraphicsDeviceFactory.Create(new GraphicsDeviceOptions
        {
            Backend = GraphicsBackend.Null,
        });
        Assert.Equal(GraphicsBackend.Null, nullDevice.Backend);
        nullDevice.Initialize(null);
        Assert.True(nullDevice.IsInitialized);
        nullDevice.BeginFrame();
        nullDevice.EndFrame();

        using IGraphicsDevice gl = GraphicsDeviceFactory.Create(new GraphicsDeviceOptions
        {
            Backend = GraphicsBackend.OpenGL,
        });
        Assert.Equal(GraphicsBackend.OpenGL, gl.Backend);
    }

