    [Fact]
    public void Graphics_CommonFacade_HasNoSilkOpenGLTypes()
    {
        AssertCommonWrapperHasNoSilkOpenGLTypes(typeof(global::XEngine.Runtime.Graphics));

        string graphicsRoot = Path.Combine(FindRepositoryRoot(), "XEngine.Runtime", "Graphics");
        string openGlRoot = Path.Combine(graphicsRoot, "Backends", "OpenGL") + Path.DirectorySeparatorChar;
        string webGl2Root = Path.Combine(graphicsRoot, "Backends", "WebGL2") + Path.DirectorySeparatorChar;

        foreach (string file in Directory.EnumerateFiles(graphicsRoot, "*.cs", SearchOption.AllDirectories))
        {
            string fullPath = Path.GetFullPath(file);
            if (fullPath.StartsWith(openGlRoot, StringComparison.OrdinalIgnoreCase))
                continue;
            // WebGL2 is a GL-family backend by design: it drives Silk.NET.OpenGL through the
            // emscripten getProcAddress bridge and reuses the OpenGL command executor.
            if (fullPath.StartsWith(webGl2Root, StringComparison.OrdinalIgnoreCase))
                continue;

            string source = File.ReadAllText(fullPath);
            Assert.DoesNotContain("Silk.NET.OpenGL", source, StringComparison.Ordinal);
            Assert.DoesNotContain("Graphics.GL", source, StringComparison.Ordinal);
        }
    }

    [Fact]
    public void ModernBackends_Map_Common_VertexFormats()
    {
        Assert.Equal(
            Silk.NET.Vulkan.Format.R32G32B32Sfloat,
            Backends.Vulkan.VulkanFormats.ToVertexFormat(VertexFormat.VertexType.Float, 3, normalized: false));
        Assert.Equal(
            Silk.NET.Vulkan.Format.R8G8B8A8Unorm,
            Backends.Vulkan.VulkanFormats.ToVertexFormat(VertexFormat.VertexType.UnsignedByte, 4, normalized: true));
        Assert.Equal(
            Vortice.DXGI.Format.R32G32B32_Float,
            Backends.D3D12.D3D12Formats.ToVertexFormat(VertexFormat.VertexType.Float, 3, normalized: false));
        Assert.Equal(
            Vortice.DXGI.Format.R8G8B8A8_UNorm,
            Backends.D3D12.D3D12Formats.ToVertexFormat(VertexFormat.VertexType.UnsignedByte, 4, normalized: true));
    }

    [Fact]
    public void GraphicsPipelineKey_Distinguishes_Exact_Pipeline_State()
    {
        var bytecode = new CompiledShaderBytecode(
            ShaderLanguage.Hlsl,
            ShaderBytecodeFormat.SpirV,
            [0x03, 0x02, 0x23, 0x07],
            [0x03, 0x02, 0x23, 0x07]);
        using var firstVariant = new ShaderVariant(bytecode);
        using var secondVariant = new ShaderVariant(bytecode);
        RasterizerState raster = new();

        var baseline = new GraphicsPipelineKey(firstVariant, 7, Topology.Triangles, in raster, index32Bit: false);
        var same = new GraphicsPipelineKey(firstVariant, 7, Topology.Triangles, in raster, index32Bit: false);
        Assert.Equal(baseline, same);
        Assert.Equal(baseline.GetHashCode(), same.GetHashCode());

        raster.DepthWrite = false;
        var differentRaster = new GraphicsPipelineKey(firstVariant, 7, Topology.Triangles, in raster, index32Bit: false);
        Assert.NotEqual(baseline, differentRaster);
        Assert.NotEqual(baseline, new GraphicsPipelineKey(secondVariant, 7, Topology.Triangles, in raster, index32Bit: false));
        Assert.NotEqual(differentRaster, new GraphicsPipelineKey(firstVariant, 8, Topology.Triangles, in raster, index32Bit: false));
        Assert.NotEqual(differentRaster, new GraphicsPipelineKey(firstVariant, 7, Topology.Lines, in raster, index32Bit: false));
        Assert.NotEqual(differentRaster, new GraphicsPipelineKey(firstVariant, 7, Topology.Triangles, in raster, index32Bit: true));
    }

    [Fact]
    public void ShaderDescriptorLayoutPlan_Assigns_CollisionFree_Physical_Bindings()
    {
        var layout = new ShaderBindingLayout
        {
            Buffers =
            [
                new ShaderBindingSlot(ShaderBindingKind.Buffer, 0, "GlobalUniforms"),
                new ShaderBindingSlot(ShaderBindingKind.Buffer, 2, "MaterialUniforms"),
            ],
            Textures =
            [
                new ShaderBindingSlot(ShaderBindingKind.Texture, 0, "MainTexture"),
                new ShaderBindingSlot(ShaderBindingKind.Texture, 3, "ShadowTexture"),
            ],
            Samplers =
            [
                new ShaderBindingSlot(ShaderBindingKind.Sampler, 0, "MainSampler"),
                new ShaderBindingSlot(ShaderBindingKind.Sampler, 3, "ShadowSampler"),
            ],
        };

        ShaderDescriptorLayoutPlan plan = ShaderDescriptorLayoutPlan.Create(layout);

        Assert.Equal(0, plan.BufferBindingBase);
        Assert.Equal(3, plan.TextureBindingBase);
        Assert.Equal(7, plan.SamplerBindingBase);
        int[] physicalBindings = Array.ConvertAll(plan.Bindings, binding => binding.PhysicalBinding);
        Assert.Collection(
            physicalBindings,
            binding => Assert.Equal(0, binding),
            binding => Assert.Equal(2, binding),
            binding => Assert.Equal(3, binding),
            binding => Assert.Equal(6, binding),
            binding => Assert.Equal(7, binding),
            binding => Assert.Equal(10, binding));
        Assert.Equal(plan.Bindings.Length, new System.Collections.Generic.HashSet<int>(physicalBindings).Count);
    }

    [Fact]
    public void ShaderDescriptorLayoutPlan_Uses_Explicit_Slang_Physical_Bindings()
    {
        var layout = new ShaderBindingLayout
        {
            Buffers = [new ShaderBindingSlot(ShaderBindingKind.Buffer, 2, "Globals", physicalBinding: 0, physicalSpace: 0)],
            Textures = [new ShaderBindingSlot(ShaderBindingKind.Texture, 3, "MainTexture", physicalBinding: 1, physicalSpace: 0)],
            Samplers = [new ShaderBindingSlot(ShaderBindingKind.Sampler, 4, "MainSampler", physicalBinding: 2, physicalSpace: 0)],
        };

        ShaderDescriptorLayoutPlan plan = ShaderDescriptorLayoutPlan.Create(layout);

        Assert.Collection(
            plan.Bindings,
            binding =>
            {
                Assert.Equal(0, binding.PhysicalBinding);
                Assert.Equal(0, binding.PhysicalGroup);
            },
            binding =>
            {
                Assert.Equal(1, binding.PhysicalBinding);
                Assert.Equal(0, binding.PhysicalGroup);
            },
            binding =>
            {
                Assert.Equal(2, binding.PhysicalBinding);
                Assert.Equal(0, binding.PhysicalGroup);
            });
        Assert.Equal(0, plan.GetPhysicalBinding(layout.Buffers[0]));
        Assert.Equal(0, plan.GetPhysicalGroup(layout.Buffers[0]));
        Assert.Equal(1, plan.GetPhysicalBinding(layout.Textures[0]));
        Assert.Equal(2, plan.GetPhysicalBinding(layout.Samplers[0]));
        Assert.Equal(0, Assert.Single(plan.BindGroups).Group);
    }

    [Fact]
    public void ShaderDescriptorLayoutPlan_Expands_Shared_Resources_To_Each_Physical_Binding()
    {
        var layout = new ShaderBindingLayout
        {
            Buffers =
            [
                new ShaderBindingSlot(
                    ShaderBindingKind.Buffer,
                    2,
                    "Globals",
                    stages: ShaderStageMask.Vertex | ShaderStageMask.Fragment,
                    physicalBindings:
                    [
                        new ShaderPhysicalBinding(0, 0, ShaderStageMask.Vertex),
                        new ShaderPhysicalBinding(1, 0, ShaderStageMask.Fragment),
                    ]),
            ],
            Textures = [new ShaderBindingSlot(ShaderBindingKind.Texture, 3, "MainTexture", physicalBinding: 2, physicalSpace: 0)],
            Samplers = [new ShaderBindingSlot(ShaderBindingKind.Sampler, 4, "MainSampler", physicalBinding: 3, physicalSpace: 0)],
        };

        ShaderDescriptorLayoutPlan plan = ShaderDescriptorLayoutPlan.Create(layout);

        Assert.Collection(
            plan.Bindings,
            binding =>
            {
                Assert.Equal("Globals", binding.Slot.Name);
                Assert.Equal(0, binding.PhysicalBinding);
            },
            binding =>
            {
                Assert.Equal("Globals", binding.Slot.Name);
                Assert.Equal(1, binding.PhysicalBinding);
            },
            binding => Assert.Equal(2, binding.PhysicalBinding),
            binding => Assert.Equal(3, binding.PhysicalBinding));
        Assert.Throws<InvalidOperationException>(() => plan.GetPhysicalBinding(layout.Buffers[0]));
    }

    [Fact]
    public void ShaderDescriptorLayoutPlan_Rejects_Partial_Or_Unsupported_Physical_Layouts()
    {
        var partial = new ShaderBindingLayout
        {
            Buffers = [new ShaderBindingSlot(ShaderBindingKind.Buffer, 0, "Globals", physicalBinding: 0, physicalSpace: 0)],
            Textures = [new ShaderBindingSlot(ShaderBindingKind.Texture, 0, "MainTexture")],
        };
        var nonzeroSet = new ShaderBindingLayout
        {
            Textures = [new ShaderBindingSlot(ShaderBindingKind.Texture, 0, "MainTexture", physicalBinding: 0, physicalSpace: 1)],
        };
        var collision = new ShaderBindingLayout
        {
            Buffers = [new ShaderBindingSlot(ShaderBindingKind.Buffer, 0, "Globals", physicalBinding: 0, physicalSpace: 0)],
            Textures = [new ShaderBindingSlot(ShaderBindingKind.Texture, 0, "MainTexture", physicalBinding: 0, physicalSpace: 0)],
        };

        Assert.Throws<InvalidOperationException>(() => ShaderDescriptorLayoutPlan.Create(partial));
        ShaderDescriptorLayoutPlan nonzeroPlan = ShaderDescriptorLayoutPlan.Create(nonzeroSet);
        Assert.Equal(1, Assert.Single(nonzeroPlan.Bindings).PhysicalGroup);
        Assert.Equal(1, Assert.Single(nonzeroPlan.BindGroups).Group);
        NotSupportedException unsupported = Assert.Throws<NotSupportedException>(() => nonzeroPlan.EnsureSingleBindGroup(0));
        Assert.Contains("descriptor set 1", unsupported.Message, StringComparison.OrdinalIgnoreCase);
        Assert.Throws<InvalidOperationException>(() => ShaderDescriptorLayoutPlan.Create(collision));
    }

    [Fact]
    public void ShaderDescriptorLayoutPlan_Groups_Physical_Bindings_By_Bind_Group()
    {
        var layout = new ShaderBindingLayout
        {
            Buffers = [new ShaderBindingSlot(ShaderBindingKind.Buffer, 0, "Globals", physicalBinding: 0, physicalSpace: 0)],
            Textures = [new ShaderBindingSlot(ShaderBindingKind.Texture, 0, "MainTexture", physicalBinding: 0, physicalSpace: 1)],
            Samplers = [new ShaderBindingSlot(ShaderBindingKind.Sampler, 1, "MainSampler", physicalBinding: 1, physicalSpace: 1)],
        };

        ShaderDescriptorLayoutPlan plan = ShaderDescriptorLayoutPlan.Create(layout);

        Assert.Equal(0, plan.GetPhysicalGroup(layout.Buffers[0]));
        Assert.Equal(1, plan.GetPhysicalGroup(layout.Textures[0]));
        Assert.Collection(
            plan.BindGroups,
            group =>
            {
                Assert.Equal(0, group.Group);
                Assert.Equal("Globals", Assert.Single(group.Bindings).Slot.Name);
            },
            group =>
            {
                Assert.Equal(1, group.Group);
                Assert.Collection(
                    group.Bindings,
                    binding => Assert.Equal("MainTexture", binding.Slot.Name),
                    binding => Assert.Equal("MainSampler", binding.Slot.Name));
            });
    }

    [Fact]
    public void Optional_D3D12_Device_Creates_Or_Skips()
    {
        if (!OperatingSystem.IsWindows())
        {
            Assert.ThrowsAny<Exception>(() =>
                GraphicsDeviceFactory.Create(new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 }));
            return;
        }

        try
        {
            using IGraphicsDevice device = GraphicsDeviceFactory.Create(new GraphicsDeviceOptions
            {
                Backend = GraphicsBackend.Direct3D12,
                Debug = false,
            });
            Assert.Equal(GraphicsBackend.Direct3D12, device.Backend);
            Assert.Contains("Direct3D", device.Capabilities.BackendName, StringComparison.OrdinalIgnoreCase);
        }
        catch (Exception ex)
        {
            Assert.True(
                IsExpectedGpuUnavailable(ex),
                $"Unexpected D3D12 failure type: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    [Fact]
    public void VulkanFormats_Preserves_Engine_Winding_For_Negative_Viewport()
    {
        Assert.Equal(Silk.NET.Vulkan.FrontFace.Clockwise,
            Backends.Vulkan.VulkanFormats.ToFrontFace(RasterizerState.WindingOrder.CW));
        Assert.Equal(Silk.NET.Vulkan.FrontFace.CounterClockwise,
            Backends.Vulkan.VulkanFormats.ToFrontFace(RasterizerState.WindingOrder.CCW));
    }

    [Fact]
    public void CommandBuffer_CarriesPresentationSurfaceTarget()
    {
        CommandBuffer cmd = global::XEngine.Runtime.Graphics.GetCommandBuffer("rhi-surface-target");
        PresentationSurfaceId surface = new(17);
        cmd.SetPresentationSurface(surface);

        Assert.Equal(surface, cmd.PresentationSurface);
        Assert.Throws<ArgumentException>(() => cmd.SetPresentationSurface(default));

        cmd._ownerReleased = true;
        CommandBufferPool.Return(cmd);

        CommandBuffer reused = global::XEngine.Runtime.Graphics.GetCommandBuffer("rhi-surface-target-reuse");
        Assert.False(reused.PresentationSurface.IsValid);
        reused._ownerReleased = true;
        CommandBufferPool.Return(reused);
    }

    [Fact]
    public void VulkanFormats_Reverses_Engine_Winding_For_Positive_Viewport()
    {
        Assert.Equal(Silk.NET.Vulkan.FrontFace.CounterClockwise,
            Backends.Vulkan.VulkanFormats.ToFrontFace(RasterizerState.WindingOrder.CW, usesPositiveViewportHeight: true));
        Assert.Equal(Silk.NET.Vulkan.FrontFace.Clockwise,
            Backends.Vulkan.VulkanFormats.ToFrontFace(RasterizerState.WindingOrder.CCW, usesPositiveViewportHeight: true));
    }

