    [Fact]
    public void GpuAvailability_Recognizes_Native_Loader_Failures()
    {
        Assert.True(IsExpectedGpuUnavailable(new DllNotFoundException("vulkan-1")));
        Assert.True(IsExpectedGpuUnavailable(new Exception("wrapper", new EntryPointNotFoundException("D3D12CreateDevice"))));
        Assert.True(IsExpectedGpuUnavailable(new BadImageFormatException("native architecture mismatch")));
    }

    [Theory]
    [InlineData("D3D12 PSO creation requires DXIL bytecode.")]
    [InlineData("Failed to compile the D3D12 framebuffer-blit shader: translator regression")]
    [InlineData("Vulkan draw requires texture '_MainTex'.")]
    [InlineData("Vulkan framebuffer blits currently support color-only or depth-only masks.")]
