    {
        Assert.False(IsExpectedGpuUnavailable(new InvalidOperationException(message)));
        Assert.False(IsExpectedGpuUnavailable(new NotSupportedException(message)));
    }

    [Fact]
    public void Optional_OpenGL_WindowSurface_Presents_And_Resizes_Or_Skip()
    {
        // macOS: GLFW/Cocoa window present from a non-main thread crashes the process natively
        // (SIGSEGV, not catchable) — same host limitation as the WebGL2 surface contracts.
        if (OperatingSystem.IsMacOS())
            return;

        try
        {
            using Silk.NET.Windowing.IWindow window = CreateModernBackendWindow(
                GraphicsBackend.OpenGL,
                "XEngine OpenGL Contract",
                320,
                180);
            var surface = new Backends.OpenGL.SilkWindowSurface(window);
            Assert.NotEqual(nint.Zero, surface.NativeHandle);

            using var device = new Backends.OpenGL.OpenGLGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.OpenGL, VSync = false });
            device.Initialize(surface);
            device.StartRenderThread(surface);
            PresentWindowFrame(device, new Color(0.08f, 0.35f, 0.24f, 1f));

            (int initialWidth, int initialHeight) = surface.FramebufferSize;
            window.Size = new Silk.NET.Maths.Vector2D<int>(400, 240);
            window.DoEvents();
            (int resizedWidth, int resizedHeight) = surface.FramebufferSize;
            Assert.True(resizedWidth != initialWidth || resizedHeight != initialHeight);
            PresentWindowFrame(device, new Color(0.08f, 0.35f, 0.24f, 1f));
            PauseForWindowCapture(window);
        }
        catch (Exception ex)
        {
