    [Fact]
    public void Optional_Vulkan_Dynamic_Buffer_Grows_On_Full_Update_Or_Skip()
    {
        try
        {
            using var device = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            device.Initialize(null);

            using var buffer = new GraphicsBuffer(BufferType.VertexBuffer, ReadOnlySpan<byte>.Empty, dynamic: true);
            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-dynamic-buffer-create"))
            {
                create.EncodeCreateBuffer(buffer, true, ReadOnlySpan<byte>.Empty);
                device.Execute(create, true);
            }

            uint engineHandle = buffer.Handle;
            Assert.Equal(1ul, device.Buffers[engineHandle].Size);

            byte[] firstFrameVertices = new byte[64 * 1024];
            firstFrameVertices.AsSpan().Fill(0x5A);
            using (CommandBuffer update = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-dynamic-buffer-grow"))
            {
                update.UpdateBuffer<byte>(buffer, firstFrameVertices);
                device.Execute(update, true);
            }

            Assert.Equal(engineHandle, buffer.Handle);
            Assert.Equal((uint)firstFrameVertices.Length, buffer.SizeInBytes);
            Assert.Equal((ulong)firstFrameVertices.Length, device.Buffers[engineHandle].Size);
        }
        catch (Exception ex)
        {
            Assert.True(
                IsExpectedGpuUnavailable(ex),
                $"Unexpected Vulkan dynamic-buffer failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

