    /// <summary>The GetTextureData / GetTextureDataPtr opcodes must round-trip through the D3D12
    /// translator — they were silently skipped once, which surfaced as runtime_screenshot
    /// returning an untouched (all-zero) capture buffer while Vulkan produced real pixels.</summary>
    [Fact]
    public void Optional_D3D12_Texture_Readback_RoundTrip_Or_Skip()
    {
        if (!OperatingSystem.IsWindows())
            return;

        try
        {
            using var device = new Backends.D3D12.D3D12GraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
            device.Initialize(null);

            // Upload round-trip: a 2x2 RGBA8 texture with distinct bytes per channel.
            byte[] uploaded = new byte[16];
            for (int i = 0; i < uploaded.Length; i++)
                uploaded[i] = (byte)(i + 1);
            using var texture = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-readback-create"))
            {
                create.EncodeCreateTexture(texture);
                create.EncodeAllocateTexture2D(texture, 0, 2, 2, 0, uploaded);
                device.Execute(create, true);
            }

            byte[] readIntoArray = new byte[16];
            using (CommandBuffer read = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-readback-array"))
            {
                read.EncodeGetTextureData(texture, 0, readIntoArray);
                device.Execute(read, true);
            }
            Assert.Equal(uploaded, readIntoArray);

            byte[] readViaPtr = new byte[16];
            using (CommandBuffer read = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-readback-ptr"))
            {
                unsafe
                {
                    fixed (byte* ptr = readViaPtr)
                    {
                        read.EncodeGetTextureDataPtr(texture, 0, (nint)ptr);
                        device.Execute(read, true);
                    }
                }
            }
            Assert.Equal(uploaded, readViaPtr);

            // Render-target round-trip: clear an offscreen attachment, then read it back the way
            // the editor's GameView capture does (render, then a standalone readback submission).
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }], 4, 4);
            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-readback-rt-create"))
            {
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 4, 4, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                device.Execute(create, true);
            }
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-readback-rt-clear"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 1f, 0f, 1f));
                device.Execute(draw, true);
            }
            byte[] cleared = new byte[4 * 4 * 4];
            using (CommandBuffer read = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-readback-rt"))
            {
                read.EncodeGetTextureData(color, 0, cleared);
                device.Execute(read, true);
            }
            for (int pixel = 0; pixel < 16; pixel++)
                Assert.True(PixelMatches(cleared, pixel, 0, 255, 0, 255), Convert.ToHexString(cleared));

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-readback-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
        }
        catch (Exception ex)
        {
            Assert.True(
                IsExpectedGpuUnavailable(ex),
                $"Unexpected D3D12 texture readback failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    [Fact]
    public void Optional_OpenGL_MultiplePresentationSurfaces_PresentResizeAndSurviveDestroy_Or_Skip()
    {
        // macOS: creating a second GLFW window that shares a GL context from a non-main thread
        // (the xunit worker) deadlocks Cocoa's window server — 100% CPU, never returns. The
        // multi-surface GL contract stays covered on Windows/Linux hosts.
        if (OperatingSystem.IsMacOS())
            return;

        try
        {
            using Silk.NET.Windowing.IWindow primaryWindow = CreateModernBackendWindow(
                GraphicsBackend.OpenGL,
                "XEngine OpenGL Primary Surface Contract",
                320,
                180);
            Silk.NET.Core.Contexts.IGLContext primaryContext = Assert.IsAssignableFrom<Silk.NET.Core.Contexts.IGLContext>(
                primaryWindow.GLContext);
            using Silk.NET.Windowing.IWindow secondaryWindow = CreateModernBackendWindow(
                GraphicsBackend.OpenGL,
                "XEngine OpenGL Secondary Surface Contract",
                240,
                160,
                primaryContext);
            var primarySurface = new Backends.OpenGL.SilkWindowSurface(primaryWindow) { VSync = false };
            var secondarySurface = new Backends.OpenGL.SilkWindowSurface(secondaryWindow) { VSync = false };

            using var device = new Backends.OpenGL.OpenGLGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.OpenGL, VSync = false });
            device.Initialize(primarySurface);
            device.StartRenderThread(primarySurface);
            Assert.True(device.TryGetPrimaryPresentationSurface(out PresentationSurfaceId primary));
            PresentationSurfaceId secondary = device.CreatePresentationSurface(secondarySurface);

            PresentOpenGLPresentationSurfaceFrame(device, primary, new Color(0.08f, 0.35f, 0.24f, 1f));
            PresentOpenGLPresentationSurfaceFrame(device, secondary, new Color(0.46f, 0.18f, 0.16f, 1f));

            device.BeginFrame();
            using (CommandBuffer primaryAfterSecondary = global::XEngine.Runtime.Graphics.GetCommandBuffer(
                       "opengl-primary-after-secondary"))
            {
                primaryAfterSecondary.SetRenderTarget(null);
                primaryAfterSecondary.ClearRenderTarget(ClearFlags.Color, new Color(0.14f, 0.22f, 0.4f, 1f));
                device.Execute(primaryAfterSecondary, wait: false);
            }
            device.EndFrame();

            secondaryWindow.Size = new Silk.NET.Maths.Vector2D<int>(400, 240);
            secondaryWindow.DoEvents();
            (int resizedWidth, int resizedHeight) = secondarySurface.FramebufferSize;
            Assert.True(device.ResizePresentationSurface(secondary, resizedWidth, resizedHeight));
            Assert.True(device.TryGetPresentationSurface(secondary, out PresentationSurfaceInfo secondaryInfo));
            Assert.Equal(resizedWidth, secondaryInfo.Width);
            Assert.Equal(resizedHeight, secondaryInfo.Height);
            PresentOpenGLPresentationSurfaceFrame(device, secondary, new Color(0.46f, 0.18f, 0.16f, 1f));

            Assert.True(device.DestroyPresentationSurface(primary));
            Assert.False(device.TryGetPrimaryPresentationSurface(out _));
            Assert.True(device.TryGetPresentationSurface(secondary, out _));
            PresentOpenGLPresentationSurfaceFrame(device, secondary, new Color(0.2f, 0.5f, 0.3f, 1f));
        }
        catch (Exception ex)
        {
            Assert.True(IsExpectedGpuUnavailable(ex),
                $"Unexpected OpenGL multi-surface presentation failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

