    [Fact]
    public void Optional_Vulkan_Dynamic_Buffer_Async_Draws_Preserve_Each_Submission_Or_Skip()
    {
        var compiler = new DxcShaderCompiler();
        ShaderCompileResult compiled = compiler.Compile(new ShaderCompileRequest
        {
            TargetBackend = GraphicsBackend.Vulkan,
            Language = ShaderLanguage.Hlsl,
            VertexSource = """
                struct VSInput { float2 position : POSITION; float4 color : COLOR; };
                struct VSOutput { float4 position : SV_Position; float4 color : COLOR; };
                VSOutput main(VSInput input) { VSOutput output; output.position = float4(input.position, 0, 1); output.color = input.color; return output; }
                """,
            FragmentSource = """
                struct PSInput { float4 position : SV_Position; float4 color : COLOR; };
                float4 main(PSInput input) : SV_Target { return input.color; }
                """,
        });
        if (!compiled.Success)
            return;

        try
        {
            using var device = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            device.Initialize(null);

            using var variant = new ShaderVariant(new CompiledShaderBytecode(
                ShaderLanguage.Hlsl,
                ShaderBytecodeFormat.SpirV,
                compiled.VertexBytecode!,
                compiled.FragmentBytecode!,
                compiled.BindingLayout,
                compiled.VertexInputLayout));
            byte[] vertices = new byte[3 * 12];
            WriteColorTriangle(vertices, 255, 0, 0);
            using var buffer = new GraphicsBuffer(BufferType.VertexBuffer, vertices, dynamic: true);
            var format = new VertexFormat(
            [
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.Color, VertexFormat.VertexType.UnsignedByte, 4, normalized: true),
            ]);
            using var vertexArray = new GraphicsVertexArray(format, buffer, null);

            const int frameCount = 8;
            var colors = new GraphicsTexture[frameCount];
            var framebuffers = new GraphicsFrameBuffer[frameCount];
            for (int frame = 0; frame < frameCount; frame++)
            {
                colors[frame] = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
                framebuffers[frame] = GraphicsFrameBuffer.CreateDeferred(
                    [new GraphicsFrameBuffer.Attachment { Texture = colors[frame] }],
                    1,
                    1);
            }

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-dynamic-buffer-async-create"))
            {
                create.EncodeCreateBuffer(buffer, true, vertices);
                for (int frame = 0; frame < frameCount; frame++)
                {
                    create.EncodeCreateTexture(colors[frame]);
                    create.EncodeAllocateTexture2D(colors[frame], 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
                    create.EncodeCreateFramebuffer(framebuffers[frame]);
                }
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, true);
            }

            RasterizerState raster = new()
            {
                DepthTest = false,
                DepthWrite = false,
                CullFace = RasterizerState.PolyFace.None,
            };
            for (int frame = 0; frame < frameCount; frame++)
            {
                byte red = (byte)(frame * 31);
                byte green = (byte)(255 - frame * 31);
                WriteColorTriangle(vertices, red, green, 0);
                using CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-dynamic-buffer-async-draw");
                // The first upload is the regular UI-style transfer recorded before a draw.
                draw.UpdateBuffer<byte>(buffer, vertices);
                draw.SetRenderTarget(framebuffers[frame]);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
                draw.SetViewport(0, 0, 1, 1);
                draw.DisableScissor();
                draw.SetRasterState(in raster);
                draw.SetShader(variant);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);

                // The second upload runs while the prior draw's render pass is active, matching
                // consecutive instanced batches. It must rename storage rather than mutate data
                // still referenced by the first draw.
                WriteColorTriangle(vertices, green, red, 0);
                draw.UpdateBuffer<byte>(buffer, vertices);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, wait: false);
            }

            device.WaitIdle();
            for (int frame = 0; frame < frameCount; frame++)
            {
                byte[] pixels = device.ReadTexture2D(device.Images[colors[frame].Handle], 4);
                AssertMaterialPixel(pixels, 0, (255f - frame * 31f) / 255f, frame * 31f / 255f, 0f, 1f);
            }

            using (CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-dynamic-buffer-async-dispose"))
            {
                for (int frame = 0; frame < frameCount; frame++)
                    dispose.EncodeDisposeFramebuffer(framebuffers[frame]);
                device.Execute(dispose, true);
            }

            for (int frame = 0; frame < frameCount; frame++)
                colors[frame].Dispose();
        }
        catch (Exception ex)
        {
            Assert.True(
                IsExpectedGpuUnavailable(ex),
                $"Unexpected Vulkan async dynamic-buffer draw failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    [Fact]
    public void Optional_Vulkan_Viewport_Uses_Top_Left_Origin_Or_Skip()
    {
        var compiler = new DxcShaderCompiler();
        ShaderCompileResult compiled = compiler.Compile(new ShaderCompileRequest
        {
            TargetBackend = GraphicsBackend.Vulkan,
            Language = ShaderLanguage.Hlsl,
            VertexSource = "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }",
            FragmentSource = "float4 main() : SV_Target { return float4(1, 0, 0, 1); }",
        });
        if (!compiled.Success)
            return;

        try
        {
            using var device = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            device.Initialize(null);
            using var variant = new ShaderVariant(new CompiledShaderBytecode(
                ShaderLanguage.Hlsl,
                ShaderBytecodeFormat.SpirV,
                compiled.VertexBytecode!,
                compiled.FragmentBytecode!,
                compiled.BindingLayout));
            float[] vertices =
            [
                -1f, 0f, 0f,
                 1f, 0f, 0f,
                -1f, 1f, 0f,
                -1f, 1f, 0f,
                 1f, 0f, 0f,
                 1f, 1f, 0f,
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }],
                1,
                2);
            var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
            using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-top-left-viewport-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 1, 2, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, wait: true);
            }

            RasterizerState raster = new()
            {
                DepthTest = false,
                DepthWrite = false,
                CullFace = RasterizerState.PolyFace.None,
            };
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-top-left-viewport-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
                draw.SetViewport(0, 0, 1, 2);
                draw.DisableScissor();
                draw.SetRasterState(in raster);
                draw.SetShader(variant);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 6);
                device.Execute(draw, wait: true);
            }

            byte[] pixels = device.ReadTexture2D(device.Images[color.Handle], 4);
            AssertMaterialPixel(pixels, 0, 1f, 0f, 0f, 1f);
            AssertMaterialPixel(pixels, 1, 0f, 0f, 0f, 1f);

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-top-left-viewport-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, wait: true);
        }
        catch (Exception ex)
        {
            Assert.True(
                IsExpectedGpuUnavailable(ex),
                $"Unexpected Vulkan viewport-origin failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    [Fact]
    public void Optional_Vulkan_Paper_Font_Atlas_Update_Renders_Or_Skip()
    {
        Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.UI);
        Rendering.Shaders.ShaderPass pass = shader.GetPass(0);
        string vertexSource = (string)typeof(Rendering.Shaders.ShaderPass)
            .GetField("_hlslVertexSource", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(pass)!;
        string fragmentSource = (string)typeof(Rendering.Shaders.ShaderPass)
            .GetField("_hlslFragmentSource", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(pass)!;
        ShaderCompileResult compiled = new RuntimeSlangShaderCompiler().Compile(new ShaderCompileRequest
        {
            TargetBackend = GraphicsBackend.Vulkan,
            Language = ShaderLanguage.Hlsl,
            VertexSource = vertexSource,
            FragmentSource = fragmentSource,
            ShaderName = shader.Name,
            PassName = pass.Name,
        });
        Assert.True(compiled.Success, compiled.ErrorMessage);

        try
        {
            using var device = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            device.Initialize(null);
            using var variant = CreateMaterialContractVariant(compiled, ShaderBytecodeFormat.SpirV);
            byte[] vertexBytes = new byte[3 * 24];
            WritePaperVertex(vertexBytes.AsSpan(0, 24), -1f, -1f, 2.75f, 2.75f);
            WritePaperVertex(vertexBytes.AsSpan(24, 24), -1f, 3f, 2.75f, 2.75f);
            WritePaperVertex(vertexBytes.AsSpan(48, 24), 3f, -1f, 2.75f, 2.75f);
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
            byte[] brushRecordBytes = CreateIdentityUiBrushRecord();
            using var brushBuffer = new GraphicsBuffer(BufferType.UniformBuffer, brushRecordBytes, dynamic: true);
            using var fontTexture = new Resources.Texture2D();
            using var defaultTexture = new Resources.Texture2D();
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }],
                1,
                1);
            var format = new VertexFormat(
            [
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.Color, VertexFormat.VertexType.UnsignedByte, 4, normalized: true),
                new(VertexFormat.VertexSemantic.TexCoord1, VertexFormat.VertexType.Float, 1),
            ]);
            using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-paper-font-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                create.EncodeCreateBuffer(brushBuffer, true, brushRecordBytes);
                create.EncodeCreateTexture(fontTexture.Handle);
                create.EncodeAllocateTexture2D(fontTexture.Handle, 0, 2, 2, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeUpdateTexture2D(fontTexture.Handle, 0, 1, 1, 1, 1, new byte[] { 255, 255, 255, 255 });
                create.EncodeSetTextureFilters(fontTexture.Handle, TextureMin.Nearest, TextureMag.Nearest);
                EncodeContractTexture(create, defaultTexture, new byte[] { 255, 255, 255, 255 });
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, true);
            }

            RasterizerState raster = new()
            {
                DepthTest = false,
                DepthWrite = false,
                CullFace = RasterizerState.PolyFace.None,
            };
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-paper-font-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
                draw.SetViewport(0, 0, 1, 1);
                draw.DisableScissor();
                draw.SetRasterState(in raster);
                draw.SetShader(variant);
                Float4x4 identity = Float4x4.Identity;
                draw.SetMatrix("projection", in identity);
                draw.SetFloat("dpiScale", 1f);
                draw.SetVector("viewportSize", new Float2(1f));
                draw.SetFloat("backdropBlurAmount", 0f);
                draw.SetInt("backdropFlipY", 0);
                draw.SetBuffer("UiBrushes", brushBuffer, 2);
                draw.SetTexture("texture0", defaultTexture);
                draw.SetTexture("fontTexture", fontTexture);
                draw.SetTexture("backdropTexture", defaultTexture);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, true);
            }

            AssertMaterialPixel(device.ReadTexture2D(device.Images[color.Handle], 4), 0, 1f, 1f, 1f, 1f);
            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-paper-font-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
        }
        catch (Exception ex)
        {
            Assert.True(
                IsExpectedGpuUnavailable(ex),
                $"Unexpected Vulkan Paper font rendering failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    // --- Crash-hardening regression (2026-08-25): missing bindings must degrade, not terminate ---
    //
    // A shader declaring a sampler and a material cbuffer that the draw NEVER binds. Before the
    // hardening this threw on the render thread ("draw requires texture / uniform buffer"), the
    // pending error rethrew on the next main-thread Submit, and the crash handler killed the whole
    // editor. Now the texture falls back to the pre-warmed white pixel and the cbuffer binds a
    // zeroed transient, so the pixel reads white (1 * white + zero tint) and the draw survives.

    private const string MissingBindingVertexSource =
        "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";

    private const string MissingBindingFragmentSource = """
Texture2D _NeverBoundTex : register(t0);
SamplerState _NeverBoundTexSampler : register(s0);
cbuffer NeverBoundMaterial : register(b2)
{
    float4 _Tint;
};
float4 main() : SV_Target
{
    return _NeverBoundTex.Sample(_NeverBoundTexSampler, float2(0.5f, 0.5f)) + _Tint;
}
""";

    [Theory]
    [InlineData(GraphicsBackend.Vulkan)]
    [InlineData(GraphicsBackend.Direct3D12)]
    public void Optional_ModernBackends_MissingBindings_Degrade_Instead_Of_Crash_Or_Skip(GraphicsBackend backend)
    {
        // DXIL emission needs the DXC downstream compiler (Windows-only vendor); degrade before
        // compiling so non-Windows hosts skip instead of failing on E00100.
        if (backend == GraphicsBackend.Direct3D12 && !OperatingSystem.IsWindows())
            return;

        ShaderCompileResult compiled = new RuntimeSlangShaderCompiler().Compile(new ShaderCompileRequest
        {
            TargetBackend = backend,
            Language = ShaderLanguage.Hlsl,
            VertexSource = MissingBindingVertexSource,
            FragmentSource = MissingBindingFragmentSource,
            VertexEntryPoint = "main",
            FragmentEntryPoint = "main",
        });
        if (IsSpirvUnavailable(backend, compiled))
            return;
        Assert.True(compiled.Success, compiled.ErrorMessage);

        byte[]? pixels = backend == GraphicsBackend.Direct3D12
            ? TryRenderMissingBindingDraw(GraphicsBackend.Direct3D12)
            : TryRenderMissingBindingDraw(GraphicsBackend.Vulkan);
        if (pixels == null)
            return;

        // White sample + zeroed tint → pure white. Any exception along the way fails the test;
        // before the hardening the draw itself crashed the process.
        AssertMaterialPixel(pixels, 0, 1f, 1f, 1f, 1f);
    }

    private static byte[]? TryRenderMissingBindingDraw(GraphicsBackend backend)
    {
        try
        {
            float[] vertices = [-1f, -1f, 0f, 3f, -1f, 0f, -1f, 3f, 0f];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());

            if (backend == GraphicsBackend.Direct3D12)
            {
                if (!OperatingSystem.IsWindows())
                    return null;
                using var device = new Backends.D3D12.D3D12GraphicsDevice(
                    new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
                device.Initialize(null);
                return DrawMissingBindingFullscreenTriangle(
                    device,
                    ShaderBytecodeFormat.Dxil,
                    vertexBytes,
                    texture => device.ReadTexture2D(
                        device.Textures[texture.Handle].Resource!, 1, 1, 4, device.Textures[texture.Handle].State));
            }

            using var vkDevice = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            vkDevice.Initialize(null);
            return DrawMissingBindingFullscreenTriangle(
                vkDevice,
                ShaderBytecodeFormat.SpirV,
                vertexBytes,
                texture => vkDevice.ReadTexture2D(vkDevice.Images[texture.Handle], 4));
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            return null;
        }
    }

    private static byte[] DrawMissingBindingFullscreenTriangle(
        IGraphicsDevice device,
        ShaderBytecodeFormat bytecodeFormat,
        ReadOnlySpan<byte> vertexBytes,
        Func<GraphicsTexture, byte[]> readback)
    {
        ShaderCompileResult compiled = new RuntimeSlangShaderCompiler().Compile(new ShaderCompileRequest
        {
            TargetBackend = device.Backend,
            Language = ShaderLanguage.Hlsl,
            VertexSource = MissingBindingVertexSource,
            FragmentSource = MissingBindingFragmentSource,
            VertexEntryPoint = "main",
            FragmentEntryPoint = "main",
        });
        Assert.True(compiled.Success, compiled.ErrorMessage);
        using var variant = new ShaderVariant(new CompiledShaderBytecode(
            ShaderLanguage.Hlsl,
            bytecodeFormat,
            compiled.VertexBytecode!,
            compiled.FragmentBytecode!,
            compiled.BindingLayout));

        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes.ToArray(), dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
            [new GraphicsFrameBuffer.Attachment { Texture = color }],
            1,
            1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("missing-binding-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, wait: true);
        }

        RasterizerState raster = new()
        {
            DepthTest = false,
            DepthWrite = false,
            CullFace = RasterizerState.PolyFace.None,
        };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("missing-binding-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
            draw.SetViewport(0, 0, 1, 1);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            draw.SetShader(variant);
            // Deliberately NO SetTexture for _NeverBoundTex and NO binding for NeverBoundMaterial:
            // the draw must degrade (white texture + zeroed cbuffer), not throw.
            draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
            device.Execute(draw, wait: true);
        }

        byte[] pixels = readback(color);
        using (CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("missing-binding-dispose"))
        {
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, wait: true);
        }
        return pixels;
    }

    [Fact]
    public void Optional_Vulkan_Swapchain_Content_Survives_RenderTarget_RoundTrip_Or_Skip()
    {
        // macOS: GLFW/Cocoa window creation from a non-main thread crashes the test host
        // natively (same host limitation as the OpenGL surface contracts above).
        if (OperatingSystem.IsMacOS())
            return;

        try
        {
            using Silk.NET.Windowing.IWindow window = CreateModernBackendWindow(
                GraphicsBackend.Vulkan,
                "XEngine Vulkan Render Target Round Trip",
                64,
                32);
            var surface = new Backends.OpenGL.SilkWindowSurface(window);
            using var device = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan, VSync = false });
            device.Initialize(surface);
            ShaderCompileResult compiled = new RuntimeSlangShaderCompiler().Compile(new ShaderCompileRequest
            {
                TargetBackend = GraphicsBackend.Vulkan,
                Language = ShaderLanguage.Hlsl,
                VertexSource = "struct VSInput { float2 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 0, 1); }",
                FragmentSource = "float4 main() : SV_Target { return float4(0, 0, 1, 1); }",
            });
            Assert.True(compiled.Success, compiled.ErrorMessage);
            using var variant = CreateMaterialContractVariant(compiled, ShaderBytecodeFormat.SpirV);
            float[] vertices = [-1f, -1f, -1f, 3f, 3f, -1f];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
            using var vertexArray = new GraphicsVertexArray(
                new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 2)]),
                vertexBuffer,
                null);
            (int width, int height) = surface.FramebufferSize;
            using var scratch = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var capture = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer scratchFramebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = scratch }], (uint)width, (uint)height);
            GraphicsFrameBuffer captureFramebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = capture }], (uint)width, (uint)height);
            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-swapchain-round-trip-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                create.EncodeCreateVertexArray(vertexArray);
                create.EncodeCreateTexture(scratch);
                create.EncodeAllocateTexture2D(scratch, 0, (uint)width, (uint)height, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(capture);
                create.EncodeAllocateTexture2D(capture, 0, (uint)width, (uint)height, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(scratchFramebuffer);
                create.EncodeCreateFramebuffer(captureFramebuffer);
                device.Execute(create, true);
            }

            RasterizerState raster = new()
            {
                DepthTest = false,
                DepthWrite = false,
                CullFace = RasterizerState.PolyFace.None,
            };
            device.BeginFrame();
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-swapchain-round-trip-draw"))
            {
                draw.SetRenderTarget(null);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(1f, 0f, 0f, 1f));
                draw.SetRenderTarget(scratchFramebuffer);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 1f, 0f, 1f));
                draw.SetRenderTarget(null);
                draw.SetViewport(0, 0, (uint)(width / 2), (uint)height);
                draw.DisableScissor();
                draw.SetRasterState(in raster);
                draw.SetShader(variant);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                draw.SetRenderTargets(captureFramebuffer, null);
                draw.BlitFramebuffer(0, 0, width, height, 0, 0, width, height, ClearFlags.Color, BlitFilter.Nearest);
                device.Execute(draw, true);
            }
            device.EndFrame();

            byte[] pixels = device.ReadTexture2D(device.Images[capture.Handle], 4);
            int middleY = height / 2;
            Assert.True(PixelMatches(pixels, middleY * width + width / 4, 0, 0, 255, 255), Convert.ToHexString(pixels));
            Assert.True(PixelMatches(pixels, middleY * width + width * 3 / 4, 255, 0, 0, 255), Convert.ToHexString(pixels));
            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-swapchain-round-trip-dispose");
            dispose.EncodeDisposeFramebuffer(scratchFramebuffer);
            dispose.EncodeDisposeFramebuffer(captureFramebuffer);
            device.Execute(dispose, true);
        }
        catch (Exception ex)
        {
            Assert.True(
                IsExpectedGpuUnavailable(ex),
                $"Unexpected Vulkan swapchain round-trip failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    [Fact]
    public void Optional_D3D12_ShaderLayout_Creates_Or_Skips()
    {
        if (!OperatingSystem.IsWindows())
            return;

        try
        {
            using var device = new Backends.D3D12.D3D12GraphicsDevice(new GraphicsDeviceOptions
            {
                Backend = GraphicsBackend.Direct3D12,
                Debug = false,
            });
            device.Initialize(null);
            var bytecode = new CompiledShaderBytecode(
                ShaderLanguage.Hlsl,
                ShaderBytecodeFormat.Dxil,
                [0x44, 0x58, 0x42, 0x43],
                [0x44, 0x58, 0x42, 0x43],
                new ShaderBindingLayout
                {
                    Buffers = [new ShaderBindingSlot(ShaderBindingKind.Buffer, 0, "GlobalUniforms")],
                    Textures = [new ShaderBindingSlot(ShaderBindingKind.Texture, 0, "MainTexture")],
                    Samplers = [new ShaderBindingSlot(ShaderBindingKind.Sampler, 0, "MainSampler")],
                });
            using var variant = new ShaderVariant(bytecode);

            Backends.D3D12.D3D12ShaderLayoutResource first = device.GetOrCreateShaderLayout(variant);
            Backends.D3D12.D3D12ShaderLayoutResource second = device.GetOrCreateShaderLayout(variant);

            Assert.Same(first, second);
            Assert.NotEqual(nint.Zero, first.RootSignature.NativePointer);
        }
        catch (Exception ex)
        {
            Assert.True(
                IsExpectedGpuUnavailable(ex),
                $"Unexpected D3D12 layout failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    [Fact]
    public void Optional_D3D12_GlobalUniforms_AutoBind_Or_Skip()
    {
        if (!OperatingSystem.IsWindows())
            return;

        var compiler = new DxcShaderCompiler();
        ShaderCompileResult compiled = compiler.Compile(new ShaderCompileRequest
        {
            TargetBackend = GraphicsBackend.Direct3D12,
            Language = ShaderLanguage.Hlsl,
            VertexSource = "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }",
            FragmentSource = "cbuffer GlobalUniforms : register(b0) { float4 Tint; }; float4 main() : SV_Target { return Tint; }",
        });
        if (!compiled.Success)
            return;

        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            using var device = new Backends.D3D12.D3D12GraphicsDevice(new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
            device.Initialize(null);
            using var variant = new ShaderVariant(new CompiledShaderBytecode(ShaderLanguage.Hlsl, ShaderBytecodeFormat.Dxil, compiled.VertexBytecode!, compiled.FragmentBytecode!, compiled.BindingLayout));
            float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
            Float4 tint = new(0.25f, 0.5f, 0.75f, 1f);
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            ReadOnlySpan<byte> uniformBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(System.Runtime.InteropServices.MemoryMarshal.CreateReadOnlySpan(ref tint, 1));
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
            using var uniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, uniformBytes, dynamic: true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }],
                1,
                1);
            var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
            using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-global-uniform-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
                create.EncodeCreateBuffer(uniformBuffer, dynamic: true, uniformBytes);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, wait: true);
            }
            SetGlobalUniformBuffer(uniformBuffer);

            RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-global-uniform-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.SetViewport(0, 0, 1, 1);
                draw.DisableScissor();
                draw.SetShader(variant);
                draw.SetRasterState(in raster);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, wait: true);
            }

            byte[] readback = device.ReadTexture2D(device.Textures[color.Handle].Resource!, 1, 1, 4, device.Textures[color.Handle].State);
            Assert.InRange(readback[0], (byte)63, (byte)64);
            Assert.InRange(readback[1], (byte)127, (byte)128);
            Assert.InRange(readback[2], (byte)191, (byte)192);
            Assert.Equal((byte)255, readback[3]);

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-global-uniform-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, wait: true);
        }
        catch (Exception ex)
        {
            Assert.True(IsExpectedGpuUnavailable(ex), $"Unexpected D3D12 global-uniform auto-bind failure: {ex.GetType().FullName}: {ex.Message}");
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
        }
    }

    // ─────────────────────── P3.3 true MSAA ───────────────────────

    private const int MsaaContractSize = 16;

    /// <summary>
    /// Triangle whose hypotenuse cuts the target diagonally, so roughly a sixteenth of the pixels
    /// straddle the edge and pick up partial coverage under MSAA.
    /// </summary>
    private static readonly float[] s_msaaContractTriangle =
    [
        -1f, -1f, 0f,
         1f, -1f, 0f,
        -1f,  1f, 0f,
    ];

    /// <summary>
    /// The MSAA acceptance criterion, shared by the D3D12 and Vulkan contract tests: a resolved
    /// multisample render is strictly better on the edge and bit-identical in the interior.
    /// <list type="bullet">
    /// <item>Single-sample rasterization is binary — every pixel is fully background or fully
    /// foreground, so the baseline must contain zero intermediate values.</item>
    /// <item>The 4× resolve averages coverage, so the edge must produce intermediate values.</item>
    /// <item>Pixels whose 4-neighbourhood is uniform in the baseline are genuinely interior (or
    /// genuinely outside) and must come back identical — MSAA must not disturb them.</item>
    /// </list>
    /// </summary>
    private static void AssertMsaaResolveBeatsSingleSample(byte[] baseline, byte[] resolved, int width, int height)
    {
        Assert.Equal(baseline.Length, resolved.Length);

        static bool IsIntermediate(byte value) => value is > 8 and < 247;

        int baselineIntermediate = 0;
        int resolvedIntermediate = 0;
        int interiorChecked = 0;
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                int i = (y * width + x) * 4;
                if (IsIntermediate(baseline[i]))
                    baselineIntermediate++;
                if (IsIntermediate(resolved[i]))
                    resolvedIntermediate++;

                if (x == 0 || y == 0 || x == width - 1 || y == height - 1)
                    continue;
                byte center = baseline[i];
                bool uniform =
                    baseline[i - 4] == center &&
                    baseline[i + 4] == center &&
                    baseline[i - width * 4] == center &&
                    baseline[i + width * 4] == center;
                if (!uniform)
                    continue;
                interiorChecked++;
                Assert.True(
                    resolved[i] == center,
                    $"MSAA resolve changed interior pixel ({x},{y}): baseline {center}, resolved {resolved[i]}.");
            }
        }

        Assert.True(interiorChecked > 0, "Test geometry produced no strictly interior pixels to compare.");
        Assert.True(
            baselineIntermediate == 0,
            $"Single-sample rasterization should be binary but produced {baselineIntermediate} intermediate pixels.");
        Assert.True(
            resolvedIntermediate > 0,
            "4x MSAA resolve produced no partially covered edge pixels — the multisample path is not actually multisampling.");
    }

    [Fact]
    public void Optional_D3D12_Msaa4_Resolve_ImprovesEdgeCoverage_Or_Skip()
    {
        if (!OperatingSystem.IsWindows())
            return;

        var compiler = new DxcShaderCompiler();
        ShaderCompileResult compiled = compiler.Compile(new ShaderCompileRequest
        {
            TargetBackend = GraphicsBackend.Direct3D12,
            Language = ShaderLanguage.Hlsl,
            VertexSource = "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }",
            FragmentSource = "float4 main() : SV_Target { return float4(1, 1, 1, 1); }",
        });
        if (!compiled.Success)
            return;

        try
        {
            using var device = new Backends.D3D12.D3D12GraphicsDevice(new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
            device.Initialize(null);

            int maxSamples = device.Capabilities.MaxSampleCount;
            Assert.True(maxSamples >= 4, $"D3D12 must report at least 4x MSAA support, reported {maxSamples}x.");

            using var variant = new ShaderVariant(new CompiledShaderBytecode(
                ShaderLanguage.Hlsl, ShaderBytecodeFormat.Dxil, compiled.VertexBytecode!, compiled.FragmentBytecode!, compiled.BindingLayout));
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(s_msaaContractTriangle.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
            var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
            using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

            const uint size = MsaaContractSize;
            using var baselineColor = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var msaaColor = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b, 4);
            using var resolveColor = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer baselineFb = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = baselineColor }], size, size);
            GraphicsFrameBuffer msaaFb = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = msaaColor }], size, size);
            Assert.Equal(4u, msaaFb.SampleCount);
            Assert.Equal(1u, baselineFb.SampleCount);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-msaa-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
                create.EncodeCreateVertexArray(vertexArray);
                create.EncodeCreateTexture(baselineColor);
                create.EncodeAllocateTexture2D(baselineColor, 0, size, size, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(msaaColor);
                create.EncodeAllocateTexture2D(msaaColor, 0, size, size, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(resolveColor);
                create.EncodeAllocateTexture2D(resolveColor, 0, size, size, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(baselineFb);
                create.EncodeCreateFramebuffer(msaaFb);
                device.Execute(create, wait: true);
            }
            Assert.Equal(4u, device.Textures[msaaColor.Handle].SampleCount);

            RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-msaa-draw"))
            {
                draw.SetRenderTarget(baselineFb);
                draw.SetViewport(0, 0, size, size);
                draw.DisableScissor();
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
                draw.SetRasterState(in raster);
                draw.SetShader(variant);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);

                draw.SetRenderTarget(msaaFb);
                draw.SetViewport(0, 0, size, size);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
                draw.SetRasterState(in raster);
                draw.SetShader(variant);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, wait: true);
            }

            using (CommandBuffer resolve = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-msaa-resolve"))
            {
                resolve.EncodeResolveTexture(msaaColor, resolveColor);
                device.Execute(resolve, wait: true);
            }

            byte[] baselinePixels = device.ReadTexture2D(
                device.Textures[baselineColor.Handle].Resource!, size, size, 4, device.Textures[baselineColor.Handle].State);
            byte[] resolvedPixels = device.ReadTexture2D(
                device.Textures[resolveColor.Handle].Resource!, size, size, 4, device.Textures[resolveColor.Handle].State);
            AssertMsaaResolveBeatsSingleSample(baselinePixels, resolvedPixels, (int)size, (int)size);

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-msaa-dispose");
            dispose.EncodeDisposeFramebuffer(baselineFb);
            dispose.EncodeDisposeFramebuffer(msaaFb);
            device.Execute(dispose, wait: true);
        }
        catch (Exception ex)
        {
            Assert.True(IsExpectedGpuUnavailable(ex), $"Unexpected D3D12 MSAA resolve failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    [Fact]
    public void Optional_Vulkan_Msaa4_Resolve_ImprovesEdgeCoverage_Or_Skip()
    {
        ShaderCompileResult compiled = new RuntimeSlangShaderCompiler().Compile(new ShaderCompileRequest
        {
            TargetBackend = GraphicsBackend.Vulkan,
            Language = ShaderLanguage.Hlsl,
            VertexSource = "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }",
            FragmentSource = "float4 main() : SV_Target { return float4(1, 1, 1, 1); }",
        });
        if (!compiled.Success)
            return;

        try
        {
            using var device = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            device.Initialize(null);

            int maxSamples = device.Capabilities.MaxSampleCount;
            Assert.True(maxSamples >= 4, $"Vulkan must report at least 4x MSAA support, reported {maxSamples}x.");

            using var variant = CreateMaterialContractVariant(compiled, ShaderBytecodeFormat.SpirV);
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(s_msaaContractTriangle.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
            var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
            using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

            const uint size = MsaaContractSize;
            using var baselineColor = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var msaaColor = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b, 4);
            using var resolveColor = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer baselineFb = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = baselineColor }], size, size);
            GraphicsFrameBuffer msaaFb = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = msaaColor }], size, size);
            Assert.Equal(4u, msaaFb.SampleCount);
            Assert.Equal(1u, baselineFb.SampleCount);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-msaa-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
                create.EncodeCreateVertexArray(vertexArray);
                create.EncodeCreateTexture(baselineColor);
                create.EncodeAllocateTexture2D(baselineColor, 0, size, size, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(msaaColor);
                create.EncodeAllocateTexture2D(msaaColor, 0, size, size, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(resolveColor);
                create.EncodeAllocateTexture2D(resolveColor, 0, size, size, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(baselineFb);
                create.EncodeCreateFramebuffer(msaaFb);
                device.Execute(create, wait: true);
            }
            Assert.Equal(4u, device.Images[msaaColor.Handle].SampleCount);

            RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-msaa-draw"))
            {
                draw.SetRenderTarget(baselineFb);
                draw.SetViewport(0, 0, size, size);
                draw.DisableScissor();
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
                draw.SetRasterState(in raster);
                draw.SetShader(variant);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);

                draw.SetRenderTarget(msaaFb);
                draw.SetViewport(0, 0, size, size);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
                draw.SetRasterState(in raster);
                draw.SetShader(variant);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, wait: true);
            }

            using (CommandBuffer resolve = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-msaa-resolve"))
            {
                resolve.EncodeResolveTexture(msaaColor, resolveColor);
                device.Execute(resolve, wait: true);
            }

            byte[] baselinePixels = device.ReadTexture2D(device.Images[baselineColor.Handle], 4);
            byte[] resolvedPixels = device.ReadTexture2D(device.Images[resolveColor.Handle], 4);
            AssertMsaaResolveBeatsSingleSample(baselinePixels, resolvedPixels, (int)size, (int)size);

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("vulkan-msaa-dispose");
            dispose.EncodeDisposeFramebuffer(baselineFb);
            dispose.EncodeDisposeFramebuffer(msaaFb);
            device.Execute(dispose, wait: true);
        }
        catch (Exception ex)
        {
            Assert.True(IsExpectedGpuUnavailable(ex), $"Unexpected Vulkan MSAA resolve failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    /// <summary>
    /// Cost A/B for the P3.3 change, measured headless so no vsync or editor UI is in the way:
    /// the removed 2× SSAA stand-in (render at 2× then downsample-blit) versus real 4× MSAA
    /// (render at native into a multisample target then resolve). Both produce the same
    /// <c>Size</c>×<c>Size</c> single-sample image from the same geometry and the same fragment
    /// shader, so the only difference is how many times that shader runs: SSAA shades every one
    /// of 4× the pixels, MSAA shades once per pixel and only multi-samples coverage.
    /// <para>Numbers are printed for the benchmark write-up; the assertion is just the direction.</para>
    /// </summary>
    [Fact]
    public void Optional_Vulkan_Msaa_Is_Cheaper_Than_SsaaStandIn_Or_Skip()
    {
        const int Size = 1024;              // final image size for both paths
        const int Overdraw = 96;            // fullscreen triangles per frame
        const int Warmup = 4;
        const int Iterations = 16;

        ShaderCompileResult compiled = new RuntimeSlangShaderCompiler().Compile(new ShaderCompileRequest
        {
            TargetBackend = GraphicsBackend.Vulkan,
            Language = ShaderLanguage.Hlsl,
            VertexSource = "struct VSInput { float2 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 0, 1); }",
            // A deliberately non-trivial fragment shader: the whole point of MSAA over SSAA is
            // that this body runs once per pixel instead of once per sub-sample.
            FragmentSource =
                "float4 main(float4 pos : SV_Position) : SV_Target {" +
                "  float acc = 0;" +
                "  [loop] for (int i = 0; i < 64; i++) { acc += sin(pos.x * 0.013 + i) * cos(pos.y * 0.017 + i); }" +
                "  return float4(saturate(acc), 0.4, 0.6, 1);" +
                "}",
        });
        if (!compiled.Success)
            return;

        try
        {
            using var device = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            device.Initialize(null);
            if (device.Capabilities.ClampSampleCount(4) != 4)
                return;

            using var variant = CreateMaterialContractVariant(compiled, ShaderBytecodeFormat.SpirV);
            // One oversized triangle covers the viewport; drawing it Overdraw times gives a
            // predictable, purely fragment-bound workload.
            float[] vertices = [-1f, -1f, -1f, 3f, 3f, -1f];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
            using var vertexArray = new GraphicsVertexArray(
                new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 2)]),
                vertexBuffer, null);

            const uint big = Size * 2;      // SSAA stand-in renders at 2x in each axis
            using var ssaaColor = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var msaaColor = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b, 4);
            using var ssaaOut = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var msaaOut = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer ssaaFb = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = ssaaColor }], big, big);
            GraphicsFrameBuffer msaaFb = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = msaaColor }], Size, Size);
            GraphicsFrameBuffer ssaaOutFb = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = ssaaOut }], Size, Size);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("msaa-cost-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
                create.EncodeCreateVertexArray(vertexArray);
                create.EncodeCreateTexture(ssaaColor);
                create.EncodeAllocateTexture2D(ssaaColor, 0, big, big, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(msaaColor);
                create.EncodeAllocateTexture2D(msaaColor, 0, Size, Size, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(ssaaOut);
                create.EncodeAllocateTexture2D(ssaaOut, 0, Size, Size, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(msaaOut);
                create.EncodeAllocateTexture2D(msaaOut, 0, Size, Size, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(ssaaFb);
                create.EncodeCreateFramebuffer(msaaFb);
                create.EncodeCreateFramebuffer(ssaaOutFb);
                device.Execute(create, wait: true);
            }
            Assert.Equal(4u, msaaFb.SampleCount);

            RasterizerState raster = new()
            {
                DepthTest = false,
                DepthWrite = false,
                CullFace = RasterizerState.PolyFace.None,
            };

            void RunSsaa()
            {
                using CommandBuffer cmd = global::XEngine.Runtime.Graphics.GetCommandBuffer("msaa-cost-ssaa");
                cmd.SetRenderTarget(ssaaFb);
                cmd.SetViewport(0, 0, big, big);
                cmd.DisableScissor();
                cmd.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
                cmd.SetRasterState(in raster);
                cmd.SetShader(variant);
                for (int i = 0; i < Overdraw; i++)
                    cmd.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                cmd.SetRenderTargets(ssaaOutFb, ssaaFb);
                cmd.BlitFramebuffer(0, 0, (int)big, (int)big, 0, 0, Size, Size, ClearFlags.Color, BlitFilter.Linear);
                device.Execute(cmd, wait: true);
            }

            void RunMsaa()
            {
                using CommandBuffer cmd = global::XEngine.Runtime.Graphics.GetCommandBuffer("msaa-cost-msaa");
                cmd.SetRenderTarget(msaaFb);
                cmd.SetViewport(0, 0, Size, Size);
                cmd.DisableScissor();
                cmd.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
                cmd.SetRasterState(in raster);
                cmd.SetShader(variant);
                for (int i = 0; i < Overdraw; i++)
                    cmd.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                cmd.EncodeResolveTexture(msaaColor, msaaOut);
                device.Execute(cmd, wait: true);
            }

            static double Median(List<double> values)
            {
                values.Sort();
                int n = values.Count;
                return n % 2 == 1 ? values[n / 2] : 0.5 * (values[n / 2 - 1] + values[n / 2]);
            }

            List<double> Measure(Action run)
            {
                for (int i = 0; i < Warmup; i++)
                    run();
                var samples = new List<double>(Iterations);
                for (int i = 0; i < Iterations; i++)
                {
                    long start = Stopwatch.GetTimestamp();
                    run();
                    samples.Add(Stopwatch.GetElapsedTime(start).TotalMilliseconds);
                }
                return samples;
            }

            // Interleave the two so any thermal / clock drift hits both equally.
            List<double> ssaa = Measure(RunSsaa);
            List<double> msaa = Measure(RunMsaa);
            ssaa.AddRange(Measure(RunSsaa));
            msaa.AddRange(Measure(RunMsaa));

            double ssaaMs = Median(ssaa);
            double msaaMs = Median(msaa);
            Console.WriteLine(
                $"[P3.3 MSAA cost] backend={device.Capabilities.BackendName} size={Size}x{Size} overdraw={Overdraw} " +
                $"ssaa2x_median_ms={ssaaMs:F3} msaa4x_median_ms={msaaMs:F3} speedup={ssaaMs / msaaMs:F2}x " +
                $"ssaa_min={ssaa[0]:F3} msaa_min={msaa[0]:F3}");

            Assert.True(
                msaaMs < ssaaMs,
                $"4x MSAA ({msaaMs:F3} ms) should beat the 2x SSAA stand-in ({ssaaMs:F3} ms): it shades a quarter as many fragments.");

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("msaa-cost-dispose");
            dispose.EncodeDisposeFramebuffer(ssaaFb);
            dispose.EncodeDisposeFramebuffer(msaaFb);
            dispose.EncodeDisposeFramebuffer(ssaaOutFb);
            device.Execute(dispose, wait: true);
        }
        catch (Exception ex)
        {
            Assert.True(IsExpectedGpuUnavailable(ex), $"Unexpected Vulkan MSAA cost benchmark failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    [Fact]
    public void GraphicsPipelineKey_Distinguishes_SampleCount()
    {
        var bytecode = new CompiledShaderBytecode(
            ShaderLanguage.Hlsl,
            ShaderBytecodeFormat.SpirV,
            [0x03, 0x02, 0x23, 0x07],
            [0x03, 0x02, 0x23, 0x07]);
        using var firstVariant = new ShaderVariant(bytecode);
        RasterizerState raster = new() { DepthTest = true, DepthWrite = true, CullFace = RasterizerState.PolyFace.Back };
        var single = new GraphicsPipelineKey(firstVariant, 7, Topology.Triangles, in raster, index32Bit: false, null, null, sampleCount: 1);
        var four = new GraphicsPipelineKey(firstVariant, 7, Topology.Triangles, in raster, index32Bit: false, null, null, sampleCount: 4);

        Assert.Equal(1, single.SampleCount);
        Assert.Equal(4, four.SampleCount);
        Assert.NotEqual(single, four);
        Assert.Equal(four, new GraphicsPipelineKey(firstVariant, 7, Topology.Triangles, in raster, index32Bit: false, null, null, sampleCount: 4));
    }

    [Fact]
    public void Capabilities_ClampSampleCount_DegradesToSupportedTier()
    {
        // Bit value == sample count (VkSampleCountFlags encoding): 1|2|4 supported, 8 not.
        var caps = new GraphicsDeviceCapabilities
        {
            SupportedColorSampleCounts = 1 | 2 | 4,
            SupportedDepthSampleCounts = 1 | 2 | 4 | 8,
        };
        Assert.Equal(4, caps.MaxSampleCount);
        Assert.Equal(4, caps.ClampSampleCount(8));
        Assert.Equal(4, caps.ClampSampleCount(4));
        Assert.Equal(2, caps.ClampSampleCount(2));
        Assert.Equal(1, caps.ClampSampleCount(1));
        Assert.True(caps.SupportsSampleCount(4));
        Assert.False(caps.SupportsSampleCount(8));

        // Depth without 4x pulls the usable maximum down: one render pass, one sample count.
        var depthLimited = new GraphicsDeviceCapabilities
        {
            SupportedColorSampleCounts = 1 | 2 | 4 | 8,
            SupportedDepthSampleCounts = 1 | 2,
        };
        Assert.Equal(2, depthLimited.MaxSampleCount);
        Assert.Equal(2, depthLimited.ClampSampleCount(8));

        // Default capabilities (a backend with no MSAA support) degrade everything to 1x.
        var none = new GraphicsDeviceCapabilities();
        Assert.Equal(1, none.MaxSampleCount);
        Assert.False(none.SupportsMultisampleTargets);
        Assert.Equal(1, none.ClampSampleCount(8));
    }

    [Fact]
    public void Optional_D3D12_ObjectUniforms_Pack_Per_Draw_Or_Skip()
    {
        if (!OperatingSystem.IsWindows())
            return;

        var compiler = new DxcShaderCompiler();
        ShaderCompileResult compiled = compiler.Compile(new ShaderCompileRequest
        {
            TargetBackend = GraphicsBackend.Direct3D12,
            Language = ShaderLanguage.Hlsl,
            VertexSource = "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }",
            FragmentSource = "cbuffer ObjectUniforms : register(b1) { float4x4 xengine_ObjectToWorld; float4x4 xengine_WorldToObject; float4x4 xengine_PrevObjectToWorld; int _ObjectID; float3 padding; }; float4 main() : SV_Target { return float4(xengine_ObjectToWorld[0][0], xengine_WorldToObject[1][1], xengine_PrevObjectToWorld[2][2], _ObjectID / 255.0); }",
        });
        if (!compiled.Success)
            return;

        try
        {
            using var device = new Backends.D3D12.D3D12GraphicsDevice(new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
            device.Initialize(null);
            using var variant = new ShaderVariant(new CompiledShaderBytecode(ShaderLanguage.Hlsl, ShaderBytecodeFormat.Dxil, compiled.VertexBytecode!, compiled.FragmentBytecode!, compiled.BindingLayout));
            float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }],
                2,
                1);
            var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
            using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-object-uniform-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, wait: true);
            }

            RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-object-uniform-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.DisableScissor();
                draw.SetShader(variant);
                draw.SetRasterState(in raster);

                Float4x4 firstObject = Float4x4.CreateScale(0.25f, 1f, 1f);
                Float4x4 firstInverse = Float4x4.CreateScale(1f, 0.5f, 1f);
                Float4x4 firstPrevious = Float4x4.CreateScale(1f, 1f, 0.75f);
                var firstProperties = new Rendering.PropertyState();
                firstProperties.SetInt("_ObjectID", 255);
                draw.SetInstanceProperties(firstProperties);
                draw.SetMatrix("xengine_ObjectToWorld", in firstObject);
                draw.SetMatrix("xengine_WorldToObject", in firstInverse);
                draw.SetMatrix("xengine_PrevObjectToWorld", in firstPrevious);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);

                Float4x4 secondObject = Float4x4.CreateScale(0.75f, 1f, 1f);
                Float4x4 secondInverse = Float4x4.CreateScale(1f, 0.25f, 1f);
                Float4x4 secondPrevious = Float4x4.CreateScale(1f, 1f, 0.5f);
                var secondProperties = new Rendering.PropertyState();
                secondProperties.SetInt("_ObjectID", 128);
                draw.SetInstanceProperties(secondProperties);
                draw.SetMatrix("xengine_ObjectToWorld", in secondObject);
                draw.SetMatrix("xengine_WorldToObject", in secondInverse);
                draw.SetMatrix("xengine_PrevObjectToWorld", in secondPrevious);
                draw.SetViewport(1, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, wait: true);
            }

            byte[] readback = device.ReadTexture2D(device.Textures[color.Handle].Resource!, 2, 1, 4, device.Textures[color.Handle].State);
            Assert.InRange(readback[0], (byte)63, (byte)64);
            Assert.InRange(readback[1], (byte)127, (byte)128);
            Assert.InRange(readback[2], (byte)191, (byte)192);
            Assert.Equal((byte)255, readback[3]);
            Assert.InRange(readback[4], (byte)191, (byte)192);
            Assert.InRange(readback[5], (byte)63, (byte)64);
            Assert.InRange(readback[6], (byte)127, (byte)128);
            Assert.InRange(readback[7], (byte)127, (byte)128);

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-object-uniform-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, wait: true);
        }
        catch (Exception ex)
        {
            Assert.True(IsExpectedGpuUnavailable(ex), $"Unexpected D3D12 object-uniform packing failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

    [Fact]
    public void Optional_D3D12_UnlitMaterial_Packs_Defaults_And_Overrides_Or_Skip()
    {
        if (!OperatingSystem.IsWindows())
            return;

        var compiler = new DxcShaderCompiler();
        ShaderCompileResult compiled = compiler.Compile(new ShaderCompileRequest
        {
            TargetBackend = GraphicsBackend.Direct3D12,
            Language = ShaderLanguage.Hlsl,
            VertexSource = "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }",
            FragmentSource = "cbuffer UnlitMaterial : register(b2) { float2 _Tiling; float2 _Offset; float4 _MainColor; }; float4 main() : SV_Target { return float4(_Tiling.x, _Offset.y, _MainColor.r, _MainColor.a); }",
        });
        if (!compiled.Success)
            return;

        try
        {
            using var device = new Backends.D3D12.D3D12GraphicsDevice(new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
            device.Initialize(null);
            using var variant = new ShaderVariant(new CompiledShaderBytecode(ShaderLanguage.Hlsl, ShaderBytecodeFormat.Dxil, compiled.VertexBytecode!, compiled.FragmentBytecode!, compiled.BindingLayout));
            using var shader = CreateUnlitMaterialContractShader();
            using var defaultsMaterial = new Resources.Material(shader);
            using var overridesMaterial = new Resources.Material(shader);
            overridesMaterial.SetVector("_Tiling", new Float2(0.75f, 1f));
            overridesMaterial.SetVector("_Offset", new Float2(0f, 0.25f));
            overridesMaterial.SetColor("_MainColor", new Color(0.5f, 0f, 0f, 0.5f));

            float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }],
                2,
                1);
            var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
            using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-unlit-material-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, wait: true);
            }

            RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-unlit-material-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.DisableScissor();
                draw.SetShader(variant);
                draw.SetRasterState(in raster);
                draw.SetMaterialProperties(defaultsMaterial);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                draw.SetMaterialProperties(overridesMaterial);
                draw.SetViewport(1, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, wait: true);
            }

            byte[] readback = device.ReadTexture2D(device.Textures[color.Handle].Resource!, 2, 1, 4, device.Textures[color.Handle].State);
            Assert.InRange(readback[0], (byte)63, (byte)64);
            Assert.InRange(readback[1], (byte)127, (byte)128);
            Assert.InRange(readback[2], (byte)191, (byte)192);
            Assert.Equal((byte)255, readback[3]);
            Assert.InRange(readback[4], (byte)191, (byte)192);
            Assert.InRange(readback[5], (byte)63, (byte)64);
            Assert.InRange(readback[6], (byte)127, (byte)128);
            Assert.InRange(readback[7], (byte)127, (byte)128);

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-unlit-material-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, wait: true);
        }
        catch (Exception ex)
        {
            Assert.True(IsExpectedGpuUnavailable(ex), $"Unexpected D3D12 Unlit material packing failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

