            Assert.Equal(Vortice.Direct3D12.ResourceDimension.Texture2D, resource.Resource!.Description.Dimension);
            Assert.Equal(2, resource.Resource.Description.DepthOrArraySize);
            Assert.Equal(Vortice.Direct3D12.ResourceStates.PixelShaderResource, resource.State);
