    [Fact]
    public void Optional_ModernBackends_StandardCoreImages_Match_Or_Skip()
    {
        byte[]? d3d12Pixels = TryRenderStandardLightingD3D12();
        byte[]? vulkanPixels = TryRenderStandardLightingVulkan();
        byte[]? referencePixels = d3d12Pixels ?? vulkanPixels;
        if (referencePixels == null)
            return;

        // Keep the artifact path exercised on single-backend development machines. The actual
        // cross-backend assertion below still only runs when both independent renders completed.
        byte[] candidatePixels = vulkanPixels ?? referencePixels;

        ImageComparisonOptions options = new(MaxChannelDelta: 3, MaxMismatchRatio: 0d);
        ImageComparisonResult comparison = BackendImageComparison.Compare(
            new RgbaImage(2, 1, referencePixels),
            new RgbaImage(2, 1, candidatePixels),
            options);

        const int panelWidth = 256;
        const int panelHeight = 128;
        byte[] d3d12Panel = UpscalePixels(referencePixels, 2, 1, panelWidth, panelHeight);
        byte[] vulkanPanel = UpscalePixels(candidatePixels, 2, 1, panelWidth, panelHeight);
        byte[] differencePanel = UpscalePixels(comparison.DifferenceRgba, 2, 1, panelWidth, panelHeight);
        byte[] screenshot = JoinHorizontal(d3d12Panel, vulkanPanel, differencePanel, panelWidth, panelHeight);
        SaveScreenshotPng("c1dg-image-comparison-harness", screenshot, panelWidth * 3, panelHeight);

        if (d3d12Pixels == null || vulkanPixels == null)
            return;
        Assert.True(comparison.Passed, comparison.ToString());
    }

