    [Fact]
    public void Optional_ModernBackends_UniversalRendererPipeline_SceneMatrices_Match_Or_Skip()
    {
        byte[]? d3d12 = TryRenderDefaultPipelineSceneMatrix(GraphicsBackend.Direct3D12);
        byte[]? vulkan = TryRenderDefaultPipelineSceneMatrix(GraphicsBackend.Vulkan);
        byte[]? reference = d3d12 ?? vulkan;
        if (reference == null)
            return;

        byte[] candidate = vulkan ?? reference;
        ImageComparisonResult comparison = BackendImageComparison.Compare(
            new RgbaImage(256, 64, reference),
            new RgbaImage(256, 64, candidate),
            new ImageComparisonOptions(MaxChannelDelta: 5, MaxMismatchRatio: 0.02));
        byte[] screenshot = JoinHorizontal(
            UpscalePixels(reference, 256, 64, 512, 128),
            UpscalePixels(candidate, 256, 64, 512, 128),
            UpscalePixels(comparison.DifferenceRgba, 256, 64, 512, 128),
            512,
            128);
        SaveScreenshotPng("c1dr-vulkan-default-render-pipeline-matrix", screenshot, 1536, 128);

        if (d3d12 != null)
            AssertFxaaMatrixTileChanged(d3d12, "D3D12");
        if (vulkan != null)
            AssertFxaaMatrixTileChanged(vulkan, "Vulkan");
        if (d3d12 != null && vulkan != null)
            Assert.True(comparison.Passed, comparison.ToString());
    }

