    [Fact]
    public void Optional_ModernBackends_WebGPU_UniversalRendererPipeline_Matches_Vulkan_Or_Skip()
    {
        byte[]? webgpu = TryRenderDefaultPipelineSceneMatrix(GraphicsBackend.WebGPU);
        byte[]? vulkan = TryRenderDefaultPipelineSceneMatrix(GraphicsBackend.Vulkan);
        if (webgpu == null)
            return;

        AssertFxaaMatrixTileChanged(webgpu, "WebGPU");
        if (vulkan == null)
            return;

        ImageComparisonResult comparison = BackendImageComparison.Compare(
            new RgbaImage(256, 64, vulkan),
            new RgbaImage(256, 64, webgpu),
            new ImageComparisonOptions(MaxChannelDelta: 5, MaxMismatchRatio: 0.02));
        byte[] screenshot = JoinHorizontal(
            UpscalePixels(vulkan, 256, 64, 512, 128),
            UpscalePixels(webgpu, 256, 64, 512, 128),
