    [MacOSMetalTheory]
    [InlineData(Rendering.QualitySettings.AntiAliasingMode.FXAA, true)]
    [InlineData(Rendering.QualitySettings.AntiAliasingMode.SMAA, true)]
    [InlineData(Rendering.QualitySettings.AntiAliasingMode.Disabled, false)]
    [InlineData(Rendering.QualitySettings.AntiAliasingMode.FXAA, false)]
    public void MetalSceneMatrix_IsolatesAndRestoresQualitySettings(
        Rendering.QualitySettings.AntiAliasingMode antiAliasing, bool imageEffects)
    {
        var previousAntiAliasing = Rendering.QualitySettings.AntiAliasing;
        bool previousImageEffects = Rendering.QualitySettings.ImageEffectsEnabled;
        string? previousDump = Environment.GetEnvironmentVariable("XENGINE_DUMP_SCENE_MATRIX_TILES");
        string? screenshotDirectory = Environment.GetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR");
        string dumpDirectory = Path.Combine(Path.GetTempPath(), "fxaa-quality-matrix-" + Guid.NewGuid().ToString("N"));
        bool passed = false;
        try
        {
            // Reproduce the startup pool pollution before a device exists. Both scene-color
            // formats must be reallocated when the helper initializes its real Metal device.
            Assert.Null(global::XEngine.Runtime.Graphics.Device);
            foreach (TextureImageFormat format in new[] { TextureImageFormat.Color4b, TextureImageFormat.Short4 })
            {
                var startupTarget = Resources.RenderTexture.GetTemporaryRT(64, 64, false, [format]);
                Resources.RenderTexture.ReleaseTemporaryRT(startupTarget);
            }
            Rendering.QualitySettings.AntiAliasing = antiAliasing;
            Rendering.QualitySettings.ImageEffectsEnabled = imageEffects;
            Environment.SetEnvironmentVariable("XENGINE_DUMP_SCENE_MATRIX_TILES", dumpDirectory);

            byte[]? matrix = TryRenderDefaultPipelineSceneMatrix(GraphicsBackend.Metal);

            Assert.NotNull(matrix);
            AssertFxaaMatrixTileChanged(matrix, "Metal; diagnostics=" + dumpDirectory);
            Assert.Equal(antiAliasing, Rendering.QualitySettings.AntiAliasing);
            Assert.Equal(imageEffects, Rendering.QualitySettings.ImageEffectsEnabled);
            Assert.Equal(screenshotDirectory, Environment.GetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR"));
            foreach (string tile in new[] { "empty", "opaque", "transparent", "fxaa" })
                Assert.True(new FileInfo(Path.Combine(dumpDirectory, $"flat_metal_{tile}.png")).Length > 0);
            passed = true;
        }
        finally
        {
            Rendering.QualitySettings.AntiAliasing = previousAntiAliasing;
            Rendering.QualitySettings.ImageEffectsEnabled = previousImageEffects;
            Environment.SetEnvironmentVariable("XENGINE_DUMP_SCENE_MATRIX_TILES", previousDump);
            if (passed && Directory.Exists(dumpDirectory))
                Directory.Delete(dumpDirectory, recursive: true);
        }
    }

