    [Fact]
    public void Optional_ModernBackends_SlangDefaultSceneMatrices_UseNoFallback_Or_Skip()
    {
        string? previousCompiler = Environment.GetEnvironmentVariable("XENGINE_SHADER_COMPILER");
        string? previousScreenshotDirectory = Environment.GetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR");
        string validationDirectory = Path.GetFullPath(Path.Combine(
            AppContext.BaseDirectory,
            "..",
            "..",
            "..",
            "..",
            "Build",
            "Validation",
            "sm10"));
        try
        {
            Directory.CreateDirectory(validationDirectory);
            Environment.SetEnvironmentVariable("XENGINE_SHADER_COMPILER", "auto");
            Environment.SetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR", validationDirectory);
            ShaderCompilerFactory.ResetTelemetryForTests();

            Stopwatch d3d12Timer = Stopwatch.StartNew();
            byte[]? d3d12 = TryRenderDefaultPipelineSceneMatrix(GraphicsBackend.Direct3D12);
            d3d12Timer.Stop();
            ShaderCompilerTelemetry afterD3D12 = ShaderCompilerFactory.GetTelemetry();

            Stopwatch vulkanTimer = Stopwatch.StartNew();
            byte[]? vulkan = TryRenderDefaultPipelineSceneMatrix(GraphicsBackend.Vulkan);
            vulkanTimer.Stop();
            ShaderCompilerTelemetry total = ShaderCompilerFactory.GetTelemetry();

            byte[]? reference = d3d12 ?? vulkan;
            ImageComparisonResult? comparison = d3d12 != null && vulkan != null
                ? BackendImageComparison.Compare(
                    new RgbaImage(256, 64, d3d12),
                    new RgbaImage(256, 64, vulkan),
                    new ImageComparisonOptions(MaxChannelDelta: 5, MaxMismatchRatio: 0.02))
                : null;

            File.WriteAllText(
                Path.Combine(validationDirectory, "sm10-telemetry.json"),
                JsonSerializer.Serialize(new
                {
                    Mode = ShaderCompilerFactory.GetConfiguredMode().ToString(),
                    SelectedCompiler = ShaderCompilerFactory
                        .GetSelectedCompilerKind(GraphicsBackend.Vulkan, "Custom/Probe")
                        .ToString(),
                    D3D12 = new
                    {
                        Available = d3d12 != null,
                        ElapsedMilliseconds = Math.Round(d3d12Timer.Elapsed.TotalMilliseconds, 3),
                        SlangCompileAttempts = afterD3D12.SlangCompileAttempts,
                        DxcCompileAttempts = afterD3D12.DxcCompileAttempts,
                    },
                    Vulkan = new
                    {
                        Available = vulkan != null,
                        ElapsedMilliseconds = Math.Round(vulkanTimer.Elapsed.TotalMilliseconds, 3),
                        SlangCompileAttempts = total.SlangCompileAttempts - afterD3D12.SlangCompileAttempts,
                        DxcCompileAttempts = total.DxcCompileAttempts - afterD3D12.DxcCompileAttempts,
                    },
                    Total = total,
                    Comparison = comparison == null ? null : new
                    {
                        comparison.Passed,
                        comparison.MaxChannelDelta,
                        comparison.MismatchedPixels,
                        comparison.MismatchRatio,
                    },
                }, new JsonSerializerOptions { WriteIndented = true }));

            Assert.Equal(ShaderCompilerKind.Slang, ShaderCompilerFactory.GetSelectedCompilerKind(
                GraphicsBackend.Direct3D12,
                "Custom/Probe"));
            Assert.Equal(ShaderCompilerKind.Slang, ShaderCompilerFactory.GetSelectedCompilerKind(
                GraphicsBackend.Vulkan,
                "Custom/Probe"));
            Assert.Equal(0, total.DxcCompileAttempts);
            Assert.Equal(0, total.FallbackCount);
            Assert.Equal(0, total.FailedRequests);

            if (reference == null)
                return;

            byte[] candidate = vulkan ?? reference;
            byte[] difference = comparison?.DifferenceRgba ?? new byte[reference.Length];
            SaveScreenshotPng(
                "sm10-slang-default-backends-raw",
                JoinHorizontal(
                    UpscalePixels(reference, 256, 64, 512, 128),
                    UpscalePixels(candidate, 256, 64, 512, 128),
                    UpscalePixels(difference, 256, 64, 512, 128),
                    512,
                    128),
                1536,
                128);

            Assert.True(total.SlangCompileAttempts > 0);
            if (comparison != null)
                Assert.True(comparison.Passed, comparison.ToString());
        }
        finally
        {
            Environment.SetEnvironmentVariable("XENGINE_SHADER_COMPILER", previousCompiler);
            Environment.SetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR", previousScreenshotDirectory);
        }
    }

