    private static byte[]? TryRenderTerrainGroup(GraphicsBackend backend)
    {
        try
        {
            byte[] pixels = backend switch
            {
                GraphicsBackend.Direct3D12 => RenderTerrainD3D12(),
                GraphicsBackend.Vulkan => RenderTerrainVulkan(),
                _ => throw new ArgumentOutOfRangeException(nameof(backend), backend, "Expected a modern backend."),
            };
            return pixels.Length == 0 ? null : pixels;
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            return null;
        }
    }

    private static byte[] RenderTerrainD3D12()
    {
        using var device = new Backends.D3D12.D3D12GraphicsDevice(
            new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
        device.Initialize(null);
        return RunTerrainContract(
            device,
            GraphicsBackend.Direct3D12,
            ShaderBytecodeFormat.Dxil,
            texture => device.ReadTexture2D(
                device.Textures[texture.Handle].Resource!,
                3,
                1,
                4,
                device.Textures[texture.Handle].State));
    }

    private static byte[] RenderTerrainVulkan()
    {
        using var device = new Backends.Vulkan.VulkanGraphicsDevice(
            new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
        device.Initialize(null);
        return RunTerrainContract(
            device,
            GraphicsBackend.Vulkan,
            ShaderBytecodeFormat.SpirV,
            texture => device.ReadTexture2D(device.Images[texture.Handle], 4));
    }

