    private static GrassParticleCapture? TryRenderGrassParticleGroup(GraphicsBackend backend)
    {
        try
        {
            return backend switch
            {
                GraphicsBackend.Direct3D12 => RenderGrassParticleD3D12(),
                GraphicsBackend.Vulkan => RenderGrassParticleVulkan(),
                _ => throw new ArgumentOutOfRangeException(nameof(backend), backend, "Expected a modern backend."),
            };
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            return null;
        }
    }

    private static GrassParticleCapture RenderGrassParticleD3D12()
    {
        using var device = new Backends.D3D12.D3D12GraphicsDevice(
            new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
        device.Initialize(null);
        byte[] Read(GraphicsTexture texture, uint width, uint height) => device.ReadTexture2D(
            device.Textures[texture.Handle].Resource!,
            width,
            height,
            4,
            device.Textures[texture.Handle].State);
        return new GrassParticleCapture(
            RunGrassContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil,
                texture => Read(texture, 3, 1)),
            RunParticleMaterialContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil,
                texture => Read(texture, 16, 8)));
    }

    private static GrassParticleCapture RenderGrassParticleVulkan()
    {
        using var device = new Backends.Vulkan.VulkanGraphicsDevice(
            new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
        device.Initialize(null);
        byte[] Read(GraphicsTexture texture) => device.ReadTexture2D(device.Images[texture.Handle], 4);
        return new GrassParticleCapture(
            RunGrassContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read),
            RunParticleMaterialContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read));
    }

    private static byte[] PackGrassParticleCapture(GrassParticleCapture capture)
    {
        byte[] pixels = new byte[16 * 9 * 4];
        capture.Grass.CopyTo(pixels, 0);
        capture.Particle.CopyTo(pixels, 16 * 4);
        return pixels;
    }

    private sealed record GrassParticleCapture(byte[] Grass, byte[] Particle);

