    private static SmaaBokehFogCapture? TryRenderSmaaBokehFogGroup(GraphicsBackend backend)
    {
        try
        {
            SmaaBokehFogCapture capture = backend switch
            {
                GraphicsBackend.Direct3D12 => RenderSmaaBokehFogD3D12(),
                GraphicsBackend.Vulkan => RenderSmaaBokehFogVulkan(),
                _ => throw new ArgumentOutOfRangeException(nameof(backend), backend, "Expected a modern backend."),
            };
            return capture.Smaa.Length == 0 || capture.BokehDof.Length == 0 || capture.VolumetricFog.Length == 0
                ? null
                : capture;
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            return null;
        }
    }

    private static SmaaBokehFogCapture RenderSmaaBokehFogD3D12()
    {
        using var device = new Backends.D3D12.D3D12GraphicsDevice(
            new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
        device.Initialize(null);
        byte[] Read(GraphicsTexture texture) => ReadD3D12Texture(device, texture);
        return new SmaaBokehFogCapture(
            RunSMAAMaterialContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil, Read),
            RunBokehDoFMaterialContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil, Read),
            RunVolumetricFogPostProcessContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil, Read));
    }

    private static SmaaBokehFogCapture RenderSmaaBokehFogVulkan()
    {
        using var device = new Backends.Vulkan.VulkanGraphicsDevice(
            new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
        device.Initialize(null);
        byte[] Read(GraphicsTexture texture) => device.ReadTexture2D(device.Images[texture.Handle], 4);
        return new SmaaBokehFogCapture(
            RunSMAAMaterialContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read),
            RunBokehDoFMaterialContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read),
            RunVolumetricFogPostProcessContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read));
    }

    private static byte[] PackSmaaBokehFogCapture(SmaaBokehFogCapture capture)
    {
        byte[] pixels = new byte[14 * 4];
        int offset = 0;
        capture.Smaa.CopyTo(pixels, offset);
        offset += capture.Smaa.Length;
        capture.BokehDof.CopyTo(pixels, offset);
        offset += capture.BokehDof.Length;
        capture.VolumetricFog.CopyTo(pixels, offset);
        return pixels;
    }

    private sealed record SmaaBokehFogCapture(
        byte[] Smaa,
        byte[] BokehDof,
        byte[] VolumetricFog);

