    private static GtaoSsrCapture? TryRenderGtaoSsrGroup(GraphicsBackend backend)
    {
        try
        {
            GtaoSsrCapture capture = backend switch
            {
                GraphicsBackend.Direct3D12 => RenderGtaoSsrD3D12(),
                GraphicsBackend.Vulkan => RenderGtaoSsrVulkan(),
                _ => throw new ArgumentOutOfRangeException(nameof(backend), backend, "Expected a modern backend."),
            };
            return capture.Calculate.Length == 0 || capture.Blur.Length == 0 || capture.Composite.Length == 0 ||
                capture.Temporal.Length == 0 || capture.Ssr.Length == 0
                ? null
                : capture;
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            return null;
        }
    }

    private static GtaoSsrCapture RenderGtaoSsrD3D12()
    {
        using var device = new Backends.D3D12.D3D12GraphicsDevice(
            new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
        device.Initialize(null);
        byte[] Read(GraphicsTexture texture, uint width) => device.ReadTexture2D(
            device.Textures[texture.Handle].Resource!, width, 1, 4, device.Textures[texture.Handle].State);
        return new GtaoSsrCapture(
            RunGTAOCalculateContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil,
                texture => Read(texture, 4)),
            RunGTAOBlurContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil,
                texture => Read(texture, 4)),
            RunGTAOCompositeContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil,
                texture => Read(texture, 2)),
            RunGTAOTemporalContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil,
                texture => Read(texture, 4)),
            RunSSRMaterialContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil,
                texture => Read(texture, 13)));
    }

    private static GtaoSsrCapture RenderGtaoSsrVulkan()
    {
        using var device = new Backends.Vulkan.VulkanGraphicsDevice(
            new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
        device.Initialize(null);
        byte[] Read(GraphicsTexture texture) => device.ReadTexture2D(device.Images[texture.Handle], 4);
        return new GtaoSsrCapture(
            RunGTAOCalculateContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read),
            RunGTAOBlurContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read),
            RunGTAOCompositeContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read),
            RunGTAOTemporalContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read),
            RunSSRMaterialContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read));
    }

    private static byte[] PackGtaoSsrCapture(GtaoSsrCapture capture)
    {
        byte[] pixels = new byte[14 * 2 * 4];
        int offset = 0;
        capture.Calculate.CopyTo(pixels, offset);
        offset += capture.Calculate.Length;
        capture.Blur.CopyTo(pixels, offset);
        offset += capture.Blur.Length;
        capture.Composite.CopyTo(pixels, offset);
        offset += capture.Composite.Length;
        capture.Temporal.CopyTo(pixels, offset);
        capture.Ssr.CopyTo(pixels, 14 * 4);
        return pixels;
    }

    private sealed record GtaoSsrCapture(
        byte[] Calculate,
        byte[] Blur,
        byte[] Composite,
        byte[] Temporal,
        byte[] Ssr);

    [Fact]
    public void Optional_ModernBackends_StandardSlangGroup_Matches_Dxc_Or_Skip()
    {
        // DXC is the reference compiler for this comparison and is vendored on Windows only.
        if (!OperatingSystem.IsWindows())
            return;

        string? previousCompiler = Environment.GetEnvironmentVariable("XENGINE_SHADER_COMPILER");
        string? previousScreenshotDirectory = Environment.GetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR");
        string validationDirectory = Path.GetFullPath(Path.Combine(
            AppContext.BaseDirectory,
            "..",
            "..",
            "..",
            "..",
            "Build",
            "Validation",
            "sm7-standard"));
        try
        {
            Environment.SetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR", validationDirectory);
            GraphicsBackend[] backends = [GraphicsBackend.Direct3D12, GraphicsBackend.Vulkan];
            foreach (GraphicsBackend backend in backends)
            {
                Environment.SetEnvironmentVariable("XENGINE_SHADER_COMPILER", "dxc");
                byte[]? standardDxc = TryRenderStandardLighting(backend);
                byte[]? transparentDxc = TryRenderDefaultPipelineSceneMatrix(backend);
                Environment.SetEnvironmentVariable("XENGINE_SHADER_COMPILER", "auto");
                byte[]? standardSlang = TryRenderStandardLighting(backend);
                byte[]? transparentSlang = TryRenderDefaultPipelineSceneMatrix(backend);
                if (standardDxc == null || standardSlang == null ||
                    transparentDxc == null || transparentSlang == null)
                {
                    continue;
                }

                ImageComparisonResult standardComparison = BackendImageComparison.Compare(
                    new RgbaImage(2, 1, standardDxc),
                    new RgbaImage(2, 1, standardSlang),
                    new ImageComparisonOptions(MaxChannelDelta: 3, MaxMismatchRatio: 0));
                ImageComparisonResult transparentComparison = BackendImageComparison.Compare(
                    new RgbaImage(256, 64, transparentDxc),
                    new RgbaImage(256, 64, transparentSlang),
                    new ImageComparisonOptions(MaxChannelDelta: 5, MaxMismatchRatio: 0.02));
                string backendName = backend.ToString().ToLowerInvariant();
                SaveScreenshotPng($"sm7-standard-{backendName}-dxc", standardDxc, 2, 1);
                SaveScreenshotPng($"sm7-standard-{backendName}-slang", standardSlang, 2, 1);
                SaveScreenshotPng(
                    $"sm7-standard-{backendName}-raw",
                    JoinHorizontal(
                        UpscalePixels(standardDxc, 2, 1, 256, 128),
                        UpscalePixels(standardSlang, 2, 1, 256, 128),
                        UpscalePixels(standardComparison.DifferenceRgba, 2, 1, 256, 128),
                        256,
                        128),
                    768,
                    128);
                SaveScreenshotPng($"sm7-transparent-{backendName}-dxc", transparentDxc, 256, 64);
                SaveScreenshotPng($"sm7-transparent-{backendName}-slang", transparentSlang, 256, 64);
                SaveScreenshotPng(
                    $"sm7-transparent-{backendName}-raw",
                    JoinHorizontal(
                        UpscalePixels(transparentDxc, 256, 64, 512, 128),
                        UpscalePixels(transparentSlang, 256, 64, 512, 128),
                        UpscalePixels(transparentComparison.DifferenceRgba, 256, 64, 512, 128),
                        512,
                        128),
                    1536,
                    128);

                Assert.True(standardComparison.Passed, $"{backend} Standard: {standardComparison}");
                Assert.True(transparentComparison.Passed, $"{backend} Transparent: {transparentComparison}");
            }
        }
        finally
        {
            Environment.SetEnvironmentVariable("XENGINE_SHADER_COMPILER", previousCompiler);
            Environment.SetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR", previousScreenshotDirectory);
        }
    }

