                GraphicsBackend.Direct3D12 => RenderSkyboxD3D12(),
                GraphicsBackend.Vulkan => RenderSkyboxVulkan(),
                _ => throw new ArgumentOutOfRangeException(nameof(backend), backend, "Expected a modern backend."),
            };
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            return null;
        }
    }

    private static SkyboxCapture RenderSkyboxD3D12()
    {
        using var device = new Backends.D3D12.D3D12GraphicsDevice(
            new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
        device.Initialize(null);
        byte[] Read(GraphicsTexture texture, uint width) => device.ReadTexture2D(
            device.Textures[texture.Handle].Resource!,
            width,
            1,
            4,
            device.Textures[texture.Handle].State);
        return new SkyboxCapture(
            RunGradientSkyboxMaterialContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil, texture => Read(texture, 2u)),
            RunProceduralSkyboxMaterialContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil, texture => Read(texture, 2u)),
            RunCubemapSkyboxMaterialContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil, texture => Read(texture, 6u)));
    }

    private static SkyboxCapture RenderSkyboxVulkan()
    {
        using var device = new Backends.Vulkan.VulkanGraphicsDevice(
            new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
        device.Initialize(null);
        byte[] Read(GraphicsTexture texture) => device.ReadTexture2D(device.Images[texture.Handle], 4);
        return new SkyboxCapture(
            RunGradientSkyboxMaterialContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read),
            RunProceduralSkyboxMaterialContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read),
            RunCubemapSkyboxMaterialContract(device, GraphicsBackend.Vulkan, ShaderBytecodeFormat.SpirV, Read));
    }

    private static byte[] PackSkyboxCapture(SkyboxCapture capture)
    {
        byte[][] rows = [capture.Gradient, capture.Procedural, capture.Cubemap];
        byte[] pixels = new byte[6 * rows.Length * 4];
        for (int row = 0; row < rows.Length; row++)
            rows[row].CopyTo(pixels, row * 6 * 4);
        return pixels;
    }

    private sealed record SkyboxCapture(byte[] Gradient, byte[] Procedural, byte[] Cubemap);

    [Fact]
    public void Optional_ModernBackends_GridUiSlangGroup_Matches_Dxc_Or_Skip()
    {
        // DXC is the reference compiler for this comparison and is vendored on Windows only.
        if (!OperatingSystem.IsWindows())
            return;

        string? previousCompiler = Environment.GetEnvironmentVariable("XENGINE_SHADER_COMPILER");
        string? previousScreenshotDirectory = Environment.GetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR");
        string validationDirectory = Path.GetFullPath(Path.Combine(
            AppContext.BaseDirectory,
            "..",
            "..",
            "..",
            "..",
            "Build",
            "Validation",
            "sm7-grid-ui"));
        try
        {
            Environment.SetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR", validationDirectory);
            GraphicsBackend[] backends = [GraphicsBackend.Direct3D12, GraphicsBackend.Vulkan];
            foreach (GraphicsBackend backend in backends)
            {
                Environment.SetEnvironmentVariable("XENGINE_SHADER_COMPILER", "dxc");
                GridUiCapture? dxcCapture = TryRenderGridUiGroup(backend);
                Environment.SetEnvironmentVariable("XENGINE_SHADER_COMPILER", "auto");
                GridUiCapture? slangCapture = TryRenderGridUiGroup(backend);
                if (dxcCapture == null || slangCapture == null)
                    continue;

                byte[] dxc = PackGridUiCapture(dxcCapture);
                byte[] slang = PackGridUiCapture(slangCapture);
                ImageComparisonResult comparison = BackendImageComparison.Compare(
                    new RgbaImage(10, 8, dxc),
                    new RgbaImage(10, 8, slang),
                    new ImageComparisonOptions(MaxChannelDelta: 3, MaxMismatchRatio: 0));
                string backendName = backend.ToString().ToLowerInvariant();
                SaveScreenshotPng($"sm7-grid-ui-{backendName}-dxc", dxc, 10, 8);
                SaveScreenshotPng($"sm7-grid-ui-{backendName}-slang", slang, 10, 8);
                SaveScreenshotPng(
                    $"sm7-grid-ui-{backendName}-raw",
                    JoinHorizontal(
                        UpscalePixels(dxc, 10, 8, 400, 320),
                        UpscalePixels(slang, 10, 8, 400, 320),
                        UpscalePixels(comparison.DifferenceRgba, 10, 8, 400, 320),
                        400,
                        320),
                    1200,
                    320);

                Assert.True(comparison.Passed, $"{backend} Grid/UI: {comparison}");
            }
        }
        finally
        {
            Environment.SetEnvironmentVariable("XENGINE_SHADER_COMPILER", previousCompiler);
            Environment.SetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR", previousScreenshotDirectory);
        }
    }

    private static GridUiCapture? TryRenderGridUiGroup(GraphicsBackend backend)
    {
        try
