            RunDefaultUIMaterialContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil, texture => Read(texture, 6u)),
            RunDefaultTextMaterialContract(device, GraphicsBackend.Direct3D12, ShaderBytecodeFormat.Dxil, texture => Read(texture, 4u)),
