    private static byte[] PackGridUiCapture(GridUiCapture capture)
    {
        byte[][] rows =
        [
            capture.Grid,
            capture.DefaultUI,
            capture.DefaultText,
            capture.DefaultTextMesh,
            capture.UIProjection,
            capture.UIFragment,
            capture.UIBlur,
