        byte[] UIBackdrop);

    private static void AssertFxaaMatrixTileChanged(byte[] matrix, string backend)
    {
        int changed = 0;
        int changedAtThreshold = 0;
        int maxDifference = 0;
        for (int y = 0; y < 64; y++)
        {
            for (int x = 0; x < 64; x++)
            {
                int opaqueOffset = (y * 256 + 64 + x) * 4;
                int fxaaOffset = (y * 256 + 192 + x) * 4;
                int difference = Math.Abs(matrix[opaqueOffset] - matrix[fxaaOffset])
                    + Math.Abs(matrix[opaqueOffset + 1] - matrix[fxaaOffset + 1])
                    + Math.Abs(matrix[opaqueOffset + 2] - matrix[fxaaOffset + 2]);
                if (difference > 0)
                    changed++;
                if (difference >= 8)
                    changedAtThreshold++;
                maxDifference = Math.Max(maxDifference, difference);
            }
        }

        Assert.True(
            changedAtThreshold >= 4,
            $"{backend} FXAA must alter multiple edge pixels; changed={changed}, changedAtThreshold={changedAtThreshold}, maxDifference={maxDifference}.");
    }

    private static byte[]? TryRenderDefaultPipelineSceneMatrix(
        GraphicsBackend backend,
        bool renderSkybox = false,
        Resources.Scene.SkyboxMode skyboxMode = Resources.Scene.SkyboxMode.Procedural)
    {
        GraphicsBackend? previousBackend = GraphicsBackendSelection.Preferred;
        var previousAntiAliasing = Rendering.QualitySettings.AntiAliasing;
        bool previousImageEffects = Rendering.QualitySettings.ImageEffectsEnabled;
        Resources.Scene? scene = null;
        Resources.RenderTexture[] targets = [];
        Resources.Mesh? cube = null;
        Resources.Material? opaqueMaterial = null;
        Resources.Material? transparentMaterial = null;
        bool completed = false;
        var tileStates = new List<object>();
        var warnings = new List<string>();
        void CaptureWarning(string message, DebugStackTrace? stackTrace, LogSeverity severity)
        {
            if (severity is LogSeverity.Warning or LogSeverity.Error or LogSeverity.Exception)
                warnings.Add(message);
        }
        GraphicsBackendSelection.Preferred = backend;
        try
        {
            global::XEngine.Runtime.Graphics.Initialize(debug: false);
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            global::XEngine.Runtime.Graphics.Dispose();
            GraphicsBackendSelection.Preferred = previousBackend;
            return null;
        }

        try
        {
            // The opaque tile is the no-AA reference, and the final tile opts into FXAA explicitly.
            // Inherited quality AA would process both tiles; disabled post-processing skips FXAA.
            Rendering.QualitySettings.AntiAliasing = Rendering.QualitySettings.AntiAliasingMode.Disabled;
            Rendering.QualitySettings.ImageEffectsEnabled = true;
            Debug.OnLog += CaptureWarning;
            scene = new Resources.Scene();
            scene.Skybox.Mode = skyboxMode;
            scene.Fog.Mode = Resources.Scene.FogParams.FogMode.Off;
            scene.Ambient.Mode = Resources.Scene.AmbientLightParams.AmbientMode.Uniform;
            scene.Ambient.Strength = renderSkybox ? 0f : 1f;
            scene.Ambient.Color = new Float4(1f, 1f, 1f, 1f);

            var cameraObject = new GameObject("Default pipeline camera");
            Camera camera = cameraObject.AddComponent<Camera>();
            targets =
            [
                new Resources.RenderTexture(64, 64, true, [TextureImageFormat.Color4b]),
                new Resources.RenderTexture(64, 64, true, [TextureImageFormat.Color4b]),
                new Resources.RenderTexture(64, 64, true, [TextureImageFormat.Color4b]),
                new Resources.RenderTexture(64, 64, true, [TextureImageFormat.Color4b]),
            ];
            camera.Target = targets[0];
            camera.ClearFlags = renderSkybox ? CameraClearFlags.Skybox : CameraClearFlags.SolidColor;
            camera.ClearColor = new Color(0.125f, 0.375f, 0.625f, 1f);
            camera.Pipeline = new Rendering.UniversalRenderPipeline();
            cameraObject.Transform.Position = new Float3(0f, 0f, -3f);
            scene.Add(cameraObject);

            if (renderSkybox)
            {
                var lightObject = new GameObject("Default pipeline directional light");
                lightObject.Transform.LocalEulerAngles = new Float3(-45f, 45f, 0f);
                DirectionalLight directionalLight = lightObject.AddComponent<DirectionalLight>();
                directionalLight.CastShadows = false;
                scene.Add(lightObject);
            }

            cube = Resources.Mesh.CreateCube(Float3.One);
            opaqueMaterial = new Resources.Material(Resources.Shader.LoadDefault(
                renderSkybox ? Resources.DefaultShader.Standard : Resources.DefaultShader.Unlit));
            opaqueMaterial.SetColor("_MainColor", new Color(0.8f, 0.1f, 0.05f, 1f));
            var cubeObject = new GameObject("Opaque cube");
            MeshRenderer opaqueRenderer = cubeObject.AddComponent<MeshRenderer>();
            opaqueRenderer.Mesh = cube;
            opaqueRenderer.Material = opaqueMaterial;
            cubeObject.Transform.Rotation = Quaternion.AxisAngle(Float3.UnitY, 0.45f);
            cubeObject.Enabled = false;
            scene.Add(cubeObject);

            transparentMaterial = new Resources.Material(
                Resources.Shader.LoadDefault(Resources.DefaultShader.StandardTransparent));
            transparentMaterial.SetColor("_MainColor", new Color(0.1f, 0.9f, 0.2f, 0.5f));
            var transparentObject = new GameObject("Transparent cube");
            MeshRenderer transparentRenderer = transparentObject.AddComponent<MeshRenderer>();
            transparentRenderer.Mesh = cube;
            transparentRenderer.Material = transparentMaterial;
            transparentObject.Transform.Rotation = Quaternion.AxisAngle(Float3.UnitY, -0.35f);
            transparentObject.Enabled = false;
            scene.Add(transparentObject);
            scene.Enable();

            byte[] RenderTile(int tile)
            {
                camera.Target = targets[tile];
                global::XEngine.Runtime.Graphics.BeginFrame();
                using (CommandBuffer clearTarget = global::XEngine.Runtime.Graphics.GetCommandBuffer("Clear pipeline matrix tile"))
                {
                    clearTarget.SetRenderTarget(targets[tile].frameBuffer);
                    clearTarget.SetViewport(0, 0, 64, 64);
                    clearTarget.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0f, 0f, 0f, 0f));
                    global::XEngine.Runtime.Graphics.Submit(clearTarget);
                }
                camera.Pipeline!.Render(camera, new Rendering.RenderingData { SkipUI = true });
                tileStates.Add(new
                {
                    tile,
                    antiAliasing = Rendering.QualitySettings.AntiAliasing.ToString(),
                    imageEffects = Rendering.QualitySettings.ImageEffectsEnabled,
                    fxaaEffects = ((Rendering.UniversalRenderPipeline)camera.Pipeline).CountEffectsForTest<Rendering.FXAAEffect>(),
                });
                global::XEngine.Runtime.Graphics.EndFrameAndWait();
                global::XEngine.Runtime.Graphics.Device!.WaitIdle();

                return backend switch
                {
                    GraphicsBackend.Direct3D12 => ReadD3D12RenderTexture(targets[tile]),
                    GraphicsBackend.Vulkan => ReadVulkanRenderTexture(targets[tile]),
                    GraphicsBackend.WebGPU => ReadWebGPURenderTexture(targets[tile]),
                    GraphicsBackend.Metal => ReadMetalRenderTexture(targets[tile]),
                    _ => throw new InvalidOperationException($"Unsupported scene-matrix backend {backend}."),
                };
            }

            byte[] empty = RenderTile(0);

            cubeObject.Enabled = true;
            byte[] opaque = RenderTile(1);

            cubeObject.Enabled = false;
            transparentObject.Enabled = true;
            byte[] transparent = RenderTile(2);

            transparentObject.Enabled = false;
            cubeObject.Enabled = true;
            camera.Effects.Add(new Rendering.FXAAEffect());
            byte[] fxaa = RenderTile(3);

            if (Environment.GetEnvironmentVariable("XENGINE_DUMP_SCENE_MATRIX_TILES") is string tileDumpDir && tileDumpDir.Length > 0)
            {
                string? previousScreenshotDirectory = Environment.GetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR");
                Environment.SetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR", tileDumpDir);
                string prefix = renderSkybox ? "sky" : "flat";
                string backendName = backend.ToString().ToLowerInvariant();
                try
                {
                    // RenderTile already performs the backend's supported render-target readback.
                    // Intermediate Metal textures can use private storage and cannot be read by CPU.
                    SaveScreenshotPng($"{prefix}_{backendName}_empty", empty, 64, 64);
                    SaveScreenshotPng($"{prefix}_{backendName}_opaque", opaque, 64, 64);
                    SaveScreenshotPng($"{prefix}_{backendName}_transparent", transparent, 64, 64);
                    SaveScreenshotPng($"{prefix}_{backendName}_fxaa", fxaa, 64, 64);
                    File.WriteAllText(Path.Combine(tileDumpDir, $"{prefix}_{backendName}_state.json"),
                        JsonSerializer.Serialize(new { tileStates, warnings }));
                }
                finally
                {
                    Environment.SetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR", previousScreenshotDirectory);
                }
            }

            if (renderSkybox)
            {
                AssertLitTile(empty, opaque, 0, "opaque");
                AssertLitTile(empty, transparent, 1, "transparent");
            }
            else
            {
                AssertMaterialPixel(empty, 32 * 64 + 32, 0.125f, 0.375f, 0.625f, 1f);
                int center = (32 * 64 + 32) * 4;
                Assert.True(
                    opaque[center] > opaque[center + 1] && opaque[center] > opaque[center + 2],
                    $"The opaque tile center must be red-dominant; got RGBA {opaque[center]}, {opaque[center + 1]}, {opaque[center + 2]}, {opaque[center + 3]}.");
                Assert.True(
                    transparent[center + 1] > transparent[center] && transparent[center + 1] > transparent[center + 2],
                    $"The transparent tile center must be green-dominant; got RGBA {transparent[center]}, {transparent[center + 1]}, {transparent[center + 2]}, {transparent[center + 3]}.");
                Assert.InRange(transparent[center + 3], (byte)96, (byte)240);
            }

            byte[] sceneMatrix = JoinHorizontal(empty, opaque, transparent, fxaa, 64, 64);
            completed = true;
            return sceneMatrix;

            static void AssertLitTile(byte[] background, byte[] tile, int dominantChannel, string label)
            {
                int litPixels = 0;
                int brightest = 0;
                for (int pixel = 0; pixel < 64 * 64; pixel++)
                {
                    int offset = pixel * 4;
                    int firstOther = (dominantChannel + 1) % 3;
                    int secondOther = (dominantChannel + 2) % 3;
                    int difference = Math.Abs(tile[offset] - background[offset])
                        + Math.Abs(tile[offset + 1] - background[offset + 1])
                        + Math.Abs(tile[offset + 2] - background[offset + 2]);
                    int dominant = tile[offset + dominantChannel];
                    if (difference >= 12 && dominant >= 16 &&
                        dominant > tile[offset + firstOther] + 4 &&
                        dominant > tile[offset + secondOther] + 4)
                    {
                        litPixels++;
                        brightest = Math.Max(brightest, dominant);
                    }
                }

                Assert.True(
                    litPixels >= 8,
                    $"The {label} tile must contain directional-lit dominant-color pixels; litPixels={litPixels}, brightest={brightest}.");
            }
        }
        catch (Exception ex) when (backend == GraphicsBackend.Vulkan && IsSpirvCodeGenUnavailable(ex))
        {
            // Host DXC cannot emit SPIR-V (Vulkan SDK not installed). Treat as a clean skip: the
            // pipeline code path is exercised on D3D12 and the cross-backend comparison only runs
            // when both backends produce output.
            return null;
        }
        finally
        {
            Debug.OnLog -= CaptureWarning;
            if (scene?.IsActive == true)
                scene.Disable();
            scene?.Dispose();
            if (!completed)
                global::XEngine.Runtime.Graphics.Dispose();
            transparentMaterial?.Dispose();
            opaqueMaterial?.Dispose();
            cube?.Dispose();
            for (int i = 0; i < targets.Length; i++)
                targets[i].Dispose();
            if (completed)
                global::XEngine.Runtime.Graphics.Device?.WaitIdle();
            global::XEngine.Runtime.Graphics.Dispose();
            GraphicsBackendSelection.Preferred = previousBackend;
            Rendering.QualitySettings.AntiAliasing = previousAntiAliasing;
            Rendering.QualitySettings.ImageEffectsEnabled = previousImageEffects;
            Rendering.PropertyState.ClearGlobalsInternal();
        }
    }

    private static byte[] ReadD3D12RenderTexture(Resources.RenderTexture target)
    {
        var device = Assert.IsType<Backends.D3D12.D3D12GraphicsDevice>(global::XEngine.Runtime.Graphics.Device);
        Backends.D3D12.D3D12TextureResource resource = device.Textures[target.MainTexture.Handle.Handle];
        return device.ReadTexture2D(resource.Resource!, 64, 64, 4, resource.State);
    }

    private static byte[] ReadVulkanRenderTexture(Resources.RenderTexture target)
    {
        var device = Assert.IsType<Backends.Vulkan.VulkanGraphicsDevice>(global::XEngine.Runtime.Graphics.Device);
        Backends.Vulkan.VkImageResource resource = device.Images[target.MainTexture.Handle.Handle];
        return device.ReadTexture2D(resource, 4);
    }

    private static byte[] ReadWebGPURenderTexture(Resources.RenderTexture target)
    {
        var device = Assert.IsType<Backends.WebGPU.WebGPUGraphicsDevice>(global::XEngine.Runtime.Graphics.Device);
        Backends.WebGPU.WebGPUTextureResource resource = device.Textures[target.MainTexture.Handle.Handle];
        return device.ReadTexture2D(resource, 0);
    }

    private static byte[] ReadMetalRenderTexture(Resources.RenderTexture target)
    {
        var device = Assert.IsType<Backends.Metal.MetalGraphicsDevice>(global::XEngine.Runtime.Graphics.Device);
        Backends.Metal.MetalTextureResource resource = device.Textures[target.MainTexture.Handle.Handle];
        return device.ReadTexture2D(resource, 0);
    }

