    [Fact]
    public void Optional_D3D12_StorageBuffer_Dispatch_Executes_Or_Skips()
    {
        if (!OperatingSystem.IsWindows())
            return;

        var compiler = new RuntimeSlangShaderCompiler();
        ShaderCompileResult compiled = compiler.Compile(new ShaderCompileRequest
        {
            TargetBackend = GraphicsBackend.Direct3D12,
            Language = ShaderLanguage.Hlsl,
            VertexSource = "",
            FragmentSource = "",
            ComputeSource = """
            RWStructuredBuffer<uint> _Counters : register(u0);
            [numthreads(1, 1, 1)]
            void main() { _Counters[0] = 7; }
            """,
        });
        if (!compiled.Success || compiled.ComputeBytecode is not { Length: > 0 })
            return;

        try
        {
            using var device = new Backends.D3D12.D3D12GraphicsDevice(new GraphicsDeviceOptions
            {
                Backend = GraphicsBackend.Direct3D12,
                Debug = false,
            });
            device.Initialize(null);
            using var variant = new ShaderVariant(new CompiledShaderBytecode(
                ShaderLanguage.Hlsl,
                ShaderBytecodeFormat.Dxil,
                [],
                [],
                compiled.BindingLayout,
                computeBytecode: compiled.ComputeBytecode));
            using var counters = new GraphicsBuffer(BufferType.StructuredBuffer, new byte[4], dynamic: true);
            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-uav-create"))
            {
                create.EncodeCreateBuffer(counters, true, new byte[4]);
                device.Execute(create, wait: true);
            }

            using (CommandBuffer dispatch = global::XEngine.Runtime.Graphics.GetCommandBuffer("d3d12-uav-dispatch"))
            {
                dispatch.SetComputeShader(variant);
                dispatch.SetBuffer("_Counters", counters);
                dispatch.DispatchCompute(1, 1, 1);
                dispatch.ResourceBarrier(GpuBarrierKind.ComputeToVertex, counters);
                device.Execute(dispatch, wait: true);
            }

            Assert.NotEqual(0ul, device.GetFenceValue());
            var pipeline = device.GetOrCreateComputePipeline(variant);
            Assert.NotEqual(nint.Zero, pipeline.NativePointer);
        }
        catch (Exception ex)
        {
            Assert.True(
                IsExpectedGpuUnavailable(ex),
                $"Unexpected D3D12 storage-buffer DispatchCompute failure: {ex.GetType().FullName}: {ex.Message}");
        }
    }

