    private static bool IsExpectedGpuUnavailable(Exception ex)
    {
        for (Exception? current = ex; current != null; current = current.InnerException)
        {
            if (current is PlatformNotSupportedException
                or DllNotFoundException
                or EntryPointNotFoundException
                or BadImageFormatException)
            {
                return true;
            }

            if (current is InvalidOperationException && IsExplicitGpuAvailabilityMessage(current.Message))
                return true;
        }

        return false;
    }

    private static Silk.NET.Windowing.IWindow CreateModernBackendWindow(
        GraphicsBackend backend,
        string title,
        int width,
        int height,
        Silk.NET.Core.Contexts.IGLContext? sharedContext = null)
    {
        Silk.NET.Windowing.WindowOptions options = backend == GraphicsBackend.Vulkan
            ? Silk.NET.Windowing.WindowOptions.DefaultVulkan
            : Silk.NET.Windowing.WindowOptions.Default;
        options.Title = title;
        options.Size = new Silk.NET.Maths.Vector2D<int>(width, height);
        options.SharedContext = sharedContext;
        if (backend == GraphicsBackend.Direct3D12)
        {
            options.API = new Silk.NET.Windowing.GraphicsAPI(
                Silk.NET.Windowing.ContextAPI.None,
                Silk.NET.Windowing.ContextProfile.Core,
                Silk.NET.Windowing.ContextFlags.ForwardCompatible,
                new Silk.NET.Windowing.APIVersion(12, 0));
        }
        options.IsVisible = Environment.GetEnvironmentVariable("XENGINE_CAPTURE_WINDOW_MATRIX") == "1";
        options.ShouldSwapAutomatically = false;
        Silk.NET.Windowing.IWindow window = Silk.NET.Windowing.Window.Create(options);
        window.Initialize();
        return window;
    }

    // Mirrors Quill's Vertex struct (24 bytes): position, uv, color, brush record index.
    private static void WritePaperVertex(Span<byte> destination, float x, float y, float u, float v, float brushIndex = 0f)
    {
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(destination, BitConverter.SingleToInt32Bits(x));
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(destination[4..], BitConverter.SingleToInt32Bits(y));
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(destination[8..], BitConverter.SingleToInt32Bits(u));
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(destination[12..], BitConverter.SingleToInt32Bits(v));
        destination[16] = 255;
        destination[17] = 255;
        destination[18] = 255;
        destination[19] = 255;
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(destination[20..], BitConverter.SingleToInt32Bits(brushIndex));
    }

    /// <summary>
    /// Builds one packed UiBrushRecord (9 float4 = 144 bytes) matching Paper/UI.shader's
    /// UiBrushes slot layout: identity transforms, scissor disabled, solid (type 0) brush.
    /// </summary>
    private static byte[] CreateIdentityUiBrushRecord()
    {
        float[] record = new float[36];
        // [0] scissor inverse affine (A,B,C,D) = identity
        record[0] = 1f;
        record[3] = 1f;
        // [1] (E,F, extentX, extentY): negative extent disables the scissor
        record[6] = -1f;
        record[7] = -1f;
        // [2] brush inverse affine = identity
        record[8] = 1f;
        record[11] = 1f;
        // [3] (E,F, brushType=0, reserved)
        // [4]/[5] gradient colors, [6] points: unused for type 0
        // [7] (cornerRadii, feather, texE=0, texF=0)
        // [8] texture inverse affine = identity
        record[32] = 1f;
        record[35] = 1f;
        byte[] bytes = new byte[record.Length * sizeof(float)];
        Buffer.BlockCopy(record, 0, bytes, 0, bytes.Length);
        return bytes;
    }

    private static void WriteColorTriangle(Span<byte> destination, byte red, byte green, byte blue)
    {
        WriteColorVertex(destination, -1f, -1f, red, green, blue);
        WriteColorVertex(destination[12..], -1f, 3f, red, green, blue);
        WriteColorVertex(destination[24..], 3f, -1f, red, green, blue);
    }

    private static void WriteColorVertex(Span<byte> destination, float x, float y, byte red, byte green, byte blue)
    {
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(destination, BitConverter.SingleToInt32Bits(x));
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(destination[4..], BitConverter.SingleToInt32Bits(y));
        destination[8] = red;
        destination[9] = green;
        destination[10] = blue;
        destination[11] = 255;
    }

