    private static void PauseForWindowCapture(Silk.NET.Windowing.IWindow window)
    {
        if (Environment.GetEnvironmentVariable("XENGINE_CAPTURE_WINDOW_MATRIX") != "1")
            return;

        DateTime end = DateTime.UtcNow.AddSeconds(8);
        while (DateTime.UtcNow < end)
        {
            window.DoEvents();
            System.Threading.Thread.Sleep(16);
        }
    }

    private static byte[] ReadD3D12Texture(
        Backends.D3D12.D3D12GraphicsDevice device,
        GraphicsTexture texture)
    {
        Backends.D3D12.D3D12TextureResource resource = device.Textures[texture.Handle];
        return device.ReadTexture2D(resource.Resource!, resource.Width, resource.Height, 4, resource.State);
    }

    private static bool IsExplicitGpuAvailabilityMessage(string message) =>
        message.StartsWith("Failed to create Direct3D 12 device. D3D12 is unavailable on this machine", StringComparison.Ordinal)
        || message.StartsWith("Failed to create DXGI factory:", StringComparison.Ordinal)
        || message.Equals("No Direct3D 12-capable DXGI adapter was found.", StringComparison.Ordinal)
        || message.StartsWith("Failed to create D3D12 device:", StringComparison.Ordinal)
        || message.StartsWith("Failed to create Vulkan instance. Vulkan is unavailable on this machine", StringComparison.Ordinal)
        || message.StartsWith("vkCreateInstance failed:", StringComparison.Ordinal)
        || message.Equals("VK_KHR_surface is not available.", StringComparison.Ordinal)
        || message.Equals("No Vulkan physical devices found.", StringComparison.Ordinal)
        || message.StartsWith("vkCreateDevice failed:", StringComparison.Ordinal)
        || message.Equals("VK_KHR_swapchain is not available.", StringComparison.Ordinal)
        || message.Equals("No graphics queue family on Vulkan device.", StringComparison.Ordinal)
        || message.Equals("No Vulkan present queue family supports the window surface.", StringComparison.Ordinal)
        || message.StartsWith("Failed to create WebGPU device. wgpu-native is unavailable", StringComparison.Ordinal)
        || message.StartsWith("wgpuCreateInstance returned null", StringComparison.Ordinal)
        || message.StartsWith("Failed to request a WebGPU adapter:", StringComparison.Ordinal)
        || message.StartsWith("Failed to request a WebGPU device:", StringComparison.Ordinal);

    private static void AssertCommonWrapperHasNoSilkOpenGLTypes(Type wrapperType)
    {
        const System.Reflection.BindingFlags Flags =
            System.Reflection.BindingFlags.Public |
            System.Reflection.BindingFlags.NonPublic |
            System.Reflection.BindingFlags.Instance |
            System.Reflection.BindingFlags.Static |
            System.Reflection.BindingFlags.DeclaredOnly;

        var offenders = new System.Collections.Generic.List<string>();
        foreach (System.Reflection.FieldInfo field in wrapperType.GetFields(Flags))
        {
            if (ContainsSilkOpenGLType(field.FieldType))
                offenders.Add($"field {field.Name}: {field.FieldType}");
        }
        foreach (System.Reflection.PropertyInfo property in wrapperType.GetProperties(Flags))
        {
            if (ContainsSilkOpenGLType(property.PropertyType))
                offenders.Add($"property {property.Name}: {property.PropertyType}");
        }
        foreach (System.Reflection.MethodInfo method in wrapperType.GetMethods(Flags))
        {
            if (ContainsSilkOpenGLType(method.ReturnType))
                offenders.Add($"return {method.Name}: {method.ReturnType}");
            foreach (System.Reflection.ParameterInfo parameter in method.GetParameters())
            {
                if (ContainsSilkOpenGLType(parameter.ParameterType))
                    offenders.Add($"parameter {method.Name}.{parameter.Name}: {parameter.ParameterType}");
            }
        }

        Assert.True(offenders.Count == 0, $"{wrapperType.FullName} leaks Silk.NET.OpenGL types: {string.Join(", ", offenders)}");
    }

    private static bool ContainsSilkOpenGLType(Type type)
    {
        while (type.HasElementType)
            type = type.GetElementType()!;
        if (type.Namespace?.StartsWith("Silk.NET.OpenGL", StringComparison.Ordinal) == true)
            return true;
        if (!type.IsGenericType)
            return false;

        Type[] genericArguments = type.GetGenericArguments();
        for (int i = 0; i < genericArguments.Length; i++)
        {
            if (ContainsSilkOpenGLType(genericArguments[i]))
                return true;
        }
        return false;
    }

