    [Fact]
    public void BlitMaterialUniforms_Pack_Default_And_Instance_Override()
    {
        Rendering.Shaders.ShaderProperty flipY = new(0f) { Name = "_FlipY", DisplayName = "Flip Render Target Y" };
        using var shader = new Resources.Shader("Blit Contract", [flipY], []);
        using var material = new Resources.Material(shader);

        Rendering.BlitMaterialUniformsData defaults = Rendering.MaterialUniformPacking.PackBlit(material._properties, shader);
        Assert.Equal(16, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.BlitMaterialUniformsData>());
        Assert.Equal(0f, defaults._FlipY);

        material.SetFloat("_FlipY", 1f);
        Rendering.BlitMaterialUniformsData overridden = Rendering.MaterialUniformPacking.PackBlit(material._properties, shader);
        Assert.Equal(1f, overridden._FlipY);
    }

    [Fact]
    public void TonemapperMaterialUniforms_Pack_RenderTargetFlip()
    {
        Rendering.Shaders.ShaderProperty contrast = new(1.1f) { Name = "Contrast", DisplayName = "Contrast" };
        Rendering.Shaders.ShaderProperty saturation = new(0.9f) { Name = "Saturation", DisplayName = "Saturation" };
        Rendering.Shaders.ShaderProperty flipY = new(0f) { Name = "_FlipY", DisplayName = "Flip Render Target Y" };
        using var shader = new Resources.Shader("Tonemapper Contract", [contrast, saturation, flipY], []);
        using var material = new Resources.Material(shader);

        Rendering.TonemapperUniformsData defaults = Rendering.MaterialUniformPacking.PackTonemapper(material._properties, shader);
        Assert.Equal(16, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.TonemapperUniformsData>());
        Assert.Equal(1.1f, defaults.Contrast);
        Assert.Equal(0.9f, defaults.Saturation);
        Assert.Equal(0f, defaults._FlipY);

        material.SetFloat("_FlipY", 1f);
        Rendering.TonemapperUniformsData overridden = Rendering.MaterialUniformPacking.PackTonemapper(material._properties, shader);
        Assert.Equal(1f, overridden._FlipY);
    }

