    private static void RunStandardMaterialBlocksContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        string vertexSource = backend == GraphicsBackend.Vulkan
            ? "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }"
            : "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string standardBlock = "cbuffer StandardMaterial : register(b2) { float2 _Tiling; float2 _Offset; float4 _MainColor; float _EmissionIntensity; float _AlphaCutoff; float _Parallax; int _ParallaxSteps; float _TranslucencyStrength; float _ScatteringPower; float _ScatteringDistortion; float _ScatteringScale; }; ";
        const string cutoutFields = "float2 _Tiling; float2 _Offset; float4 _MainColor; float _AlphaCutoff; float3 Padding;";

        var compiler = new DxcShaderCompiler();
        ShaderCompileResult standardFront = CompileMaterialContractShader(compiler, backend, vertexSource, standardBlock + "float4 main() : SV_Target { return float4(_EmissionIntensity, _AlphaCutoff, _Parallax, _ParallaxSteps / 16.0); }");
        ShaderCompileResult standardTail = CompileMaterialContractShader(compiler, backend, vertexSource, standardBlock + "float4 main() : SV_Target { return float4(_TranslucencyStrength, _ScatteringPower, _ScatteringDistortion, _ScatteringScale); }");
        ShaderCompileResult prepass = CompileMaterialContractShader(compiler, backend, vertexSource, "cbuffer PrepassMaterial : register(b2) { " + cutoutFields + " }; float4 main() : SV_Target { return float4(_Tiling.x, _Offset.y, _MainColor.r, _AlphaCutoff); }");
        ShaderCompileResult shadow = CompileMaterialContractShader(compiler, backend, vertexSource, "cbuffer ShadowMaterial : register(b2) { " + cutoutFields + " }; float4 main() : SV_Target { return float4(_Tiling.x, _Offset.y, _MainColor.r, _AlphaCutoff); }");
        if (!standardFront.Success || !standardTail.Success || !prepass.Success || !shadow.Success)
            return;

        using var standardFrontVariant = CreateMaterialContractVariant(standardFront, bytecodeFormat);
        using var standardTailVariant = CreateMaterialContractVariant(standardTail, bytecodeFormat);
        using var prepassVariant = CreateMaterialContractVariant(prepass, bytecodeFormat);
        using var shadowVariant = CreateMaterialContractVariant(shadow, bytecodeFormat);
        using var shader = CreateStandardMaterialContractShader();
        using var defaultsMaterial = new Resources.Material(shader);
        using var standardOverrides = new Resources.Material(shader);
        standardOverrides.SetFloat("_EmissionIntensity", 0.5f);
        standardOverrides.SetFloat("_AlphaCutoff", 0.625f);
        standardOverrides.SetFloat("_Parallax", 0.75f);
        standardOverrides.SetInt("_ParallaxSteps", 14);
        standardOverrides.SetFloat("_TranslucencyStrength", 0.1f);
        standardOverrides.SetFloat("_ScatteringPower", 0.3f);
        standardOverrides.SetFloat("_ScatteringDistortion", 0.5f);
        standardOverrides.SetFloat("_ScatteringScale", 0.7f);
        using var prepassOverrides = new Resources.Material(shader);
        prepassOverrides.SetVector("_Tiling", new Float2(0.5f, 0f));
        prepassOverrides.SetVector("_Offset", new Float2(0f, 0.625f));
        prepassOverrides.SetColor("_MainColor", new Color(0.75f, 0f, 0f, 1f));
        prepassOverrides.SetFloat("_AlphaCutoff", 0.875f);
        using var shadowOverrides = new Resources.Material(shader);
        shadowOverrides.SetVector("_Tiling", new Float2(0.875f, 0f));
        shadowOverrides.SetVector("_Offset", new Float2(0f, 0.75f));
        shadowOverrides.SetVector("_MainColor", new Float4(0.625f, 0f, 0f, 1f));
        shadowOverrides.SetFloat("_AlphaCutoff", 0.5f);

        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
            [new GraphicsFrameBuffer.Attachment { Texture = color }],
            8,
            1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-material-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 8, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, wait: true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-material-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, standardFrontVariant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, standardFrontVariant, standardOverrides, 1);
            DrawMaterialPixel(draw, vertexArray, standardTailVariant, defaultsMaterial, 2);
            DrawMaterialPixel(draw, vertexArray, standardTailVariant, standardOverrides, 3);
            DrawMaterialPixel(draw, vertexArray, prepassVariant, defaultsMaterial, 4);
            DrawMaterialPixel(draw, vertexArray, prepassVariant, prepassOverrides, 5);
            DrawMaterialPixel(draw, vertexArray, shadowVariant, defaultsMaterial, 6);
            DrawMaterialPixel(draw, vertexArray, shadowVariant, shadowOverrides, 7);
            device.Execute(draw, wait: true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.125f, 0.25f, 0.375f, 0.5f);
        AssertMaterialPixel(pixels, 1, 0.5f, 0.625f, 0.75f, 0.875f);
        AssertMaterialPixel(pixels, 2, 0.2f, 0.4f, 0.6f, 0.8f);
        AssertMaterialPixel(pixels, 3, 0.1f, 0.3f, 0.5f, 0.7f);
        AssertMaterialPixel(pixels, 4, 0.125f, 0.25f, 0.375f, 0.25f);
        AssertMaterialPixel(pixels, 5, 0.5f, 0.625f, 0.75f, 0.875f);
        AssertMaterialPixel(pixels, 6, 0.125f, 0.25f, 0.375f, 0.25f);
        AssertMaterialPixel(pixels, 7, 0.875f, 0.75f, 0.625f, 0.5f);

        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-material-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, wait: true);
    }

    private static byte[]? RunStandardTransparentContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            return RunStandardTransparentContractCore(device, backend, bytecodeFormat, readback);
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
        }
    }

    private static byte[]? RunStandardTransparentContractCore(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.StandardTransparent);
        Assert.NotNull(shader);
        Rendering.Shaders.ShaderPass pass = shader.GetPass("StandardTransparent");
        Assert.True(pass.HasHlsl);
        string vertexSource = (string)typeof(Rendering.Shaders.ShaderPass)
            .GetField("_hlslVertexSource", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(pass)!;
        string fragmentSource = (string)typeof(Rendering.Shaders.ShaderPass)
            .GetField("_hlslFragmentSource", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(pass)!;
        ShaderCompileResult compiled = CompileMaterialContractShader(
            ShaderCompilerFactory.GetCompiler(backend, shader.Name),
            backend,
            vertexSource,
            fragmentSource);
        if (!compiled.Success &&
            backend == GraphicsBackend.Vulkan &&
            compiled.ErrorMessage?.Contains("SPIR-V CodeGen not available", StringComparison.OrdinalIgnoreCase) == true)
        {
            return null;
        }

        Assert.True(compiled.Success, compiled.ErrorMessage);
        ShaderBindingLayout bindingLayout = Assert.IsType<ShaderBindingLayout>(compiled.BindingLayout);
        Assert.Collection(
            bindingLayout.Buffers,
            slot => { Assert.Equal(ShaderBindingKind.Buffer, slot.Kind); Assert.Equal(0, slot.Slot); Assert.Equal("GlobalUniforms", slot.Name); },
            slot => { Assert.Equal(ShaderBindingKind.Buffer, slot.Kind); Assert.Equal(1, slot.Slot); Assert.Equal("ObjectUniforms", slot.Name); },
            slot => { Assert.Equal(ShaderBindingKind.Buffer, slot.Kind); Assert.Equal(2, slot.Slot); Assert.Equal("StandardMaterial", slot.Name); });
        using ShaderVariant variant = CreateMaterialContractVariant(compiled, bytecodeFormat);

        Assert.True(pass.State.DoBlend);
        Assert.Equal(RasterizerState.Blending.SrcAlpha, pass.State.BlendSrc);
        Assert.Equal(RasterizerState.Blending.OneMinusSrcAlpha, pass.State.BlendDst);
        Assert.Equal(RasterizerState.BlendMode.Add, pass.State.Blend);

        byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
        Span<float> globalUniformValues = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
        const int ViewProjectionOffset = 3 * 16;
        for (int diagonal = 0; diagonal < 4; diagonal++)
            globalUniformValues[ViewProjectionOffset + (diagonal * 5)] = 1f;
        using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, dynamic: true);
        using var mainTexture = new Resources.Texture2D();
        using var normalTexture = new Resources.Texture2D();
        using var surfaceTexture = new Resources.Texture2D();
        using var emissionTexture = new Resources.Texture2D();
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetTexture("_MainTex", mainTexture);
        overridesMaterial.SetTexture("_NormalTex", normalTexture);
        overridesMaterial.SetTexture("_SurfaceTex", surfaceTexture);
        overridesMaterial.SetTexture("_EmissionTex", emissionTexture);
        overridesMaterial.SetColor("_MainColor", new Color(1f, 1f, 1f, 0.25f));
        Rendering.StandardMaterialUniformsData packedMaterial = Rendering.MaterialUniformPacking.PackStandard(overridesMaterial._properties, shader);
        Assert.Equal(0.25f, packedMaterial._MainColor.W);

        float[] vertices =
        [
            -1f, -1f, 0f, 0f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
            -1f, 1f, 0f, 0f, 1f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
            1f, -1f, 0f, 1f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
            1f, -1f, 0f, 1f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
            -1f, 1f, 0f, 0f, 1f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
            1f, 1f, 0f, 1f, 1f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
        ];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        using var depth = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Depth32f);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
            [
                new GraphicsFrameBuffer.Attachment { Texture = color },
                new GraphicsFrameBuffer.Attachment { Texture = depth, IsDepth = true },
            ],
            2,
            1);
        var format = new VertexFormat([
            new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
            new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
            new(VertexFormat.VertexSemantic.Normal, VertexFormat.VertexType.Float, 3),
            new(VertexFormat.VertexSemantic.Tangent, VertexFormat.VertexType.Float, 4),
        ]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-transparent-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
            create.EncodeCreateBuffer(globalUniformBuffer, dynamic: true, globalUniformBytes);
            EncodeContractTexture(create, mainTexture, new byte[] { 255, 255, 255, 255 });
            EncodeContractTexture(create, normalTexture, new byte[] { 128, 128, 255, 255 });
            EncodeContractTexture(create, surfaceTexture, new byte[] { 255, 255, 0, 255 });
            EncodeContractTexture(create, emissionTexture, new byte[] { 0, 0, 0, 255 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateTexture(depth);
            create.EncodeAllocateTexture2D(depth, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, wait: true);
        }
        SetGlobalUniformBuffer(globalUniformBuffer);

        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-transparent-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0.2f, 0.3f, 0.4f, 1f));
            draw.DisableScissor();
            draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
            draw.SetShader(variant);
            draw.SetRasterState(pass.State);
            draw.SetMaterialProperties(overridesMaterial);
            draw.SetViewport(0, 0, 2, 1);
            draw.DrawArrays(vertexArray, Topology.Triangles, 0, 6);
            device.Execute(draw, wait: true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.4f, 0.475f, 0.55f, 0.8125f);
        AssertMaterialPixel(pixels, 1, 0.4f, 0.475f, 0.55f, 0.8125f);

        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-transparent-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, wait: true);
        return pixels;
    }

    private static byte[]? TryRenderStandardLighting(GraphicsBackend backend) => backend switch
    {
        GraphicsBackend.Direct3D12 => TryRenderStandardLightingD3D12(),
        GraphicsBackend.Vulkan => TryRenderStandardLightingVulkan(),
        _ => throw new ArgumentOutOfRangeException(nameof(backend), backend, "Expected a modern backend."),
    };

    private static byte[]? TryRenderStandardLightingD3D12()
    {
        if (!OperatingSystem.IsWindows())
            return null;

        try
        {
            using var device = new Backends.D3D12.D3D12GraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
            device.Initialize(null);
            return RunStandardLightingContract(
                device,
                GraphicsBackend.Direct3D12,
                ShaderBytecodeFormat.Dxil,
                texture => device.ReadTexture2D(
                    device.Textures[texture.Handle].Resource!,
                    2,
                    1,
                    4,
                    device.Textures[texture.Handle].State));
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            return null;
        }
    }

    private static byte[]? TryRenderStandardLightingVulkan()
    {
        try
        {
            using var device = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            device.Initialize(null);
            return RunStandardLightingContract(
                device,
                GraphicsBackend.Vulkan,
                ShaderBytecodeFormat.SpirV,
                texture => device.ReadTexture2D(device.Images[texture.Handle], 4));
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            return null;
        }
    }

    private static byte[]? RunStandardLightingContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.Standard);
            Rendering.Shaders.ShaderPass pass = shader.GetPass("Standard");
            ShaderCompileResult compiled = CompileMaterialContractShader(
                ShaderCompilerFactory.GetCompiler(backend, shader.Name),
                backend,
                GetHlslSource(pass, "_hlslVertexSource"),
                GetHlslSource(pass, "_hlslFragmentSource"),
                // Match the UV2, normal and tangent streams supplied by this fixture below.
                extraDefines: ["HAS_UV2", "HAS_NORMALS", "HAS_TANGENTS"]);
            if (IsSpirvUnavailable(backend, compiled))
                return null;
            Assert.True(compiled.Success, compiled.ErrorMessage);
            ShaderVertexInputLayout vertexInputs = Assert.IsType<ShaderVertexInputLayout>(compiled.VertexInputLayout);
            Assert.Contains(vertexInputs.Inputs, input => input.Semantic == (uint)VertexFormat.VertexSemantic.Normal);

            ShaderBindingLayout layout = Assert.IsType<ShaderBindingLayout>(compiled.BindingLayout);
            Assert.Collection(layout.Buffers,
                slot => { Assert.Equal(0, slot.Slot); Assert.Equal("GlobalUniforms", slot.Name); },
                slot => { Assert.Equal(1, slot.Slot); Assert.Equal("ObjectUniforms", slot.Name); },
                slot => { Assert.Equal(2, slot.Slot); Assert.Equal("StandardMaterial", slot.Name); },
                slot => { Assert.Equal(3, slot.Slot); Assert.Equal("StandardLighting", slot.Name); },
                slot => { Assert.Equal(4, slot.Slot); Assert.Equal("StandardShadows", slot.Name); },
                slot => { Assert.Equal(5, slot.Slot); Assert.Equal("StandardReflectionProbes", slot.Name); },
                slot => { Assert.Equal(6, slot.Slot); Assert.Equal("StandardLightCookies", slot.Name); });
            Assert.Equal(22, layout.Textures.Length);
            Assert.Contains(layout.Textures, slot => slot.Slot == 0 && slot.Name == "_MainTex");
            Assert.Contains(layout.Textures, slot => slot.Slot == 11 && slot.Name == "_Lightmap");
            Assert.Contains(layout.Textures, slot => slot.Slot == 12 && slot.Name == "_LightCookieMain");
            Assert.Contains(layout.Textures, slot => slot.Slot == 13 && slot.Name == "_LightCookieAtlas");
            Assert.Contains(layout.Textures, slot => slot.Slot == 14 && slot.Name == "_ScreenSpaceShadowmap");
            Assert.Contains(layout.Textures, slot => slot.Slot == 26 && slot.Name == "_SpecCube0");
            Assert.Contains(layout.Textures, slot => slot.Slot == 27 && slot.Name == "_SpecCube1");
            Assert.Contains(layout.Textures, slot => slot.Slot == 28 && slot.Name == "_BRDFLut");
            // Clustered light list (P3.2).
            Assert.Contains(layout.Textures, slot => slot.Slot == 29 && slot.Name == "_ClusterLightList");
            // Realtime GI probe volume (GiProbes.hlsl): slots above every current consumer.
            Assert.Contains(layout.Textures, slot => slot.Slot == 32 && slot.Name == "_GiIrradianceAtlas");
            Assert.Contains(layout.Textures, slot => slot.Slot == 33 && slot.Name == "_GiProbeMoments");
            Assert.Contains(layout.Textures, slot => slot.Slot == 34 && slot.Name == "_GiProbeData");
            // 192-byte legacy block + 3 float4 cluster tail (P3.2).
            Assert.Equal(240, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.StandardLightingUniformsData>());
            Assert.Equal(112, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.StandardReflectionProbesUniformsData>());
            Assert.Equal(80, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.StandardLightCookiesUniformsData>());

            using var material = new Resources.Material(shader);
            using var mainTexture = new Resources.Texture2D();
            using var normalTexture = new Resources.Texture2D();
            using var surfaceTexture = new Resources.Texture2D();
            using var emissionTexture = new Resources.Texture2D();
            using var staticLightData = new Resources.Texture2D();
            using var staticLightNodes = new Resources.Texture2D();
            using var dynamicLightData = new Resources.Texture2D();
            using var dynamicLightNodes = new Resources.Texture2D();
            using var shadowAtlas = new Resources.Texture2D();
            using var parallaxMap = new Resources.Texture2D();
            using var translucencyMap = new Resources.Texture2D();
            using var lightmap = new Resources.Texture2D();
            using var specCube = new Resources.Cubemap();
            using var brdfLut = new Resources.Texture2D();
            material.SetTexture("_MainTex", mainTexture);
            material.SetTexture("_NormalTex", normalTexture);
            material.SetTexture("_SurfaceTex", surfaceTexture);
            material.SetTexture("_EmissionTex", emissionTexture);
            material.SetTexture("_ParallaxMap", parallaxMap);
            material.SetTexture("_TranslucencyMap", translucencyMap);
            material.SetTexture("_Lightmap", lightmap);

            byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
            Span<float> globalValues = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
            const int ViewProjectionOffset = 3 * 16;
            for (int diagonal = 0; diagonal < 4; diagonal++)
                globalValues[ViewProjectionOffset + diagonal * 5] = 1f;
            const int CameraPositionOffset = 8 * 16;
            globalValues[CameraPositionOffset + 2] = 1f;
            using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, true);

            float[] vertices =
            [
                -1f, -1f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
                3f, -1f, 0f, 2f, 0f, 0f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
                -1f, 3f, 0f, 0f, 2f, 0f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }],
                2,
                1);
            using var vertexArray = new GraphicsVertexArray(new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.TexCoord1, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.Normal, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.Tangent, VertexFormat.VertexType.Float, 4),
            ]), vertexBuffer, null);
            using ShaderVariant variant = CreateMaterialContractVariant(compiled, bytecodeFormat);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-lighting-create"))
            {
                create.EncodeCreateBuffer(globalUniformBuffer, true, globalUniformBytes);
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                EncodeContractTexture(create, mainTexture, [255, 255, 255, 255]);
                EncodeContractTexture(create, normalTexture, [128, 128, 255, 255]);
                EncodeContractTexture(create, surfaceTexture, [0, 255, 0, 255]);
                EncodeContractTexture(create, emissionTexture, [0, 0, 0, 255]);
                EncodeContractTexture(create, staticLightData, [0, 0, 0, 0]);
                EncodeContractTexture(create, staticLightNodes, [0, 0, 0, 0]);
                EncodeContractTexture(create, dynamicLightData, [0, 0, 0, 0]);
                EncodeContractTexture(create, dynamicLightNodes, [0, 0, 0, 0]);
                EncodeContractTexture(create, shadowAtlas, [255, 255, 255, 255]);
                EncodeContractTexture(create, parallaxMap, [0, 0, 0, 255]);
                EncodeContractTexture(create, translucencyMap, [255, 255, 255, 255]);
                EncodeContractTexture(create, lightmap, [255, 255, 255, 255]);
                EncodeContractCubemap(create, specCube);
                EncodeContractTexture(create, brdfLut, [255, 255, 255, 255]);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, true);
            }
            SetGlobalUniformBuffer(globalUniformBuffer);

            RasterizerState raster = pass.State;
            raster.DepthTest = false;
            raster.DepthWrite = false;
            raster.CullFace = RasterizerState.PolyFace.None;
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-lighting-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
                draw.SetGlobalTexture("_StaticLightData", staticLightData);
                draw.SetGlobalTexture("_StaticLightNodes", staticLightNodes);
                draw.SetGlobalTexture("_DynamicLightData", dynamicLightData);
                draw.SetGlobalTexture("_DynamicLightNodes", dynamicLightNodes);
                // Cluster list disabled (grid params default 0) -> BVH fallback path in-shader,
                // but the reflected descriptor still needs a valid texture on explicit APIs.
                draw.SetGlobalTexture("_ClusterLightList", staticLightData);
                draw.SetGlobalTexture("_ShadowAtlas", shadowAtlas);
                BindDummyReflectionProbes(draw, specCube, brdfLut);
                BindDummyLightCookies(draw, brdfLut);
                BindDummyGiProbes(draw, staticLightData);
                BindDummyGiProbes(draw, staticLightData);
                draw.SetGlobalInt("_StaticLightRoot", -1);
                draw.SetGlobalInt("_DynamicLightRoot", -1);
                draw.SetGlobalInt("_StaticLightTexSize", 1);
                draw.SetGlobalInt("_StaticLightTexShift", 0);
                draw.SetGlobalInt("_StaticNodeTexSize", 1);
                draw.SetGlobalInt("_StaticNodeTexShift", 0);
                draw.SetGlobalInt("_DynamicLightTexSize", 1);
                draw.SetGlobalInt("_DynamicLightTexShift", 0);
                draw.SetGlobalInt("_DynamicNodeTexSize", 1);
                draw.SetGlobalInt("_DynamicNodeTexShift", 0);
                draw.SetGlobalInt("_DirectionalLightEnabled", 0);
                // Shadow defaults: no directional shadow, no cascades. Keeps the shadow sampler on
                // the early-out path so the existing ambient + directional lighting contract still
                // holds now that the Standard variant reflects StandardShadows / _ShadowAtlas.
                draw.SetGlobalInt("_DirectionalLightShadowEnabled", 0);
                draw.SetGlobalInt("_CascadeCount", 0);
                draw.SetGlobalVector("_ShadowAtlasSize", new Float2(1f, 1f));
                draw.SetGlobalVector("_AmbientMode", new Float2(1f, 0f));
                draw.SetGlobalFloat("_AmbientStrength", 1f);
                draw.SetGlobalColor("_AmbientColor", new Color(0.125f, 0.25f, 0.375f, 1f));
                draw.SetGlobalVector("_FogStates", Float3.Zero);
                draw.SetShader(variant);
                draw.SetRasterState(in raster);
                draw.SetMaterialProperties(material);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);

                draw.SetGlobalColor("_AmbientColor", Color.Black);
                draw.SetGlobalInt("_DirectionalLightEnabled", 1);
                draw.SetGlobalVector("_DirectionalLightDirection", new Float3(0f, 0f, 1f));
                draw.SetGlobalVector("_DirectionalLightColor", new Float3(1f, 0f, 0f));
                draw.SetGlobalFloat("_DirectionalLightIntensity", 0.125f);
                draw.SetViewport(1, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, true);
            }

            byte[] pixels = readback(color);
            AssertMaterialPixel(pixels, 0, 0.125f, 0.25f, 0.375f, 1f);
            Assert.InRange(pixels[4], (byte)70, (byte)100);
            Assert.InRange(pixels[5], (byte)0, (byte)1);
            Assert.InRange(pixels[6], (byte)0, (byte)1);
            Assert.Equal((byte)255, pixels[7]);

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-lighting-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
            return pixels;
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
            Rendering.PropertyState.ClearGlobalsInternal();
        }
    }

    // Standard shadow contract (C1da). Exercises the new StandardShadows b4 block and _ShadowAtlas
    // t8 binding end-to-end: a directional light lights three pixels against an atlas tile holding
    // depth 0.25. The first has shadows disabled, the second verifies that modern [0,1] clip depth
    // remains unmodified (z=0 is lit), and the third uses light-space z=0.5 and is shadowed.
    private static void RunStandardShadowsContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.Standard);
            Rendering.Shaders.ShaderPass pass = shader.GetPass("Standard");
            ShaderCompileResult compiled = CompileMaterialContractShader(
                new DxcShaderCompiler(),
                backend,
                GetHlslSource(pass, "_hlslVertexSource"),
                GetHlslSource(pass, "_hlslFragmentSource"));
            if (IsSpirvUnavailable(backend, compiled))
                return;
            Assert.True(compiled.Success, compiled.ErrorMessage);

            ShaderBindingLayout layout = Assert.IsType<ShaderBindingLayout>(compiled.BindingLayout);
            Assert.Contains(layout.Buffers, slot => slot.Slot == 4 && slot.Name == "StandardShadows");
            Assert.Contains(layout.Buffers, slot => slot.Slot == 5 && slot.Name == "StandardReflectionProbes");
            Assert.Contains(layout.Buffers, slot => slot.Slot == 6 && slot.Name == "StandardLightCookies");
            Assert.Contains(layout.Textures, slot => slot.Slot == 8 && slot.Name == "_ShadowAtlas");
            Assert.Contains(layout.Textures, slot => slot.Slot == 12 && slot.Name == "_LightCookieMain");
            Assert.Contains(layout.Textures, slot => slot.Slot == 14 && slot.Name == "_ScreenSpaceShadowmap");
            Assert.Contains(layout.Textures, slot => slot.Slot == 26 && slot.Name == "_SpecCube0");

            // Shadow block size must match the HLSL StandardShadows cbuffer. The marshal size is
            // fixed by the C# struct layout; the assertion documents the contract and catches any
            // accidental ABI drift if MAX_SHADOW_CASTERS or the cascade slot count changes.
            int shadowSize = System.Runtime.InteropServices.Marshal.SizeOf<Rendering.StandardShadowsUniformsData>();
            Assert.True(shadowSize > 0 && shadowSize % 16 == 0, $"StandardShadowsUniformsData must be a positive 16-byte multiple, was {shadowSize}.");

            using var material = new Resources.Material(shader);
            using var mainTexture = new Resources.Texture2D();
            using var normalTexture = new Resources.Texture2D();
            using var surfaceTexture = new Resources.Texture2D();
            using var emissionTexture = new Resources.Texture2D();
            using var staticLightData = new Resources.Texture2D();
            using var staticLightNodes = new Resources.Texture2D();
            using var dynamicLightData = new Resources.Texture2D();
            using var dynamicLightNodes = new Resources.Texture2D();
            // Atlas tile holding depth ~= 0.25. This separates native modern [0,1] clip depth from
            // the legacy GL [-1,1] remap: z=0 is lit while z=0.5 is occluded.
            using var shadowAtlas = new Resources.Texture2D();
            using var parallaxMap = new Resources.Texture2D();
            using var translucencyMap = new Resources.Texture2D();
            using var lightmap = new Resources.Texture2D();
            using var specCube = new Resources.Cubemap();
            using var brdfLut = new Resources.Texture2D();
            material.SetTexture("_MainTex", mainTexture);
            material.SetTexture("_NormalTex", normalTexture);
            material.SetTexture("_SurfaceTex", surfaceTexture);
            material.SetTexture("_EmissionTex", emissionTexture);
            material.SetTexture("_ParallaxMap", parallaxMap);
            material.SetTexture("_TranslucencyMap", translucencyMap);
            material.SetTexture("_Lightmap", lightmap);

            byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
            Span<float> globalValues = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
            const int ViewProjectionOffset = 3 * 16;
            for (int diagonal = 0; diagonal < 4; diagonal++)
                globalValues[ViewProjectionOffset + diagonal * 5] = 1f;
            // Camera sits at +Z so viewDirection is well-defined (matching the lighting contract). The
            // identity cascade matrix still maps the z=0 fullscreen triangle into the upper-left
            // quadrant of clip space so projCoords land inside [0,1] without an early-out.
            const int CameraPositionOffset = 8 * 16;
            globalValues[CameraPositionOffset + 0] = 0f;
            globalValues[CameraPositionOffset + 1] = 0f;
            globalValues[CameraPositionOffset + 2] = 1f;
            using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, true);

            // Same front-facing layout as the lighting contract: normal +Z, tangent +X.
            float[] vertices =
            [
                -1f, -1f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
                3f, -1f, 0f, 2f, 0f, 0f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
                -1f, 3f, 0f, 0f, 2f, 0f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }],
                3,
                1);
            using var vertexArray = new GraphicsVertexArray(new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.TexCoord1, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.Normal, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.Tangent, VertexFormat.VertexType.Float, 4),
            ]), vertexBuffer, null);
            using ShaderVariant variant = CreateMaterialContractVariant(compiled, bytecodeFormat);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-shadows-create"))
            {
                create.EncodeCreateBuffer(globalUniformBuffer, true, globalUniformBytes);
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                EncodeContractTexture(create, mainTexture, [255, 255, 255, 255]);
                EncodeContractTexture(create, normalTexture, [128, 128, 255, 255]);
                EncodeContractTexture(create, surfaceTexture, [0, 255, 0, 255]);
                EncodeContractTexture(create, emissionTexture, [0, 0, 0, 255]);
                EncodeContractTexture(create, staticLightData, [0, 0, 0, 0]);
                EncodeContractTexture(create, staticLightNodes, [0, 0, 0, 0]);
                EncodeContractTexture(create, dynamicLightData, [0, 0, 0, 0]);
                EncodeContractTexture(create, dynamicLightNodes, [0, 0, 0, 0]);
                EncodeContractTexture(create, shadowAtlas, [64, 0, 0, 255]);
                EncodeContractTexture(create, parallaxMap, [0, 0, 0, 255]);
                EncodeContractTexture(create, translucencyMap, [255, 255, 255, 255]);
                EncodeContractTexture(create, lightmap, [255, 255, 255, 255]);
                EncodeContractCubemap(create, specCube);
                EncodeContractTexture(create, brdfLut, [255, 255, 255, 255]);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 3, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, true);
            }
            SetGlobalUniformBuffer(globalUniformBuffer);

            // Cascade atlas params: xy = atlas tile origin (0,0), z = tile resolution in texels,
            // w = world span. Keep z large relative to w so the slope/texel depth bias stays small
            // (with z=w=1 the bias is ~32 and currentDepth goes hugely negative, which always
            // compares as lit against the depth-0 atlas).
            Float4 cascadeAtlasParams = new Float4(0f, 0f, 1024f, 1f);

            RasterizerState raster = pass.State;
            raster.DepthTest = false;
            raster.DepthWrite = false;
            raster.CullFace = RasterizerState.PolyFace.None;
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-shadows-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
                draw.SetGlobalTexture("_StaticLightData", staticLightData);
                draw.SetGlobalTexture("_StaticLightNodes", staticLightNodes);
                draw.SetGlobalTexture("_DynamicLightData", dynamicLightData);
                draw.SetGlobalTexture("_DynamicLightNodes", dynamicLightNodes);
                // Cluster list disabled (grid params default 0) -> BVH fallback path in-shader,
                // but the reflected descriptor still needs a valid texture on explicit APIs.
                draw.SetGlobalTexture("_ClusterLightList", staticLightData);
                draw.SetGlobalTexture("_ShadowAtlas", shadowAtlas);
                BindDummyReflectionProbes(draw, specCube, brdfLut);
                BindDummyLightCookies(draw, brdfLut);
                BindDummyGiProbes(draw, staticLightData);
                draw.SetGlobalInt("_StaticLightRoot", -1);
                draw.SetGlobalInt("_DynamicLightRoot", -1);
                draw.SetGlobalInt("_StaticLightTexSize", 1);
                draw.SetGlobalInt("_StaticLightTexShift", 0);
                draw.SetGlobalInt("_StaticNodeTexSize", 1);
                draw.SetGlobalInt("_StaticNodeTexShift", 0);
                draw.SetGlobalInt("_DynamicLightTexSize", 1);
                draw.SetGlobalInt("_DynamicLightTexShift", 0);
                draw.SetGlobalInt("_DynamicNodeTexSize", 1);
                draw.SetGlobalInt("_DynamicNodeTexShift", 0);
                draw.SetGlobalVector("_AmbientMode", Float2.Zero);
                draw.SetGlobalFloat("_AmbientStrength", 0f);
                draw.SetGlobalColor("_AmbientColor", Color.Black);
                draw.SetGlobalVector("_FogStates", Float3.Zero);
                draw.SetGlobalVector("_ShadowAtlasSize", new Float2(1f, 1f));

                // Common directional light state for both pixels.
                draw.SetGlobalInt("_DirectionalLightEnabled", 1);
                draw.SetGlobalVector("_DirectionalLightDirection", new Float3(0f, 0f, 1f));
                draw.SetGlobalVector("_DirectionalLightColor", new Float3(1f, 0f, 0f));
                draw.SetGlobalFloat("_DirectionalLightIntensity", 0.125f);

                // Pixel 0: shadows disabled. Identity cascade + count 0 keeps the sampler on the
                // early-out path so the red directional contribution survives.
                draw.SetGlobalInt("_DirectionalLightShadowEnabled", 0);
                draw.SetGlobalInt("_CascadeCount", 0);
                draw.SetShader(variant);
                draw.SetRasterState(in raster);
                draw.SetMaterialProperties(material);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);

                // Pixel 1: shadows enabled with an identity cascade. Native modern clip z=0 must
                // remain 0, compare lit against the atlas depth, and preserve the red contribution.
                draw.SetGlobalInt("_DirectionalLightShadowEnabled", 1);
                draw.SetGlobalFloat("_DirectionalLightShadowBias", 0f);
                draw.SetGlobalFloat("_DirectionalLightShadowNormalBias", 0f);
                draw.SetGlobalFloat("_DirectionalLightShadowStrength", 1f);
                draw.SetGlobalFloat("_DirectionalLightShadowQuality", 0f);
                draw.SetGlobalInt("_CascadeCount", 1);
                draw.SetGlobalMatrix("_CascadeShadowMatrix0", Float4x4.Identity);
                draw.SetGlobalMatrix("_CascadeShadowMatrix1", Float4x4.Identity);
                draw.SetGlobalMatrix("_CascadeShadowMatrix2", Float4x4.Identity);
                draw.SetGlobalMatrix("_CascadeShadowMatrix3", Float4x4.Identity);
                draw.SetGlobalVector("_CascadeAtlasParams0", cascadeAtlasParams);
                draw.SetGlobalVector("_CascadeAtlasParams1", cascadeAtlasParams);
                draw.SetGlobalVector("_CascadeAtlasParams2", cascadeAtlasParams);
                draw.SetGlobalVector("_CascadeAtlasParams3", cascadeAtlasParams);
                draw.SetViewport(1, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);

                // Pixel 2: translate the same cascade to z=0.5. It is behind the stored depth and
                // must be fully shadowed, proving that the b4/t8 path still applies occlusion.
                Float4x4 occludedCascade = Float4x4.Identity;
                occludedCascade[2, 3] = 0.5f;
                draw.SetGlobalMatrix("_CascadeShadowMatrix0", occludedCascade);
                draw.SetViewport(2, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, true);
            }

            byte[] pixels = readback(color);
            // Pixel 0 (no shadow): red directional contribution survives. The non-zero band matches
            // the existing Standard lighting contract; the exact value depends on PBR math.
            Assert.InRange(pixels[0], (byte)50, (byte)120);
            Assert.InRange(pixels[1], (byte)0, (byte)2);
            Assert.InRange(pixels[2], (byte)0, (byte)2);
            Assert.Equal((byte)255, pixels[3]);
            // Pixel 1 (native clip z=0): still lit. A legacy *0.5+0.5 depth remap would incorrectly
            // move it behind the atlas depth and make this pixel black.
            Assert.InRange(pixels[4], (byte)50, (byte)120);
            Assert.InRange(pixels[5], (byte)0, (byte)2);
            Assert.InRange(pixels[6], (byte)0, (byte)2);
            Assert.Equal((byte)255, pixels[7]);
            // Pixel 2 (native clip z=0.5): red contribution is removed by the shadow factor.
            Assert.InRange(pixels[8], (byte)0, (byte)2);
            Assert.InRange(pixels[9], (byte)0, (byte)2);
            Assert.InRange(pixels[10], (byte)0, (byte)2);
            Assert.Equal((byte)255, pixels[11]);
            SaveScreenshotPng("c1da-standard-shadows", UpscalePixels(pixels, 3, 1, 384, 128), 384, 128);

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-shadows-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
        }
    }

    // Standard POM contract (C1db). Exercises the new _ParallaxMap t9 descriptor and the HLSL
    // StandardParallaxOcclusionMapping ray-march end-to-end. The fullscreen triangle is drawn with
    // a small positive _Parallax and a uniform mid-gray height field; the test proves the POM path
    // runs without crashing, resolves a finite final UV, and still lights through the rest of the
    // Standard pipeline (directional light + ambient). The GLSL path remains the reference for
    // visual UV-offset correctness; this contract validates the modern-backend plumbing.
    private static void RunStandardPomContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.Standard);
            Rendering.Shaders.ShaderPass pass = shader.GetPass("Standard");
            ShaderCompileResult compiled = CompileMaterialContractShader(
                new DxcShaderCompiler(),
                backend,
                GetHlslSource(pass, "_hlslVertexSource"),
                GetHlslSource(pass, "_hlslFragmentSource"));
            if (IsSpirvUnavailable(backend, compiled))
                return;
            Assert.True(compiled.Success, compiled.ErrorMessage);

            ShaderBindingLayout layout = Assert.IsType<ShaderBindingLayout>(compiled.BindingLayout);
            Assert.Contains(layout.Textures, slot => slot.Slot == 9 && slot.Name == "_ParallaxMap");

            using var material = new Resources.Material(shader);
            // Small positive height scale + a real step count so the POM ray march actually runs.
            material.SetFloat("_Parallax", 0.05f);
            material.SetInt("_ParallaxSteps", 8);
            using var mainTexture = new Resources.Texture2D();
            using var normalTexture = new Resources.Texture2D();
            using var surfaceTexture = new Resources.Texture2D();
            using var emissionTexture = new Resources.Texture2D();
            using var parallaxMap = new Resources.Texture2D();
            using var staticLightData = new Resources.Texture2D();
            using var staticLightNodes = new Resources.Texture2D();
            using var dynamicLightData = new Resources.Texture2D();
            using var dynamicLightNodes = new Resources.Texture2D();
            using var shadowAtlas = new Resources.Texture2D();
            using var translucencyMap = new Resources.Texture2D();
            using var lightmap = new Resources.Texture2D();
            using var specCube = new Resources.Cubemap();
            using var brdfLut = new Resources.Texture2D();
            material.SetTexture("_MainTex", mainTexture);
            material.SetTexture("_NormalTex", normalTexture);
            material.SetTexture("_SurfaceTex", surfaceTexture);
            material.SetTexture("_EmissionTex", emissionTexture);
            material.SetTexture("_ParallaxMap", parallaxMap);
            material.SetTexture("_TranslucencyMap", translucencyMap);
            material.SetTexture("_Lightmap", lightmap);

            byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
            Span<float> globalValues = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
            const int ViewProjectionOffset = 3 * 16;
            for (int diagonal = 0; diagonal < 4; diagonal++)
                globalValues[ViewProjectionOffset + diagonal * 5] = 1f;
            // Camera in front of the triangle so the tangent-space view direction has a usable Z
            // component (POM divides by viewDirTS.z).
            const int CameraPositionOffset = 8 * 16;
            globalValues[CameraPositionOffset + 2] = 1f;
            using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, true);

            float[] vertices =
            [
                -1f, -1f, 0f, 0f, 0f, 0f, 0f, 1f, 0f, 1f, 0f, 0f, 1f, 0f,
                3f, -1f, 0f, 2f, 0f, 0f, 0f, 1f, 0f, 1f, 0f, 0f, 1f, 0f,
                -1f, 3f, 0f, 0f, 2f, 0f, 0f, 1f, 0f, 1f, 0f, 0f, 1f, 0f,
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }],
                1,
                1);
            using var vertexArray = new GraphicsVertexArray(new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.TexCoord1, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.Normal, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.Tangent, VertexFormat.VertexType.Float, 4),
            ]), vertexBuffer, null);
            using ShaderVariant variant = CreateMaterialContractVariant(compiled, bytecodeFormat);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-pom-create"))
            {
                create.EncodeCreateBuffer(globalUniformBuffer, true, globalUniformBytes);
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                EncodeContractTexture(create, mainTexture, [255, 255, 255, 255]);
                EncodeContractTexture(create, normalTexture, [128, 128, 255, 255]);
                EncodeContractTexture(create, surfaceTexture, [0, 255, 0, 255]);
                EncodeContractTexture(create, emissionTexture, [0, 0, 0, 255]);
                // Uniform mid-gray height field so the linear march has a stable intersection.
                EncodeContractTexture(create, parallaxMap, [0, 128, 0, 255]);
                EncodeContractTexture(create, staticLightData, [0, 0, 0, 0]);
                EncodeContractTexture(create, staticLightNodes, [0, 0, 0, 0]);
                EncodeContractTexture(create, dynamicLightData, [0, 0, 0, 0]);
                EncodeContractTexture(create, dynamicLightNodes, [0, 0, 0, 0]);
                EncodeContractTexture(create, shadowAtlas, [255, 255, 255, 255]);
                EncodeContractTexture(create, translucencyMap, [255, 255, 255, 255]);
                EncodeContractTexture(create, lightmap, [255, 255, 255, 255]);
                EncodeContractCubemap(create, specCube);
                EncodeContractTexture(create, brdfLut, [255, 255, 255, 255]);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, true);
            }
            SetGlobalUniformBuffer(globalUniformBuffer);

            RasterizerState raster = pass.State;
            raster.DepthTest = false;
            raster.DepthWrite = false;
            raster.CullFace = RasterizerState.PolyFace.None;
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-pom-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
                draw.SetGlobalTexture("_StaticLightData", staticLightData);
                draw.SetGlobalTexture("_StaticLightNodes", staticLightNodes);
                draw.SetGlobalTexture("_DynamicLightData", dynamicLightData);
                draw.SetGlobalTexture("_DynamicLightNodes", dynamicLightNodes);
                // Cluster list disabled (grid params default 0) -> BVH fallback path in-shader,
                // but the reflected descriptor still needs a valid texture on explicit APIs.
                draw.SetGlobalTexture("_ClusterLightList", staticLightData);
                draw.SetGlobalTexture("_ShadowAtlas", shadowAtlas);
                BindDummyReflectionProbes(draw, specCube, brdfLut);
                BindDummyLightCookies(draw, brdfLut);
                BindDummyGiProbes(draw, staticLightData);
                draw.SetGlobalInt("_StaticLightRoot", -1);
                draw.SetGlobalInt("_DynamicLightRoot", -1);
                draw.SetGlobalInt("_StaticLightTexSize", 1);
                draw.SetGlobalInt("_StaticLightTexShift", 0);
                draw.SetGlobalInt("_StaticNodeTexSize", 1);
                draw.SetGlobalInt("_StaticNodeTexShift", 0);
                draw.SetGlobalInt("_DynamicLightTexSize", 1);
                draw.SetGlobalInt("_DynamicLightTexShift", 0);
                draw.SetGlobalInt("_DynamicNodeTexSize", 1);
                draw.SetGlobalInt("_DynamicNodeTexShift", 0);
                draw.SetGlobalInt("_DirectionalLightEnabled", 1);
                draw.SetGlobalVector("_DirectionalLightDirection", new Float3(0f, 0f, 1f));
                draw.SetGlobalVector("_DirectionalLightColor", new Float3(1f, 1f, 1f));
                draw.SetGlobalFloat("_DirectionalLightIntensity", 0.125f);
                draw.SetGlobalInt("_DirectionalLightShadowEnabled", 0);
                draw.SetGlobalInt("_CascadeCount", 0);
                draw.SetGlobalVector("_ShadowAtlasSize", new Float2(1f, 1f));
                draw.SetGlobalVector("_AmbientMode", new Float2(1f, 0f));
                draw.SetGlobalFloat("_AmbientStrength", 1f);
                draw.SetGlobalColor("_AmbientColor", new Color(0.5f, 0.5f, 0.5f, 1f));
                draw.SetGlobalVector("_FogStates", Float3.Zero);
                draw.SetShader(variant);
                draw.SetRasterState(in raster);
                draw.SetMaterialProperties(material);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, true);
            }

            byte[] pixels = readback(color);
            // POM resolved a finite UV and the pixel lit through the Standard pipeline: ambient +
            // directional on a white albedo. The exact value depends on PBR math; assert a finite,
            // non-zero, fully-opaque result that proves the ray march did not produce NaN/zero.
            Assert.Equal((byte)255, pixels[3]);
            Assert.InRange(pixels[0], (byte)100, (byte)255);
            Assert.InRange(pixels[1], (byte)100, (byte)255);
            Assert.InRange(pixels[2], (byte)100, (byte)255);

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-pom-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
        }
    }

    // Standard translucency contract (C1dc). Exercises the new _TranslucencyMap t10 descriptor and
    // the HLSL StandardCalculateTranslucency path. The fullscreen triangle is lit by a directional
    // light from behind (surface normal facing away from the light, so the front-lit PBR term is
    // zero), and translucency scatter is the only thing that can light the surface. Pixel 0 has
    // _TranslucencyStrength = 0 (no scatter) and stays at ambient; pixel 1 has a positive strength
    // against a high-thickness translucency map and gains the scatter contribution.
    private static void RunStandardTranslucencyContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.Standard);
            Rendering.Shaders.ShaderPass pass = shader.GetPass("Standard");
            ShaderCompileResult compiled = CompileMaterialContractShader(
                new DxcShaderCompiler(),
                backend,
                GetHlslSource(pass, "_hlslVertexSource"),
                GetHlslSource(pass, "_hlslFragmentSource"));
            if (IsSpirvUnavailable(backend, compiled))
                return;
            Assert.True(compiled.Success, compiled.ErrorMessage);

            ShaderBindingLayout layout = Assert.IsType<ShaderBindingLayout>(compiled.BindingLayout);
            Assert.Contains(layout.Textures, slot => slot.Slot == 10 && slot.Name == "_TranslucencyMap");

            using var material = new Resources.Material(shader);
            // Wrapped-diffuse backscatter mode (scatteringPower == 0) with a real distortion/scale.
            material.SetFloat("_ScatteringPower", 0f);
            material.SetFloat("_ScatteringDistortion", 0.5f);
            material.SetFloat("_ScatteringScale", 1f);
            using var mainTexture = new Resources.Texture2D();
            using var normalTexture = new Resources.Texture2D();
            using var surfaceTexture = new Resources.Texture2D();
            using var emissionTexture = new Resources.Texture2D();
            using var parallaxMap = new Resources.Texture2D();
            using var translucencyMap = new Resources.Texture2D();
            using var staticLightData = new Resources.Texture2D();
            using var staticLightNodes = new Resources.Texture2D();
            using var dynamicLightData = new Resources.Texture2D();
            using var dynamicLightNodes = new Resources.Texture2D();
            using var shadowAtlas = new Resources.Texture2D();
            using var lightmap = new Resources.Texture2D();
            using var specCube = new Resources.Cubemap();
            using var brdfLut = new Resources.Texture2D();
            material.SetTexture("_MainTex", mainTexture);
            material.SetTexture("_NormalTex", normalTexture);
            material.SetTexture("_SurfaceTex", surfaceTexture);
            material.SetTexture("_EmissionTex", emissionTexture);
            material.SetTexture("_ParallaxMap", parallaxMap);
            material.SetTexture("_TranslucencyMap", translucencyMap);
            material.SetTexture("_Lightmap", lightmap);

            byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
            Span<float> globalValues = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
            const int ViewProjectionOffset = 3 * 16;
            for (int diagonal = 0; diagonal < 4; diagonal++)
                globalValues[ViewProjectionOffset + diagonal * 5] = 1f;
            // Camera in front of the triangle so the view direction is +Z.
            const int CameraPositionOffset = 8 * 16;
            globalValues[CameraPositionOffset + 2] = 1f;
            using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, true);

            // Vertex normals point AWAY from the light (normal = -Z while the directional light shines
            // along +Z), so NdotL <= 0 and the front-lit PBR term is zero. Only translucency scatter
            // can add light, which makes the contract a clean either/or probe.
            float[] vertices =
            [
                -1f, -1f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, -1f, 1f, 0f, 0f, 1f,
                3f, -1f, 0f, 2f, 0f, 0f, 0f, 0f, 0f, -1f, 1f, 0f, 0f, 1f,
                -1f, 3f, 0f, 0f, 2f, 0f, 0f, 0f, 0f, -1f, 1f, 0f, 0f, 1f,
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }],
                2,
                1);
            using var vertexArray = new GraphicsVertexArray(new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.TexCoord1, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.Normal, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.Tangent, VertexFormat.VertexType.Float, 4),
            ]), vertexBuffer, null);
            using ShaderVariant variant = CreateMaterialContractVariant(compiled, bytecodeFormat);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-translucency-create"))
            {
                create.EncodeCreateBuffer(globalUniformBuffer, true, globalUniformBytes);
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                EncodeContractTexture(create, mainTexture, [255, 255, 255, 255]);
                EncodeContractTexture(create, normalTexture, [128, 128, 255, 255]);
                EncodeContractTexture(create, surfaceTexture, [0, 255, 0, 255]);
                EncodeContractTexture(create, emissionTexture, [0, 0, 0, 255]);
                EncodeContractTexture(create, parallaxMap, [0, 0, 0, 255]);
                // B = 255 (full thickness) so translucency is limited only by _TranslucencyStrength.
                EncodeContractTexture(create, translucencyMap, [255, 255, 255, 255]);
                EncodeContractTexture(create, staticLightData, [0, 0, 0, 0]);
                EncodeContractTexture(create, staticLightNodes, [0, 0, 0, 0]);
                EncodeContractTexture(create, dynamicLightData, [0, 0, 0, 0]);
                EncodeContractTexture(create, dynamicLightNodes, [0, 0, 0, 0]);
                EncodeContractTexture(create, shadowAtlas, [255, 255, 255, 255]);
                EncodeContractTexture(create, lightmap, [255, 255, 255, 255]);
                EncodeContractCubemap(create, specCube);
                EncodeContractTexture(create, brdfLut, [255, 255, 255, 255]);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, true);
            }
            SetGlobalUniformBuffer(globalUniformBuffer);

            RasterizerState raster = pass.State;
            raster.DepthTest = false;
            raster.DepthWrite = false;
            raster.CullFace = RasterizerState.PolyFace.None;
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-translucency-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
                draw.SetGlobalTexture("_StaticLightData", staticLightData);
                draw.SetGlobalTexture("_StaticLightNodes", staticLightNodes);
                draw.SetGlobalTexture("_DynamicLightData", dynamicLightData);
                draw.SetGlobalTexture("_DynamicLightNodes", dynamicLightNodes);
                // Cluster list disabled (grid params default 0) -> BVH fallback path in-shader,
                // but the reflected descriptor still needs a valid texture on explicit APIs.
                draw.SetGlobalTexture("_ClusterLightList", staticLightData);
                draw.SetGlobalTexture("_ShadowAtlas", shadowAtlas);
                BindDummyReflectionProbes(draw, specCube, brdfLut);
                BindDummyLightCookies(draw, brdfLut);
                BindDummyGiProbes(draw, staticLightData);
                draw.SetGlobalInt("_StaticLightRoot", -1);
                draw.SetGlobalInt("_DynamicLightRoot", -1);
                draw.SetGlobalInt("_StaticLightTexSize", 1);
                draw.SetGlobalInt("_StaticLightTexShift", 0);
                draw.SetGlobalInt("_StaticNodeTexSize", 1);
                draw.SetGlobalInt("_StaticNodeTexShift", 0);
                draw.SetGlobalInt("_DynamicLightTexSize", 1);
                draw.SetGlobalInt("_DynamicLightTexShift", 0);
                draw.SetGlobalInt("_DynamicNodeTexSize", 1);
                draw.SetGlobalInt("_DynamicNodeTexShift", 0);
                draw.SetGlobalInt("_DirectionalLightEnabled", 1);
                // Light shines along +Z; surface normal is -Z so the front face is unlit by PBR.
                draw.SetGlobalVector("_DirectionalLightDirection", new Float3(0f, 0f, 1f));
                draw.SetGlobalVector("_DirectionalLightColor", new Float3(0f, 1f, 0f));
                draw.SetGlobalFloat("_DirectionalLightIntensity", 1f);
                draw.SetGlobalInt("_DirectionalLightShadowEnabled", 0);
                draw.SetGlobalInt("_CascadeCount", 0);
                draw.SetGlobalVector("_ShadowAtlasSize", new Float2(1f, 1f));
                draw.SetGlobalVector("_AmbientMode", Float2.Zero);
                draw.SetGlobalFloat("_AmbientStrength", 0f);
                draw.SetGlobalColor("_AmbientColor", Color.Black);
                draw.SetGlobalVector("_FogStates", Float3.Zero);

                // Pixel 0: no translucency. With ambient off and the back facing the light, the
                // pixel is black.
                material.SetFloat("_TranslucencyStrength", 0f);
                draw.SetShader(variant);
                draw.SetRasterState(in raster);
                draw.SetMaterialProperties(material);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);

                // Pixel 1: translucency enabled. The scatter term adds green light through the
                // surface, so the pixel becomes measurably brighter than pixel 0.
                material.SetFloat("_TranslucencyStrength", 1f);
                draw.SetMaterialProperties(material);
                draw.SetViewport(1, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, true);
            }

            byte[] pixels = readback(color);
            // Pixel 0: no translucency, no ambient, back-facing -> near black.
            Assert.InRange(pixels[0], (byte)0, (byte)2);
            Assert.InRange(pixels[1], (byte)0, (byte)2);
            Assert.InRange(pixels[2], (byte)0, (byte)2);
            Assert.Equal((byte)255, pixels[3]);
            // Pixel 1: translucency scatter adds green through the surface -> green channel rises.
            Assert.InRange(pixels[4], (byte)0, (byte)2);
            Assert.InRange(pixels[5], (byte)20, (byte)200);
            Assert.InRange(pixels[6], (byte)0, (byte)2);
            Assert.Equal((byte)255, pixels[7]);
            // Pixel 1 must be strictly brighter in green than pixel 0 to prove the scatter fired.
            Assert.True(pixels[5] > pixels[1], "Translucency scatter did not raise the green channel above the no-translucency baseline.");

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-translucency-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
        }
    }

    // Standard baked-GI contract (C1dd). Exercises the per-object baked-GI plumbing end-to-end:
    // ObjectUniforms b1 now carries _GIMode/_LightmapUV/_LightmapScaleOffset/xengine_SH*, and the
    // _Lightmap texture binds through a new t11 descriptor. Two pixels share the same geometry but
    // different per-object GI state: pixel 0 uses realtime ambient (_GIMode == 0) with a small blue
    // ambient color, pixel 1 samples a baked RGBM lightmap (_GIMode == 1) holding a strong red. The
    // contract proves the modern backends route per-object GI state through b1 + t11 and that the
    // lightmap's RGBM decode changes the ambient contribution the way the GLSL path does.
    private static void RunStandardBakedGiContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.Standard);
            Rendering.Shaders.ShaderPass pass = shader.GetPass("Standard");
            ShaderCompileResult compiled = CompileMaterialContractShader(
                new DxcShaderCompiler(),
                backend,
                GetHlslSource(pass, "_hlslVertexSource"),
                GetHlslSource(pass, "_hlslFragmentSource"));
            if (IsSpirvUnavailable(backend, compiled))
                return;
            Assert.True(compiled.Success, compiled.ErrorMessage);

            ShaderBindingLayout layout = Assert.IsType<ShaderBindingLayout>(compiled.BindingLayout);
            Assert.Contains(layout.Buffers, slot => slot.Slot == 1 && slot.Name == "ObjectUniforms");
            Assert.Contains(layout.Textures, slot => slot.Slot == 11 && slot.Name == "_Lightmap");
            // ObjectUniforms grew to carry GI state; document the new ABI so accidental drift fails loud.
            int objectSize = System.Runtime.InteropServices.Marshal.SizeOf<Rendering.ObjectUniformsData>();
            Assert.True(objectSize >= 336, $"ObjectUniformsData must carry the GI fields (>=336 bytes), was {objectSize}.");

            using var material = new Resources.Material(shader);
            using var mainTexture = new Resources.Texture2D();
            using var normalTexture = new Resources.Texture2D();
            using var surfaceTexture = new Resources.Texture2D();
            using var emissionTexture = new Resources.Texture2D();
            using var parallaxMap = new Resources.Texture2D();
            using var translucencyMap = new Resources.Texture2D();
            using var staticLightData = new Resources.Texture2D();
            using var staticLightNodes = new Resources.Texture2D();
            using var dynamicLightData = new Resources.Texture2D();
            using var dynamicLightNodes = new Resources.Texture2D();
            using var shadowAtlas = new Resources.Texture2D();
            using var lightmap = new Resources.Texture2D();
            using var specCube = new Resources.Cubemap();
            using var brdfLut = new Resources.Texture2D();
            material.SetTexture("_MainTex", mainTexture);
            material.SetTexture("_NormalTex", normalTexture);
            material.SetTexture("_SurfaceTex", surfaceTexture);
            material.SetTexture("_EmissionTex", emissionTexture);
            material.SetTexture("_ParallaxMap", parallaxMap);
            material.SetTexture("_TranslucencyMap", translucencyMap);

            byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
            Span<float> globalValues = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
            const int ViewProjectionOffset = 3 * 16;
            for (int diagonal = 0; diagonal < 4; diagonal++)
                globalValues[ViewProjectionOffset + diagonal * 5] = 1f;
            const int CameraPositionOffset = 8 * 16;
            globalValues[CameraPositionOffset + 2] = 1f;
            using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, true);

            float[] vertices =
            [
                -1f, -1f, 0f, 0f, 0f, 0f, 0f, 1f, 0f, 1f, 0f, 0f, 1f, 0f,
                3f, -1f, 0f, 2f, 0f, 0f, 0f, 1f, 0f, 1f, 0f, 0f, 1f, 0f,
                -1f, 3f, 0f, 0f, 2f, 0f, 0f, 1f, 0f, 1f, 0f, 0f, 1f, 0f,
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }],
                2,
                1);
            using var vertexArray = new GraphicsVertexArray(new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.TexCoord1, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.Normal, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.Tangent, VertexFormat.VertexType.Float, 4),
            ]), vertexBuffer, null);
            using ShaderVariant variant = CreateMaterialContractVariant(compiled, bytecodeFormat);

            // Baked lightmap holds a strong red RGBM pixel: RGB = (1,0,0), A = 1 -> decoded irradiance
            // = RGB * (A * 8) = (8, 0, 0). Sampled into the ambient term, this dominates the realtime
            // ambient baseline below.
            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-bakedgi-create"))
            {
                create.EncodeCreateBuffer(globalUniformBuffer, true, globalUniformBytes);
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                EncodeContractTexture(create, mainTexture, [255, 255, 255, 255]);
                EncodeContractTexture(create, normalTexture, [128, 128, 255, 255]);
                EncodeContractTexture(create, surfaceTexture, [0, 255, 0, 255]);
                EncodeContractTexture(create, emissionTexture, [0, 0, 0, 255]);
                EncodeContractTexture(create, parallaxMap, [0, 0, 0, 255]);
                EncodeContractTexture(create, translucencyMap, [255, 255, 255, 255]);
                EncodeContractTexture(create, staticLightData, [0, 0, 0, 0]);
                EncodeContractTexture(create, staticLightNodes, [0, 0, 0, 0]);
                EncodeContractTexture(create, dynamicLightData, [0, 0, 0, 0]);
                EncodeContractTexture(create, dynamicLightNodes, [0, 0, 0, 0]);
                EncodeContractTexture(create, shadowAtlas, [255, 255, 255, 255]);
                // Baked lightmap holds a strong red RGBM pixel: RGB = (1,0,0), A = 1 -> decoded
                // irradiance = RGB * (A * 8) = (8, 0, 0).
                EncodeContractTexture(create, lightmap, [255, 0, 0, 255]);
                EncodeContractCubemap(create, specCube);
                EncodeContractTexture(create, brdfLut, [255, 255, 255, 255]);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, true);
            }
            SetGlobalUniformBuffer(globalUniformBuffer);

            // Realtime-ambient baseline: small blue ambient, no directional light, no fog. Pixel 0
            // stays on _GIMode == 0 (the default ObjectUniforms), pixel 1 swaps to the baked lightmap.
            RasterizerState raster = pass.State;
            raster.DepthTest = false;
            raster.DepthWrite = false;
            raster.CullFace = RasterizerState.PolyFace.None;
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-bakedgi-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
                draw.SetGlobalTexture("_StaticLightData", staticLightData);
                draw.SetGlobalTexture("_StaticLightNodes", staticLightNodes);
                draw.SetGlobalTexture("_DynamicLightData", dynamicLightData);
                draw.SetGlobalTexture("_DynamicLightNodes", dynamicLightNodes);
                // Cluster list disabled (grid params default 0) -> BVH fallback path in-shader,
                // but the reflected descriptor still needs a valid texture on explicit APIs.
                draw.SetGlobalTexture("_ClusterLightList", staticLightData);
                draw.SetGlobalTexture("_ShadowAtlas", shadowAtlas);
                BindDummyReflectionProbes(draw, specCube, brdfLut);
                BindDummyLightCookies(draw, brdfLut);
                BindDummyGiProbes(draw, staticLightData);
                draw.SetGlobalInt("_StaticLightRoot", -1);
                draw.SetGlobalInt("_DynamicLightRoot", -1);
                draw.SetGlobalInt("_StaticLightTexSize", 1);
                draw.SetGlobalInt("_StaticLightTexShift", 0);
                draw.SetGlobalInt("_StaticNodeTexSize", 1);
                draw.SetGlobalInt("_StaticNodeTexShift", 0);
                draw.SetGlobalInt("_DynamicLightTexSize", 1);
                draw.SetGlobalInt("_DynamicLightTexShift", 0);
                draw.SetGlobalInt("_DynamicNodeTexSize", 1);
                draw.SetGlobalInt("_DynamicNodeTexShift", 0);
                draw.SetGlobalInt("_DirectionalLightEnabled", 0);
                draw.SetGlobalInt("_DirectionalLightShadowEnabled", 0);
                draw.SetGlobalInt("_CascadeCount", 0);
                draw.SetGlobalVector("_ShadowAtlasSize", new Float2(1f, 1f));
                draw.SetGlobalVector("_AmbientMode", new Float2(1f, 0f));
                draw.SetGlobalFloat("_AmbientStrength", 1f);
                // Small blue realtime ambient so pixel 0 lands in a clearly different region from the
                // red-dominated lightmap sample on pixel 1.
                draw.SetGlobalColor("_AmbientColor", new Color(0f, 0f, 0.25f, 1f));
                draw.SetGlobalVector("_FogStates", Float3.Zero);

                // Pixel 0: realtime ambient (_GIMode == 0 is the ObjectUniforms default). No instance
                // properties -> ApplyObjectProperties leaves _GIMode at 0 and clears _Lightmap.
                draw.SetShader(variant);
                draw.SetRasterState(in raster);
                draw.SetMaterialProperties(material);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);

                // Pixel 1: baked lightmap (_GIMode == 1). The per-object PropertyState mirrors what
                // LightmapBinding.Fill produces in the real pipeline: _GIMode, _LightmapUV, the UV
                // scale/offset, and the _Lightmap texture. Encoded material-then-instance, the same
                // order DrawMesh and the batch loop use - binding a material resets the per-draw
                // instance texture layer, so instance properties must come after it.
                var bakedProps = new Rendering.PropertyState();
                bakedProps.SetInt("_GIMode", 1);
                bakedProps.SetInt("_LightmapUV", 0);
                bakedProps.SetVector("_LightmapScaleOffset", new Float4(1f, 1f, 0f, 0f));
                bakedProps.SetTexture("_Lightmap", lightmap);
                draw.SetMaterialProperties(material);
                draw.SetInstanceProperties(bakedProps);
                draw.SetViewport(1, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, true);
            }

            byte[] pixels = readback(color);
            // Pixel 0: realtime ambient = small blue -> blue channel dominates.
            Assert.InRange(pixels[0], (byte)0, (byte)2);
            Assert.InRange(pixels[1], (byte)0, (byte)2);
            Assert.InRange(pixels[2], (byte)40, (byte)120);
            Assert.Equal((byte)255, pixels[3]);
            // Pixel 1: baked lightmap = strong red (RGBM decodes to (8,0,0)) -> red channel dominates.
            Assert.InRange(pixels[4], (byte)120, (byte)255);
            Assert.InRange(pixels[5], (byte)0, (byte)2);
            Assert.InRange(pixels[6], (byte)0, (byte)2);
            Assert.Equal((byte)255, pixels[7]);
            // The two GI modes must produce visibly different output (red vs blue) to prove both the
            // realtime-ambient fall-through and the lightmap sample path fired on the modern backend.
            Assert.True(pixels[4] > pixels[0], "Baked lightmap did not raise the red channel above the realtime-ambient baseline.");
            Assert.True(pixels[2] > pixels[6], "Realtime-ambient blue channel did not stay above the baked-lightmap (red) baseline.");

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-bakedgi-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
        }
    }

    // Depth-as-SRV contract (C1de). Proves the modern backends can sample a depth attachment as a
    // shader resource -- the capability the runtime shadow atlas needs so the C1da shadow path
    // renders real cast shadows instead of a synthetic atlas. The test allocates a Depth24f texture
    // (the same format ShadowAtlas uses), renders a near triangle into it so the depth buffer holds a
    // known ~0.2 value, then samples that depth texture through a trivial shader that writes the
    // stored depth into the red channel. A non-zero, finite red readback proves the depth SRV path
    // round-trips a rendered depth value end-to-end on D3D12.
    private static void RunDepthAsShaderResourceContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        var compiler = new DxcShaderCompiler();
        const string vertexSource = "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        ShaderCompileResult clearDepth = compiler.Compile(new ShaderCompileRequest
        {
            TargetBackend = backend,
            Language = ShaderLanguage.Hlsl,
            VertexSource = vertexSource,
            FragmentSource = "float4 main() : SV_Target { return float4(0, 0, 0, 1); }",
        });
        // Sample the depth texture and write its .r (stored depth) into the red channel. This is the
        // exact read shape the Standard shadow path performs against _ShadowAtlas.
        ShaderCompileResult sampleDepth = compiler.Compile(new ShaderCompileRequest
        {
            TargetBackend = backend,
            Language = ShaderLanguage.Hlsl,
            VertexSource = vertexSource,
            FragmentSource =
                "Texture2D _DepthTex : register(t0);" +
                "SamplerState _DepthTexSampler : register(s0);" +
                "float4 main() : SV_Target { float d = _DepthTex.Sample(_DepthTexSampler, float2(0.5, 0.5)).r; return float4(d, 0, 0, 1); }",
        });
        if (IsSpirvUnavailable(backend, clearDepth) || IsSpirvUnavailable(backend, sampleDepth))
            return;
        Assert.True(clearDepth.Success, clearDepth.ErrorMessage);
        Assert.True(sampleDepth.Success, sampleDepth.ErrorMessage);

        using var clearVariant = new ShaderVariant(new CompiledShaderBytecode(ShaderLanguage.Hlsl, bytecodeFormat, clearDepth.VertexBytecode!, clearDepth.FragmentBytecode!, clearDepth.BindingLayout));
        using var sampleVariant = new ShaderVariant(new CompiledShaderBytecode(ShaderLanguage.Hlsl, bytecodeFormat, sampleDepth.VertexBytecode!, sampleDepth.FragmentBytecode!, sampleDepth.BindingLayout));

        float[] vertices =
        [
            -1f, -1f, 0.2f,
            3f, -1f, 0.2f,
            -1f, 3f, 0.2f,
        ];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        // Color target for the final sampled-depth readback.
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        // Depth texture (the shadow-atlas format). Created as a Resources.Texture2D so it can be
        // bound through SetGlobalTexture the way the runtime shadow atlas (_ShadowAtlas) is.
        using var depth = new Resources.Texture2D(1, 1, false, TextureImageFormat.Depth24f);
        GraphicsFrameBuffer depthFramebuffer = GraphicsFrameBuffer.CreateDeferred(
            [
                new GraphicsFrameBuffer.Attachment { Texture = color },
                new GraphicsFrameBuffer.Attachment { Texture = depth.Handle, IsDepth = true },
            ],
            1,
            1);
        using var sampleColor = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer sampleFramebuffer = GraphicsFrameBuffer.CreateDeferred(
            [new GraphicsFrameBuffer.Attachment { Texture = sampleColor }],
            1,
            1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("depth-srv-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateTexture(depth.Handle);
            create.EncodeAllocateTexture2D(depth.Handle, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(depthFramebuffer);
            create.EncodeCreateTexture(sampleColor);
            create.EncodeAllocateTexture2D(sampleColor, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(sampleFramebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, wait: true);
        }

        // The depth texture must be sample-ready (SRV + sampler) for the runtime shadow atlas path.
        Backends.D3D12.D3D12TextureResource depthResource = ((Backends.D3D12.D3D12GraphicsDevice)device).Textures[depth.Handle.Handle];
        Assert.True(depthResource.HasSrvDescriptor, "D3D12 depth texture must expose a shader-resource view for shadow sampling.");
        Assert.True(depthResource.HasSamplerDescriptor, "D3D12 depth texture must expose a sampler for shadow sampling.");

        // Pass 1: render a near triangle (z = 0.2) into the depth buffer so it holds a known value.
        RasterizerState depthRaster = default;
        depthRaster.DepthTest = true;
        depthRaster.DepthWrite = true;
        depthRaster.Depth = RasterizerState.DepthMode.Less;
        depthRaster.CullFace = RasterizerState.PolyFace.None;
        using (CommandBuffer renderDepth = global::XEngine.Runtime.Graphics.GetCommandBuffer("depth-srv-render"))
        {
            renderDepth.SetRenderTarget(depthFramebuffer);
            renderDepth.ClearRenderTarget(ClearFlags.Depth, new Color(0f, 0f, 0f, 1f));
            renderDepth.DisableScissor();
            renderDepth.SetShader(clearVariant);
            renderDepth.SetRasterState(in depthRaster);
            renderDepth.SetViewport(0, 0, 1, 1);
            renderDepth.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
            device.Execute(renderDepth, wait: true);
        }

        // Pass 2: bind the depth texture as _DepthTex and sample it through the trivial shader.
        using (CommandBuffer sample = global::XEngine.Runtime.Graphics.GetCommandBuffer("depth-srv-sample"))
        {
            sample.SetRenderTarget(sampleFramebuffer);
            sample.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 0f));
            sample.DisableScissor();
            sample.SetGlobalTexture("_DepthTex", depth);
            sample.SetShader(sampleVariant);
            RasterizerState colorRaster = default;
            colorRaster.DepthTest = false;
            colorRaster.DepthWrite = false;
            colorRaster.CullFace = RasterizerState.PolyFace.None;
            sample.SetRasterState(in colorRaster);
            sample.SetViewport(0, 0, 1, 1);
            sample.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
            device.Execute(sample, wait: true);
        }

        byte[] pixels = readback(sampleColor);
        // Red channel carries the sampled depth (~0.2). The exact UNORM quantization of 0.2 lands in
        // the 30-90 byte band; assert a non-trivial finite value that proves the depth SRV round-
        // tripped a rendered depth rather than reading back the cleared 1.0 far value (which would be
        // ~255).
        Assert.InRange(pixels[0], (byte)30, (byte)90);
        Assert.Equal((byte)255, pixels[3]);
        // Screenshot artifact: a single pixel whose red channel holds the sampled depth. Upscaled to
        // 128x128 so the depth-as-SRV readback (dark red ~= 0.2) is visible by eye.
        SaveScreenshotPng("c1de-depth-as-srv", UpscalePixels(pixels, 1, 1, 128, 128), 128, 128);

        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("depth-srv-dispose");
        dispose.EncodeDisposeFramebuffer(depthFramebuffer);
        dispose.EncodeDisposeFramebuffer(sampleFramebuffer);
        device.Execute(dispose, wait: true);
    }

    private static void SetStandardLightingContractState(
        CommandBuffer draw,
        Resources.Texture2D lightingTexture,
        float ambientStrength,
        Color ambientColor,
        Color ambientSky,
        Color ambientGround,
        bool useGradientAmbient)
    {
        draw.SetGlobalTexture("_StaticLightData", lightingTexture);
        draw.SetGlobalTexture("_StaticLightNodes", lightingTexture);
        draw.SetGlobalTexture("_DynamicLightData", lightingTexture);
        draw.SetGlobalTexture("_DynamicLightNodes", lightingTexture);
        draw.SetGlobalTexture("_ShadowAtlas", lightingTexture);
        draw.SetGlobalTexture("_Lightmap", lightingTexture);
        draw.SetGlobalTexture("_ScreenSpaceShadowmap", lightingTexture);
        draw.SetGlobalInt("_ScreenSpaceShadowsEnabled", 0);
        // Realtime GI probe volume dummies: slots must be bound; never sampled (no _GIMode 3).
        draw.SetGlobalTexture("_GiIrradianceAtlas", lightingTexture);
        draw.SetGlobalTexture("_GiProbeMoments", lightingTexture);
        draw.SetGlobalTexture("_GiProbeData", lightingTexture);
        draw.SetGlobalInt("_StaticLightRoot", -1);
        draw.SetGlobalInt("_DynamicLightRoot", -1);
        draw.SetGlobalInt("_StaticLightTexSize", 1);
        draw.SetGlobalInt("_StaticLightTexShift", 0);
        draw.SetGlobalInt("_StaticNodeTexSize", 1);
        draw.SetGlobalInt("_StaticNodeTexShift", 0);
        draw.SetGlobalInt("_DynamicLightTexSize", 1);
        draw.SetGlobalInt("_DynamicLightTexShift", 0);
        draw.SetGlobalInt("_DynamicNodeTexSize", 1);
        draw.SetGlobalInt("_DynamicNodeTexShift", 0);
        draw.SetGlobalInt("_DirectionalLightEnabled", 0);
        draw.SetGlobalInt("_DirectionalLightShadowEnabled", 0);
        draw.SetGlobalInt("_CascadeCount", 0);
        draw.SetGlobalVector("_ShadowAtlasSize", new Float2(1f, 1f));
        draw.SetGlobalVector("_AmbientMode", new Float2(1f, useGradientAmbient ? 1f : 0f));
        draw.SetGlobalFloat("_AmbientStrength", ambientStrength);
        draw.SetGlobalColor("_AmbientColor", ambientColor);
        draw.SetGlobalColor("_AmbientSkyColor", ambientSky);
        draw.SetGlobalColor("_AmbientGroundColor", ambientGround);
        draw.SetGlobalVector("_FogStates", Float3.Zero);
    }

    private static byte[] RunTerrainContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            Resources.Shader shader = TerrainShaderLibrary.LoadTerrainShader();
            Rendering.Shaders.ShaderPass mainPass = shader.GetPass("Terrain");
            Rendering.Shaders.ShaderPass shadowPass = shader.GetPass("TerrainShadow");
            Rendering.Shaders.ShaderPass prepass = shader.GetPass("TerrainPrepass");
            Assert.True(mainPass.HasHlsl);
            Assert.True(shadowPass.HasHlsl);
            Assert.True(prepass.HasHlsl);
            Assert.DoesNotContain("_TerrainMaterialPadding", GetHlslSource(mainPass, "_hlslVertexSource"), StringComparison.Ordinal);
            Assert.DoesNotContain("_TerrainMaterialPadding", GetHlslSource(mainPass, "_hlslFragmentSource"), StringComparison.Ordinal);
            Assert.DoesNotContain("_TerrainMaterialPadding", GetHlslSource(shadowPass, "_hlslVertexSource"), StringComparison.Ordinal);
            Assert.DoesNotContain("_TerrainMaterialPadding", GetHlslSource(shadowPass, "_hlslFragmentSource"), StringComparison.Ordinal);
            Assert.DoesNotContain("_TerrainMaterialPadding", GetHlslSource(prepass, "_hlslVertexSource"), StringComparison.Ordinal);
            Assert.DoesNotContain("_TerrainMaterialPadding", GetHlslSource(prepass, "_hlslFragmentSource"), StringComparison.Ordinal);

            IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, shader.Name);
            ShaderCompileResult mainCompiled = CompileMaterialContractShader(compiler, backend,
                GetHlslSource(mainPass, "_hlslVertexSource"), GetHlslSource(mainPass, "_hlslFragmentSource"));
            if (IsSpirvUnavailable(backend, mainCompiled)) return [];
            Assert.True(mainCompiled.Success, mainCompiled.ErrorMessage);
            ShaderBindingLayout mainLayout = Assert.IsType<ShaderBindingLayout>(mainCompiled.BindingLayout);
            Assert.Contains(mainLayout.Buffers, slot => slot.Slot == 0 && slot.Name == "GlobalUniforms");
            Assert.Contains(mainLayout.Buffers, slot => slot.Slot == 1 && slot.Name == "ObjectUniforms");
            Assert.Contains(mainLayout.Buffers, slot => slot.Slot == 2 && slot.Name == "TerrainMaterial");
            Assert.Contains(mainLayout.Buffers, slot => slot.Slot == 3 && slot.Name == "StandardLighting");
            Assert.Contains(mainLayout.Buffers, slot => slot.Slot == 4 && slot.Name == "StandardShadows");
            Assert.Contains(mainLayout.Textures, slot => slot.Slot == 20 && slot.Name == "_StaticLightData");
            Assert.Contains(mainLayout.Textures, slot => slot.Slot == 24 && slot.Name == "_ShadowAtlas");
            Assert.Contains(mainLayout.Textures, slot => slot.Slot == 29 && slot.Name == "_ScreenSpaceShadowmap");
            ShaderCompileResult shadowCompiled = CompileMaterialContractShader(compiler, backend,
                GetHlslSource(shadowPass, "_hlslVertexSource"), GetHlslSource(shadowPass, "_hlslFragmentSource"));
            ShaderCompileResult prepassCompiled = CompileMaterialContractShader(compiler, backend,
                GetHlslSource(prepass, "_hlslVertexSource"), GetHlslSource(prepass, "_hlslFragmentSource"));
            Assert.True(shadowCompiled.Success, shadowCompiled.ErrorMessage);
            Assert.True(prepassCompiled.Success, prepassCompiled.ErrorMessage);
            Assert.Contains(Assert.IsType<ShaderBindingLayout>(shadowCompiled.BindingLayout).Buffers, slot => slot.Name == "TerrainMaterial");
            Assert.Contains(Assert.IsType<ShaderBindingLayout>(prepassCompiled.BindingLayout).Buffers, slot => slot.Name == "TerrainMaterial");

            using var defaultsMaterial = new Resources.Material(shader);
            using var overridesMaterial = new Resources.Material(shader);
            overridesMaterial.SetFloat("_TerrainSize", 32f);
            overridesMaterial.SetFloat("_TerrainHeight", 8f);
            overridesMaterial.SetVector("_BrushPosition", new Float2(0.5f, 0.5f));
            overridesMaterial.SetFloat("_BrushRadius", 0.25f);
            overridesMaterial.SetFloat("_BrushFalloff", 0.75f);
            overridesMaterial.SetFloat("_BrushVisible", 1f);
            overridesMaterial.SetInt("_HasHoles", 1);
            overridesMaterial.SetInt("_LayerCount", 8);
            overridesMaterial.SetFloat("_Layer0Tiling", 2f);
            overridesMaterial.SetFloat("_Layer0Roughness", 0.25f);
            overridesMaterial.SetFloat("_Layer0Metallic", 0.5f);

            Rendering.TerrainMaterialUniformsData defaults = Rendering.MaterialUniformPacking.PackTerrain(defaultsMaterial._properties, shader);
            Assert.Equal(304, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.TerrainMaterialUniformsData>());
            Assert.Equal(
                new IntPtr(176),
                System.Runtime.InteropServices.Marshal.OffsetOf<Rendering.TerrainMaterialUniformsData>(
                    nameof(Rendering.TerrainMaterialUniformsData._Layer0Params)));
            Assert.Equal(1024f, defaults._TerrainSize);
            Assert.Equal(100f, defaults._TerrainHeight);
            Assert.Equal(4, defaults._LayerCount);
            Assert.Equal(new Float4(10f, 1f, 0f, 0f), defaults._Layer0Params);
            Rendering.TerrainMaterialUniformsData overrides = Rendering.MaterialUniformPacking.PackTerrain(overridesMaterial._properties, shader);
            Assert.Equal(32f, overrides._TerrainSize);
            Assert.Equal(8f, overrides._TerrainHeight);
            Assert.Equal(new Float2(0.5f, 0.5f), overrides._BrushPosition);
            Assert.Equal(1, overrides._HasHoles);
            Assert.Equal(8, overrides._LayerCount);
            Assert.Equal(new Float4(2f, 0.25f, 0.5f, 0f), overrides._Layer0Params);

            var instancedKeywords = new System.Collections.Generic.Dictionary<string, bool>
            {
                ["GPU_INSTANCING"] = true,
                ["TERRAIN_8_LAYERS"] = true,
                ["TERRAIN_BICUBIC"] = true,
            };
            ShaderCompileResult instancedCompiled = compiler.Compile(new ShaderCompileRequest
            {
                TargetBackend = backend,
                Language = ShaderLanguage.Hlsl,
                VertexSource = GetHlslSource(mainPass, "_hlslVertexSource"),
                FragmentSource = GetHlslSource(mainPass, "_hlslFragmentSource"),
                Keywords = instancedKeywords,
            });
            Assert.True(instancedCompiled.Success, instancedCompiled.ErrorMessage);
            ShaderCompileResult materialInstancedCompiled = compiler.Compile(new ShaderCompileRequest
            {
                TargetBackend = backend,
                Language = ShaderLanguage.Hlsl,
                VertexSource = GetHlslSource(mainPass, "_hlslVertexSource"),
                FragmentSource = GetHlslSource(mainPass, "_hlslFragmentSource"),
                Keywords = new System.Collections.Generic.Dictionary<string, bool> { ["GPU_INSTANCING"] = true },
            });
            Assert.True(materialInstancedCompiled.Success, materialInstancedCompiled.ErrorMessage);

            using var white = new Resources.Texture2D();
            using var zeroHeight = new Resources.Texture2D();
            using var magenta = new Resources.Texture2D();
            using var splat = new Resources.Texture2D();
            using var holes = new Resources.Texture2D();
            using var flatNormal = new Resources.Texture2D();
            using var tiltedNormal = new Resources.Texture2D();
            using var lightingTexture = new Resources.Texture2D();
            string[] textureNames =
            [
                "_Heightmap", "_Splatmap0", "_Splatmap1", "_HolesMap",
                "_Layer0", "_Layer0Normal", "_Layer1", "_Layer1Normal", "_Layer2", "_Layer2Normal", "_Layer3", "_Layer3Normal",
                "_Layer4", "_Layer4Normal", "_Layer5", "_Layer5Normal", "_Layer6", "_Layer6Normal", "_Layer7", "_Layer7Normal",
            ];
            for (int i = 0; i < textureNames.Length; i++)
            {
                Resources.Texture2D texture = textureNames[i].EndsWith("Normal", StringComparison.Ordinal)
                    ? flatNormal
                    : white;
                defaultsMaterial.SetTexture(textureNames[i], texture);
                overridesMaterial.SetTexture(textureNames[i], texture);
            }
            defaultsMaterial.SetTexture("_Heightmap", zeroHeight);
            overridesMaterial.SetTexture("_Heightmap", zeroHeight);
            defaultsMaterial.SetTexture("_Splatmap0", splat);
            defaultsMaterial.SetTexture("_HolesMap", holes);
            overridesMaterial.SetTexture("_Splatmap0", splat);
            overridesMaterial.SetTexture("_HolesMap", holes);
            overridesMaterial.SetTexture("_Layer0", magenta);
            overridesMaterial.SetTexture("_Layer0Normal", tiltedNormal);
            defaultsMaterial.SetTexture("_ScreenSpaceShadowmap", lightingTexture);
            overridesMaterial.SetTexture("_ScreenSpaceShadowmap", lightingTexture);
            overridesMaterial.SetFloat("_BrushVisible", 0f);
            var bindings = new System.Collections.Generic.Dictionary<string, GraphicsTexture>();
            Rendering.MaterialUniformPacking.ApplyTextureBindings(bindings, overridesMaterial._properties, shader);
            for (int i = 0; i < textureNames.Length; i++) Assert.True(bindings.ContainsKey(textureNames[i]));

            byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
            Span<float> globals = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
            const int ViewProjectionOffset = 3 * 16;
            for (int diagonal = 0; diagonal < 4; diagonal++) globals[ViewProjectionOffset + (diagonal * 5)] = 1f;
            globals[ViewProjectionOffset + 5] = 0f;
            globals[ViewProjectionOffset + 6] = 1f;
            globals[ViewProjectionOffset + 9] = 1f;
            globals[ViewProjectionOffset + 10] = 0f;
            using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, true);
            float[] vertices = [-1f, -1f, 0f, 0f, 0f, -1f, 3f, 0f, 0f, 2f, 3f, -1f, 0f, 2f, 0f];
            float[] terrainVertices = [-1f, 0f, -1f, 0f, 0f, -1f, 0f, 3f, 0f, 2f, 3f, 0f, -1f, 2f, 0f];
            ushort[] terrainIndices = [0, 1, 2];
            float[] terrainInstance =
            [
                1f, 0f, 0f, 0f,
                0f, 1f, 0f, 0f,
                0f, 0f, 1f, 0f,
                0f, 0f, 0f, 1f,
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            ReadOnlySpan<byte> terrainVertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(terrainVertices.AsSpan());
            ReadOnlySpan<byte> terrainIndexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(terrainIndices.AsSpan());
            ReadOnlySpan<byte> terrainInstanceBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(terrainInstance.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, true);
            using var terrainVertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, terrainVertexBytes, true);
            using var terrainIndexBuffer = new GraphicsBuffer(BufferType.ElementsBuffer, terrainIndexBytes, true);
            using var terrainInstanceBuffer = new GraphicsBuffer(BufferType.VertexBuffer, terrainInstanceBytes, true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var depth = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Depth32f);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }, new GraphicsFrameBuffer.Attachment { Texture = depth, IsDepth = true }], 3, 1);
            using var vertexArray = new GraphicsVertexArray(new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
            ]), vertexBuffer, null);
            var terrainVertexFormat = new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
            ]);
            var terrainInstanceFormat = new VertexFormat([
                new((VertexFormat.VertexSemantic)8, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)9, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)10, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)11, VertexFormat.VertexType.Float, 4, divisor: 1),
            ]);
            using var terrainVertexArray = new GraphicsVertexArray(
                terrainVertexFormat, terrainVertexBuffer, terrainIndexBuffer, terrainInstanceFormat, terrainInstanceBuffer);
            using ShaderVariant variant = CreateMaterialContractVariant(mainCompiled, bytecodeFormat);
            using ShaderVariant materialInstancedVariant = CreateMaterialContractVariant(materialInstancedCompiled, bytecodeFormat);
            using ShaderVariant instancedVariant = CreateMaterialContractVariant(instancedCompiled, bytecodeFormat);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("terrain-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                create.EncodeCreateBuffer(terrainVertexBuffer, true, terrainVertexBytes);
                create.EncodeCreateBuffer(terrainIndexBuffer, true, terrainIndexBytes);
                create.EncodeCreateBuffer(terrainInstanceBuffer, true, terrainInstanceBytes);
                create.EncodeCreateBuffer(globalUniformBuffer, true, globalUniformBytes);
                EncodeContractTexture(create, white, [255, 255, 255, 255]);
                EncodeContractTexture(create, zeroHeight, [0, 0, 0, 255]);
                EncodeContractTexture(create, magenta, [255, 128, 255, 255]);
                EncodeContractTexture(create, splat, [255, 0, 0, 0]);
                EncodeContractTexture(create, holes, [255, 255, 255, 255]);
                EncodeContractTexture(create, flatNormal, [128, 128, 255, 255]);
                EncodeContractTexture(create, tiltedNormal, [255, 128, 128, 255]);
                EncodeContractTexture(create, lightingTexture, [255, 255, 255, 255]);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 3, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(depth);
                create.EncodeAllocateTexture2D(depth, 0, 3, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                create.EncodeCreateVertexArray(terrainVertexArray);
                device.Execute(create, true);
            }
            SetGlobalUniformBuffer(globalUniformBuffer);
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("terrain-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
                SetStandardLightingContractState(draw, lightingTexture,
                    ambientStrength: 1f,
                    ambientColor: Color.Black,
                    ambientSky: Color.White,
                    ambientGround: Color.Black,
                    useGradientAmbient: true);
                BindDummyLightCookies(draw, lightingTexture);
                draw.SetRasterState(mainPass.State);
                draw.SetShader(materialInstancedVariant);
                draw.SetMaterialProperties(defaultsMaterial);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawIndexedInstanced(terrainVertexArray, Topology.Triangles, 3, 1);
                draw.SetMaterialProperties(overridesMaterial);
                draw.SetViewport(1, 0, 1, 1);
                draw.DrawIndexedInstanced(terrainVertexArray, Topology.Triangles, 3, 1);
                overridesMaterial.SetFloat("_TerrainSize", 2f);
                overridesMaterial.SetFloat("_TerrainHeight", 0f);
                overridesMaterial.SetInt("_HasHoles", 0);
                draw.SetShader(instancedVariant);
                draw.SetMaterialProperties(overridesMaterial);
                draw.SetViewport(2, 0, 1, 1);
                draw.DrawIndexedInstanced(terrainVertexArray, Topology.Triangles, 3, 1);
                device.Execute(draw, true);
            }
            byte[] pixels = readback(color);
            bool terrainPixelsValid = pixels[0] >= 245 && pixels[1] >= 245 && pixels[2] >= 245 && pixels[3] == 255
                && pixels[4] < pixels[0] && pixels[5] < pixels[1] && pixels[6] < pixels[2]
                && pixels[5] < pixels[4] && pixels[5] < pixels[6] && pixels[7] == 255
                && (pixels[8] > 0 || pixels[9] > 0 || pixels[10] > 0) && pixels[11] == 255;
            Assert.True(terrainPixelsValid, $"Terrain pixels invalid: {Convert.ToHexString(pixels)}");
            if (backend == GraphicsBackend.Direct3D12)
                SaveScreenshotPng("c1dq-terrain-pbr-normal", UpscalePixels(pixels, 3, 1, 384, 128), 384, 128);
            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("terrain-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
            return pixels;
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
            Rendering.PropertyState.ClearGlobalsInternal();
        }
    }

    private static byte[] RunGrassContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            Resources.Shader shader = TerrainShaderLibrary.LoadGrassShader();
            Rendering.Shaders.ShaderPass mainPass = shader.GetPass("Grass");
            Rendering.Shaders.ShaderPass prepass = shader.GetPass("GrassPrepass");
            Assert.True(mainPass.HasHlsl);
            Assert.True(prepass.HasHlsl);
            Assert.False(mainPass.State.DoBlend);
            Assert.True(mainPass.State.DepthWrite);
            Assert.Equal(RasterizerState.PolyFace.None, mainPass.State.CullFace);

            IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, shader.Name);
            ShaderCompileResult mainCompiled = CompileMaterialContractShader(compiler, backend,
                GetHlslSource(mainPass, "_hlslVertexSource"), GetHlslSource(mainPass, "_hlslFragmentSource"));
            if (IsSpirvUnavailable(backend, mainCompiled)) return [];
            Assert.True(mainCompiled.Success, mainCompiled.ErrorMessage);
            ShaderBindingLayout mainLayout = Assert.IsType<ShaderBindingLayout>(mainCompiled.BindingLayout);
            Assert.Contains(mainLayout.Buffers, slot => slot.Slot == 0 && slot.Name == "GlobalUniforms");
            Assert.Contains(mainLayout.Buffers, slot => slot.Slot == 1 && slot.Name == "ObjectUniforms");
            Assert.Contains(mainLayout.Buffers, slot => slot.Slot == 2 && slot.Name == "GrassMaterial");
            Assert.Contains(mainLayout.Buffers, slot => slot.Slot == 3 && slot.Name == "StandardLighting");
            Assert.Contains(mainLayout.Buffers, slot => slot.Slot == 4 && slot.Name == "StandardShadows");

            var keywords = new System.Collections.Generic.Dictionary<string, bool> { ["GPU_INSTANCING"] = true };
            ShaderCompileResult instancedCompiled = compiler.Compile(new ShaderCompileRequest
            {
                TargetBackend = backend,
                Language = ShaderLanguage.Hlsl,
                VertexSource = GetHlslSource(mainPass, "_hlslVertexSource"),
                FragmentSource = GetHlslSource(mainPass, "_hlslFragmentSource"),
                Keywords = keywords,
            });
            Assert.True(instancedCompiled.Success, instancedCompiled.ErrorMessage);
            ShaderBindingLayout instancedLayout = Assert.IsType<ShaderBindingLayout>(instancedCompiled.BindingLayout);
            Assert.Contains(instancedLayout.Textures, slot => slot.Slot == 0 && slot.Name == "_MainTex");
            Assert.Contains(instancedLayout.Textures, slot => slot.Slot == 1 && slot.Name == "_Heightmap");
            Assert.Contains(instancedLayout.Textures, slot => slot.Slot == 4 && slot.Name == "_StaticLightData");
            Assert.Contains(instancedLayout.Textures, slot => slot.Slot == 8 && slot.Name == "_ShadowAtlas");
            Assert.Contains(instancedLayout.Textures, slot => slot.Slot == 14 && slot.Name == "_ScreenSpaceShadowmap");

            ShaderCompileResult prepassCompiled = compiler.Compile(new ShaderCompileRequest
            {
                TargetBackend = backend,
                Language = ShaderLanguage.Hlsl,
                VertexSource = GetHlslSource(prepass, "_hlslVertexSource"),
                FragmentSource = GetHlslSource(prepass, "_hlslFragmentSource"),
                Keywords = keywords,
            });
            Assert.True(prepassCompiled.Success, prepassCompiled.ErrorMessage);
            Assert.Contains(Assert.IsType<ShaderBindingLayout>(prepassCompiled.BindingLayout).Buffers,
                slot => slot.Slot == 2 && slot.Name == "GrassMaterial");

            using var defaultsMaterial = new Resources.Material(shader);
            using var billboardMaterial = new Resources.Material(shader);
            using var alignedMaterial = new Resources.Material(shader);
            billboardMaterial.SetMatrix("_TerrainWorldToLocal", Float4x4.Identity);
            billboardMaterial.SetMatrix("_TerrainLocalToWorld", Float4x4.Identity);
            billboardMaterial.SetVector("_TerrainUp", Float3.UnitY);
            billboardMaterial.SetFloat("_TerrainSize", 2f);
            billboardMaterial.SetFloat("_TerrainHeight", 1f);
            billboardMaterial.SetFloat("_WindStrength", 0f);
            billboardMaterial.SetFloat("_Billboard", 1f);
            billboardMaterial.SetFloat("_AlignToNormal", 0f);
            billboardMaterial.SetFloat("_GrassDistance", 10f);
            billboardMaterial.SetFloat("_GrassFadeStart", 5f);
            billboardMaterial.SetFloat("_Translucency", 15f);
            alignedMaterial.SetMatrix("_TerrainWorldToLocal", Float4x4.Identity);
            alignedMaterial.SetMatrix("_TerrainLocalToWorld", Float4x4.Identity);
            alignedMaterial.SetVector("_TerrainUp", Float3.UnitY);
            alignedMaterial.SetFloat("_TerrainSize", 2f);
            alignedMaterial.SetFloat("_TerrainHeight", 1f);
            alignedMaterial.SetFloat("_WindStrength", 0f);
            alignedMaterial.SetFloat("_Billboard", 0f);
            alignedMaterial.SetFloat("_AlignToNormal", 1f);
            alignedMaterial.SetFloat("_GrassDistance", 10f);
            alignedMaterial.SetFloat("_GrassFadeStart", 5f);
            alignedMaterial.SetFloat("_Translucency", 0f);

            Rendering.GrassMaterialUniformsData defaults = Rendering.MaterialUniformPacking.PackGrass(defaultsMaterial._properties, shader);
            Assert.Equal(192, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.GrassMaterialUniformsData>());
            Assert.Equal(0.5f, defaults._AlphaCutoff);
            Assert.Equal(0.3f, defaults._WindStrength);
            Assert.Equal(1.5f, defaults._WindSpeed);
            Assert.Equal(1f, defaults._Billboard);
            Assert.Equal(15f, defaults._Translucency);
            Assert.Equal(150f, defaults._GrassDistance);
            Rendering.GrassMaterialUniformsData overrides = Rendering.MaterialUniformPacking.PackGrass(billboardMaterial._properties, shader);
            Assert.Equal(Float4x4.Identity, overrides._TerrainLocalToWorld);
            Assert.Equal(Float3.UnitY, overrides._TerrainUp);
            Assert.Equal(2f, overrides._TerrainSize);
            Assert.Equal(0f, overrides._WindStrength);
            Assert.Equal(10f, overrides._GrassDistance);
            defaultsMaterial.SetFloat("_Translucency", 0f);

            using var white = new Resources.Texture2D();
            using var magenta = new Resources.Texture2D();
            using var heightmap = new Resources.Texture2D();
            using var lightingTexture = new Resources.Texture2D();
            defaultsMaterial.SetTexture("_MainTex", white);
            defaultsMaterial.SetTexture("_Heightmap", heightmap);
            bool useVulkanBindingSmoke = backend == GraphicsBackend.Vulkan;
            billboardMaterial.SetTexture("_MainTex", useVulkanBindingSmoke ? white : magenta);
            billboardMaterial.SetTexture("_Heightmap", heightmap);
            alignedMaterial.SetTexture("_MainTex", white);
            alignedMaterial.SetTexture("_Heightmap", heightmap);
            var bindings = new System.Collections.Generic.Dictionary<string, GraphicsTexture>();
            Rendering.MaterialUniformPacking.ApplyTextureBindings(bindings, billboardMaterial._properties, shader);
            Assert.Equal(2, bindings.Count);
            Assert.True(bindings.ContainsKey("_MainTex"));
            Assert.True(bindings.ContainsKey("_Heightmap"));
            defaultsMaterial.SetTexture("_ScreenSpaceShadowmap", lightingTexture);
            billboardMaterial.SetTexture("_ScreenSpaceShadowmap", lightingTexture);
            alignedMaterial.SetTexture("_ScreenSpaceShadowmap", lightingTexture);

            byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
            Span<float> globals = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
            const int ViewOffset = 0;
            const int ViewProjectionOffset = 3 * 16;
            for (int diagonal = 0; diagonal < 4; diagonal++)
            {
                globals[ViewOffset + (diagonal * 5)] = 1f;
                globals[ViewProjectionOffset + (diagonal * 5)] = 1f;
            }
            using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, true);
            float[] vertices = [-1f, -1f, 0f, 0f, 0f, 3f, -1f, 0f, 2f, 0f, -1f, 3f, 0f, 0f, 2f];
            ushort[] indices = [0, 1, 2];
            Rendering.InstanceData[] billboardInstances =
            [
                new Rendering.InstanceData(Float4x4.Identity, Color.White, new Float4(0f, 0f, 0f, 0f)),
            ];
            Rendering.InstanceData[] alignedInstances =
            [
                new Rendering.InstanceData(Float4x4.Identity, new Color(0f, 1f, 0f, 1f), new Float4(0f, 0f, 0f, 0f)),
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            ReadOnlySpan<byte> indexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(indices.AsSpan());
            ReadOnlySpan<byte> billboardInstanceBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(billboardInstances.AsSpan());
            ReadOnlySpan<byte> alignedInstanceBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(alignedInstances.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, true);
            using var indexBuffer = new GraphicsBuffer(BufferType.ElementsBuffer, indexBytes, true);
            using var instanceBuffer = new GraphicsBuffer(BufferType.VertexBuffer, billboardInstanceBytes, true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var depth = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Depth32f);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }, new GraphicsFrameBuffer.Attachment { Texture = depth, IsDepth = true }], 3, 1);
            var vertexFormat = new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
            ]);
            var instanceFormat = new VertexFormat([
                new((VertexFormat.VertexSemantic)8, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)9, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)10, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)11, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)12, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)13, VertexFormat.VertexType.Float, 4, divisor: 1),
            ]);
            using var vertexArray = new GraphicsVertexArray(vertexFormat, vertexBuffer, null);
            using var instancedVertexArray = new GraphicsVertexArray(vertexFormat, vertexBuffer, indexBuffer, instanceFormat, instanceBuffer);
            using ShaderVariant variant = CreateMaterialContractVariant(mainCompiled, bytecodeFormat);
            using ShaderVariant instancedVariant = CreateMaterialContractVariant(instancedCompiled, bytecodeFormat);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("grass-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                create.EncodeCreateBuffer(indexBuffer, true, indexBytes);
                create.EncodeCreateBuffer(instanceBuffer, true, billboardInstanceBytes);
                create.EncodeCreateBuffer(globalUniformBuffer, true, globalUniformBytes);
                EncodeContractTexture(create, white, [255, 255, 255, 255]);
                EncodeContractTexture(create, magenta, [255, 0, 255, 255]);
                EncodeContractTexture(create, heightmap, [128, 128, 128, 255]);
                EncodeContractTexture(create, lightingTexture, [255, 255, 255, 255]);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 3, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(depth);
                create.EncodeAllocateTexture2D(depth, 0, 3, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                create.EncodeCreateVertexArray(instancedVertexArray);
                device.Execute(create, true);
            }
            SetGlobalUniformBuffer(globalUniformBuffer);
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("grass-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
                SetStandardLightingContractState(draw, lightingTexture,
                    ambientStrength: useVulkanBindingSmoke ? 1f : 0f,
                    ambientColor: Color.Black,
                    ambientSky: useVulkanBindingSmoke ? Color.White : Color.Black,
                    ambientGround: useVulkanBindingSmoke ? Color.White : Color.Black,
                    useGradientAmbient: useVulkanBindingSmoke);
                BindDummyLightCookies(draw, lightingTexture);
                draw.SetGlobalInt("_DirectionalLightEnabled", useVulkanBindingSmoke ? 0 : 1);
                draw.SetGlobalVector("_DirectionalLightDirection", Float3.UnitX);
                draw.SetGlobalVector("_DirectionalLightColor", Float3.One);
                draw.SetGlobalFloat("_DirectionalLightIntensity", 1f);
                draw.SetRasterState(mainPass.State);
                DrawMaterialPixel(draw, vertexArray, variant, defaultsMaterial, 0);
                draw.SetShader(instancedVariant);
                draw.SetMaterialProperties(billboardMaterial);
                draw.SetViewport(1, 0, 1, 1);
                draw.DrawIndexedInstanced(instancedVertexArray, Topology.Triangles, 3, 1);
                draw.UpdateBuffer(instanceBuffer, alignedInstanceBytes);
                draw.SetMaterialProperties(alignedMaterial);
                draw.SetViewport(2, 0, 1, 1);
                draw.DrawIndexedInstanced(instancedVertexArray, Topology.Triangles, 3, 1);
                device.Execute(draw, true);
            }
            byte[] pixels = readback(color);
            AssertMaterialPixel(pixels, 0,
                useVulkanBindingSmoke ? 1f : 0f,
                useVulkanBindingSmoke ? 1f : 0f,
                useVulkanBindingSmoke ? 1f : 0f,
                1f);
            Assert.True(pixels[4] > 0 || pixels[5] > 0 || pixels[6] > 0,
                $"Grass billboard pixel must be lit: {Convert.ToHexString(pixels)}");
            Assert.True(pixels[7] == 255, $"Grass billboard alpha must be opaque: {Convert.ToHexString(pixels)}");
            if (useVulkanBindingSmoke)
            {
                Assert.True(pixels[8] > 0 || pixels[9] > 0 || pixels[10] > 0,
                    $"Grass aligned pixel must receive ambient light: {Convert.ToHexString(pixels)}");
                Assert.True(pixels[11] == 255, $"Grass aligned alpha must be opaque: {Convert.ToHexString(pixels)}");
            }
            else
            {
                AssertMaterialPixel(pixels, 2, 0f, 0f, 0f, 1f);
            }
            if (backend == GraphicsBackend.Direct3D12)
                SaveScreenshotPng("c1dq-grass-pbr-translucency", UpscalePixels(pixels, 3, 1, 384, 128), 384, 128);
            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("grass-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
            return pixels;
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
            Rendering.PropertyState.ClearGlobalsInternal();
        }
    }

    private static byte[] RunVolumetricFogPostProcessContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        string[] fogMarchGlobalNames =
        [
            "_StaticLightRoot", "_DynamicLightRoot",
            "_StaticLightTexSize", "_StaticLightTexShift", "_StaticNodeTexSize", "_StaticNodeTexShift",
            "_DynamicLightTexSize", "_DynamicLightTexShift", "_DynamicNodeTexSize", "_DynamicNodeTexShift",
            "_DirectionalLightEnabled", "_DirectionalLightShadowEnabled", "_CascadeCount",
        ];
        var previousFogMarchGlobals = new Dictionary<string, int?>(fogMarchGlobalNames.Length);
        foreach (string name in fogMarchGlobalNames)
        {
            previousFogMarchGlobals[name] = Rendering.PropertyState.s_globalInts.TryGetValue(name, out int value)
                ? value
                : null;
        }
        try
        {
            Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.VolumetricFog);
            Rendering.Shaders.ShaderPass marchPass = shader.GetPass("FogMarch");
            Rendering.Shaders.ShaderPass temporalPass = shader.GetPass("FogTemporal");
            Rendering.Shaders.ShaderPass compositePass = shader.GetPass("FogComposite");
            Assert.True(marchPass.HasHlsl);
            Assert.True(temporalPass.HasHlsl);
            Assert.True(compositePass.HasHlsl);

            IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/VolumetricFog");
            ShaderCompileResult marchCompiled = CompileMaterialContractShader(compiler, backend,
                GetHlslSource(marchPass, "_hlslVertexSource"), GetHlslSource(marchPass, "_hlslFragmentSource"));
            if (IsSpirvUnavailable(backend, marchCompiled)) return [];
            Assert.True(marchCompiled.Success, marchCompiled.ErrorMessage);
            ShaderBindingLayout marchLayout = Assert.IsType<ShaderBindingLayout>(marchCompiled.BindingLayout);
            Assert.Collection(marchLayout.Buffers,
                slot => { Assert.Equal(0, slot.Slot); Assert.Equal("GlobalUniforms", slot.Name); },
                slot => { Assert.Equal(1, slot.Slot); Assert.Equal("ObjectUniforms", slot.Name); },
                slot => { Assert.Equal(2, slot.Slot); Assert.Equal("FogMarchPS", slot.Name); });
            Assert.Collection(marchLayout.Textures,
                slot => { Assert.Equal(0, slot.Slot); Assert.Equal("_CameraDepthTexture", slot.Name); },
                slot => { Assert.Equal(1, slot.Slot); Assert.Equal("_StaticLightData", slot.Name); },
                slot => { Assert.Equal(2, slot.Slot); Assert.Equal("_StaticLightNodes", slot.Name); },
                slot => { Assert.Equal(3, slot.Slot); Assert.Equal("_DynamicLightData", slot.Name); },
                slot => { Assert.Equal(4, slot.Slot); Assert.Equal("_DynamicLightNodes", slot.Name); },
                slot => { Assert.Equal(5, slot.Slot); Assert.Equal("_ShadowAtlas", slot.Name); });

            using var marchMaterial = new Resources.Material(shader);
            marchMaterial.SetFloat("_FogDensity", 1f);
            marchMaterial.SetFloat("_FogScattering", 0f);
            marchMaterial.SetFloat("_FogExtinction", 1f);
            marchMaterial.SetFloat("_FogMaxDistance", 1f);
            marchMaterial.SetInt("_FogSteps", 8);
            marchMaterial.SetColor("_FogColorTint", new Color(1f, 1f, 1f, 1f));
            marchMaterial.SetFloat("_FogDithering", 0f);
            marchMaterial.SetColor("_FogAmbientColor", new Color(1f, 0f, 0f, 1f));
            marchMaterial.SetFloat("_FogAmbientIntensity", 1f);
            marchMaterial.SetInt("_FogEnableDirectional", 0);
            marchMaterial.SetInt("_FogEnableDirectionalShadows", 0);
            marchMaterial.SetInt("_FogEnablePointLights", 0);
            marchMaterial.SetInt("_FogEnablePointShadows", 0);
            marchMaterial.SetInt("_FogEnableSpotLights", 0);
            marchMaterial.SetInt("_FogEnableSpotShadows", 0);
            marchMaterial.SetInt("_FogVolumeCount", 0);
            using var marchDepth = new Resources.Texture2D();
            using var staticLightData = new Resources.Texture2D();
            using var staticLightNodes = new Resources.Texture2D();
            using var dynamicLightData = new Resources.Texture2D();
            using var dynamicLightNodes = new Resources.Texture2D();
            using var shadowAtlas = new Resources.Texture2D();
            marchMaterial.SetTexture("_CameraDepthTexture", marchDepth);
            marchMaterial.SetTexture("_StaticLightData", staticLightData);
            marchMaterial.SetTexture("_StaticLightNodes", staticLightNodes);
            marchMaterial.SetTexture("_DynamicLightData", dynamicLightData);
            marchMaterial.SetTexture("_DynamicLightNodes", dynamicLightNodes);
            marchMaterial.SetTexture("_ShadowAtlas", shadowAtlas);
            Rendering.FogMarchUniformsData marchUniforms = Rendering.MaterialUniformPacking.PackFogMarch(marchMaterial._properties);
            Assert.Equal(4320, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.FogMarchUniformsData>());
            Assert.Equal(1f, marchUniforms._FogMarchParams0.X);
            Assert.Equal(8, marchUniforms._FogMarchFlags0X);

            byte[] marchGlobalBytes;
            Rendering.GlobalUniformsData marchGlobal = new()
            {
                xengine_MatV = Float4x4.Identity,
                xengine_MatIV = Float4x4.Identity,
                xengine_MatP = Float4x4.Identity,
                xengine_MatVP = Float4x4.Identity,
                xengine_PrevViewProj = Float4x4.Identity,
                xengine_MatIP = Float4x4.Identity,
                xengine_MatIVP = Float4x4.Identity,
                xengine_MatVP_NonJittered = Float4x4.Identity,
                _ProjectionParams = new Float4(0f, 1f, 100f, 0f),
            };
            marchGlobalBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(
                System.Runtime.InteropServices.MemoryMarshal.CreateReadOnlySpan(ref marchGlobal, 1)).ToArray();
            float[] marchVertices = [-1f, -1f, 0f, 0f, 0f, 3f, -1f, 0f, 2f, 0f, -1f, 3f, 0f, 0f, 2f];
            ReadOnlySpan<byte> marchVertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(marchVertices.AsSpan());
            using var marchVertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, marchVertexBytes, true);
            using var marchGlobalBuffer = new GraphicsBuffer(BufferType.UniformBuffer, marchGlobalBytes, true);
            using var marchColor = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var marchColorDepth = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Depth32f);
            GraphicsFrameBuffer marchFramebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = marchColor }, new GraphicsFrameBuffer.Attachment { Texture = marchColorDepth, IsDepth = true }], 1, 1);
            var marchVertexFormat = new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
            ]);
            using var marchVertexArray = new GraphicsVertexArray(marchVertexFormat, marchVertexBuffer, null);
            using ShaderVariant marchVariant = CreateMaterialContractVariant(marchCompiled, bytecodeFormat);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("fog-march-create"))
            {
                create.EncodeCreateBuffer(marchVertexBuffer, true, marchVertexBytes);
                create.EncodeCreateBuffer(marchGlobalBuffer, true, marchGlobalBytes);
                EncodeContractTexture(create, marchDepth, [255, 255, 255, 255]);
                EncodeContractTexture(create, staticLightData, [0, 0, 0, 255]);
                EncodeContractTexture(create, staticLightNodes, [0, 0, 0, 255]);
                EncodeContractTexture(create, dynamicLightData, [0, 0, 0, 255]);
                EncodeContractTexture(create, dynamicLightNodes, [0, 0, 0, 255]);
                EncodeContractTexture(create, shadowAtlas, [255, 255, 255, 255]);
                create.EncodeCreateTexture(marchColor);
                create.EncodeAllocateTexture2D(marchColor, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(marchColorDepth);
                create.EncodeAllocateTexture2D(marchColorDepth, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(marchFramebuffer);
                create.EncodeCreateVertexArray(marchVertexArray);
                device.Execute(create, true);
            }
            SetGlobalUniformBuffer(marchGlobalBuffer);
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("fog-march-draw"))
            {
                draw.SetGlobalInt("_StaticLightRoot", -1);
                draw.SetGlobalInt("_DynamicLightRoot", -1);
                draw.SetGlobalInt("_StaticLightTexSize", 1);
                draw.SetGlobalInt("_StaticLightTexShift", 0);
                draw.SetGlobalInt("_StaticNodeTexSize", 1);
                draw.SetGlobalInt("_StaticNodeTexShift", 0);
                draw.SetGlobalInt("_DynamicLightTexSize", 1);
                draw.SetGlobalInt("_DynamicLightTexShift", 0);
                draw.SetGlobalInt("_DynamicNodeTexSize", 1);
                draw.SetGlobalInt("_DynamicNodeTexShift", 0);
                draw.SetGlobalInt("_DirectionalLightEnabled", 0);
                draw.SetGlobalInt("_DirectionalLightShadowEnabled", 0);
                draw.SetGlobalInt("_CascadeCount", 0);
                draw.SetRenderTarget(marchFramebuffer);
                draw.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", marchGlobalBuffer);
                draw.SetRasterState(marchPass.State);
                draw.SetShader(marchVariant);
                draw.SetMaterialProperties(marchMaterial);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawArrays(marchVertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, true);
            }
            byte[] marchPixels = readback(marchColor);
            AssertMaterialPixel(marchPixels, 0, 0.672f, 0f, 0f, 0.368f);
            using (CommandBuffer marchDispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("fog-march-dispose"))
            {
                marchDispose.EncodeDisposeFramebuffer(marchFramebuffer);
                device.Execute(marchDispose, true);
            }

            ShaderCompileResult temporalCompiled = CompileMaterialContractShader(compiler, backend,
                GetHlslSource(temporalPass, "_hlslVertexSource"), GetHlslSource(temporalPass, "_hlslFragmentSource"));
            if (IsSpirvUnavailable(backend, temporalCompiled)) return [];
            Assert.True(temporalCompiled.Success, temporalCompiled.ErrorMessage);
            ShaderBindingLayout temporalLayout = Assert.IsType<ShaderBindingLayout>(temporalCompiled.BindingLayout);
            Assert.Collection(temporalLayout.Buffers,
                slot => { Assert.Equal(0, slot.Slot); Assert.Equal("GlobalUniforms", slot.Name); },
                slot => { Assert.Equal(1, slot.Slot); Assert.Equal("ObjectUniforms", slot.Name); },
                slot => { Assert.Equal(2, slot.Slot); Assert.Equal("FogTemporalPS", slot.Name); });
            Assert.Collection(temporalLayout.Textures,
                slot => { Assert.Equal(0, slot.Slot); Assert.Equal("_FogCurrentTex", slot.Name); },
                slot => { Assert.Equal(1, slot.Slot); Assert.Equal("_FogHistoryTex", slot.Name); },
                slot => { Assert.Equal(2, slot.Slot); Assert.Equal("_CameraDepthTexture", slot.Name); });

            ShaderCompileResult compositeCompiled = CompileMaterialContractShader(compiler, backend,
                GetHlslSource(compositePass, "_hlslVertexSource"), GetHlslSource(compositePass, "_hlslFragmentSource"));
            Assert.True(compositeCompiled.Success, compositeCompiled.ErrorMessage);
            ShaderBindingLayout compositeLayout = Assert.IsType<ShaderBindingLayout>(compositeCompiled.BindingLayout);
            Assert.Collection(compositeLayout.Buffers,
                slot => { Assert.Equal(0, slot.Slot); Assert.Equal("GlobalUniforms", slot.Name); },
                slot => { Assert.Equal(1, slot.Slot); Assert.Equal("ObjectUniforms", slot.Name); },
                slot => { Assert.Equal(2, slot.Slot); Assert.Equal("FogCompositePS", slot.Name); });
            Assert.Collection(compositeLayout.Textures,
                slot => { Assert.Equal(0, slot.Slot); Assert.Equal("_MainTex", slot.Name); },
                slot => { Assert.Equal(1, slot.Slot); Assert.Equal("_FogTex", slot.Name); },
                slot => { Assert.Equal(2, slot.Slot); Assert.Equal("_CameraDepthTexture", slot.Name); });

            using var temporalMaterial = new Resources.Material(shader);
            temporalMaterial.SetVector("_LowResolution", new Float2(3f, 3f));
            temporalMaterial.SetFloat("_FogHistoryValid", 1f);
            temporalMaterial.SetFloat("_FogTemporalBlend", 0.5f);
            using var compositeMaterial = new Resources.Material(shader);
            compositeMaterial.SetVector("_Resolution", new Float2(2f, 1f));
            compositeMaterial.SetVector("_LowResolution", new Float2(1f, 1f));
            compositeMaterial.SetFloat("_FogUpsampleThreshold", 0.1f);

            Rendering.FogTemporalUniformsData temporalUniforms = Rendering.MaterialUniformPacking.PackFogTemporal(temporalMaterial._properties);
            Rendering.FogCompositeUniformsData compositeUniforms = Rendering.MaterialUniformPacking.PackFogComposite(compositeMaterial._properties);
            Assert.Equal(16, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.FogTemporalUniformsData>());
            Assert.Equal(32, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.FogCompositeUniformsData>());
            Assert.Equal(new Float2(3f, 3f), temporalUniforms._LowResolution);
            Assert.Equal(0.5f, temporalUniforms._FogTemporalBlend);
            Assert.Equal(new Float2(2f, 1f), compositeUniforms._Resolution);
            Assert.Equal(0.1f, compositeUniforms._FogUpsampleThreshold);

            using var current = new Resources.Texture2D();
            using var history = new Resources.Texture2D();
            using var depth = new Resources.Texture2D();
            using var scene = new Resources.Texture2D();
            using var fog = new Resources.Texture2D();
            temporalMaterial.SetTexture("_FogCurrentTex", current);
            temporalMaterial.SetTexture("_FogHistoryTex", history);
            temporalMaterial.SetTexture("_CameraDepthTexture", depth);
            compositeMaterial.SetTexture("_MainTex", scene);
            compositeMaterial.SetTexture("_FogTex", fog);
            compositeMaterial.SetTexture("_CameraDepthTexture", depth);
            var bindings = new System.Collections.Generic.Dictionary<string, GraphicsTexture>();
            Rendering.MaterialUniformPacking.ApplyTextureBindings(bindings, temporalMaterial._properties, shader);
            Assert.Equal(3, bindings.Count);
            Assert.True(bindings.ContainsKey("_FogCurrentTex"));
            Assert.True(bindings.ContainsKey("_FogHistoryTex"));
            Assert.True(bindings.ContainsKey("_CameraDepthTexture"));

            byte[] currentPixels = new byte[3 * 3 * 4];
            for (int i = 0; i < 9; i++)
            {
                currentPixels[i * 4] = 255;
                currentPixels[i * 4 + 3] = 255;
            }
            currentPixels[4 * 4 + 1] = 0;
            currentPixels[1 * 4 + 1] = 255;
            currentPixels[2 * 4] = 0;
            currentPixels[2 * 4 + 1] = 0;
            currentPixels[2 * 4 + 2] = 0;
            byte[] globalBytes;
            Rendering.GlobalUniformsData global = new()
            {
                xengine_MatV = Float4x4.Identity,
                xengine_MatIV = Float4x4.Identity,
                xengine_MatP = Float4x4.Identity,
                xengine_MatVP = Float4x4.Identity,
                xengine_PrevViewProj = Float4x4.Identity,
                xengine_MatIP = Float4x4.Identity,
                xengine_MatIVP = Float4x4.Identity,
                xengine_MatVP_NonJittered = Float4x4.Identity,
                _ProjectionParams = new Float4(0f, 1f, 100f, 0f),
            };
            globalBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(
                System.Runtime.InteropServices.MemoryMarshal.CreateReadOnlySpan(ref global, 1)).ToArray();
            float[] vertices = [-1f, -1f, 0f, 0f, 0f, 3f, -1f, 0f, 2f, 0f, -1f, 3f, 0f, 0f, 2f];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, true);
            using var globalBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalBytes, true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var colorDepth = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Depth32f);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }, new GraphicsFrameBuffer.Attachment { Texture = colorDepth, IsDepth = true }], 2, 1);
            var vertexFormat = new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
            ]);
            using var vertexArray = new GraphicsVertexArray(vertexFormat, vertexBuffer, null);
            using ShaderVariant temporalVariant = CreateMaterialContractVariant(temporalCompiled, bytecodeFormat);
            using ShaderVariant compositeVariant = CreateMaterialContractVariant(compositeCompiled, bytecodeFormat);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("fog-post-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                create.EncodeCreateBuffer(globalBuffer, true, globalBytes);
                create.EncodeCreateTexture(current.Handle);
                create.EncodeAllocateTexture2D(current.Handle, 0, 3, 3, 0, currentPixels);
                // This fixture executes on an explicit device; Texture's queued global
                // initialization does not deliver its point-sampling state to that device.
                create.EncodeSetTextureFilters(current.Handle, current.MinFilter, current.MagFilter);
                EncodeContractTexture(create, history, [0, 255, 0, 255]);
                EncodeContractTexture(create, depth, [128, 128, 128, 255]);
                EncodeContractTexture(create, scene, [255, 255, 255, 255]);
                EncodeContractTexture(create, fog, [0, 0, 255, 128]);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(colorDepth);
                create.EncodeAllocateTexture2D(colorDepth, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, true);
            }
            SetGlobalUniformBuffer(globalBuffer);
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("fog-post-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", globalBuffer);
                draw.SetRasterState(temporalPass.State);
                draw.SetShader(temporalVariant);
                draw.SetMaterialProperties(temporalMaterial);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                draw.SetRasterState(compositePass.State);
                draw.SetShader(compositeVariant);
                draw.SetMaterialProperties(compositeMaterial);
                draw.SetViewport(1, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, true);
            }
            byte[] pixels = readback(color);
            AssertMaterialPixel(pixels, 0, 0.5f, 0.5f, 0f, 1f);
            AssertMaterialPixel(pixels, 1, 0.5f, 0.5f, 1f, 1f);
            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("fog-post-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
            byte[] capture = new byte[marchPixels.Length + pixels.Length];
            marchPixels.CopyTo(capture, 0);
            pixels.CopyTo(capture, marchPixels.Length);
            return capture;
        }
        finally
        {
            foreach ((string name, int? value) in previousFogMarchGlobals)
            {
                if (value.HasValue)
                    Rendering.PropertyState.s_globalInts[name] = value.Value;
                else
                    Rendering.PropertyState.s_globalInts.Remove(name);
            }
            SetGlobalUniformBuffer(previousGlobalBuffer);
        }
    }

    private static void RunStandardAnisotropicContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.StandardAnisotropic);
            Rendering.Shaders.ShaderPass mainPass = shader.GetPass("StandardAniso");
            Rendering.Shaders.ShaderPass prepass = shader.GetPass("Prepass");
            Rendering.Shaders.ShaderPass shadowPass = shader.GetPass("ShadowCaster");
            Assert.True(mainPass.HasHlsl);
            Assert.True(prepass.HasHlsl);
            Assert.True(shadowPass.HasHlsl);
            Assert.False(mainPass.State.DoBlend);
            Assert.True(mainPass.State.DepthWrite);
            Assert.Equal(RasterizerState.PolyFace.Back, mainPass.State.CullFace);

            string mainVertex = GetHlslSource(mainPass, "_hlslVertexSource");
            string mainFragment = GetHlslSource(mainPass, "_hlslFragmentSource");
            IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/StandardAnisotropic");
            ShaderCompileResult mainCompiled = CompileMaterialContractShader(compiler, backend, mainVertex, mainFragment);
            if (IsSpirvUnavailable(backend, mainCompiled))
                return;
            Assert.True(mainCompiled.Success, mainCompiled.ErrorMessage);
            ShaderBindingLayout mainLayout = Assert.IsType<ShaderBindingLayout>(mainCompiled.BindingLayout);
            Assert.Collection(mainLayout.Buffers,
                slot => { Assert.Equal(0, slot.Slot); Assert.Equal("GlobalUniforms", slot.Name); },
                slot => { Assert.Equal(1, slot.Slot); Assert.Equal("ObjectUniforms", slot.Name); },
                slot => { Assert.Equal(2, slot.Slot); Assert.Equal("AnisotropicMaterial", slot.Name); });

            ShaderCompileResult prepassCompiled = CompileMaterialContractShader(
                compiler, backend, GetHlslSource(prepass, "_hlslVertexSource"), GetHlslSource(prepass, "_hlslFragmentSource"));
            ShaderCompileResult shadowCompiled = CompileMaterialContractShader(
                compiler, backend, GetHlslSource(shadowPass, "_hlslVertexSource"), GetHlslSource(shadowPass, "_hlslFragmentSource"));
            Assert.True(prepassCompiled.Success, prepassCompiled.ErrorMessage);
            Assert.True(shadowCompiled.Success, shadowCompiled.ErrorMessage);
            Assert.Contains(Assert.IsType<ShaderBindingLayout>(prepassCompiled.BindingLayout).Buffers, slot => slot.Name == "PrepassMaterial");
            Assert.Contains(Assert.IsType<ShaderBindingLayout>(shadowCompiled.BindingLayout).Buffers, slot => slot.Name == "ShadowMaterial");

            using var defaultsMaterial = new Resources.Material(shader);
            using var overridesMaterial = new Resources.Material(shader);
            overridesMaterial.SetVector("_Tiling", new Float2(0.5f, 2f));
            overridesMaterial.SetVector("_Offset", new Float2(0.25f, 0.75f));
            overridesMaterial.SetColor("_MainColor", new Color(0.25f, 0.5f, 0.75f, 1f));
            overridesMaterial.SetFloat("_EmissionIntensity", 1f);
            overridesMaterial.SetFloat("_AlphaCutoff", 0.25f);
            overridesMaterial.SetFloat("_Anisotropy", 0.8f);

            Rendering.AnisotropicMaterialUniformsData defaults = Rendering.MaterialUniformPacking.PackAnisotropic(defaultsMaterial._properties, shader);
            Assert.Equal(48, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.AnisotropicMaterialUniformsData>());
            Assert.Equal(new Float2(1f, 1f), defaults._Tiling);
            Assert.Equal(new Float2(0f, 0f), defaults._Offset);
            Assert.Equal(new Float4(1f, 1f, 1f, 1f), defaults._MainColor);
            Assert.Equal(1f, defaults._EmissionIntensity);
            Assert.Equal(0.5f, defaults._AlphaCutoff);
            Assert.Equal(0.5f, defaults._Anisotropy);
            Rendering.AnisotropicMaterialUniformsData overrides = Rendering.MaterialUniformPacking.PackAnisotropic(overridesMaterial._properties, shader);
            Assert.Equal(new Float2(0.5f, 2f), overrides._Tiling);
            Assert.Equal(new Float2(0.25f, 0.75f), overrides._Offset);
            Assert.Equal(new Float4(0.25f, 0.5f, 0.75f, 1f), overrides._MainColor);
            Assert.Equal(1f, overrides._EmissionIntensity);
            Assert.Equal(0.25f, overrides._AlphaCutoff);
            Assert.Equal(0.8f, overrides._Anisotropy);
            Rendering.CutoutMaterialUniformsData cutout = Rendering.MaterialUniformPacking.PackCutout(overridesMaterial._properties, shader);
            Assert.Equal(48, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.CutoutMaterialUniformsData>());
            Assert.Equal(0.25f, cutout._AlphaCutoff);

            using var defaultMain = new Resources.Texture2D();
            using var defaultNormal = new Resources.Texture2D();
            using var defaultSurface = new Resources.Texture2D();
            using var defaultEmission = new Resources.Texture2D();
            using var defaultDirection = new Resources.Texture2D();
            using var overrideMain = new Resources.Texture2D();
            using var overrideNormal = new Resources.Texture2D();
            using var overrideSurface = new Resources.Texture2D();
            using var overrideEmission = new Resources.Texture2D();
            using var overrideDirection = new Resources.Texture2D();
            defaultsMaterial.SetTexture("_MainTex", defaultMain);
            defaultsMaterial.SetTexture("_NormalTex", defaultNormal);
            defaultsMaterial.SetTexture("_SurfaceTex", defaultSurface);
            defaultsMaterial.SetTexture("_EmissionTex", defaultEmission);
            defaultsMaterial.SetTexture("_AnisoDirectionMap", defaultDirection);
            overridesMaterial.SetTexture("_MainTex", overrideMain);
            overridesMaterial.SetTexture("_NormalTex", overrideNormal);
            overridesMaterial.SetTexture("_SurfaceTex", overrideSurface);
            overridesMaterial.SetTexture("_EmissionTex", overrideEmission);
            overridesMaterial.SetTexture("_AnisoDirectionMap", overrideDirection);
            var bindings = new System.Collections.Generic.Dictionary<string, GraphicsTexture>();
            Rendering.MaterialUniformPacking.ApplyTextureBindings(bindings, overridesMaterial._properties, shader);
            Assert.Equal(overrideMain.Handle, bindings["_MainTex"]);
            Assert.Equal(overrideNormal.Handle, bindings["_NormalTex"]);
            Assert.Equal(overrideSurface.Handle, bindings["_SurfaceTex"]);
            Assert.Equal(overrideEmission.Handle, bindings["_EmissionTex"]);
            Assert.Equal(overrideDirection.Handle, bindings["_AnisoDirectionMap"]);

            byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
            Span<float> globalUniformValues = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
            const int ViewProjectionOffset = 3 * 16;
            for (int diagonal = 0; diagonal < 4; diagonal++)
                globalUniformValues[ViewProjectionOffset + (diagonal * 5)] = 1f;
            using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, dynamic: true);
            float[] vertices =
            [
                -1f, -1f, 0f, 0f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
                -1f, 3f, 0f, 0f, 2f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
                3f, -1f, 0f, 2f, 0f, 0f, 0f, 1f, 1f, 0f, 0f, 1f,
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var depth = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Depth32f);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }, new GraphicsFrameBuffer.Attachment { Texture = depth, IsDepth = true }], 2, 1);
            var format = new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.Normal, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.Tangent, VertexFormat.VertexType.Float, 4),
            ]);
            using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
            using ShaderVariant variant = CreateMaterialContractVariant(mainCompiled, bytecodeFormat);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-anisotropic-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                create.EncodeCreateBuffer(globalUniformBuffer, true, globalUniformBytes);
                EncodeContractTexture(create, defaultMain, [255, 255, 255, 255]);
                EncodeContractTexture(create, defaultNormal, [128, 128, 255, 255]);
                EncodeContractTexture(create, defaultSurface, [0, 128, 0, 255]);
                EncodeContractTexture(create, defaultEmission, [0, 0, 0, 255]);
                EncodeContractTexture(create, defaultDirection, [128, 128, 0, 255]);
                EncodeContractTexture(create, overrideMain, [0, 0, 0, 255]);
                EncodeContractTexture(create, overrideNormal, [128, 128, 255, 255]);
                EncodeContractTexture(create, overrideSurface, [0, 128, 0, 255]);
                EncodeContractTexture(create, overrideEmission, [100, 40, 90, 255]);
                EncodeContractTexture(create, overrideDirection, [255, 0, 0, 255]);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(depth);
                create.EncodeAllocateTexture2D(depth, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, wait: true);
            }
            SetGlobalUniformBuffer(globalUniformBuffer);
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-anisotropic-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
                draw.SetRasterState(mainPass.State);
                DrawMaterialPixel(draw, vertexArray, variant, defaultsMaterial, 0);
                DrawMaterialPixel(draw, vertexArray, variant, overridesMaterial, 1);
                device.Execute(draw, wait: true);
            }
            byte[] pixels = readback(color);
            AssertMaterialPixel(pixels, 0, 1f, 1f, 1f, 1f);
            AssertMaterialPixel(pixels, 1, 100f / 255f, 40f / 255f, 90f / 255f, 1f);
            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-anisotropic-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, wait: true);
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
        }
    }

    private static string GetHlslSource(Rendering.Shaders.ShaderPass pass, string fieldName) =>
        (string)typeof(Rendering.Shaders.ShaderPass)
            .GetField(fieldName, System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(pass)!;

    private static bool IsSpirvUnavailable(GraphicsBackend backend, ShaderCompileResult result) =>
        backend == GraphicsBackend.Vulkan && !result.Success &&
        result.ErrorMessage?.Contains("SPIR-V CodeGen not available", StringComparison.OrdinalIgnoreCase) == true;

    // True when an exception's message (or inner chain) indicates the host DXC cannot emit SPIR-V.
    // Used by the UniversalRenderPipeline scene-matrix helper to skip the Vulkan leg when the Vulkan
    // SDK is not installed, matching the contract-test skip pattern.
    private static bool IsSpirvCodeGenUnavailable(Exception ex)
    {
        for (Exception? e = ex; e != null; e = e.InnerException)
        {
            if (e.Message.Contains("SPIR-V CodeGen not available", StringComparison.OrdinalIgnoreCase))
                return true;
        }
        return false;
    }

    private static void RunRefractionContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            RunRefractionContractCore(device, backend, bytecodeFormat, readback);
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
        }
    }

    private static void RunRefractionContractCore(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.Refraction);
        Assert.NotNull(shader);
        Rendering.Shaders.ShaderPass pass = shader.GetPass("Refraction");
        Assert.True(pass.HasHlsl);
        Assert.True(pass.HasGrabTexture);
        Assert.Equal("_GrabTexture", pass.GrabTextureName);

        string vertexSource = (string)typeof(Rendering.Shaders.ShaderPass)
            .GetField("_hlslVertexSource", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(pass)!;
        string fragmentSource = (string)typeof(Rendering.Shaders.ShaderPass)
            .GetField("_hlslFragmentSource", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(pass)!;
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/Refraction");
        ShaderCompileResult compiled = CompileMaterialContractShader(compiler, backend, vertexSource, fragmentSource);
        if (!compiled.Success &&
            backend == GraphicsBackend.Vulkan &&
            compiled.ErrorMessage?.Contains("SPIR-V CodeGen not available", StringComparison.OrdinalIgnoreCase) == true)
        {
            return;
        }

        Assert.True(compiled.Success, compiled.ErrorMessage);
        ShaderBindingLayout bindingLayout = Assert.IsType<ShaderBindingLayout>(compiled.BindingLayout);
        Assert.Collection(
            bindingLayout.Buffers,
            slot => { Assert.Equal(0, slot.Slot); Assert.Equal("GlobalUniforms", slot.Name); },
            slot => { Assert.Equal(1, slot.Slot); Assert.Equal("ObjectUniforms", slot.Name); },
            slot => { Assert.Equal(2, slot.Slot); Assert.Equal("RefractionMaterial", slot.Name); });
        Assert.Collection(
            bindingLayout.Textures,
            slot => { Assert.Equal(0, slot.Slot); Assert.Equal("_GrabTexture", slot.Name); });
        Assert.Collection(
            bindingLayout.Samplers,
            slot => { Assert.Equal(0, slot.Slot); Assert.Equal("_GrabTextureSampler", slot.Name); });
        using ShaderVariant variant = CreateMaterialContractVariant(compiled, bytecodeFormat);

        Assert.True(pass.State.DoBlend);
        Assert.Equal(RasterizerState.Blending.SrcAlpha, pass.State.BlendSrc);
        Assert.Equal(RasterizerState.Blending.OneMinusSrcAlpha, pass.State.BlendDst);
        Assert.False(pass.State.DepthWrite);
        Assert.Equal(RasterizerState.PolyFace.Back, pass.State.CullFace);

        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetFloat("_RefractionStrength", 0.25f);
        overridesMaterial.SetFloat("_NoiseScale", 2f);
        overridesMaterial.SetColor("_Tint", new Color(0.5f, 0.25f, 0.75f, 1f));
        overridesMaterial.SetFloat("_BlurRadius", 0.125f);
        overridesMaterial.SetFloat("_BlurMIP", 0f);
        overridesMaterial.SetInt("_BlurSteps", 2);

        Rendering.RefractionMaterialUniformsData defaults = Rendering.MaterialUniformPacking.PackRefraction(defaultsMaterial._properties, shader);
        Assert.Equal(48, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.RefractionMaterialUniformsData>());
        Assert.Equal(0.1f, defaults._RefractionStrength);
        Assert.Equal(1f, defaults._NoiseScale);
        Assert.Equal(new Float4(1f, 1f, 1f, 1f), defaults._Tint);
        Assert.Equal(0.02f, defaults._BlurRadius);
        Assert.Equal(2f, defaults._BlurMIP);
        Assert.Equal(4, defaults._BlurSteps);
        Rendering.RefractionMaterialUniformsData overrides = Rendering.MaterialUniformPacking.PackRefraction(overridesMaterial._properties, shader);
        Assert.Equal(0.25f, overrides._RefractionStrength);
        Assert.Equal(2f, overrides._NoiseScale);
        Assert.Equal(new Float4(0.5f, 0.25f, 0.75f, 1f), overrides._Tint);
        Assert.Equal(0.125f, overrides._BlurRadius);
        Assert.Equal(0f, overrides._BlurMIP);
        Assert.Equal(2, overrides._BlurSteps);

        byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
        Span<float> globalUniformValues = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
        const int ViewProjectionOffset = 3 * 16;
        for (int diagonal = 0; diagonal < 4; diagonal++)
            globalUniformValues[ViewProjectionOffset + (diagonal * 5)] = 1f;
        const int ScreenParamsOffset = (8 * 16) + 4 + 4;
        globalUniformValues[ScreenParamsOffset] = 2f;
        globalUniformValues[ScreenParamsOffset + 1] = 1f;
        globalUniformValues[ScreenParamsOffset + 2] = 0.5f;
        globalUniformValues[ScreenParamsOffset + 3] = 1f;
        using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, dynamic: true);
        using var defaultGrabTexture = new Resources.Texture2D();
        using var overrideGrabTexture = new Resources.Texture2D();

        float[] vertices =
        [
            -1f, -1f, 0f, 0f, 0f, 0f, 0f, 1f,
            -1f, 3f, 0f, 0f, 2f, 0f, 0f, 1f,
            3f, -1f, 0f, 2f, 0f, 0f, 0f, 1f,
        ];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        using var depth = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Depth32f);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
            [
                new GraphicsFrameBuffer.Attachment { Texture = color },
                new GraphicsFrameBuffer.Attachment { Texture = depth, IsDepth = true },
            ],
            2,
            1);
        var format = new VertexFormat([
            new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
            new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
            new(VertexFormat.VertexSemantic.Normal, VertexFormat.VertexType.Float, 3),
        ]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("refraction-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
            create.EncodeCreateBuffer(globalUniformBuffer, dynamic: true, globalUniformBytes);
            EncodeContractTexture(create, defaultGrabTexture, [64, 128, 192, 255]);
            EncodeContractTexture(create, overrideGrabTexture, [200, 160, 120, 255]);
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateTexture(depth);
            create.EncodeAllocateTexture2D(depth, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, wait: true);
        }
        SetGlobalUniformBuffer(globalUniformBuffer);

        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("refraction-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0f, 0f, 0f, 0f));
            draw.DisableScissor();
            draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
            draw.SetRasterState(pass.State);
            draw.SetGlobalTexture("_GrabTexture", defaultGrabTexture);
            DrawMaterialPixel(draw, vertexArray, variant, defaultsMaterial, 0);
            draw.SetGlobalTexture("_GrabTexture", overrideGrabTexture);
            DrawMaterialPixel(draw, vertexArray, variant, overridesMaterial, 1);
            draw.ClearGlobalTexture("_GrabTexture");
            device.Execute(draw, wait: true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 64f / 255f, 128f / 255f, 192f / 255f, 1f);
        AssertMaterialPixel(pixels, 1, 100f / 255f, 40f / 255f, 90f / 255f, 1f);

        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("refraction-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, wait: true);
    }

    private static void RunCinematicEffectsContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.CinematicEffects);
        Rendering.Shaders.ShaderPass pass = shader.GetPass("CinematicEffects");
        string vertexSource = (string)typeof(Rendering.Shaders.ShaderPass)
            .GetField("_hlslVertexSource", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!.GetValue(pass)!;
        string fragmentSource = (string)typeof(Rendering.Shaders.ShaderPass)
            .GetField("_hlslFragmentSource", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!.GetValue(pass)!;
        ShaderCompileResult compiled = ShaderCompilerFactory.GetCompiler(backend, "Default/CinematicEffects").Compile(new ShaderCompileRequest
        {
            TargetBackend = backend,
            Language = ShaderLanguage.Hlsl,
            VertexSource = vertexSource,
            FragmentSource = fragmentSource,
        });
        if (!compiled.Success && backend == GraphicsBackend.Vulkan &&
            compiled.ErrorMessage?.Contains("SPIR-V CodeGen not available", StringComparison.OrdinalIgnoreCase) == true) return;
        Assert.True(compiled.Success, compiled.ErrorMessage);
        ShaderBindingLayout layout = Assert.IsType<ShaderBindingLayout>(compiled.BindingLayout);
        Assert.Collection(layout.Buffers,
            slot => { Assert.Equal(0, slot.Slot); Assert.Equal("GlobalUniforms", slot.Name); },
            slot => { Assert.Equal(1, slot.Slot); Assert.Equal("ObjectUniforms", slot.Name); },
            slot => { Assert.Equal(2, slot.Slot); Assert.Equal("CinematicEffectsPS", slot.Name); });
        Assert.Collection(layout.Textures,
            slot => Assert.Equal("_MainTex", slot.Name),
            slot => Assert.Equal("_LUTTex", slot.Name),
            slot => Assert.Equal("_CameraDepthTexture", slot.Name));
        using ShaderVariant variant = CreateMaterialContractVariant(compiled, bytecodeFormat);

        using var material = new Resources.Material(shader);
        material.SetVector("_Resolution", new Float2(1f, 1f));
        material.SetFloat("_VignetteIntensity", 0f); material.SetFloat("_VignetteSmoothness", 0.2f); material.SetFloat("_VignetteRoundness", 1f);
        material.SetFloat("_ChromaticIntensity", 0f); material.SetFloat("_ChromaticDistortion", 0.5f);
        material.SetFloat("_GrainIntensity", 0f); material.SetFloat("_GrainResponse", 0.5f);
        material.SetFloat("_PostExposure", 0f); material.SetFloat("_Contrast", 0f); material.SetFloat("_Saturation", 0f); material.SetFloat("_Temperature", 0f);
        material.SetColor("_Lift", new Color(0f, 0f, 0f, 0f)); material.SetColor("_Gamma", new Color(0f, 0f, 0f, 0f)); material.SetColor("_Gain", new Color(0f, 0f, 0f, 0f));
        material.SetFloat("_LUTContribution", 1f); material.SetFloat("_LUTSize", 1f);
        material.SetFloat("_SharpenAmount", 0f); material.SetFloat("_SharpenRadius", 1f);
        material.SetFloat("_EdgeIntensity", 0f); material.SetColor("_EdgeColor", new Color(0f, 0f, 0f, 1f)); material.SetFloat("_EdgeBackgroundFade", 1f);
        material.SetFloat("_PixelSize", 1f); material.SetFloat("_GodRayIntensity", 0f); material.SetFloat("_GodRayDecay", 0.96f);
        material.SetFloat("_GodRayDensity", 0.5f); material.SetFloat("_GodRayWeight", 0.6f); material.SetInt("_GodRaySamples", 8);
        material.SetFloat("_GodRayThreshold", 1f); material.SetVector("_SunScreenPos", new Float2(0.5f, 0.5f));
        material.SetInt("_EffectFlags", (int)Rendering.CinematicEffectFlags.All);
        Rendering.CinematicEffectsUniformsData packed = Rendering.MaterialUniformPacking.PackCinematicEffects(material._properties);
        Assert.Equal(192, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.CinematicEffectsUniformsData>());
        Assert.Equal(8, packed._GodRaySamples);
        Assert.Equal((int)Rendering.CinematicEffectFlags.All, packed._EffectFlags);

        using var mainTexture = new Resources.Texture2D(); using var lutTexture = new Resources.Texture2D(); using var depthTexture = new Resources.Texture2D();
        material.SetTexture("_MainTex", mainTexture); material.SetTexture("_LUTTex", lutTexture); material.SetTexture("_CameraDepthTexture", depthTexture);
        byte[] globalBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
        using var globalBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalBytes, true);
        float[] vertices = [-1f, -1f, 0f, 0f, 0f, -1f, 3f, 0f, 0f, 2f, 3f, -1f, 0f, 2f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 1, 1);
        using var vertexArray = new GraphicsVertexArray(new VertexFormat([
            new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
            new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2)]), vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("cinematic-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes); create.EncodeCreateBuffer(globalBuffer, true, globalBytes);
            EncodeContractTexture(create, mainTexture, [64, 128, 192, 255]); EncodeContractTexture(create, lutTexture, [24, 200, 80, 255]); EncodeContractTexture(create, depthTexture, [255, 255, 255, 255]);
            create.EncodeCreateTexture(color); create.EncodeAllocateTexture2D(color, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer); create.EncodeCreateVertexArray(vertexArray); device.Execute(create, true);
        }
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("cinematic-draw"))
        {
            draw.SetRenderTarget(framebuffer); draw.DisableScissor(); draw.SetBuffer("GlobalUniforms", globalBuffer); draw.SetRasterState(pass.State);
            DrawMaterialPixel(draw, vertexArray, variant, material, 0); device.Execute(draw, true);
        }
        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 24f / 255f, 200f / 255f, 80f / 255f, 1f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("cinematic-dispose"); dispose.EncodeDisposeFramebuffer(framebuffer); device.Execute(dispose, true);
    }

    private static void RunStandardMaterialTextureContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        string vertexSource = backend == GraphicsBackend.Vulkan
            ? "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }"
            : "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string bindingPrefix0 = "";
        const string bindingPrefix1 = "";
        const string bindingPrefix2 = "";
        const string bindingPrefix3 = "";
        string fragmentSource =
            bindingPrefix0 + "Texture2D _MainTex : register(t0); " + bindingPrefix0 + "SamplerState _MainTexSampler : register(s0); " +
            bindingPrefix1 + "Texture2D _NormalTex : register(t1); " + bindingPrefix1 + "SamplerState _NormalTexSampler : register(s1); " +
            bindingPrefix2 + "Texture2D _SurfaceTex : register(t2); " + bindingPrefix2 + "SamplerState _SurfaceTexSampler : register(s2); " +
            bindingPrefix3 + "Texture2D _EmissionTex : register(t3); " + bindingPrefix3 + "SamplerState _EmissionTexSampler : register(s3); " +
            "float4 main() : SV_Target { float2 uv = float2(0.5, 0.5); return float4(_MainTex.Sample(_MainTexSampler, uv).r, _NormalTex.Sample(_NormalTexSampler, uv).g, _SurfaceTex.Sample(_SurfaceTexSampler, uv).b, _EmissionTex.Sample(_EmissionTexSampler, uv).a); }";
        var compiler = new DxcShaderCompiler();
        ShaderCompileResult compiled = CompileMaterialContractShader(compiler, backend, vertexSource, fragmentSource);
        if (!compiled.Success)
            return;

        using var variant = CreateMaterialContractVariant(compiled, bytecodeFormat);
        using var defaultMain = new Resources.Texture2D();
        using var defaultNormal = new Resources.Texture2D();
        using var defaultSurface = new Resources.Texture2D();
        using var defaultEmission = new Resources.Texture2D();
        using var overrideMain = new Resources.Texture2D();
        using var overrideNormal = new Resources.Texture2D();
        using var overrideSurface = new Resources.Texture2D();
        using var overrideEmission = new Resources.Texture2D();
        using var shader = CreateStandardTextureContractShader(defaultMain, defaultNormal, defaultSurface, defaultEmission);
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetTexture("_MainTex", overrideMain);
        overridesMaterial.SetTexture("_NormalTex", overrideNormal);
        overridesMaterial.SetTexture("_SurfaceTex", overrideSurface);
        overridesMaterial.SetTexture("_EmissionTex", overrideEmission);

        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 2, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-texture-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, defaultMain, new byte[] { 64, 0, 0, 255 });
            EncodeContractTexture(create, defaultNormal, new byte[] { 0, 128, 0, 255 });
            EncodeContractTexture(create, defaultSurface, new byte[] { 0, 0, 192, 255 });
            EncodeContractTexture(create, defaultEmission, new byte[] { 0, 0, 0, 255 });
            EncodeContractTexture(create, overrideMain, new byte[] { 192, 0, 0, 255 });
            EncodeContractTexture(create, overrideNormal, new byte[] { 0, 64, 0, 255 });
            EncodeContractTexture(create, overrideSurface, new byte[] { 0, 0, 128, 255 });
            EncodeContractTexture(create, overrideEmission, new byte[] { 0, 0, 0, 128 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-texture-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetShader(variant);
            draw.SetRasterState(in raster);
            draw.SetMaterialProperties(defaultsMaterial);
            draw.SetViewport(0, 0, 1, 1);
            draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
            draw.SetMaterialProperties(overridesMaterial);
            draw.SetViewport(1, 0, 1, 1);
            draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
            device.Execute(draw, true);
        }

        Assert.Equal(new byte[] { 64, 128, 192, 255, 192, 64, 128, 128 }, readback(color));
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("standard-texture-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
    }

    private static byte[] RunGradientSkyboxMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        string vertexSource = backend == GraphicsBackend.Vulkan
            ? "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }"
            : "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string fragmentSource = "cbuffer GradientPS : register(b2) { float4 _TopColor; float4 _BottomColor; float _Exponent; }; float4 main() : SV_Target { return float4(_TopColor.r, _BottomColor.g, _Exponent / 4.0, _TopColor.a); }";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/GradientSkybox");
        ShaderCompileResult compiled = CompileMaterialContractShader(compiler, backend, vertexSource, fragmentSource);
        Assert.True(compiled.Success, compiled.ErrorMessage);

        using var variant = CreateMaterialContractVariant(compiled, bytecodeFormat);
        using var shader = CreateGradientSkyboxContractShader();
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetColor("_TopColor", new Color(0.875f, 0f, 0f, 1f));
        overridesMaterial.SetVector("_BottomColor", new Float4(0f, 0.25f, 0f, 1f));
        overridesMaterial.SetFloat("_Exponent", 3f);

        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 2, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("gradient-skybox-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("gradient-skybox-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, variant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, variant, overridesMaterial, 1);
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.125f, 0.75f, 0.5f, 0.5f);
        AssertMaterialPixel(pixels, 1, 0.875f, 0.25f, 0.75f, 1f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("gradient-skybox-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
        return pixels;
    }

    private static byte[] RunCubemapSkyboxMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        string[] bindings = backend == GraphicsBackend.Vulkan
            ? ["", "", "", "", "", ""]
            : [string.Empty, string.Empty, string.Empty, string.Empty, string.Empty, string.Empty];
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string block = "cbuffer CubemapSkyboxPS : register(b2) { float4 _Tint; float _Exposure; float3 _Padding; }; ";
        string resources = bindings[0] + "Texture2D _CubeRight : register(t0); " + bindings[0] + "SamplerState _CubeRightSampler : register(s0); "
            + bindings[1] + "Texture2D _CubeLeft : register(t1); " + bindings[1] + "SamplerState _CubeLeftSampler : register(s1); "
            + bindings[2] + "Texture2D _CubeTop : register(t2); " + bindings[2] + "SamplerState _CubeTopSampler : register(s2); "
            + bindings[3] + "Texture2D _CubeBottom : register(t3); " + bindings[3] + "SamplerState _CubeBottomSampler : register(s3); "
            + bindings[4] + "Texture2D _CubeFront : register(t4); " + bindings[4] + "SamplerState _CubeFrontSampler : register(s4); "
            + bindings[5] + "Texture2D _CubeBack : register(t5); " + bindings[5] + "SamplerState _CubeBackSampler : register(s5); ";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/CubemapSkybox");
        ShaderCompileResult constants = CompileMaterialContractShader(compiler, backend, vertexSource, block + "float4 main() : SV_Target { return float4(_Tint.rgb, _Exposure / 4.0); }");
        ShaderCompileResult firstFaces = CompileMaterialContractShader(compiler, backend, vertexSource, block + resources + "float4 main() : SV_Target { float2 uv = float2(0.5, 0.5); return float4(_CubeRight.Sample(_CubeRightSampler, uv).r, _CubeLeft.Sample(_CubeLeftSampler, uv).g, _CubeTop.Sample(_CubeTopSampler, uv).b, _CubeBottom.Sample(_CubeBottomSampler, uv).a); }");
        ShaderCompileResult lastFaces = CompileMaterialContractShader(compiler, backend, vertexSource, block + resources + "float4 main() : SV_Target { float2 uv = float2(0.5, 0.5); return float4(_CubeFront.Sample(_CubeFrontSampler, uv).r, _CubeBack.Sample(_CubeBackSampler, uv).g, _Tint.b, _Exposure / 4.0); }");
        Assert.True(constants.Success, constants.ErrorMessage);
        Assert.True(firstFaces.Success, firstFaces.ErrorMessage);
        Assert.True(lastFaces.Success, lastFaces.ErrorMessage);

        using var constantsVariant = CreateMaterialContractVariant(constants, bytecodeFormat);
        using var firstFacesVariant = CreateMaterialContractVariant(firstFaces, bytecodeFormat);
        using var lastFacesVariant = CreateMaterialContractVariant(lastFaces, bytecodeFormat);
        Resources.Texture2D[] defaultFaces = [new(), new(), new(), new(), new(), new()];
        Resources.Texture2D[] overrideFaces = [new(), new(), new(), new(), new(), new()];
        using var shader = CreateCubemapSkyboxContractShader(defaultFaces);
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetColor("_Tint", new Color(0.25f, 0.5f, 0.75f, 1f));
        overridesMaterial.SetFloat("_Exposure", 2f);
        string[] names = ["_CubeRight", "_CubeLeft", "_CubeTop", "_CubeBottom", "_CubeFront", "_CubeBack"];
        for (int i = 0; i < names.Length; i++)
            overridesMaterial.SetTexture(names[i], overrideFaces[i]);

        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 6, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("cubemap-skybox-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            byte[][] defaultPixels = [[32, 1, 1, 255], [1, 64, 1, 255], [1, 1, 96, 255], [1, 1, 1, 128], [160, 1, 1, 255], [1, 192, 1, 255]];
            byte[][] overridePixels = [[224, 1, 1, 255], [1, 160, 1, 255], [1, 1, 128, 255], [1, 1, 1, 64], [96, 1, 1, 255], [1, 80, 1, 255]];
            for (int i = 0; i < defaultFaces.Length; i++)
            {
                EncodeContractTexture(create, defaultFaces[i], defaultPixels[i]);
                EncodeContractTexture(create, overrideFaces[i], overridePixels[i]);
            }
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 6, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("cubemap-skybox-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, constantsVariant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, constantsVariant, overridesMaterial, 1);
            DrawMaterialPixel(draw, vertexArray, firstFacesVariant, defaultsMaterial, 2);
            DrawMaterialPixel(draw, vertexArray, firstFacesVariant, overridesMaterial, 3);
            DrawMaterialPixel(draw, vertexArray, lastFacesVariant, defaultsMaterial, 4);
            DrawMaterialPixel(draw, vertexArray, lastFacesVariant, overridesMaterial, 5);
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 1f, 1f, 1f, 0.25f);
        AssertMaterialPixel(pixels, 1, 0.25f, 0.5f, 0.75f, 0.5f);
        AssertMaterialPixel(pixels, 2, 32f / 255f, 64f / 255f, 96f / 255f, 128f / 255f);
        AssertMaterialPixel(pixels, 3, 224f / 255f, 160f / 255f, 128f / 255f, 64f / 255f);
        AssertMaterialPixel(pixels, 4, 160f / 255f, 192f / 255f, 1f, 0.25f);
        AssertMaterialPixel(pixels, 5, 96f / 255f, 80f / 255f, 0.75f, 0.5f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("cubemap-skybox-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
        for (int i = 0; i < defaultFaces.Length; i++)
        {
            defaultFaces[i].Dispose();
            overrideFaces[i].Dispose();
        }
        return pixels;
    }

    private static byte[] RunProceduralSkyboxMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        string vertexSource = "cbuffer SkyVS : register(b2) { float2 Resolution; float fogDensity; float3 _SunDir; }; struct VSInput { " + location + "float3 position : POSITION; }; struct VSOutput { float4 position : SV_Position; float4 data : TEXCOORD0; }; VSOutput main(VSInput input) { VSOutput output; output.position = float4(input.position, 1); output.data = float4(Resolution.x / 8.0, fogDensity, _SunDir.z, _SunDir.x); return output; }";
        const string fragmentSource = "struct PSInput { float4 position : SV_Position; float4 data : TEXCOORD0; }; float4 main(PSInput input) : SV_Target { return input.data; }";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/ProceduralSkybox");
        ShaderCompileResult compiled = CompileMaterialContractShader(compiler, backend, vertexSource, fragmentSource);
        Assert.True(compiled.Success, compiled.ErrorMessage);

        using var variant = CreateMaterialContractVariant(compiled, bytecodeFormat);
        using var shader = CreateProceduralSkyboxContractShader();
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetVector("Resolution", new Float2(6f, 1f));
        overridesMaterial.SetFloat("fogDensity", 0.25f);
        overridesMaterial.SetVector("_SunDir", new Float3(0.875f, 0f, 0.5f));

        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 2, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("procedural-skybox-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("procedural-skybox-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, variant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, variant, overridesMaterial, 1);
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.25f, 0.5f, 0.75f, 0.125f);
        AssertMaterialPixel(pixels, 1, 0.75f, 0.25f, 0.5f, 0.875f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("procedural-skybox-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
        return pixels;
    }

    private static byte[] RunTonemapperMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        const string binding = "";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        string fragmentSource = "cbuffer TonemapperPS : register(b2) { float Contrast; float Saturation; }; " + binding + "Texture2D _MainTex : register(t0); " + binding + "SamplerState _MainTexSampler : register(s0); float4 main() : SV_Target { float4 sampled = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); return float4(Contrast / 2.0, Saturation / 2.0, sampled.b, sampled.a); }";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/Tonemapper");
        ShaderCompileResult compiled = CompileMaterialContractShader(compiler, backend, vertexSource, fragmentSource);
        Assert.True(compiled.Success, compiled.ErrorMessage);

        using var variant = CreateMaterialContractVariant(compiled, bytecodeFormat);
        using var defaultTexture = new Resources.Texture2D();
        using var overrideTexture = new Resources.Texture2D();
