            EncodeContractTexture(create, overrideMain, new byte[] { 200, 120, 240, 128 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 4, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("sprite-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, constantsVariant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, constantsVariant, overridesMaterial, 1);
            DrawMaterialPixel(draw, vertexArray, shadedVariant, defaultsMaterial, 2);
            DrawMaterialPixel(draw, vertexArray, shadedVariant, overridesMaterial, 3);
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 1f, 0f, 1f, 1f);
        AssertMaterialPixel(pixels, 1, 0.5f, 0.25f, 0.75f, 0.625f);
        AssertMaterialPixel(pixels, 2, 64f / 255f, 128f / 255f, 192f / 255f, 1f);
        AssertMaterialPixel(pixels, 3, (200f / 255f) * 0.75f, (120f / 255f) * 0.5f, (240f / 255f) * 0.25f, (128f / 255f) * 0.625f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("sprite-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
    }

    private static void RunLineMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        const string binding = "";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        string resources = binding + "Texture2D _MainTex : register(t0); " + binding + "SamplerState _MainTexSampler : register(s0); ";
        string fragmentSource = resources + "struct PSOutput { float4 gAlbedo : SV_Target0; float4 gMotionVector : SV_Target1; float4 gNormal : SV_Target2; float4 gSurface : SV_Target3; }; PSOutput main() { PSOutput o; float4 albedo = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); o.gAlbedo = albedo; o.gMotionVector = float4(0.25, 0.5, 0, 1); o.gNormal = float4(0, 0, 1, 1); o.gSurface = float4(1, 0, 0, 1); return o; }";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/Line");
        ShaderCompileResult compiled = CompileMaterialContractShader(compiler, backend, vertexSource, fragmentSource);
        if (!compiled.Success)
            return;

        using var variant = CreateMaterialContractVariant(compiled, bytecodeFormat);
        using var defaultMain = new Resources.Texture2D();
        using var overrideMain = new Resources.Texture2D();
        using var shader = CreateUnlitTextureContractShader(defaultMain);
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetTexture("_MainTex", overrideMain);

        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var albedo = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        using var motion = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        using var normal = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        using var surface = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
            [
                new GraphicsFrameBuffer.Attachment { Texture = albedo },
                new GraphicsFrameBuffer.Attachment { Texture = motion },
                new GraphicsFrameBuffer.Attachment { Texture = normal },
                new GraphicsFrameBuffer.Attachment { Texture = surface },
            ],
            2,
            1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("line-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, defaultMain, new byte[] { 64, 128, 192, 255 });
            EncodeContractTexture(create, overrideMain, new byte[] { 200, 120, 240, 128 });
            create.EncodeCreateTexture(albedo);
            create.EncodeAllocateTexture2D(albedo, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateTexture(motion);
            create.EncodeAllocateTexture2D(motion, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateTexture(normal);
            create.EncodeAllocateTexture2D(normal, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateTexture(surface);
            create.EncodeAllocateTexture2D(surface, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("line-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, variant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, variant, overridesMaterial, 1);
            device.Execute(draw, true);
        }

        byte[] albedoPixels = readback(albedo);
        AssertMaterialPixel(albedoPixels, 0, 64f / 255f, 128f / 255f, 192f / 255f, 1f);
        AssertMaterialPixel(albedoPixels, 1, 200f / 255f, 120f / 255f, 240f / 255f, 128f / 255f);
        AssertMaterialPixel(readback(normal), 0, 0f, 0f, 1f, 1f);
        AssertMaterialPixel(readback(surface), 0, 1f, 0f, 0f, 1f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("line-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
    }

    private static byte[] RunParticleMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        GraphicsBuffer? previousGlobalBuffer = GetGlobalUniformBuffer();
        try
        {
            Resources.Shader shader = Resources.Shader.LoadDefault(Resources.DefaultShader.Particle);
            Rendering.Shaders.ShaderPass pass = shader.GetPass("Particle");
            Assert.True(pass.HasHlsl);

            IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, shader.Name);
            var keywords = new System.Collections.Generic.Dictionary<string, bool> { ["GPU_INSTANCING"] = true };
            ShaderCompileResult compiled = compiler.Compile(new ShaderCompileRequest
            {
                TargetBackend = backend,
                Language = ShaderLanguage.Hlsl,
                VertexSource = GetHlslSource(pass, "_hlslVertexSource"),
                FragmentSource = GetHlslSource(pass, "_hlslFragmentSource"),
                Keywords = keywords,
            });
            if (IsSpirvUnavailable(backend, compiled)) return [];
            Assert.True(compiled.Success, compiled.ErrorMessage);
            ShaderBindingLayout layout = Assert.IsType<ShaderBindingLayout>(compiled.BindingLayout);
            Assert.Contains(layout.Buffers, slot => slot.Slot == 0 && slot.Name == "GlobalUniforms");
            Assert.Contains(layout.Buffers, slot => slot.Slot == 1 && slot.Name == "ObjectUniforms");
            Assert.Contains(layout.Buffers, slot => slot.Slot == 2 && slot.Name == "ParticleMaterial");
            Assert.Contains(layout.Textures, slot => slot.Slot == 0 && slot.Name == "_MainTex");

            using var mainTexture = new Resources.Texture2D();
            using var material = new Resources.Material(shader);
            material.SetTexture("_MainTex", mainTexture);
            Rendering.ParticleMaterialUniformsData uniforms = Rendering.MaterialUniformPacking.PackParticle(material._properties, shader);
            Assert.Equal(32, System.Runtime.InteropServices.Marshal.SizeOf<Rendering.ParticleMaterialUniformsData>());
            Assert.Equal(new Float4(1f, 1f, 1f, 1f), uniforms._MainColor);
            Assert.Equal(1f, uniforms._SoftParticlesFactor);

            byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
            Span<float> globals = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
            const int ViewOffset = 0;
            const int ViewProjectionOffset = 3 * 16;
            for (int diagonal = 0; diagonal < 4; diagonal++)
            {
                globals[ViewOffset + (diagonal * 5)] = 1f;
                globals[ViewProjectionOffset + (diagonal * 5)] = 1f;
            }

            float[] vertices =
            [
                -0.5f, -0.25f, 0f, 0f, 1f, 1f, 1f, 1f, 1f,
                 0.5f, -0.25f, 0f, 1f, 1f, 1f, 1f, 1f, 1f,
                 0.5f,  0.25f, 0f, 1f, 0f, 1f, 1f, 1f, 1f,
                -0.5f,  0.25f, 0f, 0f, 0f, 1f, 1f, 1f, 1f,
            ];
            ushort[] indices = [0, 1, 2, 0, 2, 3];
            Rendering.InstanceData[] instances =
            [
                new Rendering.InstanceData
                {
                    ModelRow0 = new Float4(0.7f, 0f, 0f, 0f),
                    ModelRow1 = new Float4(0f, 1.3f, 0f, 0f),
                    ModelRow2 = new Float4(0f, 0f, 1f, 0f),
                    ModelRow3 = new Float4(-0.5f, 0f, 0f, 1f),
                    Color = new Color(1f, 0f, 0f, 1f),
                    CustomData = new Float4(0.25f, 0f, 0f, 0.5f),
                },
                new Rendering.InstanceData
                {
                    ModelRow0 = new Float4(0f, 0.7f, 0f, 0f),
                    ModelRow1 = new Float4(-1.3f, 0f, 0f, 0f),
                    ModelRow2 = new Float4(0f, 0f, 1f, 0f),
                    ModelRow3 = new Float4(0.5f, 0f, 0f, 1f),
                    Color = new Color(0f, 1f, 0f, 1f),
                    CustomData = new Float4(0.75f, 0.5f, 0f, 0.5f),
                },
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            ReadOnlySpan<byte> indexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(indices.AsSpan());
            ReadOnlySpan<byte> instanceBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(instances.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, true);
            using var indexBuffer = new GraphicsBuffer(BufferType.ElementsBuffer, indexBytes, true);
            using var instanceBuffer = new GraphicsBuffer(BufferType.VertexBuffer, instanceBytes, true);
            using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, true);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var depth = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Depth32f);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }, new GraphicsFrameBuffer.Attachment { Texture = depth, IsDepth = true }], 16, 8);
            var vertexFormat = new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
                new(VertexFormat.VertexSemantic.Color, VertexFormat.VertexType.Float, 4),
            ]);
            var instanceFormat = new VertexFormat([
                new((VertexFormat.VertexSemantic)8, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)9, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)10, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)11, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)12, VertexFormat.VertexType.Float, 4, divisor: 1),
                new((VertexFormat.VertexSemantic)13, VertexFormat.VertexType.Float, 4, divisor: 1),
            ]);
            using var vertexArray = new GraphicsVertexArray(vertexFormat, vertexBuffer, indexBuffer, instanceFormat, instanceBuffer);
            using ShaderVariant variant = CreateMaterialContractVariant(compiled, bytecodeFormat);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("particle-instancing-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
                create.EncodeCreateBuffer(indexBuffer, true, indexBytes);
                create.EncodeCreateBuffer(instanceBuffer, true, instanceBytes);
                create.EncodeCreateBuffer(globalUniformBuffer, true, globalUniformBytes);
                create.EncodeCreateTexture(mainTexture.Handle);
                create.EncodeAllocateTexture2D(mainTexture.Handle, 0, 2, 1, 0,
                    [255, 0, 0, 255, 255, 255, 0, 255]);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 16, 8, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(depth);
                create.EncodeAllocateTexture2D(depth, 0, 16, 8, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, true);
            }

            SetGlobalUniformBuffer(globalUniformBuffer);
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("particle-instancing-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0f, 0f, 0f, 0f));
                draw.DisableScissor();
                draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
                draw.SetRasterState(pass.State);
                draw.SetShader(variant);
                draw.SetMaterialProperties(material);
                // zonezero M9: soft-particle fade samples the camera depth texture; bind the
                // contract framebuffer's depth attachment the way CopyDepth does globally.
                draw.SetTexture("_CameraDepthTexture", depth);
                draw.SetViewport(0, 0, 16, 8);
                draw.DrawIndexedInstanced(vertexArray, Topology.Triangles, 6, 2);
                device.Execute(draw, true);
            }

            byte[] pixels = readback(color);
            int redPixel = ((4 * 16) + 4) * 4;
            Assert.InRange(pixels[redPixel], (byte)180, (byte)255);
            Assert.InRange(pixels[redPixel + 1], (byte)0, (byte)4);
            Assert.InRange(pixels[redPixel + 2], (byte)0, (byte)4);
            Assert.Equal((byte)255, pixels[redPixel + 3]);
            int greenPixel = ((4 * 16) + 12) * 4;
            Assert.InRange(pixels[greenPixel], (byte)0, (byte)4);
            Assert.InRange(pixels[greenPixel + 1], (byte)180, (byte)255);
            Assert.InRange(pixels[greenPixel + 2], (byte)0, (byte)4);
            Assert.Equal((byte)255, pixels[greenPixel + 3]);
            AssertMaterialPixel(pixels, 0, 0f, 0f, 0f, 0f);
            if (backend == GraphicsBackend.Direct3D12)
                SaveScreenshotPng("c1dq-particle-billboard-instancing", UpscalePixels(pixels, 16, 8, 512, 256), 512, 256);

            using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("particle-instancing-dispose");
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, true);
            return pixels;
        }
        finally
        {
            SetGlobalUniformBuffer(previousGlobalBuffer);
            Rendering.PropertyState.ClearGlobalsInternal();
        }
    }

    private static void RunGizmosGlobalDepthContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        const string binding = "";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        string resources = binding + "Texture2D _CameraDepthTexture : register(t0); " + binding + "SamplerState _CameraDepthSampler : register(s0); ";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/Gizmos");
        ShaderCompileResult fragment = CompileMaterialContractShader(compiler, backend, vertexSource, resources + "float4 main() : SV_Target { float4 color = float4(0.8, 0.4, 0.2, 1.0); if (step(_CameraDepthTexture.Sample(_CameraDepthSampler, float2(0.5, 0.5)).r, 0.49999) > 0.5) { color.rgb *= 0.5; color.a *= 0.3; } return color; }");
        if (!fragment.Success)
            return;

        using var variant = CreateMaterialContractVariant(fragment, bytecodeFormat);
        using var depthVisible = new Resources.Texture2D();
        using var depthOccluded = new Resources.Texture2D();
        using var shader = CreateGridContractShader();
        using var material = new Resources.Material(shader);
        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 2, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("gizmos-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, depthVisible, new byte[] { 224, 0, 0, 255 });
            EncodeContractTexture(create, depthOccluded, new byte[] { 32, 0, 0, 255 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 2, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("gizmos-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            draw.SetGlobalTexture("_CameraDepthTexture", depthVisible);
            DrawMaterialPixel(draw, vertexArray, variant, material, 0);
            draw.SetGlobalTexture("_CameraDepthTexture", depthOccluded);
            DrawMaterialPixel(draw, vertexArray, variant, material, 1);
            draw.ClearGlobalTexture("_CameraDepthTexture");
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.8f, 0.4f, 0.2f, 1f);
        AssertMaterialPixel(pixels, 1, 0.4f, 0.2f, 0.1f, 0.3f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("gizmos-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
    }

    private static byte[] RunGridMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        const string binding = "";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string gridBlock = "cbuffer GridPS : register(b2) { float4 _GridColor; float _PrimaryGridSize; float _SecondaryGridSize; float _LineWidth; float _Falloff; float _MaxDist; }; ";
        string resources = binding + "Texture2D _CameraDepthTexture : register(t0); " + binding + "SamplerState _CameraDepthSampler : register(s0); ";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/Grid");
        ShaderCompileResult front = CompileMaterialContractShader(compiler, backend, vertexSource, gridBlock + resources + "float4 main() : SV_Target { return float4(_GridColor.r, _GridColor.a, _PrimaryGridSize / 4.0, _SecondaryGridSize); }");
        ShaderCompileResult tail = CompileMaterialContractShader(compiler, backend, vertexSource, gridBlock + resources + "float4 main() : SV_Target { float depth = _CameraDepthTexture.Sample(_CameraDepthSampler, float2(0.5, 0.5)).r; return float4(_LineWidth, _Falloff / 2.0, _MaxDist / 8.0, depth); }");
        Assert.True(front.Success, front.ErrorMessage);
        Assert.True(tail.Success, tail.ErrorMessage);

        using var frontVariant = CreateMaterialContractVariant(front, bytecodeFormat);
        using var tailVariant = CreateMaterialContractVariant(tail, bytecodeFormat);
        using var depthA = new Resources.Texture2D();
        using var depthB = new Resources.Texture2D();
        using var shader = CreateGridContractShader();
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetColor("_GridColor", new Color(0.75f, 0f, 0f, 0.625f));
        overridesMaterial.SetFloat("_PrimaryGridSize", 2f);
        overridesMaterial.SetFloat("_SecondaryGridSize", 0.25f);
        overridesMaterial.SetFloat("_LineWidth", 0.5f);
        overridesMaterial.SetFloat("_Falloff", 1.5f);
        overridesMaterial.SetFloat("_MaxDist", 2f);

        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 4, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("grid-material-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, depthA, new byte[] { 224, 0, 0, 255 });
            EncodeContractTexture(create, depthB, new byte[] { 32, 0, 0, 255 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 4, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("grid-material-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            draw.SetGlobalTexture("_CameraDepthTexture", depthA);
            DrawMaterialPixel(draw, vertexArray, frontVariant, defaultsMaterial, 0);
            draw.SetGlobalTexture("_CameraDepthTexture", depthB);
            DrawMaterialPixel(draw, vertexArray, frontVariant, overridesMaterial, 1);
            draw.SetGlobalTexture("_CameraDepthTexture", depthA);
            DrawMaterialPixel(draw, vertexArray, tailVariant, defaultsMaterial, 2);
            draw.SetGlobalTexture("_CameraDepthTexture", depthB);
            DrawMaterialPixel(draw, vertexArray, tailVariant, overridesMaterial, 3);
            draw.ClearGlobalTexture("_CameraDepthTexture");
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.125f, 0.25f, 0.25f, 0.5f);
        AssertMaterialPixel(pixels, 1, 0.75f, 0.625f, 0.5f, 0.25f);
        AssertMaterialPixel(pixels, 2, 0.125f, 0.5f, 0.75f, 224f / 255f);
        AssertMaterialPixel(pixels, 3, 0.5f, 0.75f, 0.25f, 32f / 255f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("grid-material-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
        return pixels;
    }

    private static byte[] RunFXAAMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        const string binding = "";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string block = "cbuffer FXAAPS : register(b0) { float2 _Resolution; float _EdgeThresholdMin; float _EdgeThresholdMax; float _SubpixelQuality; }; ";
        string resources = binding + "Texture2D _MainTex : register(t0); " + binding + "SamplerState _MainTexSampler : register(s0); ";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/FXAA");
        ShaderCompileResult front = CompileMaterialContractShader(compiler, backend, vertexSource, block + "float4 main() : SV_Target { return float4(_Resolution.x / 8.0, _Resolution.y / 8.0, _EdgeThresholdMin * 4.0, _EdgeThresholdMax * 4.0); }");
        ShaderCompileResult tail = CompileMaterialContractShader(compiler, backend, vertexSource, block + resources + "float4 main() : SV_Target { float4 c = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); return float4(_SubpixelQuality, c.r, c.g, c.b); }");
        Assert.True(front.Success, front.ErrorMessage);
        Assert.True(tail.Success, tail.ErrorMessage);

        using var frontVariant = CreateMaterialContractVariant(front, bytecodeFormat);
        using var tailVariant = CreateMaterialContractVariant(tail, bytecodeFormat);
        using var defaultTexture = new Resources.Texture2D();
        using var overrideTexture = new Resources.Texture2D();
        using var shader = CreateFXAAContractShader(defaultTexture);
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetVector("_Resolution", new Float2(2f, 4f));
        overridesMaterial.SetFloat("_EdgeThresholdMin", 0.125f);
        overridesMaterial.SetFloat("_EdgeThresholdMax", 0.25f);
        overridesMaterial.SetFloat("_SubpixelQuality", 0.25f);
        overridesMaterial.SetTexture("_MainTex", overrideTexture);
        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 4, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("fxaa-material-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, defaultTexture, new byte[] { 32, 64, 128, 255 });
            EncodeContractTexture(create, overrideTexture, new byte[] { 192, 160, 96, 255 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 4, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }
        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("fxaa-material-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, frontVariant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, frontVariant, overridesMaterial, 1);
            DrawMaterialPixel(draw, vertexArray, tailVariant, defaultsMaterial, 2);
            DrawMaterialPixel(draw, vertexArray, tailVariant, overridesMaterial, 3);
            device.Execute(draw, true);
        }
        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.5f, 1f, 0.125f, 0.25f);
        AssertMaterialPixel(pixels, 1, 0.25f, 0.5f, 0.5f, 1f);
        AssertMaterialPixel(pixels, 2, 0.75f, 32f / 255f, 64f / 255f, 128f / 255f);
        AssertMaterialPixel(pixels, 3, 0.25f, 192f / 255f, 160f / 255f, 96f / 255f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("fxaa-material-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
        return pixels;
    }

    private static byte[] RunSMAAMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        string Binding(int _) => string.Empty;
        string TextureResource(int index, string name) => Binding(index) + $"Texture2D {name} : register(t{index}); " + Binding(index) + $"SamplerState {name}Sampler : register(s{index}); ";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string block = "cbuffer SMAAPS : register(b0) { float2 _Resolution; float _EdgeThreshold; float Padding; }; ";
        string mainResource = TextureResource(0, "_MainTex");
        string edgeFragment = block + mainResource
            + "float4 main() : SV_Target { float4 c = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); return float4(_Resolution.x / 8.0, _EdgeThreshold * 4.0, c.r, c.g); }";
        string blendFragment = block + mainResource + TextureResource(1, "_AreaTex") + TextureResource(2, "_SearchTex")
            + "float4 main() : SV_Target { return float4(_MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)).r, _AreaTex.Sample(_AreaTexSampler, float2(0.5, 0.5)).g, _SearchTex.Sample(_SearchTexSampler, float2(0.5, 0.5)).b, _EdgeThreshold); }";
        string neighborhoodFragment = block + mainResource + TextureResource(1, "_BlendTex")
            + "float4 main() : SV_Target { return float4(_MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)).r, _BlendTex.Sample(_BlendTexSampler, float2(0.5, 0.5)).g, _Resolution.y / 8.0, _EdgeThreshold); }";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/SMAA");
        ShaderCompileResult edge = CompileMaterialContractShader(compiler, backend, vertexSource, edgeFragment);
        ShaderCompileResult blend = CompileMaterialContractShader(compiler, backend, vertexSource, blendFragment);
        ShaderCompileResult neighborhood = CompileMaterialContractShader(compiler, backend, vertexSource, neighborhoodFragment);
        static bool IsSpirVUnavailable(ShaderCompileResult result) =>
            !result.Success &&
            result.ErrorMessage?.Contains("SPIR-V CodeGen not available", StringComparison.OrdinalIgnoreCase) == true;
        if (backend == GraphicsBackend.Vulkan && IsSpirVUnavailable(edge) && IsSpirVUnavailable(blend) && IsSpirVUnavailable(neighborhood))
            return [];
        Assert.True(edge.Success, $"SMAA EdgeDetection contract compile failed: {edge.ErrorMessage}");
        Assert.True(blend.Success, $"SMAA BlendWeights contract compile failed: {blend.ErrorMessage}");
        Assert.True(neighborhood.Success, $"SMAA NeighborhoodBlend contract compile failed: {neighborhood.ErrorMessage}");

        using var edgeVariant = CreateMaterialContractVariant(edge, bytecodeFormat);
        using var blendVariant = CreateMaterialContractVariant(blend, bytecodeFormat);
        using var neighborhoodVariant = CreateMaterialContractVariant(neighborhood, bytecodeFormat);
        using var defaultMainTexture = new Resources.Texture2D();
        using var overrideMainTexture = new Resources.Texture2D();
        using var defaultAreaTexture = new Resources.Texture2D();
        using var overrideAreaTexture = new Resources.Texture2D();
        using var defaultSearchTexture = new Resources.Texture2D();
        using var overrideSearchTexture = new Resources.Texture2D();
        using var defaultBlendTexture = new Resources.Texture2D();
        using var overrideBlendTexture = new Resources.Texture2D();
        using var shader = CreateSMAAContractShader(defaultMainTexture, defaultAreaTexture, defaultSearchTexture, defaultBlendTexture);
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetVector("_Resolution", new Float2(2f, 6f));
        overridesMaterial.SetFloat("_EdgeThreshold", 0.25f);
        overridesMaterial.SetTexture("_MainTex", overrideMainTexture);
        overridesMaterial.SetTexture("_AreaTex", overrideAreaTexture);
        overridesMaterial.SetTexture("_SearchTex", overrideSearchTexture);
        overridesMaterial.SetTexture("_BlendTex", overrideBlendTexture);

        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 6, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("smaa-material-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, defaultMainTexture, [32, 64, 96, 255]);
            EncodeContractTexture(create, overrideMainTexture, [200, 180, 160, 255]);
            EncodeContractTexture(create, defaultAreaTexture, [48, 128, 64, 255]);
            EncodeContractTexture(create, overrideAreaTexture, [80, 144, 112, 255]);
            EncodeContractTexture(create, defaultSearchTexture, [96, 112, 224, 255]);
            EncodeContractTexture(create, overrideSearchTexture, [128, 96, 192, 255]);
            EncodeContractTexture(create, defaultBlendTexture, [160, 16, 48, 255]);
            EncodeContractTexture(create, overrideBlendTexture, [176, 208, 32, 255]);
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 6, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("smaa-material-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, edgeVariant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, edgeVariant, overridesMaterial, 1);
            DrawMaterialPixel(draw, vertexArray, blendVariant, defaultsMaterial, 2);
            DrawMaterialPixel(draw, vertexArray, blendVariant, overridesMaterial, 3);
            DrawMaterialPixel(draw, vertexArray, neighborhoodVariant, defaultsMaterial, 4);
            DrawMaterialPixel(draw, vertexArray, neighborhoodVariant, overridesMaterial, 5);
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.5f, 0.5f, 32f / 255f, 64f / 255f);
        AssertMaterialPixel(pixels, 1, 0.25f, 1f, 200f / 255f, 180f / 255f);
        AssertMaterialPixel(pixels, 2, 32f / 255f, 128f / 255f, 224f / 255f, 0.125f);
        AssertMaterialPixel(pixels, 3, 200f / 255f, 144f / 255f, 192f / 255f, 0.25f);
        AssertMaterialPixel(pixels, 4, 32f / 255f, 16f / 255f, 1f, 0.125f);
        AssertMaterialPixel(pixels, 5, 200f / 255f, 208f / 255f, 0.75f, 0.25f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("smaa-material-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
        return pixels;
    }

    private static byte[] RunBloomMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string vertexSource = "struct VSInput { float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string mainResource = "Texture2D _MainTex : register(t0); SamplerState _MainTexSampler : register(s0); ";
        const string bloomResource = "Texture2D _BloomTex : register(t1); SamplerState _BloomTexSampler : register(s1); ";
        const string thresholdBlock = "cbuffer BloomThresholdPS : register(b0) { float _Threshold; float3 Padding; }; ";
        const string compositeBlock = "cbuffer BloomCompositePS : register(b0) { float _Intensity; float3 Padding; }; ";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/Bloom");
        ShaderCompileResult threshold = CompileMaterialContractShader(compiler, backend, vertexSource, thresholdBlock + mainResource + "float4 main() : SV_Target { float4 c = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); return float4(_Threshold, c.r, c.g, c.b); }");
        ShaderCompileResult downsample = CompileMaterialContractShader(compiler, backend, vertexSource, mainResource + "float4 main() : SV_Target { return _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); }");
        ShaderCompileResult upsample = CompileMaterialContractShader(compiler, backend, vertexSource, mainResource + "float4 main() : SV_Target { return _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); }");
        ShaderCompileResult composite = CompileMaterialContractShader(compiler, backend, vertexSource, compositeBlock + mainResource + bloomResource + "float4 main() : SV_Target { float4 mainColor = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); float4 bloom = _BloomTex.Sample(_BloomTexSampler, float2(0.5, 0.5)); return float4(_Intensity, mainColor.r, bloom.g, bloom.b); }");
        if (IsSpirvUnavailable(backend, threshold)) return [];
        Assert.True(threshold.Success, threshold.ErrorMessage);
        Assert.True(downsample.Success, downsample.ErrorMessage);
        Assert.True(upsample.Success, upsample.ErrorMessage);
        Assert.True(composite.Success, composite.ErrorMessage);

        using var thresholdVariant = CreateMaterialContractVariant(threshold, bytecodeFormat);
        using var downsampleVariant = CreateMaterialContractVariant(downsample, bytecodeFormat);
        using var upsampleVariant = CreateMaterialContractVariant(upsample, bytecodeFormat);
        using var compositeVariant = CreateMaterialContractVariant(composite, bytecodeFormat);
        using var defaultMainTexture = new Resources.Texture2D();
        using var overrideMainTexture = new Resources.Texture2D();
        using var upsampleMainTexture = new Resources.Texture2D();
        using var defaultBloomTexture = new Resources.Texture2D();
        using var overrideBloomTexture = new Resources.Texture2D();
        using var shader = CreateBloomContractShader(defaultMainTexture, defaultBloomTexture);
        using var defaultsMaterial = new Resources.Material(shader);
        using var mutableMaterial = new Resources.Material(shader);
        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 6, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("bloom-material-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, defaultMainTexture, new byte[] { 32, 64, 96, 255 });
            EncodeContractTexture(create, overrideMainTexture, new byte[] { 192, 160, 128, 255 });
            EncodeContractTexture(create, upsampleMainTexture, new byte[] { 224, 48, 80, 255 });
            EncodeContractTexture(create, defaultBloomTexture, new byte[] { 16, 128, 240, 255 });
            EncodeContractTexture(create, overrideBloomTexture, new byte[] { 96, 224, 64, 255 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 6, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("bloom-material-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, thresholdVariant, defaultsMaterial, 0);
            mutableMaterial.SetFloat("_Threshold", 0.75f);
            mutableMaterial.SetTexture("_MainTex", overrideMainTexture);
            DrawMaterialPixel(draw, vertexArray, thresholdVariant, mutableMaterial, 1);
            DrawMaterialPixel(draw, vertexArray, downsampleVariant, defaultsMaterial, 2);
            mutableMaterial.SetTexture("_MainTex", upsampleMainTexture);
            DrawMaterialPixel(draw, vertexArray, upsampleVariant, mutableMaterial, 3);
            DrawMaterialPixel(draw, vertexArray, compositeVariant, defaultsMaterial, 4);
            mutableMaterial.SetFloat("_Intensity", 0.25f);
            mutableMaterial.SetTexture("_MainTex", overrideMainTexture);
            mutableMaterial.SetTexture("_BloomTex", overrideBloomTexture);
            DrawMaterialPixel(draw, vertexArray, compositeVariant, mutableMaterial, 5);
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.25f, 32f / 255f, 64f / 255f, 96f / 255f);
        AssertMaterialPixel(pixels, 1, 0.75f, 192f / 255f, 160f / 255f, 128f / 255f);
        AssertMaterialPixel(pixels, 2, 32f / 255f, 64f / 255f, 96f / 255f, 1f);
        AssertMaterialPixel(pixels, 3, 224f / 255f, 48f / 255f, 80f / 255f, 1f);
        AssertMaterialPixel(pixels, 4, 0.5f, 32f / 255f, 128f / 255f, 240f / 255f);
        AssertMaterialPixel(pixels, 5, 0.25f, 192f / 255f, 224f / 255f, 64f / 255f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("bloom-material-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
        return pixels;
    }

    private static byte[] RunBokehDoFMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        const string binding0 = "";
        const string binding1 = "";
        const string binding2 = "";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string block = "cbuffer BokehDoFPS : register(b0) { float2 _Resolution; float _FocusStrength; float _ManualFocusPoint; float _MaxBlurRadius; float3 BokehDoFPadding; }; ";
        string depthResource = binding1 + "Texture2D _CameraDepthTexture : register(t1); " + binding1 + "SamplerState _CameraDepthSampler : register(s1); ";

        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/EnhancedBokehdoF");
        // Pass 0 "CircularHorizMRT": writes _MaxBlurRadius into R, _ManualFocusPoint into G, _FocusStrength into B across the MRT pair.
        string horizMainResource = binding0 + "Texture2D _MainTex : register(t0); " + binding0 + "SamplerState _MainTexSampler : register(s0); ";
        string horizFragment = block + horizMainResource + depthResource +
            "struct MRTOutput { float4 OutputR : SV_Target0; float4 OutputG : SV_Target1; float4 OutputB : SV_Target2; }; " +
            "MRTOutput main() { float3 m = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)).rgb; float radius = _MaxBlurRadius > 1 ? _MaxBlurRadius / 255.0 : _MaxBlurRadius; MRTOutput o; o.OutputR = float4(radius, m.r, m.g, m.b); o.OutputG = float4(_ManualFocusPoint, 0, 0, 0); o.OutputB = float4(_FocusStrength, 0, 0, 0); return o; }";
        // Pass 1 "CircularVerticalComposite": three color inputs packed into a single SV_Target (channel layout R=main, G=horizR, B=horizG).
        string vertMainResource = binding0 + "Texture2D _HorizR : register(t0); " + binding0 + "SamplerState _HorizRSampler : register(s0); ";
        string vertFragment = block + vertMainResource + depthResource +
            "float4 main() : SV_Target { float3 r = _HorizR.Sample(_HorizRSampler, float2(0.5, 0.5)).rgb; float resolution = _Resolution.x > 1 ? _Resolution.x / 255.0 : _Resolution.x; return float4(resolution, r.r, r.g, r.b); }";
        // Pass 2 "DoFCombine": blends main + blurred driven by the CoC-derived factor (exercised via _FocusStrength output for a deterministic readback).
        string combineMainResource = binding0 + "Texture2D _MainTex : register(t0); " + binding0 + "SamplerState _MainTexSampler : register(s0); ";
        string combineBlurResource = binding1 + "Texture2D _BlurredTex : register(t1); " + binding1 + "SamplerState _BlurredTexSampler : register(s1); ";
        string combineDepthResource = binding2 + "Texture2D _CameraDepthTexture : register(t2); " + binding2 + "SamplerState _CameraDepthSampler : register(s2); ";
        string combineFragment = block + combineMainResource + combineBlurResource + combineDepthResource +
            "float4 main() : SV_Target { float3 mainColor = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)).rgb; float3 blur = _BlurredTex.Sample(_BlurredTexSampler, float2(0.5, 0.5)).rgb; return float4(_FocusStrength, mainColor.r, blur.g, _ManualFocusPoint); }";

        ShaderCompileResult horiz = CompileMaterialContractShader(compiler, backend, vertexSource, horizFragment);
        ShaderCompileResult vertical = CompileMaterialContractShader(compiler, backend, vertexSource, vertFragment);
        ShaderCompileResult combine = CompileMaterialContractShader(compiler, backend, vertexSource, combineFragment);
        if (IsSpirvUnavailable(backend, horiz)) return [];
        Assert.True(horiz.Success, horiz.ErrorMessage);
        Assert.True(vertical.Success, vertical.ErrorMessage);
        Assert.True(combine.Success, combine.ErrorMessage);

        using var horizVariant = CreateMaterialContractVariant(horiz, bytecodeFormat);
        using var verticalVariant = CreateMaterialContractVariant(vertical, bytecodeFormat);
        using var combineVariant = CreateMaterialContractVariant(combine, bytecodeFormat);
        using var mainTexture = new Resources.Texture2D();
        using var depthTexture = new Resources.Texture2D();
        using var horizRTexture = new Resources.Texture2D();
        using var blurredTexture = new Resources.Texture2D();
        using var shader = CreateBokehDoFContractShader(mainTexture, depthTexture, horizRTexture, blurredTexture);
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetVector("_Resolution", new XEngine.Vector.Float2(0.75f, 0.125f));
        overridesMaterial.SetFloat("_FocusStrength", 0.5f);
        overridesMaterial.SetFloat("_ManualFocusPoint", 0.25f);
        overridesMaterial.SetFloat("_MaxBlurRadius", 0.625f);

        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 5, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("bokehdof-material-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, mainTexture, new byte[] { 200, 160, 120, 255 });
            EncodeContractTexture(create, depthTexture, new byte[] { 255, 255, 255, 255 });
            EncodeContractTexture(create, horizRTexture, new byte[] { 64, 96, 128, 255 });
            EncodeContractTexture(create, blurredTexture, new byte[] { 32, 192, 16, 255 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 5, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("bokehdof-material-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            // Pass 0 defaults: _MaxBlurRadius 4, _ManualFocusPoint 0.5, _FocusStrength 200
            DrawMaterialPixel(draw, vertexArray, horizVariant, defaultsMaterial, 0);
            // Pass 0 overrides: _MaxBlurRadius 0.625, _ManualFocusPoint 0.25, _FocusStrength 0.5
            DrawMaterialPixel(draw, vertexArray, horizVariant, overridesMaterial, 1);
            // Pass 1 defaults: _Resolution (blurWidth 4, blurHeight 4) -> x=4/255
            DrawMaterialPixel(draw, vertexArray, verticalVariant, defaultsMaterial, 2);
            // Pass 1 overrides: _Resolution (0.75, 0.125) -> x=0.75
            DrawMaterialPixel(draw, vertexArray, verticalVariant, overridesMaterial, 3);
            // Pass 2 overrides: _FocusStrength 0.5, _ManualFocusPoint 0.25
            DrawMaterialPixel(draw, vertexArray, combineVariant, overridesMaterial, 4);
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 4f / 255f, 200f / 255f, 160f / 255f, 120f / 255f);
        AssertMaterialPixel(pixels, 1, 0.625f, 200f / 255f, 160f / 255f, 120f / 255f);
        AssertMaterialPixel(pixels, 2, 4f / 255f, 64f / 255f, 96f / 255f, 128f / 255f);
        AssertMaterialPixel(pixels, 3, 0.75f, 64f / 255f, 96f / 255f, 128f / 255f);
        AssertMaterialPixel(pixels, 4, 0.5f, 200f / 255f, 192f / 255f, 0.25f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("bokehdof-material-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
        return pixels;
    }

    private static byte[] RunSSRMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        string Binding(int _) => string.Empty;
        string TextureResource(int index, string name) => Binding(index) + $"Texture2D {name} : register(t{index}); " + Binding(index) + $"SamplerState {name}Sampler : register(s{index}); ";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";

        const string rayBlock = "cbuffer SSRRayCastPS : register(b2) { float4 _JitterSizeAndOffset; float _NumSteps; float _BRDFBias; float2 Padding; }; ";
        string rayResources = TextureResource(0, "_CameraDepthTexture") + TextureResource(1, "_CameraNormalsTexture")
            + TextureResource(2, "_CameraMotionVectorsTexture") + TextureResource(3, "_Noise");
        string rayFragment = rayBlock + rayResources
            + "float4 main() : SV_Target { float a = (_CameraDepthTexture.Sample(_CameraDepthTextureSampler, .5).r + 2 * _CameraNormalsTexture.Sample(_CameraNormalsTextureSampler, .5).g + 3 * _CameraMotionVectorsTexture.Sample(_CameraMotionVectorsTextureSampler, .5).b + 4 * _Noise.Sample(_NoiseSampler, .5).a) / 10; return float4(_JitterSizeAndOffset.x, _NumSteps, _BRDFBias, a); }";

        const string blurBlock = "cbuffer SSRSceneBlurPS : register(b0) { float2 _BlurDir; float2 Padding; }; ";
        string blurFragment = blurBlock + TextureResource(0, "_MainTex")
            + "float4 main() : SV_Target { float4 c = _MainTex.Sample(_MainTexSampler, .5); return float4(_BlurDir, c.b, c.a); }";

        const string resolveBlock = "cbuffer SSRResolvePS : register(b2) { float2 _NoiseSize; float2 _ResolveSize; float4 _JitterSizeAndOffset; float _BRDFBias; float _EdgeFactor; float _MaxMipMap; int _RayReuse; int _UseNormalization; int _Fireflies; float Padding; }; ";
        string resolveFrontFragment = resolveBlock
            + "float4 main() : SV_Target { return float4(_NoiseSize.x, _ResolveSize.y, _JitterSizeAndOffset.z, _BRDFBias); }";
        string resolveResources = TextureResource(0, "_RayCast") + TextureResource(1, "_CameraDepthTexture")
            + TextureResource(2, "_CameraNormalsTexture") + TextureResource(3, "_CameraMotionVectorsTexture")
            + TextureResource(4, "_Noise") + TextureResource(5, "_Scene0") + TextureResource(6, "_Scene1")
            + TextureResource(7, "_Scene2") + TextureResource(8, "_Scene3") + TextureResource(9, "_Scene4");
        string resolveTailFragment = resolveBlock + resolveResources
            + "float4 main() : SV_Target { float resources = (_RayCast.Sample(_RayCastSampler, .5).r + _CameraDepthTexture.Sample(_CameraDepthTextureSampler, .5).r + _CameraNormalsTexture.Sample(_CameraNormalsTextureSampler, .5).g + _CameraMotionVectorsTexture.Sample(_CameraMotionVectorsTextureSampler, .5).b + _Noise.Sample(_NoiseSampler, .5).a + _Scene0.Sample(_Scene0Sampler, .5).r + _Scene1.Sample(_Scene1Sampler, .5).g + _Scene2.Sample(_Scene2Sampler, .5).b + _Scene3.Sample(_Scene3Sampler, .5).a + _Scene4.Sample(_Scene4Sampler, .5).r) / 10; return float4(_EdgeFactor, _MaxMipMap / 8, float(_RayReuse + _UseNormalization + _Fireflies) / 12, resources); }";

        const string temporalBlock = "cbuffer SSRTemporalPS : register(b2) { int _ReflectionVelocity; float _TScale; float _TResponse; float Padding; }; ";
        string temporalResources = TextureResource(0, "_MainTex") + TextureResource(1, "_PreviousBuffer")
            + TextureResource(2, "_RayCast") + TextureResource(3, "_CameraDepthTexture")
            + TextureResource(4, "_CameraMotionVectorsTexture");
        string temporalFragment = temporalBlock + temporalResources
            + "float4 main() : SV_Target { float resources = (_MainTex.Sample(_MainTexSampler, .5).r + _PreviousBuffer.Sample(_PreviousBufferSampler, .5).g + _RayCast.Sample(_RayCastSampler, .5).b + _CameraDepthTexture.Sample(_CameraDepthTextureSampler, .5).r + _CameraMotionVectorsTexture.Sample(_CameraMotionVectorsTextureSampler, .5).b) / 5; return float4(float(_ReflectionVelocity) / 4, _TScale, _TResponse, resources); }";

        string reprojectFragment = TextureResource(0, "_MainTex") + TextureResource(1, "_CameraMotionVectorsTexture")
            + "float4 main() : SV_Target { float4 c = _MainTex.Sample(_MainTexSampler, .5); float4 m = _CameraMotionVectorsTexture.Sample(_CameraMotionVectorsTextureSampler, .5); return float4(c.r, m.g, c.b, m.a); }";

        const string combineBlock = "cbuffer SSRCombinePS : register(b2) { int _UseFresnel; float3 Padding; }; ";
        string combineResources = TextureResource(0, "_MainTex") + TextureResource(1, "_ReflectionBuffer")
            + TextureResource(2, "_CameraDepthTexture") + TextureResource(3, "_CameraNormalsTexture")
            + TextureResource(4, "_CameraMotionVectorsTexture");
        string combineFragment = combineBlock + combineResources
            + "float4 main() : SV_Target { float a = (_CameraDepthTexture.Sample(_CameraDepthTextureSampler, .5).r + _CameraNormalsTexture.Sample(_CameraNormalsTextureSampler, .5).g + _CameraMotionVectorsTexture.Sample(_CameraMotionVectorsTextureSampler, .5).b) / 3; return float4(float(_UseFresnel) / 4, _MainTex.Sample(_MainTexSampler, .5).r, _ReflectionBuffer.Sample(_ReflectionBufferSampler, .5).g, a); }";

        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/SSR");
        ShaderCompileResult ray = CompileMaterialContractShader(compiler, backend, vertexSource, rayFragment);
        ShaderCompileResult blur = CompileMaterialContractShader(compiler, backend, vertexSource, blurFragment);
        ShaderCompileResult resolveFront = CompileMaterialContractShader(compiler, backend, vertexSource, resolveFrontFragment);
        ShaderCompileResult resolveTail = CompileMaterialContractShader(compiler, backend, vertexSource, resolveTailFragment);
        ShaderCompileResult temporal = CompileMaterialContractShader(compiler, backend, vertexSource, temporalFragment);
        ShaderCompileResult reproject = CompileMaterialContractShader(compiler, backend, vertexSource, reprojectFragment);
        ShaderCompileResult combine = CompileMaterialContractShader(compiler, backend, vertexSource, combineFragment);
        static bool IsSpirVUnavailable(ShaderCompileResult result) =>
            !result.Success &&
            result.ErrorMessage?.Contains("SPIR-V CodeGen not available", StringComparison.OrdinalIgnoreCase) == true;
        if (backend == GraphicsBackend.Vulkan &&
            IsSpirVUnavailable(ray) &&
            IsSpirVUnavailable(blur) &&
            IsSpirVUnavailable(resolveFront) &&
            IsSpirVUnavailable(resolveTail) &&
            IsSpirVUnavailable(temporal) &&
            IsSpirVUnavailable(reproject) &&
            IsSpirVUnavailable(combine))
        {
            return [];
        }
        Assert.True(ray.Success, $"SSR RayCast contract compile failed: {ray.ErrorMessage}");
        Assert.True(blur.Success, $"SSR SceneBlur contract compile failed: {blur.ErrorMessage}");
        Assert.True(resolveFront.Success, $"SSR Resolve front contract compile failed: {resolveFront.ErrorMessage}");
        Assert.True(resolveTail.Success, $"SSR Resolve tail contract compile failed: {resolveTail.ErrorMessage}");
        Assert.True(temporal.Success, $"SSR Temporal contract compile failed: {temporal.ErrorMessage}");
        Assert.True(reproject.Success, $"SSR Reproject contract compile failed: {reproject.ErrorMessage}");
        Assert.True(combine.Success, $"SSR Combine contract compile failed: {combine.ErrorMessage}");

        using var rayVariant = CreateMaterialContractVariant(ray, bytecodeFormat);
        using var blurVariant = CreateMaterialContractVariant(blur, bytecodeFormat);
        using var resolveFrontVariant = CreateMaterialContractVariant(resolveFront, bytecodeFormat);
        using var resolveTailVariant = CreateMaterialContractVariant(resolveTail, bytecodeFormat);
        using var temporalVariant = CreateMaterialContractVariant(temporal, bytecodeFormat);
        using var reprojectVariant = CreateMaterialContractVariant(reproject, bytecodeFormat);
        using var combineVariant = CreateMaterialContractVariant(combine, bytecodeFormat);
        using var mainTexture = new Resources.Texture2D();
        using var overrideMainTexture = new Resources.Texture2D();
        using var depthTexture = new Resources.Texture2D();
        using var normalsTexture = new Resources.Texture2D();
        using var motionTexture = new Resources.Texture2D();
        using var noiseTexture = new Resources.Texture2D();
        using var rayTexture = new Resources.Texture2D();
        using var scene0Texture = new Resources.Texture2D();
        using var scene1Texture = new Resources.Texture2D();
        using var scene2Texture = new Resources.Texture2D();
        using var scene3Texture = new Resources.Texture2D();
        using var scene4Texture = new Resources.Texture2D();
        using var previousTexture = new Resources.Texture2D();
        using var reflectionTexture = new Resources.Texture2D();
        using var shader = CreateSSRContractShader(mainTexture, depthTexture, normalsTexture, motionTexture, noiseTexture,
            rayTexture, scene0Texture, scene1Texture, scene2Texture, scene3Texture, scene4Texture, previousTexture, reflectionTexture);
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        SetSSRTextures(defaultsMaterial, mainTexture, depthTexture, normalsTexture, motionTexture, noiseTexture, rayTexture,
            scene0Texture, scene1Texture, scene2Texture, scene3Texture, scene4Texture, previousTexture, reflectionTexture);
        SetSSRTextures(overridesMaterial, overrideMainTexture, depthTexture, normalsTexture, motionTexture, noiseTexture, rayTexture,
            scene0Texture, scene1Texture, scene2Texture, scene3Texture, scene4Texture, previousTexture, reflectionTexture);
        overridesMaterial.SetVector("_JitterSizeAndOffset", new Float4(0.75f, 0.625f, 0.5f, 0.375f));
        overridesMaterial.SetFloat("_NumSteps", 0.25f);
        overridesMaterial.SetFloat("_BRDFBias", 0.125f);
        overridesMaterial.SetVector("_BlurDir", new Float2(0.75f, 0.625f));
        overridesMaterial.SetVector("_NoiseSize", new Float2(0.75f, 0.625f));
        overridesMaterial.SetVector("_ResolveSize", new Float2(0.5f, 0.375f));
        overridesMaterial.SetFloat("_EdgeFactor", 0.75f);
        overridesMaterial.SetFloat("_MaxMipMap", 6f);
        overridesMaterial.SetInt("_RayReuse", 2);
        overridesMaterial.SetInt("_UseNormalization", 3);
        overridesMaterial.SetInt("_Fireflies", 4);
        overridesMaterial.SetInt("_ReflectionVelocity", 2);
        overridesMaterial.SetFloat("_TScale", 0.75f);
        overridesMaterial.SetFloat("_TResponse", 0.25f);
        overridesMaterial.SetInt("_UseFresnel", 3);

        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 13, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("ssr-material-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, mainTexture, [80, 96, 112, 128]);
            EncodeContractTexture(create, overrideMainTexture, [184, 200, 216, 232]);
            EncodeContractTexture(create, depthTexture, [16, 0, 0, 255]);
            EncodeContractTexture(create, normalsTexture, [0, 32, 0, 255]);
            EncodeContractTexture(create, motionTexture, [0, 0, 48, 255]);
            EncodeContractTexture(create, noiseTexture, [0, 0, 0, 64]);
            EncodeContractTexture(create, rayTexture, [144, 160, 176, 192]);
            EncodeContractTexture(create, scene0Texture, [8, 0, 0, 255]);
            EncodeContractTexture(create, scene1Texture, [0, 16, 0, 255]);
            EncodeContractTexture(create, scene2Texture, [0, 0, 24, 255]);
            EncodeContractTexture(create, scene3Texture, [0, 0, 0, 32]);
            EncodeContractTexture(create, scene4Texture, [40, 0, 0, 255]);
            EncodeContractTexture(create, previousTexture, [56, 72, 88, 104]);
            EncodeContractTexture(create, reflectionTexture, [120, 136, 152, 168]);
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 13, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("ssr-material-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, rayVariant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, rayVariant, overridesMaterial, 1);
            DrawMaterialPixel(draw, vertexArray, blurVariant, defaultsMaterial, 2);
            DrawMaterialPixel(draw, vertexArray, blurVariant, overridesMaterial, 3);
            DrawMaterialPixel(draw, vertexArray, resolveFrontVariant, defaultsMaterial, 4);
            DrawMaterialPixel(draw, vertexArray, resolveFrontVariant, overridesMaterial, 5);
            DrawMaterialPixel(draw, vertexArray, resolveTailVariant, defaultsMaterial, 6);
            DrawMaterialPixel(draw, vertexArray, resolveTailVariant, overridesMaterial, 7);
            DrawMaterialPixel(draw, vertexArray, temporalVariant, defaultsMaterial, 8);
            DrawMaterialPixel(draw, vertexArray, temporalVariant, overridesMaterial, 9);
            DrawMaterialPixel(draw, vertexArray, reprojectVariant, defaultsMaterial, 10);
            DrawMaterialPixel(draw, vertexArray, combineVariant, defaultsMaterial, 11);
            DrawMaterialPixel(draw, vertexArray, combineVariant, overridesMaterial, 12);
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.125f, 0.625f, 0.75f, 48f / 255f);
        AssertMaterialPixel(pixels, 1, 0.75f, 0.25f, 0.125f, 48f / 255f);
        AssertMaterialPixel(pixels, 2, 0.125f, 0.25f, 112f / 255f, 128f / 255f);
        AssertMaterialPixel(pixels, 3, 0.75f, 0.625f, 216f / 255f, 232f / 255f);
        AssertMaterialPixel(pixels, 4, 0.125f, 0.5f, 0.375f, 0.75f);
        AssertMaterialPixel(pixels, 5, 0.75f, 0.375f, 0.5f, 0.125f);
        AssertMaterialPixel(pixels, 6, 0.25f, 0.5f, 0.5f, 424f / 2550f);
        AssertMaterialPixel(pixels, 7, 0.75f, 0.75f, 0.75f, 424f / 2550f);
        AssertMaterialPixel(pixels, 8, 0.25f, 0.375f, 0.625f, 392f / 1275f);
        AssertMaterialPixel(pixels, 9, 0.5f, 0.75f, 0.25f, 496f / 1275f);
        AssertMaterialPixel(pixels, 10, 80f / 255f, 0f, 112f / 255f, 1f);
        AssertMaterialPixel(pixels, 11, 0.5f, 80f / 255f, 136f / 255f, 32f / 255f);
        AssertMaterialPixel(pixels, 12, 0.75f, 184f / 255f, 136f / 255f, 32f / 255f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("ssr-material-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
        return pixels;
    }

    private static void SetSSRTextures(
        Resources.Material material,
        Resources.Texture2D mainTexture,
        Resources.Texture2D depthTexture,
        Resources.Texture2D normalsTexture,
        Resources.Texture2D motionTexture,
        Resources.Texture2D noiseTexture,
        Resources.Texture2D rayTexture,
        Resources.Texture2D scene0Texture,
        Resources.Texture2D scene1Texture,
        Resources.Texture2D scene2Texture,
        Resources.Texture2D scene3Texture,
        Resources.Texture2D scene4Texture,
        Resources.Texture2D previousTexture,
        Resources.Texture2D reflectionTexture)
    {
        material.SetTexture("_MainTex", mainTexture);
        material.SetTexture("_CameraDepthTexture", depthTexture);
        material.SetTexture("_CameraNormalsTexture", normalsTexture);
        material.SetTexture("_CameraMotionVectorsTexture", motionTexture);
        material.SetTexture("_Noise", noiseTexture);
        material.SetTexture("_RayCast", rayTexture);
        material.SetTexture("_Scene0", scene0Texture);
        material.SetTexture("_Scene1", scene1Texture);
        material.SetTexture("_Scene2", scene2Texture);
        material.SetTexture("_Scene3", scene3Texture);
        material.SetTexture("_Scene4", scene4Texture);
        material.SetTexture("_PreviousBuffer", previousTexture);
        material.SetTexture("_ReflectionBuffer", reflectionTexture);
    }

    private static void RunMotionBlurMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        const string binding0 = "";
        const string binding1 = "";
        const string binding2 = "";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string block = "cbuffer MotionBlurPS : register(b2) { float2 _Resolution; float _Intensity; int _Samples; float _MaxBlurRadius; float3 Padding; }; ";
        string resources = binding0 + "Texture2D _MainTex : register(t0); " + binding0 + "SamplerState _MainTexSampler : register(s0); "
            + binding1 + "Texture2D _MotionVectorsTex : register(t1); " + binding1 + "SamplerState _MotionVectorsSampler : register(s1); "
            + binding2 + "Texture2D _CameraDepthTexture : register(t2); " + binding2 + "SamplerState _CameraDepthSampler : register(s2); ";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/MotionBlur");
        ShaderCompileResult front = CompileMaterialContractShader(compiler, backend, vertexSource, block + "float4 main() : SV_Target { return float4(_Resolution.x / 8.0, _Resolution.y / 8.0, _Intensity, float(_Samples) / 16.0); }");
        ShaderCompileResult tail = CompileMaterialContractShader(compiler, backend, vertexSource, block + resources + "float4 main() : SV_Target { float4 mainColor = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); float4 motion = _MotionVectorsTex.Sample(_MotionVectorsSampler, float2(0.5, 0.5)); float4 depth = _CameraDepthTexture.Sample(_CameraDepthSampler, float2(0.5, 0.5)); return float4(_MaxBlurRadius / 64.0, mainColor.r, motion.g, depth.b); }");
        if (!front.Success || !tail.Success)
            return;

        using var frontVariant = CreateMaterialContractVariant(front, bytecodeFormat);
        using var tailVariant = CreateMaterialContractVariant(tail, bytecodeFormat);
        using var defaultMainTexture = new Resources.Texture2D();
        using var overrideMainTexture = new Resources.Texture2D();
        using var defaultMotionTexture = new Resources.Texture2D();
        using var overrideMotionTexture = new Resources.Texture2D();
        using var depthTextureA = new Resources.Texture2D();
        using var depthTextureB = new Resources.Texture2D();
        using var shader = CreateMotionBlurContractShader(defaultMainTexture, defaultMotionTexture);
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetVector("_Resolution", new Float2(2f, 4f));
        overridesMaterial.SetFloat("_Intensity", 0.25f);
        overridesMaterial.SetInt("_Samples", 4);
        overridesMaterial.SetFloat("_MaxBlurRadius", 16f);
        overridesMaterial.SetTexture("_MainTex", overrideMainTexture);
        overridesMaterial.SetTexture("_MotionVectorsTex", overrideMotionTexture);
        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 4, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("motion-blur-material-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, defaultMainTexture, new byte[] { 32, 64, 96, 255 });
            EncodeContractTexture(create, overrideMainTexture, new byte[] { 224, 192, 160, 255 });
            EncodeContractTexture(create, defaultMotionTexture, new byte[] { 64, 96, 128, 255 });
            EncodeContractTexture(create, overrideMotionTexture, new byte[] { 128, 160, 192, 255 });
            EncodeContractTexture(create, depthTextureA, new byte[] { 128, 160, 192, 255 });
            EncodeContractTexture(create, depthTextureB, new byte[] { 96, 80, 64, 255 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 4, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("motion-blur-material-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, frontVariant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, frontVariant, overridesMaterial, 1);
            draw.SetGlobalTexture("_CameraDepthTexture", depthTextureA);
            DrawMaterialPixel(draw, vertexArray, tailVariant, defaultsMaterial, 2);
            draw.SetGlobalTexture("_CameraDepthTexture", depthTextureB);
            DrawMaterialPixel(draw, vertexArray, tailVariant, overridesMaterial, 3);
            draw.ClearGlobalTexture("_CameraDepthTexture");
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.5f, 1f, 0.5f, 0.5f);
        AssertMaterialPixel(pixels, 1, 0.25f, 0.5f, 0.25f, 0.25f);
        AssertMaterialPixel(pixels, 2, 0.5f, 32f / 255f, 96f / 255f, 192f / 255f);
        AssertMaterialPixel(pixels, 3, 0.25f, 224f / 255f, 160f / 255f, 64f / 255f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("motion-blur-material-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
    }

    private static byte[] RunAutoExposureMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        const string binding0 = "";
        const string binding1 = "";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string adaptBlock = "cbuffer AutoExposureAdaptPS : register(b2) { float _AdaptSpeedUp; float _AdaptSpeedDown; float _HistoryValid; float Padding; }; ";
        const string applyBlock = "cbuffer AutoExposureApplyPS : register(b0) { float _ExposureComp; float _MinExposure; float _MaxExposure; float Padding; }; ";
        string resources = binding0 + "Texture2D _MainTex : register(t0); " + binding0 + "SamplerState _MainTexSampler : register(s0); "
            + binding1 + "Texture2D _AdaptedTex : register(t1); " + binding1 + "SamplerState _AdaptedTexSampler : register(s1); ";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/AutoExposure");
        ShaderCompileResult extract = CompileMaterialContractShader(compiler, backend, vertexSource, resources + "float4 main() : SV_Target { return _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); }");
        ShaderCompileResult downsample = CompileMaterialContractShader(compiler, backend, vertexSource, resources + "float4 main() : SV_Target { return _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); }");
        ShaderCompileResult adaptFront = CompileMaterialContractShader(compiler, backend, vertexSource, adaptBlock + "float4 main() : SV_Target { return float4(_AdaptSpeedUp / 4.0, _AdaptSpeedDown / 4.0, _HistoryValid, 1.0); }");
        ShaderCompileResult adaptTail = CompileMaterialContractShader(compiler, backend, vertexSource, adaptBlock + resources + "float4 main() : SV_Target { float4 current = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); float4 adapted = _AdaptedTex.Sample(_AdaptedTexSampler, float2(0.5, 0.5)); return float4(current.r, adapted.g, _AdaptSpeedUp / 4.0, _HistoryValid); }");
        ShaderCompileResult applyFront = CompileMaterialContractShader(compiler, backend, vertexSource, applyBlock + "float4 main() : SV_Target { return float4((_ExposureComp + 2.0) / 4.0, _MinExposure / 4.0, _MaxExposure / 8.0, 1.0); }");
        ShaderCompileResult applyTail = CompileMaterialContractShader(compiler, backend, vertexSource, applyBlock + resources + "float4 main() : SV_Target { float4 scene = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); float4 adapted = _AdaptedTex.Sample(_AdaptedTexSampler, float2(0.5, 0.5)); return float4(scene.r, adapted.g, scene.b, adapted.b); }");
        if (IsSpirvUnavailable(backend, extract)) return [];
        Assert.True(extract.Success, extract.ErrorMessage);
        Assert.True(downsample.Success, downsample.ErrorMessage);
        Assert.True(adaptFront.Success, adaptFront.ErrorMessage);
        Assert.True(adaptTail.Success, adaptTail.ErrorMessage);
        Assert.True(applyFront.Success, applyFront.ErrorMessage);
        Assert.True(applyTail.Success, applyTail.ErrorMessage);

        using var extractVariant = CreateMaterialContractVariant(extract, bytecodeFormat);
        using var downsampleVariant = CreateMaterialContractVariant(downsample, bytecodeFormat);
        using var adaptFrontVariant = CreateMaterialContractVariant(adaptFront, bytecodeFormat);
        using var adaptTailVariant = CreateMaterialContractVariant(adaptTail, bytecodeFormat);
        using var applyFrontVariant = CreateMaterialContractVariant(applyFront, bytecodeFormat);
        using var applyTailVariant = CreateMaterialContractVariant(applyTail, bytecodeFormat);
        using var defaultMainTexture = new Resources.Texture2D();
        using var overrideMainTexture = new Resources.Texture2D();
        using var defaultAdaptedTexture = new Resources.Texture2D();
        using var overrideAdaptedTexture = new Resources.Texture2D();
        using var shader = CreateAutoExposureContractShader(defaultMainTexture, defaultAdaptedTexture);
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetFloat("_AdaptSpeedUp", 4f);
        overridesMaterial.SetFloat("_AdaptSpeedDown", 2f);
        overridesMaterial.SetFloat("_HistoryValid", 1f);
        overridesMaterial.SetFloat("_ExposureComp", -1f);
        overridesMaterial.SetFloat("_MinExposure", 0.25f);
        overridesMaterial.SetFloat("_MaxExposure", 8f);
        overridesMaterial.SetTexture("_MainTex", overrideMainTexture);
        overridesMaterial.SetTexture("_AdaptedTex", overrideAdaptedTexture);
        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 10, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("auto-exposure-material-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, defaultMainTexture, new byte[] { 32, 64, 96, 255 });
            EncodeContractTexture(create, overrideMainTexture, new byte[] { 192, 160, 128, 255 });
            EncodeContractTexture(create, defaultAdaptedTexture, new byte[] { 64, 128, 160, 255 });
            EncodeContractTexture(create, overrideAdaptedTexture, new byte[] { 224, 192, 32, 255 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 10, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("auto-exposure-material-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, extractVariant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, downsampleVariant, overridesMaterial, 1);
            DrawMaterialPixel(draw, vertexArray, adaptFrontVariant, defaultsMaterial, 2);
            DrawMaterialPixel(draw, vertexArray, adaptFrontVariant, overridesMaterial, 3);
            DrawMaterialPixel(draw, vertexArray, adaptTailVariant, defaultsMaterial, 4);
            DrawMaterialPixel(draw, vertexArray, adaptTailVariant, overridesMaterial, 5);
            DrawMaterialPixel(draw, vertexArray, applyFrontVariant, defaultsMaterial, 6);
            DrawMaterialPixel(draw, vertexArray, applyFrontVariant, overridesMaterial, 7);
            DrawMaterialPixel(draw, vertexArray, applyTailVariant, defaultsMaterial, 8);
            DrawMaterialPixel(draw, vertexArray, applyTailVariant, overridesMaterial, 9);
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 32f / 255f, 64f / 255f, 96f / 255f, 1f);
        AssertMaterialPixel(pixels, 1, 192f / 255f, 160f / 255f, 128f / 255f, 1f);
        AssertMaterialPixel(pixels, 2, 0.5f, 0.25f, 0f, 1f);
        AssertMaterialPixel(pixels, 3, 1f, 0.5f, 1f, 1f);
        AssertMaterialPixel(pixels, 4, 32f / 255f, 128f / 255f, 0.5f, 0f);
        AssertMaterialPixel(pixels, 5, 192f / 255f, 192f / 255f, 1f, 1f);
        AssertMaterialPixel(pixels, 6, 0.625f, 0.03125f, 0.5f, 1f);
        AssertMaterialPixel(pixels, 7, 0.25f, 0.0625f, 1f, 1f);
        AssertMaterialPixel(pixels, 8, 32f / 255f, 128f / 255f, 96f / 255f, 160f / 255f);
        AssertMaterialPixel(pixels, 9, 192f / 255f, 192f / 255f, 128f / 255f, 32f / 255f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("auto-exposure-material-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
        return pixels;
    }

    private static void RunTAAMaterialContract(
        IGraphicsDevice device,
        GraphicsBackend backend,
        ShaderBytecodeFormat bytecodeFormat,
        Func<GraphicsTexture, byte[]> readback)
    {
        const string location = "";
        const string binding0 = "";
        const string binding1 = "";
        const string binding2 = "";
        const string binding3 = "";
        string vertexSource = "struct VSInput { " + location + "float3 position : POSITION; }; float4 main(VSInput input) : SV_Position { return float4(input.position, 1); }";
        const string block = "cbuffer TAAResolvePS : register(b2) { float2 _Resolution; float2 _Jitter; float _HistoryValid; float _BlendFactor; float _MotionScale; float _Sharpness; }; ";
        string resources = binding0 + "Texture2D _MainTex : register(t0); " + binding0 + "SamplerState _MainTexSampler : register(s0); "
            + binding1 + "Texture2D _HistoryTex : register(t1); " + binding1 + "SamplerState _HistoryTexSampler : register(s1); "
            + binding2 + "Texture2D _MotionVectorsTex : register(t2); " + binding2 + "SamplerState _MotionVectorsSampler : register(s2); "
            + binding3 + "Texture2D _CameraDepthTexture : register(t3); " + binding3 + "SamplerState _CameraDepthSampler : register(s3); ";
        IShaderCompiler compiler = ShaderCompilerFactory.GetCompiler(backend, "Default/TAA");
        ShaderCompileResult front = CompileMaterialContractShader(compiler, backend, vertexSource, block + "float4 main() : SV_Target { return float4(_Resolution.x / 8.0, _Resolution.y / 8.0, _HistoryValid, _BlendFactor); }");
        ShaderCompileResult tail = CompileMaterialContractShader(compiler, backend, vertexSource, block + resources + "float4 main() : SV_Target { float4 current = _MainTex.Sample(_MainTexSampler, float2(0.5, 0.5)); float4 history = _HistoryTex.Sample(_HistoryTexSampler, float2(0.5, 0.5)); float4 motion = _MotionVectorsTex.Sample(_MotionVectorsSampler, float2(0.5, 0.5)); float4 depth = _CameraDepthTexture.Sample(_CameraDepthSampler, float2(0.5, 0.5)); return float4(current.r, history.g, motion.b, depth.a); }");
        if (!front.Success || !tail.Success)
            return;

        using var frontVariant = CreateMaterialContractVariant(front, bytecodeFormat);
        using var tailVariant = CreateMaterialContractVariant(tail, bytecodeFormat);
        using var mainDefault = new Resources.Texture2D();
        using var mainOverride = new Resources.Texture2D();
        using var historyDefault = new Resources.Texture2D();
        using var historyOverride = new Resources.Texture2D();
        using var motionDefault = new Resources.Texture2D();
        using var motionOverride = new Resources.Texture2D();
        using var depthDefault = new Resources.Texture2D();
        using var depthOverride = new Resources.Texture2D();
        using var shader = CreateTAAContractShader(mainDefault, historyDefault, motionDefault);
        using var defaultsMaterial = new Resources.Material(shader);
        using var overridesMaterial = new Resources.Material(shader);
        overridesMaterial.SetVector("_Resolution", new Float2(2f, 4f));
        overridesMaterial.SetVector("_Jitter", new Float2(-0.25f, 0.5f));
        overridesMaterial.SetFloat("_HistoryValid", 1f);
        overridesMaterial.SetFloat("_BlendFactor", 0.75f);
        overridesMaterial.SetFloat("_MotionScale", 4f);
        overridesMaterial.SetFloat("_Sharpness", 0.5f);
        overridesMaterial.SetTexture("_MainTex", mainOverride);
        overridesMaterial.SetTexture("_HistoryTex", historyOverride);
        overridesMaterial.SetTexture("_MotionVectorsTex", motionOverride);
        float[] vertices = [-1f, -1f, 0f, 0f, 1f, 0f, 1f, -1f, 0f];
        ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes, dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred([new GraphicsFrameBuffer.Attachment { Texture = color }], 4, 1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);
        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("taa-material-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, true, vertexBytes);
            EncodeContractTexture(create, mainDefault, new byte[] { 32, 64, 96, 255 });
            EncodeContractTexture(create, mainOverride, new byte[] { 192, 160, 128, 255 });
            EncodeContractTexture(create, historyDefault, new byte[] { 64, 128, 160, 255 });
            EncodeContractTexture(create, historyOverride, new byte[] { 224, 192, 32, 255 });
            EncodeContractTexture(create, motionDefault, new byte[] { 16, 48, 80, 255 });
            EncodeContractTexture(create, motionOverride, new byte[] { 96, 128, 160, 255 });
            EncodeContractTexture(create, depthDefault, new byte[] { 32, 64, 96, 128 });
            EncodeContractTexture(create, depthOverride, new byte[] { 160, 192, 224, 64 });
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 4, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, true);
        }

        RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("taa-material-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.DisableScissor();
            draw.SetRasterState(in raster);
            DrawMaterialPixel(draw, vertexArray, frontVariant, defaultsMaterial, 0);
            DrawMaterialPixel(draw, vertexArray, frontVariant, overridesMaterial, 1);
            draw.SetGlobalTexture("_CameraDepthTexture", depthDefault);
            DrawMaterialPixel(draw, vertexArray, tailVariant, defaultsMaterial, 2);
            draw.SetGlobalTexture("_CameraDepthTexture", depthOverride);
            DrawMaterialPixel(draw, vertexArray, tailVariant, overridesMaterial, 3);
            draw.ClearGlobalTexture("_CameraDepthTexture");
            device.Execute(draw, true);
        }

        byte[] pixels = readback(color);
        AssertMaterialPixel(pixels, 0, 0.5f, 1f, 0f, 0.9f);
        AssertMaterialPixel(pixels, 1, 0.25f, 0.5f, 1f, 0.75f);
        AssertMaterialPixel(pixels, 2, 32f / 255f, 128f / 255f, 80f / 255f, 128f / 255f);
        AssertMaterialPixel(pixels, 3, 192f / 255f, 192f / 255f, 160f / 255f, 64f / 255f);
        using CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("taa-material-dispose");
        dispose.EncodeDisposeFramebuffer(framebuffer);
        device.Execute(dispose, true);
    }

