    private static Resources.Shader CreateGTAOContractShader(Resources.Texture2D noiseTextureValue)
    {
        Rendering.Shaders.ShaderProperty slices = new(6) { Name = "_Slices", DisplayName = "Slices" };
        Rendering.Shaders.ShaderProperty directionSamples = new(32) { Name = "_DirectionSamples", DisplayName = "Direction Samples" };
        Rendering.Shaders.ShaderProperty radius = new(0.5f) { Name = "_Radius", DisplayName = "Radius" };
        Rendering.Shaders.ShaderProperty intensity = new(1f) { Name = "_Intensity", DisplayName = "Intensity" };
        Rendering.Shaders.ShaderProperty noiseScale = new(new Float2(0.25f, 0.5f)) { Name = "_NoiseScale", DisplayName = "Noise Scale" };
        Rendering.Shaders.ShaderProperty jitterOffset = new(new Float2(0.125f, 0.25f)) { Name = "_JitterOffset", DisplayName = "Jitter Offset" };
        Rendering.Shaders.ShaderProperty noise = new(noiseTextureValue) { Name = "_Noise", DisplayName = "Noise" };
        return new Resources.Shader("GTAO Calculate Contract", [slices, directionSamples, radius, intensity, noiseScale, jitterOffset, noise], []);
    }

    private static Resources.Shader CreateGTAOBlurContractShader(Resources.Texture2D mainTextureValue)
    {
        Rendering.Shaders.ShaderProperty direction = new(new Float2(1f, 0f)) { Name = "_BlurDirection", DisplayName = "Blur Direction" };
        Rendering.Shaders.ShaderProperty radius = new(1f) { Name = "_BlurRadius", DisplayName = "Blur Radius" };
        Rendering.Shaders.ShaderProperty mainTexture = new(mainTextureValue) { Name = "_MainTex", DisplayName = "Main Texture" };
        return new Resources.Shader("GTAO Blur Contract", [direction, radius, mainTexture], []);
    }

    private static Resources.Shader CreateGTAOCompositeContractShader(Resources.Texture2D mainTextureValue, Resources.Texture2D aoTextureValue)
    {
        Rendering.Shaders.ShaderProperty mainTexture = new(mainTextureValue) { Name = "_MainTex", DisplayName = "Main Texture" };
        Rendering.Shaders.ShaderProperty aoTexture = new(aoTextureValue) { Name = "_AOTex", DisplayName = "AO Texture" };
        return new Resources.Shader("GTAO Composite Contract", [mainTexture, aoTexture], []);
    }

    private static Resources.Shader CreateGTAOTemporalContractShader(Resources.Texture2D mainTextureValue, Resources.Texture2D previousTextureValue, Resources.Texture2D motionTextureValue)
    {
        Rendering.Shaders.ShaderProperty response = new(0.75f) { Name = "_TResponse", DisplayName = "Temporal Response" };
        Rendering.Shaders.ShaderProperty mainTexture = new(mainTextureValue) { Name = "_MainTex", DisplayName = "Current AO" };
        Rendering.Shaders.ShaderProperty previousTexture = new(previousTextureValue) { Name = "_PreviousBuffer", DisplayName = "Previous AO" };
        Rendering.Shaders.ShaderProperty motionTexture = new(motionTextureValue) { Name = "_CameraMotionVectorsTexture", DisplayName = "Motion Vectors" };
        return new Resources.Shader("GTAO Temporal Contract", [response, mainTexture, previousTexture, motionTexture], []);
    }

    private static void EncodeContractTexture(CommandBuffer commandBuffer, Resources.Texture2D texture, byte[] pixels)
    {
        commandBuffer.EncodeCreateTexture(texture.Handle);
        commandBuffer.EncodeAllocateTexture2D(texture.Handle, 0, 1, 1, 0, pixels);
    }

    private static void EncodeContractCubemap(CommandBuffer commandBuffer, Resources.Cubemap cubemap)
    {
        commandBuffer.EncodeCreateTexture(cubemap.Handle);
        byte[] face = new byte[4 * 4 * cubemap.BytesPerPixel()];
        for (int i = 0; i < 6; i++)
            commandBuffer.EncodeAllocateTextureCubeFace(cubemap.Handle, i, 0, 4, face);
    }

    private static void BindDummyGiProbes(CommandBuffer draw, Resources.Texture2D dummy)
    {
        // Realtime GI probe volume off: dummies satisfy the reflected slots; the black data
        // texture (alpha 0) also makes GiProbesActive() read false inside the shader.
        draw.SetGlobalTexture("_GiIrradianceAtlas", dummy);
        draw.SetGlobalTexture("_GiProbeMoments", dummy);
        draw.SetGlobalTexture("_GiProbeData", dummy);
    }

    private static void BindDummyReflectionProbes(CommandBuffer draw, Resources.Cubemap cube, Resources.Texture2D brdfLut)
    {
        draw.SetGlobalTextureCube("_SpecCube0", cube);
        draw.SetGlobalTextureCube("_SpecCube1", cube);
        draw.SetGlobalTexture("_BRDFLut", brdfLut);
        draw.SetGlobalInt("_ReflectionProbeCount", 0);
        draw.SetGlobalVector("_ProbeWeights", Float2.Zero);
    }

    private static void BindDummyLightCookies(CommandBuffer draw, Resources.Texture2D white)
    {
        draw.SetGlobalTexture("_LightCookieMain", white);
        draw.SetGlobalTexture("_LightCookieAtlas", white);
        draw.SetGlobalInt("_LightCookieMainEnabled", 0);
        draw.SetGlobalFloat("_LightCookieMainIntensity", 0f);
        draw.SetGlobalMatrix("_LightCookieMainWorldToLight", Float4x4.Identity);
        draw.SetGlobalTexture("_ScreenSpaceShadowmap", white);
        draw.SetGlobalInt("_ScreenSpaceShadowsEnabled", 0);
    }

    private static void DrawMaterialPixel(
        CommandBuffer draw,
        GraphicsVertexArray vertexArray,
        ShaderVariant variant,
        Resources.Material material,
        int pixel)
    {
        draw.SetShader(variant);
        draw.SetMaterialProperties(material);
        draw.SetViewport(pixel, 0, 1, 1);
        draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
    }

    private static void AssertMaterialPixel(byte[] pixels, int pixel, float red, float green, float blue, float alpha)
    {
        int offset = pixel * 4;
        int expectedRed = (int)MathF.Round(red * 255f);
        int expectedGreen = (int)MathF.Round(green * 255f);
        int expectedBlue = (int)MathF.Round(blue * 255f);
        int expectedAlpha = (int)MathF.Round(alpha * 255f);
        bool matches = ChannelMatches(pixels[offset], expectedRed)
            && ChannelMatches(pixels[offset + 1], expectedGreen)
            && ChannelMatches(pixels[offset + 2], expectedBlue)
            && ChannelMatches(pixels[offset + 3], expectedAlpha);
        Assert.True(matches,
            $"Pixel {pixel} expected RGBA ({expectedRed}, {expectedGreen}, {expectedBlue}, {expectedAlpha}) +/- 1, " +
            $"actual ({pixels[offset]}, {pixels[offset + 1]}, {pixels[offset + 2]}, {pixels[offset + 3]}). Full={Convert.ToHexString(pixels)}");
    }

    private static bool ChannelMatches(byte actual, int expected) =>
        actual >= Math.Max(0, expected - 1) && actual <= Math.Min(255, expected + 1);

    private static bool PixelMatches(byte[] pixels, int pixel, int red, int green, int blue, int alpha)
    {
        int offset = pixel * 4;
        return ChannelMatches(pixels[offset], red)
            && ChannelMatches(pixels[offset + 1], green)
            && ChannelMatches(pixels[offset + 2], blue)
            && ChannelMatches(pixels[offset + 3], alpha);
    }

    // Nearest-neighbor upscale of an RGBA8 framebuffer so 1x1 / 2x1 contract frames become visible
    // PNGs under docs/screenshots/.
    private static byte[] UpscalePixels(byte[] source, int sourceWidth, int sourceHeight, int targetWidth, int targetHeight)
    {
        byte[] target = new byte[targetWidth * targetHeight * 4];
        for (int y = 0; y < targetHeight; y++)
        {
            int srcY = (int)((long)y * sourceHeight / targetHeight);
            for (int x = 0; x < targetWidth; x++)
            {
                int srcX = (int)((long)x * sourceWidth / targetWidth);
                int src = (srcY * sourceWidth + srcX) * 4;
                int dst = (y * targetWidth + x) * 4;
                target[dst] = source[src];
                target[dst + 1] = source[src + 1];
                target[dst + 2] = source[src + 2];
                target[dst + 3] = source[src + 3];
            }
        }
        return target;
    }

    private static byte[] JoinHorizontal(
        byte[] first,
        byte[] second,
        byte[] third,
        int panelWidth,
        int panelHeight)
    {
        int panelRowBytes = panelWidth * 4;
        byte[] result = new byte[panelWidth * 3 * panelHeight * 4];
        int resultRowBytes = panelRowBytes * 3;
        for (int y = 0; y < panelHeight; y++)
        {
            int sourceOffset = y * panelRowBytes;
            int targetOffset = y * resultRowBytes;
            Buffer.BlockCopy(first, sourceOffset, result, targetOffset, panelRowBytes);
            Buffer.BlockCopy(second, sourceOffset, result, targetOffset + panelRowBytes, panelRowBytes);
            Buffer.BlockCopy(third, sourceOffset, result, targetOffset + panelRowBytes * 2, panelRowBytes);
        }
        return result;
    }

    private static byte[] JoinHorizontal(
        byte[] first,
        byte[] second,
        byte[] third,
        byte[] fourth,
        int panelWidth,
        int panelHeight)
    {
        int panelRowBytes = panelWidth * 4;
        byte[] result = new byte[panelWidth * 4 * panelHeight * 4];
        int resultRowBytes = panelRowBytes * 4;
        for (int y = 0; y < panelHeight; y++)
        {
            int sourceOffset = y * panelRowBytes;
            int targetOffset = y * resultRowBytes;
            Buffer.BlockCopy(first, sourceOffset, result, targetOffset, panelRowBytes);
            Buffer.BlockCopy(second, sourceOffset, result, targetOffset + panelRowBytes, panelRowBytes);
            Buffer.BlockCopy(third, sourceOffset, result, targetOffset + panelRowBytes * 2, panelRowBytes);
            Buffer.BlockCopy(fourth, sourceOffset, result, targetOffset + panelRowBytes * 3, panelRowBytes);
        }
        return result;
    }

    // Saves an RGBA8 framebuffer as a PNG under docs/screenshots/<name>.png without third-party
    // dependencies (manual zlib framing around DeflateStream). Used by the C1da/C1de contracts so
    // the runtime render output is inspectable by eye, not just asserted programmatically.
    private static string SaveScreenshotPng(string name, byte[] rgba, int width, int height)
    {
        string? overrideDirectory = Environment.GetEnvironmentVariable("XENGINE_TEST_SCREENSHOT_DIR");
        string dir = string.IsNullOrWhiteSpace(overrideDirectory)
            ? Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "docs", "screenshots"))
            : Path.GetFullPath(overrideDirectory);
        Directory.CreateDirectory(dir);
        string path = Path.Combine(dir, name + ".png");

        using var memory = new MemoryStream();
        memory.WriteByte(0x89); memory.WriteByte(0x50); memory.WriteByte(0x4E); memory.WriteByte(0x47);
        memory.WriteByte(0x0D); memory.WriteByte(0x0A); memory.WriteByte(0x1A); memory.WriteByte(0x0A);

        byte[] ihdr = new byte[13];
        WriteBigEndianInt32(ihdr, 0, width);
        WriteBigEndianInt32(ihdr, 4, height);
        ihdr[8] = 8;
        ihdr[9] = 6;
        ihdr[10] = 0;
        ihdr[11] = 0;
        ihdr[12] = 0;
        WritePngChunk(memory, "IHDR", ihdr);

        byte[] raw = new byte[(width * 4 + 1) * height];
        int srcRow = width * 4;
        for (int y = 0; y < height; y++)
        {
            raw[y * (srcRow + 1)] = 0;
            Buffer.BlockCopy(rgba, y * srcRow, raw, y * (srcRow + 1) + 1, srcRow);
        }
        byte[] idat;
        using (var deflate = new MemoryStream())
        {
            deflate.WriteByte(0x78);
            deflate.WriteByte(0x9C);
            using (var compressor = new System.IO.Compression.DeflateStream(deflate, System.IO.Compression.CompressionLevel.Optimal, true))
                compressor.Write(raw, 0, raw.Length);
            uint adler = Adler32(raw);
            byte[] adlerBytes = new byte[4];
            WriteBigEndianInt32(adlerBytes, 0, (int)adler);
            deflate.Write(adlerBytes, 0, 4);
            idat = deflate.ToArray();
        }
        WritePngChunk(memory, "IDAT", idat);
        WritePngChunk(memory, "IEND", Array.Empty<byte>());
        File.WriteAllBytes(path, memory.ToArray());
        return Path.GetFullPath(path);
    }

    private static void WriteBigEndianInt32(byte[] buffer, int offset, int value)
    {
        buffer[offset + 0] = (byte)((value >> 24) & 0xFF);
        buffer[offset + 1] = (byte)((value >> 16) & 0xFF);
        buffer[offset + 2] = (byte)((value >> 8) & 0xFF);
        buffer[offset + 3] = (byte)(value & 0xFF);
    }

    private static void WritePngChunk(Stream stream, string type, byte[] data)
    {
        byte[] lengthBytes = new byte[4];
        WriteBigEndianInt32(lengthBytes, 0, data.Length);
        stream.Write(lengthBytes, 0, 4);
        byte[] typeBytes = System.Text.Encoding.ASCII.GetBytes(type);
        stream.Write(typeBytes, 0, 4);
        if (data.Length > 0)
            stream.Write(data, 0, data.Length);
        uint crc = Crc32(typeBytes, data);
        byte[] crcBytes = new byte[4];
        WriteBigEndianInt32(crcBytes, 0, (int)crc);
        stream.Write(crcBytes, 0, 4);
    }

    private static uint Crc32(byte[] type, byte[] data)
    {
        uint crc = 0xFFFFFFFFu;
        for (int i = 0; i < type.Length; i++) crc = (crc >> 8) ^ s_pngCrcTable[(crc ^ type[i]) & 0xFF];
        for (int i = 0; i < data.Length; i++) crc = (crc >> 8) ^ s_pngCrcTable[(crc ^ data[i]) & 0xFF];
        return crc ^ 0xFFFFFFFFu;
    }

    private static uint Adler32(byte[] data)
    {
        const uint modulus = 65521u;
        uint a = 1, b = 0;
        for (int i = 0; i < data.Length; i++)
        {
            a = (a + data[i]) % modulus;
            b = (b + a) % modulus;
        }
        return (b << 16) | a;
    }

    private static readonly uint[] s_pngCrcTable = BuildPngCrcTable();
    private static uint[] BuildPngCrcTable()
    {
        uint[] table = new uint[256];
        for (uint n = 0; n < 256; n++)
        {
            uint c = n;
            for (int k = 0; k < 8; k++)
                c = (c & 1u) != 0u ? (0xEDB88320u ^ (c >> 1)) : (c >> 1);
            table[n] = c;
        }
        return table;
    }

    private static CommandOpcode ReadOpcode(ReadOnlySpan<byte> s, ref int pos)
    {
        ushort v = (ushort)(s[pos] | (s[pos + 1] << 8));
        pos += 2;
        return (CommandOpcode)v;
    }

    private static int ReadI32(ReadOnlySpan<byte> s, ref int pos)
    {
        int v = BitConverter.ToInt32(s.Slice(pos, 4));
        pos += 4;
        return v;
    }

    private static ushort ReadU16(ReadOnlySpan<byte> s, ref int pos)
    {
        ushort v = BitConverter.ToUInt16(s.Slice(pos, 2));
        pos += 2;
        return v;
    }

    private static uint ReadU32(ReadOnlySpan<byte> s, ref int pos)
    {
        uint v = BitConverter.ToUInt32(s.Slice(pos, 4));
        pos += 4;
        return v;
    }

    private static string FindRepositoryRoot()
    {
        DirectoryInfo? directory = new(AppContext.BaseDirectory);
        while (directory != null)
        {
            if (File.Exists(Path.Combine(directory.FullName, "Directory.Build.props"))
                && File.Exists(Path.Combine(directory.FullName, "XEngine.Runtime", "XEngine.Runtime.csproj")))
                return directory.FullName;
            directory = directory.Parent;
        }

        directory = new DirectoryInfo(Environment.CurrentDirectory);
        while (directory != null)
        {
            if (File.Exists(Path.Combine(directory.FullName, "Directory.Build.props"))
                && File.Exists(Path.Combine(directory.FullName, "XEngine.Runtime", "XEngine.Runtime.csproj")))
                return directory.FullName;
            directory = directory.Parent;
        }
        throw new DirectoryNotFoundException("Could not locate the XEngine repository root.");
    }

    // --- Project Toon end-to-end lighting (2026-08-25 dark-character diagnosis) ---
    //
    // Compiles the REAL game project's Toon.shader (ZonezeroTestProject), renders a fullscreen
    // triangle lit by the engine's StandardLighting globals (directional only, shadows off),
    // and asserts the output matches the expected banded-lit color. This is the full chain the
    // editor exercises — ShaderParser include resolution, Slang reflection layout, the generic
    // ToonShadingMaterial packing, and the engine-managed StandardLighting/StandardShadows
    // cbuffers — so a black render here reproduces (and then guards against) the
    // "characters render black, lighting seems off" symptom.

    private static byte[]? TryRenderProjectToon(GraphicsBackend backend)
    {
        try
        {
            string shaderPath = Path.Combine(
                FindRepositoryRoot(), "ZonezeroTestProject", "Assets", "ZZZ", "Shaders", "Toon.shader");
            if (!File.Exists(shaderPath))
                return null; // submodule not checked out — clean skip

            if (!AssetImporting.ShaderParser.ParseShader(shaderPath, File.ReadAllText(shaderPath), path =>
            {
                // Same resolution order as Shader.LoadFromFile: file-relative first, then the
                // engine's embedded default includes (XEngineCG, StandardLighting, ...).
                string? absolutePath = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(shaderPath)!, path));
                if (File.Exists(absolutePath))
                    return File.ReadAllText(absolutePath);
                try { return Resources.EmbeddedResources.ReadAllText(path); }
                catch { return null; }
            }, out Resources.Shader? toon) || toon == null)
            {
                Assert.Fail("Project Toon.shader failed to parse.");
                return null;
            }

            Rendering.Shaders.ShaderPass pass = toon.GetPass(0);
            string vertexSource = GetHlslSource(pass, "_hlslVertexSource");
            // TEMP-PROBE H: hardcode the normal in VS to bypass vertex-input binding.
            vertexSource = vertexSource.Replace("TransformDirection(GetMorphedNormal(input.vertexNormal))", "float3(0.0, 0.0, 1.0)");
            string fragmentSource = GetHlslSource(pass, "_hlslFragmentSource");

            ShaderCompileResult compiled = new RuntimeSlangShaderCompiler().Compile(new ShaderCompileRequest
            {
                TargetBackend = backend,
                Language = ShaderLanguage.Hlsl,
                VertexSource = vertexSource,
                FragmentSource = fragmentSource,
                VertexEntryPoint = "main",
                FragmentEntryPoint = "main",
                ShaderName = "Zonezero/Toon",
            });
            if (IsSpirvUnavailable(backend, compiled))
                return null;
            Assert.True(compiled.Success, compiled.ErrorMessage);

            ShaderBytecodeFormat bytecodeFormat = backend == GraphicsBackend.Vulkan
                ? ShaderBytecodeFormat.SpirV
                : ShaderBytecodeFormat.Dxil;
            using var variant = new ShaderVariant(new CompiledShaderBytecode(
                ShaderLanguage.Hlsl, bytecodeFormat, compiled.VertexBytecode!, compiled.FragmentBytecode!,
                compiled.BindingLayout, compiled.VertexInputLayout));

            // Fullscreen triangle, normals facing the light (+Z) so the toon band saturates to 1.
            float[] vertices =
            [
                -1f, -1f, 0f, 0.5f, 0.5f, 0f, 0f, 1f,
                3f, -1f, 0f, 0.5f, 0.5f, 0f, 0f, 1f,
                -1f, 3f, 0f, 0.5f, 0.5f, 0f, 0f, 1f,
            ];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());

            if (backend == GraphicsBackend.Direct3D12)
            {
                if (!OperatingSystem.IsWindows())
                    return null;
                using var device = new Backends.D3D12.D3D12GraphicsDevice(
                    new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
                device.Initialize(null);
                return RenderProjectToonTriangle(
                    device, variant, toon, vertexBytes,
                    texture => device.ReadTexture2D(
                        device.Textures[texture.Handle].Resource!, 1, 1, 4, device.Textures[texture.Handle].State));
            }

            using var vkDevice = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            vkDevice.Initialize(null);
            return RenderProjectToonTriangle(
                vkDevice, variant, toon, vertexBytes,
                texture => vkDevice.ReadTexture2D(vkDevice.Images[texture.Handle], 4));
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            return null;
        }
    }

    private static byte[] RenderProjectToonTriangle(
        IGraphicsDevice device,
        ShaderVariant variant,
        Resources.Shader toonShader,
        ReadOnlySpan<byte> vertexBytes,
        Func<GraphicsTexture, byte[]> readback)
    {
        // GlobalUniforms identity VP.
        byte[] globalUniformBytes = new byte[Rendering.GlobalUniformsData.SizeInBytes];
        Span<float> gv = System.Runtime.InteropServices.MemoryMarshal.Cast<byte, float>(globalUniformBytes.AsSpan());
        const int ViewProjectionOffset = 3 * 16;
        for (int diagonal = 0; diagonal < 4; diagonal++)
            gv[ViewProjectionOffset + (diagonal * 5)] = 1f;
        using var globalUniformBuffer = new GraphicsBuffer(BufferType.UniformBuffer, globalUniformBytes, dynamic: true);

        using var white = new Resources.Texture2D(1, 1, false, TextureImageFormat.Color4b);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        using var depth = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Depth32f);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
            [
                new GraphicsFrameBuffer.Attachment { Texture = color },
                new GraphicsFrameBuffer.Attachment { Texture = depth, IsDepth = true },
            ],
            1,
            1);
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes.ToArray(), dynamic: true);
        var format = new VertexFormat([
            new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
            new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
            new(VertexFormat.VertexSemantic.Normal, VertexFormat.VertexType.Float, 3),
        ]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("project-toon-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
            create.EncodeCreateBuffer(globalUniformBuffer, dynamic: true, globalUniformBytes);
            EncodeContractTexture(create, white, [255, 255, 255, 255]);
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateTexture(depth);
            create.EncodeAllocateTexture2D(depth, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, wait: true);
        }
        SetGlobalUniformBuffer(globalUniformBuffer);

        using var material = new Resources.Material(toonShader);

        RasterizerState raster = new()
        {
            DepthTest = false,
            DepthWrite = false,
            CullFace = RasterizerState.PolyFace.None,
        };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("project-toon-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0f, 0f, 0f, 1f));
            draw.DisableScissor();
            draw.SetBuffer("GlobalUniforms", globalUniformBuffer);
            // BVH / atlas / probe descriptors must be valid even on the disabled path.
            draw.SetGlobalTexture("_StaticLightData", white);
            draw.SetGlobalTexture("_StaticLightNodes", white);
            draw.SetGlobalTexture("_DynamicLightData", white);
            draw.SetGlobalTexture("_DynamicLightNodes", white);
            draw.SetGlobalTexture("_ShadowAtlas", white);
            draw.SetGlobalInt("_StaticLightRoot", -1);
            draw.SetGlobalInt("_DynamicLightRoot", -1);
            draw.SetGlobalInt("_StaticLightTexSize", 1);
            draw.SetGlobalInt("_StaticLightTexShift", 0);
            draw.SetGlobalInt("_StaticNodeTexSize", 1);
            draw.SetGlobalInt("_StaticNodeTexShift", 0);
            draw.SetGlobalInt("_DynamicLightTexSize", 1);
            draw.SetGlobalInt("_DynamicLightTexShift", 0);
            draw.SetGlobalInt("_DynamicNodeTexSize", 1);
            draw.SetGlobalInt("_DynamicNodeTexShift", 0);
            draw.SetGlobalInt("_DirectionalLightShadowEnabled", 0);
            draw.SetGlobalInt("_DirectionalLightEnabled", 1);
            draw.SetGlobalVector("_DirectionalLightDirection", new Float3(0f, 0f, 1f));
            draw.SetGlobalVector("_DirectionalLightColor", new Float3(1f, 0.5f, 0.25f));
            // Unity-parity raw intensity: the Toon shader no longer applies the legacy * 8, so
            // intensity 1 (as in the imported combat scene) keeps the output exactly in range.
            draw.SetGlobalFloat("_DirectionalLightIntensity", 1f);
            draw.SetShader(variant);
            draw.SetRasterState(in raster);
            draw.SetMaterialProperties(material);
            draw.SetViewport(0, 0, 1, 1);
            draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
            device.Execute(draw, wait: true);
        }

        byte[] pixels = readback(color);
        using (CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("project-toon-dispose"))
        {
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, wait: true);
        }
        return pixels;
    }

    [Theory]
    [InlineData(GraphicsBackend.Vulkan)]
    [InlineData(GraphicsBackend.Direct3D12)]
    public void Optional_ModernBackends_ProjectToon_LightsUp_Or_Skip(GraphicsBackend backend)
    {
        byte[]? pixels = TryRenderProjectToon(backend);
        if (pixels == null)
            return;

        // band=1, shadow off -> occ=1 -> L=1; albedo=white*tint(white); ambient term replaced by
        // lightColor = (1, 0.5, 0.25) * 1 = (1, 0.5, 0.25) at Unity-parity raw intensity
        // (`GetMainLight().color`; the legacy "* 8" compensation left the Toon shader 2026-08-27).
        // Black output here is the "dark characters, lighting not working" regression.
        AssertMaterialPixel(pixels, 0, 1f, 0.5f, 0.25f, 1f);
    }

    // --- MiniToon: isolates whether the StandardLighting cbuffer data reaches a fragment shader
    // on Vulkan at all (no Toon logic, no textures, no other cbuffers). Same global setup as the
    // project Toon test; expects the directional color through flags. ---

    private const string MiniToonVertex = """
cbuffer ToonShadingMaterial : register(b2)
{
    float4 _MainColor;
};
struct VSInput { float3 position : POSITION; };
float4 main(VSInput input) : SV_Position
{
    return float4(input.position, 1);
}
""";

    private const string MiniToonFragment = """
cbuffer ToonShadingMaterial : register(b2)
{
    float4 _MainColor;
};
cbuffer StandardLighting : register(b3)
{
    int4 _StandardLightFlags;
    int4 _StandardStaticLightMeta;
    int4 _StandardDynamicLightMeta;
    float4 _StandardDirectionalDirectionIntensity;
    float4 _StandardDirectionalColor;
    float4 _StandardAmbientModeStrength;
    float4 _StandardAmbientColor;
    float4 _StandardAmbientSkyColor;
    float4 _StandardAmbientGroundColor;
    float4 _StandardFogColor;
    float4 _StandardFogParams;
    float4 _StandardFogStates;
    float4 _ClusterGridParams;
    float4 _ClusterZParams;
    float4 _ClusterCameraForward;
};
float4 main() : SV_Target
{
    return float4(_StandardDirectionalColor.rgb, 1) * _StandardLightFlags.x;
}
""";

    private static byte[]? TryRenderMiniToon(GraphicsBackend backend)
    {
        try
        {
            // DXIL emission goes through the DXC downstream compiler, which is only vendored on
            // Windows; on other hosts the compile itself fails (E00100) before the device guard
            // below, so degrade to skip up front instead of failing.
            if (backend == GraphicsBackend.Direct3D12 && !OperatingSystem.IsWindows())
                return null;

            ShaderCompileResult compiled = new RuntimeSlangShaderCompiler().Compile(new ShaderCompileRequest
            {
                TargetBackend = backend,
                Language = ShaderLanguage.Hlsl,
                VertexSource = MiniToonVertex,
                FragmentSource = MiniToonFragment,
                VertexEntryPoint = "main",
                FragmentEntryPoint = "main",
                ShaderName = "MiniToon",
            });
            if (IsSpirvUnavailable(backend, compiled))
                return null;
            Assert.True(compiled.Success, compiled.ErrorMessage);

            using var variant = new ShaderVariant(new CompiledShaderBytecode(
                ShaderLanguage.Hlsl,
                backend == GraphicsBackend.Vulkan ? ShaderBytecodeFormat.SpirV : ShaderBytecodeFormat.Dxil,
                compiled.VertexBytecode!,
                compiled.FragmentBytecode!,
                compiled.BindingLayout));

            float[] vertices = [-1f, -1f, 0f, 3f, -1f, 0f, -1f, 3f, 0f];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());

            if (backend == GraphicsBackend.Direct3D12)
            {
                if (!OperatingSystem.IsWindows())
                    return null;
                using var device = new Backends.D3D12.D3D12GraphicsDevice(
                    new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
                device.Initialize(null);
                return RenderMiniToon(device, variant, vertexBytes,
                    texture => device.ReadTexture2D(
                        device.Textures[texture.Handle].Resource!, 1, 1, 4, device.Textures[texture.Handle].State));
            }

            using var vkDevice = new Backends.Vulkan.VulkanGraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            vkDevice.Initialize(null);
            return RenderMiniToon(vkDevice, variant, vertexBytes,
                texture => vkDevice.ReadTexture2D(vkDevice.Images[texture.Handle], 4));
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
            return null;
        }
    }

    private static byte[] RenderMiniToon(
        IGraphicsDevice device,
        ShaderVariant variant,
        ReadOnlySpan<byte> vertexBytes,
        Func<GraphicsTexture, byte[]> readback)
    {
        using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes.ToArray(), dynamic: true);
        using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
        GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
            [new GraphicsFrameBuffer.Attachment { Texture = color }],
            1,
            1);
        var format = new VertexFormat([new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3)]);
        using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

        using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("minitoon-create"))
        {
            create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
            create.EncodeCreateTexture(color);
            create.EncodeAllocateTexture2D(color, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
            create.EncodeCreateFramebuffer(framebuffer);
            create.EncodeCreateVertexArray(vertexArray);
            device.Execute(create, wait: true);
        }

        RasterizerState raster = new()
        {
            DepthTest = false,
            DepthWrite = false,
            CullFace = RasterizerState.PolyFace.None,
        };
        using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("minitoon-draw"))
        {
            draw.SetRenderTarget(framebuffer);
            draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
            draw.DisableScissor();
            draw.SetGlobalInt("_DirectionalLightEnabled", 1);
            draw.SetGlobalVector("_DirectionalLightDirection", new Float3(0f, 0f, 1f));
            draw.SetGlobalVector("_DirectionalLightColor", new Float3(1f, 0.5f, 0.25f));
            draw.SetGlobalFloat("_DirectionalLightIntensity", 0.125f);
            draw.SetShader(variant);
            draw.SetRasterState(in raster);
            draw.SetViewport(0, 0, 1, 1);
            draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
            device.Execute(draw, wait: true);
        }

        byte[] pixels = readback(color);
        using (CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("minitoon-dispose"))
        {
            dispose.EncodeDisposeFramebuffer(framebuffer);
            device.Execute(dispose, wait: true);
        }
        return pixels;
    }

    [Theory]
    [InlineData(GraphicsBackend.Vulkan)]
    [InlineData(GraphicsBackend.Direct3D12)]
    public void Optional_ModernBackends_MiniToon_StandardLighting_Reaches_PixelShader_Or_Skip(GraphicsBackend backend)
    {
        byte[]? pixels = TryRenderMiniToon(backend);
        if (pixels == null)
            return;

        // flags.x=1 gates the directional color straight to the output.
        AssertMaterialPixel(pixels, 0, 1f, 0.5f, 0.25f, 1f);
    }

    // --- Two-step texture upload: allocate empty then TexSubImage2D (the editor's asset path) ---
    //
    // The one-shot EncodeAllocateTexture2D(data) path works everywhere (see every contract test
    // above). The editor's asset pipeline instead allocates an empty image (RecreateImage →
    // TexImage2D(null)) and then fills it (SetData → TexSubImage2D). If the second step's
    // vkCmdCopyBufferToImage silently fails, the image keeps its uninitialized contents (black)
    // and every textured mesh renders as a silhouette — the "characters are pure black" symptom.

    private const string TwoStepVertex = """
struct VSInput { float3 position : POSITION; float2 uv : TEXCOORD0; };
struct VSOutput { float4 position : SV_Position; float2 uv : TEXCOORD0; };
VSOutput main(VSInput input)
{
    VSOutput output;
    output.position = float4(input.position, 1);
    output.uv = input.uv;
    return output;
}
""";

    private const string TwoStepFragment = """
Texture2D _MainTex : register(t0);
SamplerState _MainTexSampler : register(s0);
struct PSInput { float4 position : SV_Position; float2 uv : TEXCOORD0; };
float4 main(PSInput input) : SV_Target
{
    return _MainTex.Sample(_MainTexSampler, input.uv);
}
""";

    [Fact]
    public void Optional_D3D12_FramebufferDescriptors_RecycleAcross128Submissions()
    {
        try
        {
            using var device = new Backends.D3D12.D3D12GraphicsDevice(
                new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12 });
            device.Initialize(null);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var depth = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Depth32f);
            using (var create = global::XEngine.Runtime.Graphics.GetCommandBuffer("descriptor-fixture"))
            {
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateTexture(depth);
                create.EncodeAllocateTexture2D(depth, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
                device.Execute(create, wait: true);
            }
            for (int i = 0; i < 128; i++)
            {
                var framebuffer = GraphicsFrameBuffer.CreateDeferred([
                    new GraphicsFrameBuffer.Attachment { Texture = color },
                    new GraphicsFrameBuffer.Attachment { Texture = depth, IsDepth = true },
                ], 1, 1);
                using var commands = global::XEngine.Runtime.Graphics.GetCommandBuffer("descriptor-reuse");
                // Match viewport recreation: a new depth allocation starts in DepthWrite.
                commands.EncodeAllocateTexture2D(depth, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
                commands.EncodeCreateFramebuffer(framebuffer);
                commands.SetRenderTarget(framebuffer);
                commands.ClearRenderTarget(ClearFlags.Color | ClearFlags.Depth, new Color(0f, 1f, 0f, 1f));
                commands.EncodeDisposeFramebuffer(framebuffer);
                device.Execute(commands, wait: false);
            }
            device.WaitIdle();
            byte[] pixels = device.ReadTexture2D(device.Textures[color.Handle].Resource!,
                1, 1, 4, device.Textures[color.Handle].State);
            AssertMaterialPixel(pixels, 0, 0, 1, 0, 1);
            Assert.Empty(device.Framebuffers);
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex)) { }
    }

    [Theory]
    [InlineData(GraphicsBackend.Vulkan)]
    [InlineData(GraphicsBackend.Direct3D12)]
    public void Optional_ModernBackends_TwoStepTextureUpload_PreservesData_Or_Skip(GraphicsBackend backend)
    {
        ShaderCompileResult compiled = new RuntimeSlangShaderCompiler().Compile(new ShaderCompileRequest
        {
            TargetBackend = backend,
            Language = ShaderLanguage.Hlsl,
            VertexSource = TwoStepVertex,
            FragmentSource = TwoStepFragment,
            VertexEntryPoint = "main",
            FragmentEntryPoint = "main",
        });
        if (IsSpirvUnavailable(backend, compiled))
            return;
        Assert.True(compiled.Success, compiled.ErrorMessage);

        try
        {
            using IGraphicsDevice device = backend == GraphicsBackend.Direct3D12
                ? new Backends.D3D12.D3D12GraphicsDevice(new GraphicsDeviceOptions { Backend = GraphicsBackend.Direct3D12, EnableValidation = true })
                : new Backends.Vulkan.VulkanGraphicsDevice(new GraphicsDeviceOptions { Backend = GraphicsBackend.Vulkan });
            device.Initialize(null);

            using var variant = new ShaderVariant(new CompiledShaderBytecode(
                ShaderLanguage.Hlsl,
                backend == GraphicsBackend.Vulkan ? ShaderBytecodeFormat.SpirV : ShaderBytecodeFormat.Dxil,
                compiled.VertexBytecode!, compiled.FragmentBytecode!,
                compiled.BindingLayout,
                compiled.VertexInputLayout));

            // Step 1: create + allocate the texture EMPTY (RecreateImage path).
            // Step 2: fill via TexSubImage2D (SetData path).
            int texW = 256, texH = 256;
            byte[] texel = new byte[texW * texH * 4];
            for (int ty = 0; ty < texH; ty++)
                for (int tx = 0; tx < texW; tx++)
                {
                    int off = (ty * texW + tx) * 4;
                    texel[off + 0] = 200; texel[off + 1] = 120; texel[off + 2] = 40; texel[off + 3] = 255;
                }
            using var texture = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            using var color = new GraphicsTexture(TextureType.Texture2D, TextureImageFormat.Color4b);
            GraphicsFrameBuffer framebuffer = GraphicsFrameBuffer.CreateDeferred(
                [new GraphicsFrameBuffer.Attachment { Texture = color }], 1, 1);

            float[] vertices = [-1f, -1f, 0f, 0f, 0f, 3f, -1f, 0f, 1f, 0f, -1f, 3f, 0f, 0f, 1f];
            ReadOnlySpan<byte> vertexBytes = System.Runtime.InteropServices.MemoryMarshal.AsBytes(vertices.AsSpan());
            using var vertexBuffer = new GraphicsBuffer(BufferType.VertexBuffer, vertexBytes.ToArray(), dynamic: true);
            var format = new VertexFormat([
                new(VertexFormat.VertexSemantic.Position, VertexFormat.VertexType.Float, 3),
                new(VertexFormat.VertexSemantic.TexCoord0, VertexFormat.VertexType.Float, 2),
            ]);
            using var vertexArray = new GraphicsVertexArray(format, vertexBuffer, null);

            using (CommandBuffer create = global::XEngine.Runtime.Graphics.GetCommandBuffer("twostep-create"))
            {
                create.EncodeCreateBuffer(vertexBuffer, dynamic: true, vertexBytes);
                create.EncodeCreateTexture(color);
                create.EncodeAllocateTexture2D(color, 0, 1, 1, 0, ReadOnlySpan<byte>.Empty);
                create.EncodeCreateFramebuffer(framebuffer);
                create.EncodeCreateVertexArray(vertexArray);
                device.Execute(create, wait: true);
            }
            // Step 1b: allocate the texture EMPTY through this device (the constructor
            // submitted its own create via Graphics.Submit, which drops when Graphics.Device
            // is null in this standalone-device test).
            using (CommandBuffer alloc = global::XEngine.Runtime.Graphics.GetCommandBuffer("twostep-alloc"))
            {
                alloc.EncodeCreateTexture(texture);
                alloc.EncodeAllocateTexture2D(texture, 0, (uint)texW, (uint)texH, 0, ReadOnlySpan<byte>.Empty);
                device.Execute(alloc, wait: true);
            }
            // Step 2: fill via UpdateTexture in a separate command buffer (SetData path).
            using (CommandBuffer update = global::XEngine.Runtime.Graphics.GetCommandBuffer("twostep-update"))
            {
                update.EncodeUpdateTexture2D(texture, 0, 0, 0, (uint)texW, (uint)texH, texel);
                device.Execute(update, wait: true);
            }

            RasterizerState raster = new() { DepthTest = false, DepthWrite = false, CullFace = RasterizerState.PolyFace.None };
            using (CommandBuffer draw = global::XEngine.Runtime.Graphics.GetCommandBuffer("twostep-draw"))
            {
                draw.SetRenderTarget(framebuffer);
                draw.ClearRenderTarget(ClearFlags.Color, new Color(0f, 0f, 0f, 1f));
                draw.DisableScissor();
                draw.SetTexture("_MainTex", texture);
                draw.SetShader(variant);
                draw.SetRasterState(in raster);
                draw.SetViewport(0, 0, 1, 1);
                draw.DrawArrays(vertexArray, Topology.Triangles, 0, 3);
                device.Execute(draw, wait: true);
            }

            byte[] pixels;
            if (device is Backends.D3D12.D3D12GraphicsDevice d3d)
                pixels = d3d.ReadTexture2D(d3d.Textures[color.Handle].Resource!, 1, 1, 4, d3d.Textures[color.Handle].State);
            else
                pixels = ((Backends.Vulkan.VulkanGraphicsDevice)device).ReadTexture2D(((Backends.Vulkan.VulkanGraphicsDevice)device).Images[color.Handle], 4);

            using (CommandBuffer dispose = global::XEngine.Runtime.Graphics.GetCommandBuffer("twostep-dispose"))
            {
                dispose.EncodeDisposeFramebuffer(framebuffer);
                device.Execute(dispose, wait: true);
            }

            // The texel (200,120,40) must survive the allocate-then-update roundtrip.
            AssertMaterialPixel(pixels, 0, 200f / 255f, 120f / 255f, 40f / 255f, 1f);
        }
        catch (Exception ex) when (IsExpectedGpuUnavailable(ex))
        {
        }
    }
    [Fact]
    public void MagickNet_DecodesCharacterTexture_WithRealPixels()
    {
        string path = Path.Combine(FindRepositoryRoot(),
            "ZonezeroTestProject", "Assets", "ZZZ", "Arts", "PlayerModel", "\u53EF\u7433", "PNG", "Corin_Body_D.tga.png");
        if (!File.Exists(path)) return;
        using var image = new ImageMagick.MagickImage(path);
        Assert.Equal(2048u, image.Width);
        Assert.Equal(2048u, image.Height);
        image.Flip();
        image.ColorSpace = ImageMagick.ColorSpace.sRGB;
        image.ColorType = ImageMagick.ColorType.TrueColorAlpha;
        unsafe
        {
            var ptr = image.GetPixelsUnsafe().GetAreaPointer(0, 0, image.Width, image.Height);
            var b = (byte*)ptr;
            int nz = 0;
            for (int i = 0; i < 4000; i++) if (b[i] != 0) nz++;
            Assert.True(nz > 100, "Magick decoded " + nz + " non-zero bytes in first 4000.");
        }
    }

}
